end)

]],
    [[[
popupManage
]]] = [=[
(function(triggerId, action, targetScript, ...)
    local POPUP_VAR = "helltrainUiPopupV1"
    local POPUP_STATE = "popupState"
    local targetArgs = {...}
    local ALLOWED_POPUP_HTML = {
        ["캐릭터 리스트"] = true,
        ["도감"] = true,
        ["덱 확인"] = true,
        ["플레이 가이드"] = true,
        ["설정"] = true,
    }

    local function emptyState()
        return {
            current = nil,
            history = {}
        }
    end

    local function getPopupState()
        local state = getState(triggerId, POPUP_STATE)

        if type(state) ~= "table" then
            return emptyState()
        end

        if type(state.history) ~= "table" then
            state.history = {}
        end

        return state
    end

    local function setPopupState(state)
        setState(triggerId, POPUP_STATE, state)

        local savedState = getState(triggerId, POPUP_STATE)
        local ok, encoded = pcall(json.encode, savedState)
        if ok then
            debug(2, "popup state saved: " .. encoded)
        end
    end

    local function clearPopupHtml()
        setChatVar(triggerId, POPUP_VAR, "")
    end

    local function makeEntry(script, args)
        return {
            script = script,
            args = args or {}
        }
    end

    local function isAllowedEntry(entry)
        if type(entry) ~= "table" or type(entry.script) ~= "string" then
            return false
        end
        local args = type(entry.args) == "table" and entry.args or {}
        if entry.script == "uiRender" then
            return (args[1] == "append" or args[1] == "popup")
                and ALLOWED_POPUP_HTML[args[2]] == true
                and args[3] == nil
        end
        if entry.script == "캐릭터 프로필" then
            return args[1] == "유지영" and args[2] == nil
        end
        return false
    end

    local function argsEqual(left, right)
        left = left or {}
        right = right or {}

        if #left ~= #right then
            return false
        end

        for index, value in ipairs(left) do
            if value ~= right[index] then
                return false
            end
        end

        return true
    end

    local function entriesEqual(left, right)
        return type(left) == "table"
            and type(right) == "table"
            and left.script == right.script
            and argsEqual(left.args, right.args)
    end

    local function clearPopupState()
        setPopupState(emptyState())
    end

    local function closePopup()
        clearPopupHtml()
        clearPopupState()
    end

    local function renderPopup(entry)
        if not entry or not entry.script or entry.script == "" then
            debug(1, "popupManage error: empty target script.")
            return false
        end
        if not isAllowedEntry(entry) then
            debug(1, "popupManage error: disallowed popup target.")
            return false
        end

        clearPopupHtml()
        runScript(triggerId, entry.script, table.unpack(entry.args or {}))
        return true
    end

    local actions = {}

    actions.root = function()
        local state = getPopupState()
        local nextEntry = makeEntry(targetScript, targetArgs)

        if entriesEqual(state.current, nextEntry) then
            closePopup()
            return
        end

        local nextState = {
            current = nextEntry,
            history = {}
        }

        if not renderPopup(nextEntry) then
            return
        end
        setPopupState(nextState)
    end

    actions.push = function()
        local state = getPopupState()
        local nextEntry = makeEntry(targetScript, targetArgs)

        if state.current and state.current.script then
            table.insert(state.history, state.current)
        end

        state.current = nextEntry
        if not renderPopup(nextEntry) then
            return
        end
        setPopupState(state)
    end

    actions.replace = function()
        local state = getPopupState()
        local nextEntry = makeEntry(targetScript, targetArgs)

        state.current = nextEntry
        if not renderPopup(nextEntry) then
            return
        end
        setPopupState(state)
    end

    actions.back = function()
        local state = getPopupState()
        local previous = table.remove(state.history)

        if not previous then
            closePopup()
            return
        end

        state.current = previous
        if not renderPopup(previous) then
            return
        end
        setPopupState(state)
    end

    actions.close = function()
        closePopup()
    end

    local handler = actions[action]

    if not handler then
        debug(1, "popupManage error: unknown action " .. tostring(action))
        return
    end

    handler()
end)

]=],
    [[[
runProgression
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local KIND = "runProgressionV1"
    local MIN_DECK_SIZE = 10
    local MAX_DECK_SIZE = 20
    local MAX_CARD_COPIES = 2
    local REWARD_OFFER_SIZE = 3
    local CHARACTER_OFFER_SIZE = 3
    local MAX_SESSIONS = 999
    local BATTLE_SEED_MAX = 2147483646
    local MAX_SAFE_INTEGER = 9007199254740991
    local TRANSIT_ALGORITHM = "tokyo_subway_segment_v1"

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(state, applied, stale)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            state = state,
            applied = applied == true,
            stale = stale == true,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isSafeInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and math.abs(value) <= MAX_SAFE_INTEGER
            and (minimum == nil or value >= minimum)
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function objectPath(path, key)
        if type(key) == "string"
            and string.match(key, "^[A-Za-z_][A-Za-z0-9_]*$") ~= nil then
            return path .. "." .. key
        end
        return path .. "[" .. string.format("%q", tostring(key)) .. "]"
    end

    local function appendError(errors, code, path, message)
        errors[#errors + 1] = makeError(code, path, message)
    end

    local function inspectJsonTable(value, path, errors)
        if type(value) ~= "table" then
            appendError(errors, "expected_table", path, "테이블이어야 합니다.")
            return nil, nil
        end
        if getmetatable(value) ~= nil then
            appendError(errors, "metatable_not_allowed", path, "JSON 값에는 메타테이블을 사용할 수 없습니다.")
            return nil, nil
        end

        local numericCount = 0
        local maximum = 0
        local hasNumeric = false
        local hasString = false
        local stringKeys = {}
        for key in pairs(value) do
            if type(key) == "number" then
                hasNumeric = true
                numericCount = numericCount + 1
                if not isSafeInteger(key, 1) then
                    appendError(errors, "invalid_array_index", path, "배열 인덱스는 1 이상의 연속 정수여야 합니다.")
                    return nil, nil
                end
                if key > maximum then
                    maximum = key
                end
            elseif type(key) == "string" then
                hasString = true
                stringKeys[#stringKeys + 1] = key
            else
                appendError(errors, "invalid_object_key", path, "JSON 객체 키는 문자열이어야 합니다.")
                return nil, nil
            end
        end
        if hasNumeric and hasString then
            appendError(errors, "mixed_table", path, "배열 인덱스와 객체 키를 함께 사용할 수 없습니다.")
            return nil, nil
        end
        if hasNumeric then
            if numericCount ~= maximum then
                appendError(errors, "sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다.")
                return nil, nil
            end
            return "array", maximum
        end
        table.sort(stringKeys)
        return "object", stringKeys
    end

    local function validateJson(value, path, errors, active)
        local valueType = type(value)
        if valueType == "string" or valueType == "boolean" or valueType == "nil" then
            return
        end
        if valueType == "number" then
            if not isFinite(value) then
                appendError(errors, "non_finite_number", path, "유한하지 않은 숫자는 상태에 저장할 수 없습니다.")
            end
            return
        end
        if valueType ~= "table" then
            appendError(
                errors,
                "unsupported_type",
                path,
                "상태에 저장할 수 없는 자료형입니다: " .. valueType
            )
            return
        end
        if getmetatable(value) ~= nil then
            appendError(errors, "metatable_not_allowed", path, "상태 값에는 메타테이블을 사용할 수 없습니다.")
            return
        end

        active = active or {}
        if active[value] then
            appendError(errors, "circular_reference", path, "순환 참조가 있는 상태는 사용할 수 없습니다.")
            return
        end
        active[value] = true
        local kind, shape = inspectJsonTable(value, path, errors)
        if kind == "array" then
            for index = 1, shape do
                validateJson(value[index], path .. "[" .. index .. "]", errors, active)
            end
        elseif kind == "object" then
            for _, key in ipairs(shape) do
                validateJson(value[key], objectPath(path, key), errors, active)
            end
        end
        active[value] = nil
    end

    local function cloneJson(value, path, active)
        local valueType = type(value)
        if valueType == "nil" or valueType == "string" or valueType == "boolean" then
            return value, nil
        end
        if valueType == "number" then
            if not isFinite(value) then
                return nil, makeError("non_finite_number", path, "유한하지 않은 숫자는 상태에 저장할 수 없습니다.")
            end
            return value, nil
        end
        if valueType ~= "table" then
            return nil, makeError(
                "unsupported_type",
                path,
                "상태에 저장할 수 없는 자료형입니다: " .. valueType
            )
        end
        if getmetatable(value) ~= nil then
            return nil, makeError("metatable_not_allowed", path, "상태 값에는 메타테이블을 사용할 수 없습니다.")
        end

        active = active or {}
        if active[value] then
            return nil, makeError("circular_reference", path, "순환 참조가 있는 상태는 사용할 수 없습니다.")
        end
        active[value] = true

        local shapeErrors = {}
        local kind, shape = inspectJsonTable(value, path, shapeErrors)
        if #shapeErrors > 0 then
            active[value] = nil
            return nil, shapeErrors[1]
        end

        local copy = {}
        if kind == "array" then
            for index = 1, shape do
                local itemCopy, itemError = cloneJson(value[index], path .. "[" .. index .. "]", active)
                if itemError then
                    active[value] = nil
                    return nil, itemError
                end
                copy[index] = itemCopy
            end
        else
            for _, key in ipairs(shape) do
                local itemCopy, itemError = cloneJson(value[key], objectPath(path, key), active)
                if itemError then
                    active[value] = nil
                    return nil, itemError
                end
                copy[key] = itemCopy
            end
        end
        active[value] = nil
        return copy, nil
    end

    local function deepEqual(left, right, seen)
        if type(left) ~= type(right) then
            return false
        end
        if type(left) ~= "table" then
            return left == right
        end
        if getmetatable(left) ~= nil or getmetatable(right) ~= nil then
            return false
        end
        seen = seen or {}
        if seen[left] ~= nil then
            return seen[left] == right
        end
        seen[left] = right
        for key, value in pairs(left) do
            if not deepEqual(value, right[key], seen) then
                seen[left] = nil
                return false
            end
        end
        for key in pairs(right) do
            if left[key] == nil then
                seen[left] = nil
                return false
            end
        end
        seen[left] = nil
        return true
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return
        end
        for key in pairs(value) do
            if type(key) ~= "string" or allowed[key] ~= true then
                appendError(errors, "unknown_field", objectPath(path, key), "허용되지 않은 필드입니다.")
            end
        end
    end

    local function denseArrayLength(value, path, errors)
        local kind, shape = inspectJsonTable(value, path, errors)
        if kind == "object" and type(shape) == "table" and #shape == 0 then
            return 0
        end
        if kind ~= "array" then
            if kind ~= nil then
                appendError(errors, "expected_array", path, "1부터 시작하는 연속 배열이어야 합니다.")
            end
            return nil
        end
        return shape
    end

    local function copyArray(value)
        local copy = {}
        for index, item in ipairs(value or {}) do
            copy[index] = item
        end
        return copy
    end

    local function contains(value, target)
        for _, item in ipairs(value or {}) do
            if item == target then
                return true
            end
        end
        return false
    end

    local function normalizeStaticData(staticInput)
        if type(staticInput) == "table"
            and getmetatable(staticInput) == nil
            and type(rawget(staticInput, "data")) == "table" then
            return rawget(staticInput, "data")
        end
        return staticInput
    end

    local function appendNestedErrors(target, moduleName, report)
        local nested = type(report) == "table" and report.errors or nil
        if type(nested) ~= "table" or #nested == 0 then
            target[#target + 1] = makeError(
                "module_failed_without_errors",
                "$.runtime." .. moduleName,
                moduleName .. "이 오류 상세 없이 실패했습니다."
            )
            return
        end
        for index, item in ipairs(nested) do
            if type(item) == "table" then
                target[#target + 1] = makeError(
                    type(item.code) == "string" and item.code or "nested_error",
                    type(item.path) == "string" and item.path or ("$.runtime." .. moduleName),
                    type(item.message) == "string"
                        and item.message
                        or (moduleName .. " 오류 " .. index .. "에 설명이 없습니다.")
                )
            else
                target[#target + 1] = makeError(
                    "invalid_nested_error",
                    "$.runtime." .. moduleName .. ".errors[" .. index .. "]",
                    "하위 모듈 오류 항목이 객체가 아닙니다."
                )
            end
        end
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError(
                    "runtime_unavailable",
                    "$.runtime." .. moduleName,
                    moduleName .. "을 호출할 runScript 실행기가 없습니다."
                ),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                makeError(
                    "module_call_error",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. " 호출 중 오류가 발생했습니다: " .. tostring(report)
                ),
            }
        end
        if type(report) ~= "table" or getmetatable(report) ~= nil then
            return nil, {
                makeError(
                    "invalid_module_result",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. "이 일반 테이블 결과를 반환하지 않았습니다."
                ),
            }
        end
        if report.schemaVersion ~= SCHEMA_VERSION
            or type(report.errors) ~= "table"
            or (report.ok ~= true and report.ok ~= false) then
            return nil, {
                makeError(
                    "invalid_module_envelope",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. " 결과 envelope가 올바르지 않습니다."
                ),
            }
        end
        if report.ok ~= true then
            local errors = {}
            appendNestedErrors(errors, moduleName, report)
            return nil, errors
        end
        if #report.errors ~= 0 then
            return nil, {
                makeError(
                    "success_with_errors",
                    "$.runtime." .. moduleName .. ".errors",
                    "성공한 하위 모듈 결과에 오류가 포함되어 있습니다."
                ),
            }
        end
        return report, nil
    end

    local function buildPools(staticInput)
        local staticData = normalizeStaticData(staticInput)
        local errors = {}
        if type(staticData) ~= "table" or getmetatable(staticData) ~= nil then
            appendError(errors, "invalid_static_data", "$.staticData", "정적 데이터는 일반 테이블이어야 합니다.")
            return nil, nil, nil, errors
        end

        local cards = rawget(staticData, "cards")
        local characters = rawget(staticData, "characters")
        if type(cards) ~= "table" or getmetatable(cards) ~= nil then
            appendError(errors, "invalid_card_database", "$.staticData.cards", "플레이어 카드 풀을 만들 cards 맵이 필요합니다.")
        end
        if type(characters) ~= "table" or getmetatable(characters) ~= nil then
            appendError(errors, "invalid_character_database", "$.staticData.characters", "대상 후보를 만들 characters 맵이 필요합니다.")
        end
        if #errors > 0 then
            return nil, nil, nil, errors
        end

        local playerPool = {}
        for cardId, card in pairs(cards) do
            local path = objectPath("$.staticData.cards", cardId)
            if type(cardId) ~= "string" then
                appendError(errors, "invalid_card_key", "$.staticData.cards", "카드 맵 키는 문자열이어야 합니다.")
            elseif type(card) ~= "table" or getmetatable(card) ~= nil then
                appendError(errors, "invalid_card_record", path, "카드 레코드는 일반 테이블이어야 합니다.")
            elseif card.owner == "player" then
                if not isAsciiId(cardId) or card.id ~= cardId then
                    appendError(errors, "invalid_player_card", path, "플레이어 카드 키와 내부 ID가 올바르지 않습니다.")
                else
                    playerPool[#playerPool + 1] = cardId
                end
            end
        end
        table.sort(playerPool)

        local characterPool = {}
        for characterId, character in pairs(characters) do
            local path = objectPath("$.staticData.characters", characterId)
            if not isAsciiId(characterId) then
                appendError(errors, "invalid_character_id", path, "캐릭터 키는 lower_snake_case ASCII ID여야 합니다.")
            elseif type(character) ~= "table"
                or getmetatable(character) ~= nil
                or character.id ~= characterId then
                appendError(errors, "invalid_character_record", path, "캐릭터 키와 내부 ID가 올바르지 않습니다.")
            else
                characterPool[#characterPool + 1] = characterId
            end
        end
        table.sort(characterPool)

        if #playerPool == 0 then
            appendError(errors, "empty_player_card_pool", "$.staticData.cards", "카드 보상 후보가 될 플레이어 카드가 없습니다.")
        end
        if #characterPool < CHARACTER_OFFER_SIZE then
            appendError(
                errors,
                "insufficient_character_pool",
                "$.staticData.characters",
                "다음 대상 선택에는 서로 다른 캐릭터가 최소 3명 필요합니다."
            )
        end
        if #errors > 0 then
            return nil, nil, nil, errors
        end
        return staticData, playerPool, characterPool, nil
    end

    local function validateSetup(setupInput, staticInput)
        local setupCopy, setupCopyError = cloneJson(setupInput, "$.gameSetup")
        if setupCopyError then
            return nil, nil, nil, nil, { setupCopyError }
        end
        local staticData, playerPool, characterPool, poolErrors = buildPools(staticInput)
        if poolErrors then
            return nil, nil, nil, nil, poolErrors
        end

        local validated, validationErrors = callModule(
            "gameSetup",
            "validate",
            setupCopy,
            staticInput
        )
        if validationErrors then
            return nil, nil, nil, nil, validationErrors
        end
        if type(validated.state) ~= "table" or getmetatable(validated.state) ~= nil then
            return nil, nil, nil, nil, {
                makeError(
                    "missing_validated_setup",
                    "$.runtime.gameSetup.state",
                    "gameSetup.validate가 canonical 설정 상태를 반환하지 않았습니다."
                ),
            }
        end
        if not deepEqual(setupCopy, validated.state) then
            return nil, nil, nil, nil, {
                makeError(
                    "setup_validation_mismatch",
                    "$.gameSetup",
                    "원본 설정 상태가 seed와 선택 이력으로 재생한 canonical 상태와 다릅니다."
                ),
            }
        end
        if validated.state.kind ~= "gameSetupV1" or validated.state.phase ~= "battleReady" then
            return nil, nil, nil, nil, {
                makeError(
                    "setup_not_battle_ready",
                    "$.gameSetup.phase",
                    "runProgression에는 원본 gameSetupV1 battleReady 상태가 필요합니다."
                ),
            }
        end
        return validated.state, staticData, playerPool, characterPool, nil
    end

    local function callNextIntegers(rng, ranges)
        local report, callErrors = callModule(
            "deterministicRng",
            "nextIntegers",
            rng,
            ranges
        )
        if callErrors then
            return nil, nil, callErrors
        end

        local errors = {}
        local valueCount = denseArrayLength(report.value, "$.runtime.deterministicRng.value", errors)
        if valueCount ~= #ranges then
            appendError(
                errors,
                "invalid_rng_batch_size",
                "$.runtime.deterministicRng.value",
                "결정적 RNG 결과 개수가 요청 범위 개수와 다릅니다."
            )
        elseif valueCount ~= nil then
            for index = 1, valueCount do
                local value = report.value[index]
                local range = ranges[index]
                if not isSafeInteger(value, range.minimum) or value > range.maximum then
                    appendError(
                        errors,
                        "invalid_rng_batch_value",
                        "$.runtime.deterministicRng.value[" .. index .. "]",
                        "결정적 RNG 결과가 요청 범위를 벗어났습니다."
                    )
                end
            end
        end
        if type(report.rng) ~= "table"
            or getmetatable(report.rng) ~= nil
            or not isSafeInteger(report.rng.seed, 0)
            or not isSafeInteger(report.rng.cursor, 0)
            or report.rng.seed ~= rng.seed
            or (#ranges > 0 and report.rng.cursor <= rng.cursor)
            or (#ranges == 0 and report.rng.cursor ~= rng.cursor) then
            appendError(
                errors,
                "invalid_rng_result",
                "$.runtime.deterministicRng.rng",
                "결정적 RNG가 올바른 다음 상태를 반환하지 않았습니다."
            )
        end
        if #errors > 0 then
            return nil, nil, errors
        end
        return copyArray(report.value), {
            seed = report.rng.seed,
            cursor = report.rng.cursor,
        }, nil
    end

    local function pickWithoutReplacement(rng, candidates, count)
        local remaining = copyArray(candidates)
        local ranges = {}
        for pick = 1, count do
            ranges[pick] = {
                minimum = 1,
                maximum = #remaining - pick + 1,
            }
        end
        local selectedIndices, nextRng, rngErrors = callNextIntegers(rng, ranges)
        if rngErrors then
            return nil, nil, rngErrors
        end
        local selected = {}
        for pick = 1, count do
            local selectedIndex = selectedIndices[pick]
            selected[pick] = remaining[selectedIndex]
            table.remove(remaining, selectedIndex)
        end
        return selected, nextRng, nil
    end

    local function hashCanonical(prefix, canonical)
        local hashA = 0
        local hashB = 0
        for index = 1, #canonical do
            local byte = string.byte(canonical, index)
            hashA = (hashA * 131 + byte) % 2147483647
            hashB = (hashB * 137 + byte) % 2147483629
        end
        return prefix
            .. ":" .. tostring(#canonical)
            .. ":" .. tostring(hashA)
            .. ":" .. tostring(hashB)
    end

    local function appendCanonicalArray(parts, label, array)
        parts[#parts + 1] = "|" .. label .. "=" .. tostring(#array) .. ":"
        for _, value in ipairs(array) do
            parts[#parts + 1] = tostring(#value)
            parts[#parts + 1] = ":"
            parts[#parts + 1] = value
            parts[#parts + 1] = ";"
        end
    end

    local function buildRewardToken(setupId, sessionNumber, rng, settlement, deck, kind, cardIds)
        local parts = {
            "setupId=", tostring(#setupId), ":", setupId,
            "|session=", tostring(sessionNumber),
            "|cursor=", tostring(rng.cursor),
            "|battleId=", tostring(#settlement.battleId), ":", settlement.battleId,
            "|turnId=", tostring(#settlement.turnId), ":", settlement.turnId,
            "|kind=", kind,
        }
        appendCanonicalArray(parts, "deck", deck)
        appendCanonicalArray(parts, "offer", cardIds or {})
        return hashCanonical("run-progression-reward-v1", table.concat(parts))
    end

    local function buildCharacterToken(setupId, sessionNumber, rng, settlement, deck, characterIds)
        local parts = {
            "setupId=", tostring(#setupId), ":", setupId,
            "|session=", tostring(sessionNumber),
            "|cursor=", tostring(rng.cursor),
            "|battleId=", tostring(#settlement.battleId), ":", settlement.battleId,
            "|turnId=", tostring(#settlement.turnId), ":", settlement.turnId,
        }
        appendCanonicalArray(parts, "deck", deck)
        appendCanonicalArray(parts, "characters", characterIds)
        return hashCanonical("run-progression-character-v1", table.concat(parts))
    end

    local function countDeck(deck, playerPool, path)
        local errors = {}
        local length = denseArrayLength(deck, path, errors)
        if length ~= nil and (length < MIN_DECK_SIZE or length > MAX_DECK_SIZE) then
            appendError(
                errors,
                "invalid_deck_size",
                path,
                "런 덱은 10장 이상 20장 이하여야 합니다."
            )
        end
        local allowed = {}
        for _, cardId in ipairs(playerPool) do
            allowed[cardId] = true
        end
        local counts = {}
        if length ~= nil then
            for index = 1, length do
                local cardId = deck[index]
                if not isAsciiId(cardId) or allowed[cardId] ~= true then
                    appendError(
                        errors,
                        "unknown_player_card",
                        path .. "[" .. index .. "]",
                        "런 덱 카드가 현재 플레이어 카드 풀에 없습니다."
                    )
                else
                    counts[cardId] = (counts[cardId] or 0) + 1
                    if counts[cardId] > MAX_CARD_COPIES then
                        appendError(
                            errors,
                            "card_copy_limit_exceeded",
                            path .. "[" .. index .. "]",
                            "런 덱에는 같은 카드를 2장까지만 넣을 수 있습니다."
                        )
                    end
                end
            end
        end
        if #errors > 0 then
            return nil, nil, errors
        end
        return counts, length, nil
    end

    local function generateRewardOffer(
        setupId,
        sessionNumber,
        rng,
        settlement,
        deck,
        playerPool
    )
        local counts, deckLength, deckErrors = countDeck(deck, playerPool, "$.playerCardIds")
        if deckErrors then
            return nil, nil, deckErrors
        end
        local eligible = {}
        if deckLength < MAX_DECK_SIZE then
            for _, cardId in ipairs(playerPool) do
                if (counts[cardId] or 0) < MAX_CARD_COPIES then
                    eligible[#eligible + 1] = cardId
                end
            end
        end

        if #eligible == 0 then
            return {
                kind = "none",
                interactionToken = buildRewardToken(
                    setupId,
                    sessionNumber,
                    rng,
                    settlement,
                    deck,
                    "none",
                    {}
                ),
            }, {
                seed = rng.seed,
                cursor = rng.cursor,
            }, nil
        end

        local offerCount = math.min(REWARD_OFFER_SIZE, #eligible)
        local cardIds, nextRng, offerErrors = pickWithoutReplacement(rng, eligible, offerCount)
        if offerErrors then
            return nil, nil, offerErrors
        end
        return {
            kind = "card",
            cardIds = cardIds,
            interactionToken = buildRewardToken(
                setupId,
                sessionNumber,
                nextRng,
                settlement,
                deck,
                "card",
                cardIds
            ),
        }, nextRng, nil
    end

    local function generateCharacterOffer(
        setupId,
        sessionNumber,
        rng,
        settlement,
        deck,
        characterPool
    )
        local characterIds, nextRng, offerErrors = pickWithoutReplacement(
            rng,
            characterPool,
            CHARACTER_OFFER_SIZE
        )
        if offerErrors then
            return nil, nil, offerErrors
        end
        return {
            characterIds = characterIds,
            interactionToken = buildCharacterToken(
                setupId,
                sessionNumber,
                nextRng,
                settlement,
                deck,
                characterIds
            ),
        }, nextRng, nil
    end

    local function generateBattleSeed(rng)
        local values, nextRng, rngErrors = callNextIntegers(rng, {
            {
                minimum = 1,
                maximum = BATTLE_SEED_MAX,
            },
        })
        if rngErrors then
            return nil, nil, rngErrors
        end
        return values[1], nextRng, nil
    end

    local function buildJourney(seed, staticInput)
        local report, journeyErrors = callModule(
            "subwayJourney",
            "build",
            seed,
            staticInput
        )
        if journeyErrors then
            return nil, journeyErrors
        end
        local errors = {}
        if not isSafeInteger(report.turnLimit, 1) then
            appendError(errors, "invalid_turn_limit", "$.runtime.subwayJourney.turnLimit", "여정 제한 턴이 올바르지 않습니다.")
        end
        local transit = report.transit
        if type(transit) ~= "table" or getmetatable(transit) ~= nil then
            appendError(errors, "invalid_transit", "$.runtime.subwayJourney.transit", "여정 이동 구간이 일반 객체가 아닙니다.")
        else
            checkAllowedKeys(
                transit,
                { algorithm = true, lineId = true, stationIds = true },
                "$.runtime.subwayJourney.transit",
                errors
            )
            if transit.algorithm ~= TRANSIT_ALGORITHM then
                appendError(
                    errors,
                    "invalid_transit_algorithm",
                    "$.runtime.subwayJourney.transit.algorithm",
                    "지원하지 않는 여정 알고리즘입니다."
                )
            end
            if not isAsciiId(transit.lineId) then
                appendError(
                    errors,
                    "invalid_transit_line",
                    "$.runtime.subwayJourney.transit.lineId",
                    "여정 노선 ID가 올바르지 않습니다."
                )
            end
            local stationCount = denseArrayLength(
                transit.stationIds,
                "$.runtime.subwayJourney.transit.stationIds",
                errors
            )
            if stationCount ~= nil
                and isSafeInteger(report.turnLimit, 1)
                and stationCount ~= report.turnLimit + 1 then
                appendError(
                    errors,
                    "transit_length_mismatch",
                    "$.runtime.subwayJourney.transit.stationIds",
                    "여정 역 개수는 제한 턴보다 하나 많아야 합니다."
                )
            elseif stationCount ~= nil then
                for index = 1, stationCount do
                    if not isAsciiId(transit.stationIds[index]) then
                        appendError(
                            errors,
                            "invalid_station_id",
                            "$.runtime.subwayJourney.transit.stationIds[" .. index .. "]",
                            "여정 역 ID가 올바르지 않습니다."
                        )
                    end
                end
            end
        end
        if #errors > 0 then
            return nil, errors
        end
        return {
            turnLimit = report.turnLimit,
            transit = {
                algorithm = transit.algorithm,
                lineId = transit.lineId,
                stationIds = copyArray(transit.stationIds),
            },
        }, nil
    end

    local function buildBattleSpec(
        setupId,
        sessionNumber,
        seed,
        characterId,
        deck,
        environmentId,
        staticInput
    )
        local journey, journeyErrors = buildJourney(seed, staticInput)
        if journeyErrors then
            return nil, journeyErrors
        end
        return {
            battleId = "battle-" .. setupId .. "-session-" .. string.format("%03d", sessionNumber),
            seed = seed,
            playerCardIds = copyArray(deck),
            characterId = characterId,
            perkIds = {},
            environmentId = environmentId,
            turnLimit = journey.turnLimit,
            lineId = journey.transit.lineId,
            stationIds = copyArray(journey.transit.stationIds),
        }, nil
    end

    local function buildInitialBattleSpec(setup, staticInput)
        local journey, journeyErrors = buildJourney(setup.battleSpec.seed, staticInput)
        if journeyErrors then
            return nil, journeyErrors
        end
        return {
            battleId = setup.battleSpec.battleId,
            seed = setup.battleSpec.seed,
            playerCardIds = copyArray(setup.selectedCardIds),
            characterId = setup.selectedCharacterId,
            perkIds = {},
            environmentId = setup.battleSpec.environmentId,
            turnLimit = journey.turnLimit,
            lineId = journey.transit.lineId,
            stationIds = copyArray(journey.transit.stationIds),
        }, nil
    end

    local OUTCOME_REASONS = {
        card_checkpoint = true,
        turn_end_checkpoint = true,
        turn_limit = true,
    }

    local function normalizeSummary(summaryInput, staticData, path)
        path = path or "$.summary"
        local summary, cloneError = cloneJson(summaryInput, path)
        if cloneError then
            return nil, { cloneError }
        end
        local errors = {}
        if type(summary) ~= "table" or getmetatable(summary) ~= nil then
            appendError(errors, "invalid_summary", path, "전투 종료 summary는 일반 객체여야 합니다.")
            return nil, errors
        end
        checkAllowedKeys(summary, {
            battleId = true,
            turnId = true,
            characterId = true,
            status = true,
            reasonCode = true,
            turnNumber = true,
            turnLimit = true,
            finalStealth = true,
            finalResistance = true,
            environmentId = true,
            transit = true,
        }, path, errors)

        if not isRuntimeId(summary.battleId) then
            appendError(errors, "invalid_battle_id", path .. ".battleId", "summary battleId가 올바르지 않습니다.")
        end
        if not isRuntimeId(summary.turnId) then
            appendError(errors, "invalid_turn_id", path .. ".turnId", "summary turnId가 올바르지 않습니다.")
        end
        if not isAsciiId(summary.characterId)
            or type(staticData.characters[summary.characterId]) ~= "table" then
            appendError(errors, "unknown_character", path .. ".characterId", "summary 캐릭터를 정적 데이터에서 찾을 수 없습니다.")
        end
        if summary.status ~= "victory" and summary.status ~= "defeat" then
            appendError(errors, "invalid_status", path .. ".status", "summary status는 victory 또는 defeat여야 합니다.")
        end
        if OUTCOME_REASONS[summary.reasonCode] ~= true then
            appendError(errors, "invalid_reason_code", path .. ".reasonCode", "summary 종료 사유가 올바르지 않습니다.")
        end
        if not isSafeInteger(summary.turnNumber, 1) then
            appendError(errors, "invalid_turn_number", path .. ".turnNumber", "summary 턴 번호는 1 이상의 정수여야 합니다.")
        end
        if not isSafeInteger(summary.turnLimit, 1)
            or (isSafeInteger(summary.turnNumber, 1) and summary.turnNumber > summary.turnLimit) then
            appendError(errors, "invalid_turn_limit", path .. ".turnLimit", "summary 제한 턴이 올바르지 않습니다.")
        end
        if not isFinite(summary.finalStealth) then
            appendError(errors, "invalid_final_stealth", path .. ".finalStealth", "최종 은폐는 유한한 숫자여야 합니다.")
        end
        if not isFinite(summary.finalResistance) then
            appendError(errors, "invalid_final_resistance", path .. ".finalResistance", "최종 저항은 유한한 숫자여야 합니다.")
        end
        if not isAsciiId(summary.environmentId)
            or type(staticData.environments) ~= "table"
            or type(staticData.environments[summary.environmentId]) ~= "table" then
            appendError(errors, "unknown_environment", path .. ".environmentId", "summary 환경을 정적 데이터에서 찾을 수 없습니다.")
        end

        local transit = summary.transit
        if type(transit) ~= "table" or getmetatable(transit) ~= nil then
            appendError(errors, "invalid_transit", path .. ".transit", "summary transit은 일반 객체여야 합니다.")
        else
            checkAllowedKeys(
                transit,
                { algorithm = true, lineId = true, stationIds = true },
                path .. ".transit",
                errors
            )
            if transit.algorithm ~= TRANSIT_ALGORITHM then
                appendError(
                    errors,
                    "invalid_transit_algorithm",
                    path .. ".transit.algorithm",
                    "summary transit 알고리즘이 올바르지 않습니다."
                )
            end
            if not isAsciiId(transit.lineId)
                or type(staticData.subwayLines) ~= "table"
                or type(staticData.subwayLines[transit.lineId]) ~= "table" then
                appendError(errors, "unknown_subway_line", path .. ".transit.lineId", "summary 지하철 노선을 찾을 수 없습니다.")
            end
            local stationCount = denseArrayLength(
                transit.stationIds,
                path .. ".transit.stationIds",
                errors
            )
            if stationCount ~= nil
                and isSafeInteger(summary.turnLimit, 1)
                and stationCount ~= summary.turnLimit + 1 then
                appendError(
                    errors,
                    "transit_length_mismatch",
                    path .. ".transit.stationIds",
                    "summary 역 개수는 제한 턴보다 하나 많아야 합니다."
                )
            elseif stationCount ~= nil then
                for index = 1, stationCount do
                    if not isAsciiId(transit.stationIds[index]) then
                        appendError(
                            errors,
                            "invalid_station_id",
                            path .. ".transit.stationIds[" .. index .. "]",
                            "summary 역 ID가 올바르지 않습니다."
                        )
                    end
                end
            end
        end

        if isRuntimeId(summary.battleId)
            and isSafeInteger(summary.turnNumber, 1)
            and summary.turnId ~= string.format("%s-turn-%03d", summary.battleId, summary.turnNumber) then
            appendError(
                errors,
                "turn_identity_mismatch",
                path .. ".turnId",
                "summary turnId가 battleId와 턴 번호에서 결정되는 ID와 다릅니다."
            )
        end

        if isFinite(summary.finalResistance)
            and isFinite(summary.finalStealth)
            and (summary.status == "victory" or summary.status == "defeat") then
            if summary.finalResistance <= 0 and summary.status ~= "victory" then
                appendError(errors, "victory_priority", path .. ".status", "저항이 0 이하이면 승리를 우선해야 합니다.")
            elseif summary.finalResistance > 0
                and summary.finalStealth <= 0
                and summary.status ~= "defeat" then
                appendError(errors, "defeat_required", path .. ".status", "은폐가 0 이하이면 패배여야 합니다.")
            elseif summary.status == "victory" and summary.finalResistance > 0 then
                appendError(errors, "invalid_victory", path .. ".status", "저항이 남은 summary는 승리일 수 없습니다.")
            elseif summary.status == "defeat"
                and summary.finalStealth > 0
                and summary.turnNumber < summary.turnLimit then
                appendError(errors, "invalid_defeat", path .. ".status", "은폐가 남고 제한 턴 전이면 패배일 수 없습니다.")
            end
        end
        if summary.reasonCode == "turn_limit"
            and (summary.status ~= "defeat"
                or summary.turnNumber ~= summary.turnLimit
                or (isFinite(summary.finalResistance) and summary.finalResistance <= 0)
                or (isFinite(summary.finalStealth) and summary.finalStealth <= 0)) then
            appendError(
                errors,
                "invalid_turn_limit_outcome",
                path .. ".reasonCode",
                "turn_limit 패배는 마지막 턴에 저항과 은폐가 모두 남은 경우여야 합니다."
            )
        elseif (summary.reasonCode == "card_checkpoint"
                or summary.reasonCode == "turn_end_checkpoint")
            and isFinite(summary.finalResistance)
            and isFinite(summary.finalStealth)
            and summary.finalResistance > 0
            and summary.finalStealth > 0 then
            appendError(
                errors,
                "invalid_resource_outcome",
                path .. ".reasonCode",
                "자원 checkpoint 종료에는 저항 또는 은폐가 0 이하여야 합니다."
            )
        end

        if #errors > 0 then
            return nil, errors
        end
        return summary, nil
    end

    local function summaryMatchesSpec(summary, battleSpec, path)
        path = path or "$.summary"
        local errors = {}
        if type(battleSpec) ~= "table" then
            appendError(errors, "missing_battle_spec", "$.battleSpec", "summary와 대조할 현재 전투 사양이 없습니다.")
            return errors
        end
        local comparisons = {
            { field = "battleId", expected = battleSpec.battleId },
            { field = "characterId", expected = battleSpec.characterId },
            { field = "environmentId", expected = battleSpec.environmentId },
            { field = "turnLimit", expected = battleSpec.turnLimit },
        }
        for _, comparison in ipairs(comparisons) do
            if summary[comparison.field] ~= comparison.expected then
                appendError(
                    errors,
                    "settlement_battle_mismatch",
                    path .. "." .. comparison.field,
                    "종료 summary가 현재 battleReady 전투 사양과 다릅니다."
                )
            end
        end
        if type(summary.transit) == "table" then
            if summary.transit.lineId ~= battleSpec.lineId then
                appendError(
                    errors,
                    "settlement_transit_mismatch",
                    path .. ".transit.lineId",
                    "종료 summary 노선이 현재 전투 사양과 다릅니다."
                )
            end
            if not deepEqual(summary.transit.stationIds, battleSpec.stationIds) then
                appendError(
                    errors,
                    "settlement_transit_mismatch",
                    path .. ".transit.stationIds",
                    "종료 summary 이동 구간이 현재 전투 사양과 다릅니다."
                )
            end
        end
        return errors
    end

    local function validateRewardChoice(choiceInput, path)
        local choice, cloneError = cloneJson(choiceInput, path)
        if cloneError then
            return nil, { cloneError }
        end
        local errors = {}
        if type(choice) ~= "table" or getmetatable(choice) ~= nil then
            appendError(errors, "invalid_reward_choice", path, "보상 선택은 일반 객체여야 합니다.")
            return nil, errors
        end
        checkAllowedKeys(choice, { kind = true, cardId = true }, path, errors)
        if choice.kind == "card" then
            if not isAsciiId(choice.cardId) then
                appendError(errors, "invalid_reward_card", path .. ".cardId", "카드 보상 선택에는 cardId가 필요합니다.")
            end
        elseif choice.kind == "none" then
            if choice.cardId ~= nil then
                appendError(errors, "unexpected_reward_card", path .. ".cardId", "none 보상 선택에는 cardId를 넣을 수 없습니다.")
            end
        else
            appendError(errors, "invalid_reward_kind", path .. ".kind", "보상 선택 kind는 card 또는 none이어야 합니다.")
        end
        if #errors > 0 then
            return nil, errors
        end
        return choice, nil
    end

    local function applyRewardChoice(offer, choice, deck, playerPool, path)
        local counts, deckLength, deckErrors = countDeck(deck, playerPool, "$.playerCardIds")
        if deckErrors then
            return nil, deckErrors
        end
        if choice.kind == "none" then
            return copyArray(deck), nil
        end
        if offer.kind == "none" then
            return nil, {
                makeError(
                    "reward_choice_mismatch",
                    path .. ".kind",
                    "보상 카드가 없을 때는 continue 선택만 사용할 수 있습니다."
                ),
            }
        end
        if choice.kind ~= "card" or not contains(offer.cardIds, choice.cardId) then
            return nil, {
                makeError(
                    "reward_not_in_offer",
                    path,
                    "선택한 카드가 현재 보상 제안에 없습니다."
                ),
            }
        end
        if deckLength >= MAX_DECK_SIZE or (counts[choice.cardId] or 0) >= MAX_CARD_COPIES then
            return nil, {
                makeError(
                    "reward_no_longer_eligible",
                    path .. ".cardId",
                    "선택한 카드를 현재 덱에 추가할 수 없습니다."
                ),
            }
        end
        local nextDeck = copyArray(deck)
        nextDeck[#nextDeck + 1] = choice.cardId
        return nextDeck, nil
    end

    local SUMMARY_FIELDS = {
        "battleId",
        "turnId",
        "characterId",
        "status",
        "reasonCode",
        "turnNumber",
        "turnLimit",
        "finalStealth",
        "finalResistance",
        "environmentId",
        "transit",
    }

    local function copySettlementFromRecord(record, path)
        local summaryInput = {}
        for _, field in ipairs(SUMMARY_FIELDS) do
            local value = record[field]
            if field == "transit" then
                local transitCopy, transitError = cloneJson(value, path .. ".transit")
                if transitError then
                    return nil, transitError
                end
                summaryInput.transit = transitCopy
            else
                summaryInput[field] = value
            end
        end
        return summaryInput, nil
    end

    local function makeSessionRecord(settlement)
        local record = {}
        for _, field in ipairs(SUMMARY_FIELDS) do
            if field == "transit" then
                record.transit = {
                    algorithm = settlement.transit.algorithm,
                    lineId = settlement.transit.lineId,
                    stationIds = copyArray(settlement.transit.stationIds),
                }
            else
                record[field] = settlement[field]
            end
        end
        return record
    end

    local function buildState(
        setupId,
        phase,
        sessions,
        rng,
        deck,
        stats,
        phaseValue
    )
        local sessionCount = #sessions
        local state = {
            schemaVersion = SCHEMA_VERSION,
            kind = KIND,
            setupId = setupId,
            phase = phase,
            sessionNumber = phase == "battleReady" and sessionCount + 1 or sessionCount,
            rng = {
                seed = rng.seed,
                cursor = rng.cursor,
            },
            playerCardIds = copyArray(deck),
            perkIds = {},
            stats = {
                completed = stats.completed,
                victories = stats.victories,
                defeats = stats.defeats,
            },
            sessions = sessions,
            lastSettlement = makeSessionRecord(sessions[sessionCount]),
        }
        if phase == "reward" then
            state.rewardOffer = phaseValue
        elseif phase == "characterSelect" then
            state.characterOffer = phaseValue
        elseif phase == "battleReady" then
            state.battleSpec = phaseValue
        end
        return state
    end

    local function replaySessions(setup, staticData, staticInput, playerPool, characterPool, sessionInput)
        local sessionShapeErrors = {}
        local sessionCount = denseArrayLength(sessionInput, "$.state.sessions", sessionShapeErrors)
        if sessionCount ~= nil and (sessionCount < 1 or sessionCount > MAX_SESSIONS) then
            appendError(
                sessionShapeErrors,
                "invalid_session_count",
                "$.state.sessions",
                "runProgression에는 1개 이상 999개 이하의 정산 이력이 필요합니다."
            )
        end
        if #sessionShapeErrors > 0 then
            return nil, sessionShapeErrors
        end

        local initialSpec, initialSpecErrors = buildInitialBattleSpec(setup, staticInput)
        if initialSpecErrors then
            return nil, initialSpecErrors
        end
        local _, _, initialDeckErrors = countDeck(
            setup.selectedCardIds,
            playerPool,
            "$.gameSetup.selectedCardIds"
        )
        if initialDeckErrors then
            return nil, initialDeckErrors
        end
        local rng = {
            seed = setup.rng.seed,
            cursor = setup.rng.cursor,
        }
        local deck = copyArray(setup.selectedCardIds)
        local currentSpec = initialSpec
        local stats = {
            completed = 0,
            victories = 0,
            defeats = 0,
        }
        local canonicalSessions = {}

        for sessionIndex = 1, sessionCount do
            local inputRecord = sessionInput[sessionIndex]
            local recordPath = "$.state.sessions[" .. sessionIndex .. "]"
            if type(inputRecord) ~= "table" or getmetatable(inputRecord) ~= nil then
                return nil, {
                    makeError("invalid_session_record", recordPath, "정산 이력 항목은 일반 객체여야 합니다."),
                }
            end
            local recordErrors = {}
            checkAllowedKeys(
                inputRecord,
                {
                    battleId = true,
                    turnId = true,
                    characterId = true,
                    status = true,
                    reasonCode = true,
                    turnNumber = true,
                    turnLimit = true,
                    finalStealth = true,
                    finalResistance = true,
                    environmentId = true,
                    transit = true,
                    rewardChoice = true,
                    nextCharacterId = true,
                },
                recordPath,
                recordErrors
            )
            if #recordErrors > 0 then
                return nil, recordErrors
            end

            local settlementInput, settlementCopyError = copySettlementFromRecord(
                inputRecord,
                recordPath
            )
            if settlementCopyError then
                return nil, { settlementCopyError }
            end
            local settlement, settlementErrors = normalizeSummary(
                settlementInput,
                staticData,
                recordPath
            )
            if settlementErrors then
                return nil, settlementErrors
            end
            local matchErrors = summaryMatchesSpec(
                settlement,
                currentSpec,
                recordPath
            )
            if #matchErrors > 0 then
                return nil, matchErrors
            end

            stats.completed = stats.completed + 1
            if settlement.status == "victory" then
                stats.victories = stats.victories + 1
            else
                stats.defeats = stats.defeats + 1
            end

            local canonicalRecord = makeSessionRecord(settlement)
            canonicalSessions[sessionIndex] = canonicalRecord

            if settlement.status == "victory" then
                local rewardOffer, afterRewardRng, rewardErrors = generateRewardOffer(
                    setup.setupId,
                    sessionIndex,
                    rng,
                    settlement,
                    deck,
                    playerPool
                )
                if rewardErrors then
                    return nil, rewardErrors
                end
                rng = afterRewardRng

                if inputRecord.rewardChoice == nil then
                    if sessionIndex ~= sessionCount then
                        return nil, {
                            makeError(
                                "incomplete_historical_session",
                                recordPath .. ".rewardChoice",
                                "마지막 항목이 아닌 승리 정산 이력에는 보상 선택이 필요합니다."
                            ),
                        }
                    end
                    return buildState(
                        setup.setupId,
                        "reward",
                        canonicalSessions,
                        rng,
                        deck,
                        stats,
                        rewardOffer
                    ), nil
                end

                local rewardChoice, choiceErrors = validateRewardChoice(
                    inputRecord.rewardChoice,
                    recordPath .. ".rewardChoice"
                )
                if choiceErrors then
                    return nil, choiceErrors
                end
                local nextDeck, applyErrors = applyRewardChoice(
                    rewardOffer,
                    rewardChoice,
                    deck,
                    playerPool,
                    recordPath .. ".rewardChoice"
                )
                if applyErrors then
                    return nil, applyErrors
                end
                deck = nextDeck
                canonicalRecord.rewardChoice = rewardChoice
            else
                if inputRecord.rewardChoice ~= nil then
                    local rewardChoice, choiceErrors = validateRewardChoice(
                        inputRecord.rewardChoice,
                        recordPath .. ".rewardChoice"
                    )
                    if choiceErrors then
                        return nil, choiceErrors
                    end
                    if rewardChoice.kind ~= "none" then
                        return nil, {
                            makeError(
                                "reward_not_allowed_after_defeat",
                                recordPath .. ".rewardChoice",
                                "패배한 세션에서는 카드 보상을 획득할 수 없습니다."
                            ),
                        }
                    end
                end
                canonicalRecord.rewardChoice = {
                    kind = "none",
                }
            end

            local characterOffer, afterCharacterRng, characterErrors = generateCharacterOffer(
                setup.setupId,
                sessionIndex,
                rng,
                settlement,
                deck,
                characterPool
            )
            if characterErrors then
                return nil, characterErrors
            end
            rng = afterCharacterRng

            if inputRecord.nextCharacterId == nil then
                if sessionIndex ~= sessionCount then
                    return nil, {
                        makeError(
                            "incomplete_historical_session",
                            recordPath .. ".nextCharacterId",
                            "마지막 항목이 아닌 정산 이력에는 다음 대상 선택이 필요합니다."
                        ),
                    }
                end
                return buildState(
                    setup.setupId,
                    "characterSelect",
                    canonicalSessions,
                    rng,
                    deck,
                    stats,
                    characterOffer
                ), nil
            end
            if not isAsciiId(inputRecord.nextCharacterId)
                or not contains(characterOffer.characterIds, inputRecord.nextCharacterId) then
                return nil, {
                    makeError(
                        "character_not_in_replayed_offer",
                        recordPath .. ".nextCharacterId",
                        "다음 대상이 결정적으로 재생한 캐릭터 후보에 포함되지 않습니다."
                    ),
                }
            end
            canonicalRecord.nextCharacterId = inputRecord.nextCharacterId

            if sessionIndex >= MAX_SESSIONS then
                return nil, {
                    makeError(
                        "session_limit_reached",
                        recordPath .. ".nextCharacterId",
                        "세션 번호 999 뒤에는 새 전투를 만들 수 없습니다."
                    ),
                }
            end
            local battleSeed, afterSeedRng, seedErrors = generateBattleSeed(rng)
            if seedErrors then
                return nil, seedErrors
            end
            rng = afterSeedRng
            local nextSpec, specErrors = buildBattleSpec(
                setup.setupId,
                sessionIndex + 1,
                battleSeed,
                inputRecord.nextCharacterId,
                deck,
                currentSpec.environmentId,
                staticInput
            )
            if specErrors then
                return nil, specErrors
            end
            currentSpec = nextSpec

            if sessionIndex == sessionCount then
                return buildState(
                    setup.setupId,
                    "battleReady",
                    canonicalSessions,
                    rng,
                    deck,
                    stats,
                    currentSpec
                ), nil
            end
        end
        return nil, {
            makeError("missing_progression_state", "$.state", "정산 이력에서 runProgression 상태를 재생하지 못했습니다."),
        }
    end

    local function validateStateShape(state, setupId)
        local errors = {}
        validateJson(state, "$.state", errors, {})
        if type(state) ~= "table" or getmetatable(state) ~= nil then
            return errors
        end
        checkAllowedKeys(state, {
            schemaVersion = true,
            kind = true,
            setupId = true,
            phase = true,
            sessionNumber = true,
            rng = true,
            playerCardIds = true,
            perkIds = true,
            stats = true,
            sessions = true,
            lastSettlement = true,
            rewardOffer = true,
            characterOffer = true,
            battleSpec = true,
        }, "$.state", errors)

        if state.schemaVersion ~= SCHEMA_VERSION then
            appendError(errors, "unsupported_schema_version", "$.state.schemaVersion", "지원하지 않는 runProgression 스키마입니다.")
        end
        if state.kind ~= KIND then
            appendError(errors, "invalid_state_kind", "$.state.kind", "상태 kind는 runProgressionV1이어야 합니다.")
        end
        if state.setupId ~= setupId then
            appendError(errors, "setup_identity_mismatch", "$.state.setupId", "상태가 원본 gameSetup에 속하지 않습니다.")
        end
        if state.phase ~= "reward"
            and state.phase ~= "characterSelect"
            and state.phase ~= "battleReady" then
            appendError(errors, "invalid_phase", "$.state.phase", "지원하지 않는 runProgression phase입니다.")
        end
        if not isSafeInteger(state.sessionNumber, 1) or state.sessionNumber > MAX_SESSIONS then
            appendError(errors, "invalid_session_number", "$.state.sessionNumber", "세션 번호는 1 이상 999 이하여야 합니다.")
        end

        if type(state.rng) ~= "table" or getmetatable(state.rng) ~= nil then
            appendError(errors, "invalid_rng", "$.state.rng", "progression rng는 일반 객체여야 합니다.")
        else
            checkAllowedKeys(state.rng, { seed = true, cursor = true }, "$.state.rng", errors)
            if not isSafeInteger(state.rng.seed, 0) then
                appendError(errors, "invalid_rng_seed", "$.state.rng.seed", "progression RNG seed가 올바르지 않습니다.")
            end
            if not isSafeInteger(state.rng.cursor, 0) then
                appendError(errors, "invalid_rng_cursor", "$.state.rng.cursor", "progression RNG cursor가 올바르지 않습니다.")
            end
        end

        local perkCount = denseArrayLength(state.perkIds, "$.state.perkIds", errors)
        if perkCount ~= nil and perkCount ~= 0 then
            appendError(errors, "unsupported_perks", "$.state.perkIds", "현재 progression 버전의 perkIds는 빈 배열이어야 합니다.")
        end

        if type(state.stats) ~= "table" or getmetatable(state.stats) ~= nil then
            appendError(errors, "invalid_stats", "$.state.stats", "누적 전적은 일반 객체여야 합니다.")
        else
            checkAllowedKeys(
                state.stats,
                { completed = true, victories = true, defeats = true },
                "$.state.stats",
                errors
            )
            for _, field in ipairs({ "completed", "victories", "defeats" }) do
                if not isSafeInteger(state.stats[field], 0) then
                    appendError(errors, "invalid_stat", "$.state.stats." .. field, "누적 전적은 0 이상의 정수여야 합니다.")
                end
            end
            if isSafeInteger(state.stats.completed, 0)
                and isSafeInteger(state.stats.victories, 0)
                and isSafeInteger(state.stats.defeats, 0)
                and state.stats.completed ~= state.stats.victories + state.stats.defeats then
                appendError(errors, "stats_total_mismatch", "$.state.stats", "완료 세션 수가 승리와 패배 합계와 다릅니다.")
            end
        end

        local sessionCount = denseArrayLength(state.sessions, "$.state.sessions", errors)
        if sessionCount ~= nil and (sessionCount < 1 or sessionCount > MAX_SESSIONS) then
            appendError(errors, "invalid_session_count", "$.state.sessions", "정산 이력 개수가 올바르지 않습니다.")
        end
        if state.phase == "reward" then
            if state.rewardOffer == nil then
                appendError(errors, "missing_reward_offer", "$.state.rewardOffer", "reward phase에는 보상 제안이 필요합니다.")
            end
            if state.characterOffer ~= nil or state.battleSpec ~= nil then
                appendError(errors, "unexpected_phase_field", "$.state", "reward phase에는 다른 phase 자료를 넣을 수 없습니다.")
            end
        elseif state.phase == "characterSelect" then
            if state.characterOffer == nil then
                appendError(errors, "missing_character_offer", "$.state.characterOffer", "characterSelect phase에는 대상 후보가 필요합니다.")
            end
            if state.rewardOffer ~= nil or state.battleSpec ~= nil then
                appendError(errors, "unexpected_phase_field", "$.state", "characterSelect phase에는 다른 phase 자료를 넣을 수 없습니다.")
            end
        elseif state.phase == "battleReady" then
            if state.battleSpec == nil then
                appendError(errors, "missing_battle_spec", "$.state.battleSpec", "battleReady phase에는 다음 전투 사양이 필요합니다.")
            end
            if state.rewardOffer ~= nil or state.characterOffer ~= nil then
                appendError(errors, "unexpected_phase_field", "$.state", "battleReady phase에는 다른 phase 자료를 넣을 수 없습니다.")
            end
        end
        return errors
    end

    local function validateAndReplay(
        stateInput,
        setup,
        staticData,
        staticInput,
        playerPool,
        characterPool
    )
        local state, cloneError = cloneJson(stateInput, "$.state")
        if cloneError then
            return nil, { cloneError }
        end
        local shapeErrors = validateStateShape(state, setup.setupId)
        if #shapeErrors > 0 then
            return nil, shapeErrors
        end
        local expected, replayErrors = replaySessions(
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool,
            state.sessions
        )
        if replayErrors then
            return nil, replayErrors
        end
        if not deepEqual(state, expected) then
            return nil, {
                makeError(
                    "progression_state_replay_mismatch",
                    "$.state",
                    "저장된 runProgression 상태가 원본 setup과 선택 이력으로 재생한 canonical 상태와 다릅니다."
                ),
            }
        end
        return expected, nil
    end

    local function validateClaimCommand(commandInput)
        local command, cloneError = cloneJson(commandInput, "$.command")
        if cloneError then
            return nil, { cloneError }
        end
        local errors = {}
        if type(command) ~= "table" or getmetatable(command) ~= nil then
            appendError(errors, "invalid_command", "$.command", "보상 선택 명령은 일반 객체여야 합니다.")
            return nil, errors
        end
        checkAllowedKeys(
            command,
            { cardId = true, interactionToken = true },
            "$.command",
            errors
        )
        if not isAsciiId(command.cardId) then
            appendError(
                errors,
                "invalid_command_card",
                "$.command.cardId",
                "보상 선택에는 플레이어 cardId 또는 continue가 필요합니다."
            )
        end
        if type(command.interactionToken) ~= "string"
            or string.match(
                command.interactionToken,
                "^run%-progression%-reward%-v1:%d+:%d+:%d+$"
            ) == nil then
            appendError(errors, "invalid_command_token", "$.command.interactionToken", "보상 interactionToken 형식이 올바르지 않습니다.")
        end
        if #errors > 0 then
            return nil, errors
        end
        return command, nil
    end

    local function validateCharacterCommand(commandInput)
        local command, cloneError = cloneJson(commandInput, "$.command")
        if cloneError then
            return nil, { cloneError }
        end
        local errors = {}
        if type(command) ~= "table" or getmetatable(command) ~= nil then
            appendError(errors, "invalid_command", "$.command", "대상 선택 명령은 일반 객체여야 합니다.")
            return nil, errors
        end
        checkAllowedKeys(
            command,
            { characterId = true, interactionToken = true },
            "$.command",
            errors
        )
        if not isAsciiId(command.characterId) then
            appendError(errors, "invalid_command_character", "$.command.characterId", "대상 선택에는 characterId가 필요합니다.")
        end
        if type(command.interactionToken) ~= "string"
            or string.match(
                command.interactionToken,
                "^run%-progression%-character%-v1:%d+:%d+:%d+$"
            ) == nil then
            appendError(errors, "invalid_command_token", "$.command.interactionToken", "대상 interactionToken 형식이 올바르지 않습니다.")
        end
        if #errors > 0 then
            return nil, errors
        end
        return command, nil
    end

    local function settle(currentInput, setupInput, summaryInput, staticInput)
        local setup, staticData, playerPool, characterPool, setupErrors =
            validateSetup(setupInput, staticInput)
        if setupErrors then
            return failure(setupErrors)
        end
        local summary, summaryErrors = normalizeSummary(summaryInput, staticData, "$.summary")
        if summaryErrors then
            return failure(summaryErrors)
        end

        local sessions
        local current
        if currentInput == nil then
            local initialSpec, specErrors = buildInitialBattleSpec(setup, staticInput)
            if specErrors then
                return failure(specErrors)
            end
            local matchErrors = summaryMatchesSpec(summary, initialSpec, "$.summary")
            if #matchErrors > 0 then
                return failure(matchErrors)
            end
            sessions = {
                makeSessionRecord(summary),
            }
        else
            local currentErrors
            current, currentErrors = validateAndReplay(
                currentInput,
                setup,
                staticData,
                staticInput,
                playerPool,
                characterPool
            )
            if currentErrors then
                return failure(currentErrors)
            end
            if current.lastSettlement.battleId == summary.battleId
                and current.lastSettlement.turnId == summary.turnId then
                if not deepEqual(current.lastSettlement, summary) then
                    return failure({
                        makeError(
                            "settlement_receipt_conflict",
                            "$.summary",
                            "같은 battleId와 turnId의 정산 summary가 이미 저장된 내용과 다릅니다."
                        ),
                    })
                end
                return success(current, false, true)
            end
            if current.phase ~= "battleReady" then
                return failure({
                    makeError(
                        "different_settlement_while_pending",
                        "$.summary",
                        "현재 정산의 보상과 다음 대상 선택을 마치기 전에는 다른 전투를 정산할 수 없습니다."
                    ),
                })
            end
            local matchErrors = summaryMatchesSpec(summary, current.battleSpec, "$.summary")
            if #matchErrors > 0 then
                return failure(matchErrors)
            end
            sessions = {}
            for index, record in ipairs(current.sessions) do
                local recordCopy, recordError = cloneJson(record, "$.state.sessions[" .. index .. "]")
                if recordError then
                    return failure({ recordError })
                end
                sessions[index] = recordCopy
            end
            sessions[#sessions + 1] = makeSessionRecord(summary)
        end

        local nextState, replayErrors = replaySessions(
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool,
            sessions
        )
        if replayErrors then
            return failure(replayErrors)
        end
        return success(nextState, true, false)
    end

    local function claimReward(currentInput, setupInput, commandInput, staticInput)
        local command, commandErrors = validateClaimCommand(commandInput)
        if commandErrors then
            return failure(commandErrors)
        end
        local setup, staticData, playerPool, characterPool, setupErrors =
            validateSetup(setupInput, staticInput)
        if setupErrors then
            return failure(setupErrors)
        end
        local current, currentErrors = validateAndReplay(
            currentInput,
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool
        )
        if currentErrors then
            return failure(currentErrors)
        end
        if current.phase ~= "reward"
            or command.interactionToken ~= current.rewardOffer.interactionToken then
            return success(current, false, true)
        end

        local choice
        if command.cardId == "continue" then
            choice = {
                kind = "none",
            }
        else
            choice = {
                kind = "card",
            }
            choice.cardId = command.cardId
        end
        local _, applyErrors = applyRewardChoice(
            current.rewardOffer,
            choice,
            current.playerCardIds,
            playerPool,
            "$.command"
        )
        if applyErrors then
            return failure(applyErrors)
        end

        local sessions, sessionsError = cloneJson(current.sessions, "$.state.sessions")
        if sessionsError then
            return failure({ sessionsError })
        end
        sessions[#sessions].rewardChoice = choice
        local nextState, replayErrors = replaySessions(
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool,
            sessions
        )
        if replayErrors then
            return failure(replayErrors)
        end
        return success(nextState, true, false)
    end

    local function chooseCharacter(currentInput, setupInput, commandInput, staticInput)
        local command, commandErrors = validateCharacterCommand(commandInput)
        if commandErrors then
            return failure(commandErrors)
        end
        local setup, staticData, playerPool, characterPool, setupErrors =
            validateSetup(setupInput, staticInput)
        if setupErrors then
            return failure(setupErrors)
        end
        local current, currentErrors = validateAndReplay(
            currentInput,
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool
        )
        if currentErrors then
            return failure(currentErrors)
        end
        if current.phase ~= "characterSelect"
            or command.interactionToken ~= current.characterOffer.interactionToken then
            return success(current, false, true)
        end
        if not contains(current.characterOffer.characterIds, command.characterId) then
            return failure({
                makeError(
                    "character_not_in_offer",
                    "$.command.characterId",
                    "선택한 캐릭터가 현재 대상 후보에 없습니다."
                ),
            })
        end

        local sessions, sessionsError = cloneJson(current.sessions, "$.state.sessions")
        if sessionsError then
            return failure({ sessionsError })
        end
        sessions[#sessions].nextCharacterId = command.characterId
        local nextState, replayErrors = replaySessions(
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool,
            sessions
        )
        if replayErrors then
            return failure(replayErrors)
        end
        return success(nextState, true, false)
    end

    local function validateState(currentInput, setupInput, staticInput)
        local setup, staticData, playerPool, characterPool, setupErrors =
            validateSetup(setupInput, staticInput)
        if setupErrors then
            return failure(setupErrors)
        end
        if currentInput == nil then
            return failure({
                makeError("missing_progression_state", "$.state", "검증할 runProgression 상태가 필요합니다."),
            })
        end
        local current, currentErrors = validateAndReplay(
            currentInput,
            setup,
            staticData,
            staticInput,
            playerPool,
            characterPool
        )
        if currentErrors then
            return failure(currentErrors)
        end
        return success(current, false, false)
    end

    local arguments = { ... }
    if action == "settle" then
        return settle(arguments[1], arguments[2], arguments[3], arguments[4])
    elseif action == "claimReward" then
        return claimReward(arguments[1], arguments[2], arguments[3], arguments[4])
    elseif action == "chooseCharacter" then
        return chooseCharacter(arguments[1], arguments[2], arguments[3], arguments[4])
    elseif action == "validate" then
        return validateState(arguments[1], arguments[2], arguments[3])
    end
    return failure({
        makeError(
            "unknown_action",
            "$.action",
            "지원하지 않는 runProgression 작업입니다: " .. tostring(action)
        ),
    })
end)

]],
    [[[
runProgressionView
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local VIEW_KIND = "runProgressionView"
    local STATE_KIND = "runProgressionV1"
    local SETUP_KIND = "gameSetupV1"
    local DECK_MIN = 10
    local DECK_MAX = 20
    local CARD_COPY_LIMIT = 2
    local CHARACTER_OFFER_SIZE = 3
    local REWARD_OFFER_MAX = 3

    local VALID_PHASES = {
        reward = true,
        characterSelect = true,
        battleReady = true,
    }

    local VALID_OUTCOMES = {
        victory = true,
        defeat = true,
    }

    local REASON_LABELS = {
        card_checkpoint = "카드 해결 중 승패 확정",
        turn_end_checkpoint = "턴 종료 판정",
        turn_limit = "제한 구간 도착",
    }

    local function addError(errors, code, path, message)
        errors[#errors + 1] = {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(key, value)
        local result = {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
        }
        if key ~= nil then
            result[key] = value
        end
        return result
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum, maximum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
            and (maximum == nil or value <= maximum)
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function isInteractionToken(value)
        return type(value) == "string"
            and value ~= ""
            and #value <= 512
            and string.find(value, "[%z\1-\31\127]") == nil
    end

    local function objectPath(path, key)
        if type(key) == "string"
            and string.match(key, "^[A-Za-z_][A-Za-z0-9_]*$") then
            return path .. "." .. key
        end
        return path .. "[" .. string.format("%q", tostring(key)) .. "]"
    end

    local function inspectTable(value, path, errors)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            addError(errors, "expected_plain_table", path, "메타테이블이 없는 테이블이어야 합니다.")
            return nil
        end

        local numericCount = 0
        local maximum = 0
        local hasNumeric = false
        local hasString = false
        local stringKeys = {}
        for key in pairs(value) do
            if type(key) == "number" then
                hasNumeric = true
                numericCount = numericCount + 1
                if not isInteger(key, 1) then
                    addError(errors, "invalid_array_index", path, "배열 인덱스는 1 이상의 정수여야 합니다.")
                    return nil
                end
                if key > maximum then maximum = key end
            elseif type(key) == "string" then
                hasString = true
                stringKeys[#stringKeys + 1] = key
            else
                addError(errors, "invalid_object_key", path, "객체 키는 문자열이어야 합니다.")
                return nil
            end
        end

        if hasNumeric and hasString then
            addError(errors, "mixed_table", path, "배열 인덱스와 객체 키를 함께 사용할 수 없습니다.")
            return nil
        end
        if hasNumeric then
            if numericCount ~= maximum then
                addError(errors, "sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다.")
                return nil
            end
            return "array", maximum
        end
        if hasString then
            table.sort(stringKeys)
            return "object", stringKeys
        end
        return "array", 0
    end

    local function getArrayLength(value, path, errors)
        local kind, length = inspectTable(value, path, errors)
        if kind ~= "array" then
            if kind ~= nil then
                addError(errors, "expected_array", path, "1부터 이어지는 연속 배열이어야 합니다.")
            end
            return nil
        end
        return length
    end

    local function validateJsonSafe(value, path, errors, active)
        local valueType = type(value)
        if valueType == "string" or valueType == "boolean" then return end
        if valueType == "number" then
            if not isFinite(value) then
                addError(errors, "non_finite_number", path, "NaN과 무한대는 View에 넣을 수 없습니다.")
            end
            return
        end
        if valueType ~= "table" then
            addError(errors, "unsupported_type", path, "View에 넣을 수 없는 자료형입니다: " .. valueType)
            return
        end
        if getmetatable(value) ~= nil then
            addError(errors, "metatable_not_allowed", path, "View에는 메타테이블을 사용할 수 없습니다.")
            return
        end

        active = active or {}
        if active[value] then
            addError(errors, "circular_reference", path, "순환 참조가 있는 값은 사용할 수 없습니다.")
            return
        end
        active[value] = true
        local kind, shape = inspectTable(value, path, errors)
        if kind == "array" then
            for index = 1, shape do
                validateJsonSafe(value[index], path .. "[" .. index .. "]", errors, active)
            end
        elseif kind == "object" then
            for _, key in ipairs(shape) do
                validateJsonSafe(value[key], objectPath(path, key), errors, active)
            end
        end
        active[value] = nil
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" then return end
        for key in pairs(value) do
            if type(key) ~= "string" or allowed[key] ~= true then
                addError(errors, "unknown_field", objectPath(path, key), "허용 목록에 없는 필드입니다.")
            end
        end
    end

    local function cloneJson(value, path, active)
        if type(value) ~= "table" then return value, nil end
        if getmetatable(value) ~= nil then
            return nil, {
                code = "metatable_not_allowed",
                path = path,
                message = "복제할 값에는 메타테이블을 사용할 수 없습니다.",
            }
        end
        active = active or {}
        if active[value] then
            return nil, {
                code = "circular_reference",
                path = path,
                message = "순환 참조가 있는 값을 복제할 수 없습니다.",
            }
        end
        active[value] = true
        local copy = {}
        for key, item in pairs(value) do
            local itemCopy, itemError = cloneJson(item, objectPath(path, key), active)
            if itemError then
                active[value] = nil
                return nil, itemError
            end
            copy[key] = itemCopy
        end
        active[value] = nil
        return copy, nil
    end

    local function deepEqual(left, right, active)
        if type(left) ~= type(right) then return false end
        if type(left) ~= "table" then return left == right end
        if getmetatable(left) ~= nil or getmetatable(right) ~= nil then return false end
        active = active or {}
        if active[left] ~= nil then return active[left] == right end
        active[left] = right
        for key, value in pairs(left) do
            if not deepEqual(value, right[key], active) then
                active[left] = nil
                return false
            end
        end
        for key in pairs(right) do
            if left[key] == nil then
                active[left] = nil
                return false
            end
        end
        active[left] = nil
        return true
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table"
            and getmetatable(staticData) == nil
            and type(rawget(staticData, "data")) == "table" then
            return rawget(staticData, "data")
        end
        return staticData
    end

    local function appendNestedErrors(target, prefix, report)
        if type(report) ~= "table" or type(report.errors) ~= "table" then
            addError(target, "validation_failed", prefix, "하위 검증 결과를 읽을 수 없습니다.")
            return
        end
        local appended = false
        for _, item in ipairs(report.errors) do
            appended = true
            local suffix = tostring(type(item) == "table" and item.path or "$")
            if string.sub(suffix, 1, 1) == "$" then
                suffix = string.sub(suffix, 2)
            else
                suffix = "." .. suffix
            end
            addError(
                target,
                tostring(type(item) == "table" and item.code or "validation_failed"),
                prefix .. suffix,
                tostring(type(item) == "table" and item.message or "하위 검증에 실패했습니다.")
            )
        end
        if not appended then
            addError(target, "validation_failed", prefix, "하위 검증이 상세 오류 없이 실패했습니다.")
        end
    end

    local function callRuntime(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                code = "runtime_unavailable",
                path = "$.runtime." .. moduleName,
                message = "runScript 실행기를 찾을 수 없습니다.",
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                code = "runtime_call_error",
                path = "$.runtime." .. moduleName,
                message = moduleName .. "." .. moduleAction .. " 실행에 실패했습니다: " .. tostring(report),
            }
        end
        if type(report) ~= "table" or getmetatable(report) ~= nil then
            return nil, {
                code = "invalid_runtime_result",
                path = "$.runtime." .. moduleName,
                message = "하위 모듈이 일반 테이블 결과를 반환하지 않았습니다.",
            }
        end
        return report, nil
    end

    local function validateIdArray(value, path, errors, minimum, maximum, allowDuplicates)
        local length = getArrayLength(value, path, errors)
        if length == nil then return nil end
        if minimum ~= nil and length < minimum then
            addError(errors, "array_too_short", path, "항목 수가 최소값보다 작습니다.")
        end
        if maximum ~= nil and length > maximum then
            addError(errors, "array_too_long", path, "항목 수가 최대값보다 큽니다.")
        end
        local seen = {}
        for index = 1, length do
            local id = value[index]
            if not isAsciiId(id) then
                addError(errors, "invalid_id", path .. "[" .. index .. "]", "lower_snake_case ASCII ID여야 합니다.")
            elseif seen[id] and allowDuplicates ~= true then
                addError(errors, "duplicate_id", path .. "[" .. index .. "]", "같은 ID를 중복할 수 없습니다.")
            else
                seen[id] = true
            end
        end
        return length
    end

    local function validateTransit(transit, path, staticData, turnLimit, errors)
        if type(transit) ~= "table" or getmetatable(transit) ~= nil then
            addError(errors, "invalid_transit", path, "이동 구간은 일반 테이블이어야 합니다.")
            return
        end
        checkAllowedKeys(transit, {
            algorithm = true,
            lineId = true,
            stationIds = true,
        }, path, errors)
        if transit.algorithm ~= "tokyo_subway_segment_v1" then
            addError(errors, "invalid_transit_algorithm", path .. ".algorithm", "지원하지 않는 이동 구간 알고리즘입니다.")
        end
        if not isAsciiId(transit.lineId) then
            addError(errors, "invalid_line_id", path .. ".lineId", "노선 ID가 올바르지 않습니다.")
        end
        local stationCount = validateIdArray(
            transit.stationIds,
            path .. ".stationIds",
            errors,
            2,
            nil,
            true
        )
        if stationCount ~= nil
            and isInteger(turnLimit, 1)
            and stationCount ~= turnLimit + 1 then
            addError(errors, "transit_length_mismatch", path .. ".stationIds", "역 수는 제한 턴보다 하나 많아야 합니다.")
        end

        local line = type(staticData) == "table"
            and type(staticData.subwayLines) == "table"
            and staticData.subwayLines[transit.lineId]
            or nil
        if type(line) ~= "table" then
            addError(errors, "unknown_line", path .. ".lineId", "정적 데이터에서 노선을 찾을 수 없습니다.")
            return
        end

        local knownStations = {}
        local adjacency = {}
        for _, routePath in ipairs(type(line.paths) == "table" and line.paths or {}) do
            local stations = type(routePath) == "table" and routePath.stations or {}
            for index, station in ipairs(stations) do
                if type(station) == "table" and isAsciiId(station.id) then
                    knownStations[station.id] = true
                    adjacency[station.id] = adjacency[station.id] or {}
                    local nextStation = stations[index + 1]
                    if type(nextStation) == "table" and isAsciiId(nextStation.id) then
                        adjacency[station.id][nextStation.id] = true
                        adjacency[nextStation.id] = adjacency[nextStation.id] or {}
                        adjacency[nextStation.id][station.id] = true
                    end
                end
            end
            if type(routePath) == "table"
                and routePath.circular == true
                and #stations > 1 then
                local first = stations[1]
                local last = stations[#stations]
                if type(first) == "table" and type(last) == "table" then
                    adjacency[first.id] = adjacency[first.id] or {}
                    adjacency[last.id] = adjacency[last.id] or {}
                    adjacency[first.id][last.id] = true
                    adjacency[last.id][first.id] = true
                end
            end
        end
        if stationCount ~= nil then
            for index = 1, stationCount do
                local stationId = transit.stationIds[index]
                if isAsciiId(stationId) and not knownStations[stationId] then
                    addError(errors, "unknown_station", path .. ".stationIds[" .. index .. "]", "선택 노선에서 역을 찾을 수 없습니다.")
                end
                if index > 1 then
                    local previousId = transit.stationIds[index - 1]
                    if isAsciiId(previousId)
                        and isAsciiId(stationId)
                        and not (adjacency[previousId] and adjacency[previousId][stationId]) then
                        addError(errors, "non_adjacent_station", path .. ".stationIds[" .. index .. "]", "서로 인접하지 않은 역이 이동 구간에 있습니다.")
                    end
                end
            end
        end
    end

    local function validateSettlement(settlement, path, staticData, errors)
        if type(settlement) ~= "table" or getmetatable(settlement) ~= nil then
            addError(errors, "invalid_settlement", path, "세션 정산은 일반 테이블이어야 합니다.")
            return
        end
        checkAllowedKeys(settlement, {
            battleId = true,
            turnId = true,
            characterId = true,
            status = true,
            reasonCode = true,
            turnNumber = true,
            turnLimit = true,
            finalStealth = true,
            finalResistance = true,
            environmentId = true,
            transit = true,
        }, path, errors)
        if not isRuntimeId(settlement.battleId) then
            addError(errors, "invalid_battle_id", path .. ".battleId", "battleId가 올바르지 않습니다.")
        end
        if not isRuntimeId(settlement.turnId) then
            addError(errors, "invalid_turn_id", path .. ".turnId", "turnId가 올바르지 않습니다.")
        end
        if not isAsciiId(settlement.characterId)
            or type(staticData.characters[settlement.characterId]) ~= "table" then
            addError(errors, "unknown_character", path .. ".characterId", "정적 데이터에서 상대를 찾을 수 없습니다.")
        end
        if VALID_OUTCOMES[settlement.status] ~= true then
            addError(errors, "invalid_outcome", path .. ".status", "세션 결과는 victory 또는 defeat여야 합니다.")
        end
        if REASON_LABELS[settlement.reasonCode] == nil then
            addError(errors, "invalid_reason_code", path .. ".reasonCode", "지원하지 않는 세션 종료 사유입니다.")
        elseif settlement.reasonCode == "turn_limit" and settlement.status ~= "defeat" then
            addError(errors, "turn_limit_outcome_mismatch", path, "제한 턴 종료는 패배여야 합니다.")
        end
        if not isInteger(settlement.turnNumber, 1) then
            addError(errors, "invalid_turn_number", path .. ".turnNumber", "종료 턴은 1 이상의 정수여야 합니다.")
        end
        if not isInteger(settlement.turnLimit, 1) then
            addError(errors, "invalid_turn_limit", path .. ".turnLimit", "제한 턴은 1 이상의 정수여야 합니다.")
        elseif isInteger(settlement.turnNumber, 1)
            and settlement.turnNumber > settlement.turnLimit then
            addError(errors, "turn_number_exceeds_limit", path .. ".turnNumber", "종료 턴은 제한 턴을 넘을 수 없습니다.")
        end
        if not isFinite(settlement.finalStealth) then
            addError(errors, "invalid_final_stealth", path .. ".finalStealth", "최종 은폐는 유한한 숫자여야 합니다.")
        end
        if not isFinite(settlement.finalResistance) then
            addError(errors, "invalid_final_resistance", path .. ".finalResistance", "최종 저항은 유한한 숫자여야 합니다.")
        end
        if not isAsciiId(settlement.environmentId)
            or type(staticData.environments[settlement.environmentId]) ~= "table" then
            addError(errors, "unknown_environment", path .. ".environmentId", "정적 데이터에서 환경을 찾을 수 없습니다.")
        end
        validateTransit(settlement.transit, path .. ".transit", staticData, settlement.turnLimit, errors)
    end

    local function validateRewardChoice(choice, path, staticData, errors)
        if type(choice) ~= "table" or getmetatable(choice) ~= nil then
            addError(errors, "invalid_reward_choice", path, "보상 선택 영수증은 일반 테이블이어야 합니다.")
            return
        end
        if choice.kind == "card" then
            checkAllowedKeys(choice, { kind = true, cardId = true }, path, errors)
            if not isAsciiId(choice.cardId)
                or type(staticData.cards[choice.cardId]) ~= "table"
                or staticData.cards[choice.cardId].owner ~= "player" then
                addError(errors, "unknown_reward_card", path .. ".cardId", "선택한 플레이어 보상 카드를 찾을 수 없습니다.")
            end
        elseif choice.kind == "none" then
            checkAllowedKeys(choice, { kind = true }, path, errors)
        else
            addError(errors, "invalid_reward_kind", path .. ".kind", "보상 종류는 card 또는 none이어야 합니다.")
        end
    end

    local SETTLEMENT_FIELDS = {
        "battleId",
        "turnId",
        "characterId",
        "status",
        "reasonCode",
        "turnNumber",
        "turnLimit",
        "finalStealth",
        "finalResistance",
        "environmentId",
        "transit",
    }

    local function settlementFromSession(receipt)
        local settlement = {}
        for _, field in ipairs(SETTLEMENT_FIELDS) do
            settlement[field] = receipt[field]
        end
        return settlement
    end

    local function validateSessionReceipt(receipt, path, staticData, errors)
        if type(receipt) ~= "table" or getmetatable(receipt) ~= nil then
            addError(errors, "invalid_session_receipt", path, "세션 영수증은 일반 테이블이어야 합니다.")
            return
        end
        checkAllowedKeys(receipt, {
            battleId = true,
            turnId = true,
            characterId = true,
            status = true,
            reasonCode = true,
            turnNumber = true,
            turnLimit = true,
            finalStealth = true,
            finalResistance = true,
            environmentId = true,
            transit = true,
            rewardChoice = true,
            nextCharacterId = true,
        }, path, errors)
        validateSettlement(settlementFromSession(receipt), path, staticData, errors)
        if receipt.rewardChoice ~= nil then
            validateRewardChoice(receipt.rewardChoice, path .. ".rewardChoice", staticData, errors)
        end
        if receipt.nextCharacterId ~= nil
            and (not isAsciiId(receipt.nextCharacterId)
                or type(staticData.characters[receipt.nextCharacterId]) ~= "table") then
            addError(errors, "unknown_next_character", path .. ".nextCharacterId", "다음 상대를 정적 데이터에서 찾을 수 없습니다.")
        end
        if receipt.nextCharacterId ~= nil and receipt.rewardChoice == nil then
            addError(errors, "next_character_before_reward", path, "보상을 확정하기 전에 다음 상대를 기록할 수 없습니다.")
        end
    end

    local function validateRewardOffer(offer, path, cardCopies, deckCount, staticData, errors)
        if type(offer) ~= "table" or getmetatable(offer) ~= nil then
            addError(errors, "invalid_reward_offer", path, "보상 제안은 일반 테이블이어야 합니다.")
            return
        end
        if offer.kind == "card" then
            checkAllowedKeys(offer, {
                kind = true,
                cardIds = true,
                interactionToken = true,
            }, path, errors)
            local length = validateIdArray(
                offer.cardIds,
                path .. ".cardIds",
                errors,
                1,
                REWARD_OFFER_MAX
            )
            if length ~= nil then
                if deckCount >= DECK_MAX then
                    addError(errors, "reward_card_at_deck_limit", path, "덱 한도에서는 새 카드 보상을 제안할 수 없습니다.")
                end
                for index = 1, length do
                    local cardId = offer.cardIds[index]
                    local card = staticData.cards[cardId]
                    if type(card) ~= "table" or card.owner ~= "player" then
                        addError(errors, "unknown_reward_card", path .. ".cardIds[" .. index .. "]", "플레이어 보상 카드를 찾을 수 없습니다.")
                    elseif (cardCopies[cardId] or 0) >= CARD_COPY_LIMIT then
                        addError(errors, "reward_copy_limit", path .. ".cardIds[" .. index .. "]", "이미 두 장 보유한 카드는 보상으로 제안할 수 없습니다.")
                    end
                end
            end
        elseif offer.kind == "none" then
            checkAllowedKeys(offer, {
                kind = true,
                interactionToken = true,
            }, path, errors)
        else
            addError(errors, "invalid_reward_kind", path .. ".kind", "보상 제안 종류는 card 또는 none이어야 합니다.")
        end
        if not isInteractionToken(offer.interactionToken) then
            addError(errors, "invalid_interaction_token", path .. ".interactionToken", "보상 상호작용 토큰이 올바르지 않습니다.")
        end
    end

    local function validateCharacterOffer(offer, path, staticData, errors)
        if type(offer) ~= "table" or getmetatable(offer) ~= nil then
            addError(errors, "invalid_character_offer", path, "캐릭터 제안은 일반 테이블이어야 합니다.")
            return
        end
        checkAllowedKeys(offer, {
            characterIds = true,
            interactionToken = true,
        }, path, errors)
        local length = validateIdArray(
            offer.characterIds,
            path .. ".characterIds",
            errors,
            CHARACTER_OFFER_SIZE,
            CHARACTER_OFFER_SIZE
        )
        if length ~= nil then
            for index = 1, length do
                local characterId = offer.characterIds[index]
                if type(staticData.characters[characterId]) ~= "table" then
                    addError(errors, "unknown_character", path .. ".characterIds[" .. index .. "]", "제안 캐릭터를 찾을 수 없습니다.")
                end
            end
        end
        if not isInteractionToken(offer.interactionToken) then
            addError(errors, "invalid_interaction_token", path .. ".interactionToken", "캐릭터 상호작용 토큰이 올바르지 않습니다.")
        end
    end

    local function validateBattleSpec(spec, path, playerCardIds, perkIds, staticData, errors)
        if type(spec) ~= "table" or getmetatable(spec) ~= nil then
            addError(errors, "invalid_battle_spec", path, "다음 전투 사양은 일반 테이블이어야 합니다.")
            return
        end
        checkAllowedKeys(spec, {
            battleId = true,
            seed = true,
            characterId = true,
            playerCardIds = true,
            perkIds = true,
            environmentId = true,
            turnLimit = true,
            lineId = true,
            stationIds = true,
        }, path, errors)
        if not isRuntimeId(spec.battleId) then
            addError(errors, "invalid_battle_id", path .. ".battleId", "다음 battleId가 올바르지 않습니다.")
        end
        if not isInteger(spec.seed, 1, 2147483646) then
            addError(errors, "invalid_battle_seed", path .. ".seed", "전투 seed가 허용 범위를 벗어났습니다.")
        end
        if not isAsciiId(spec.characterId)
            or type(staticData.characters[spec.characterId]) ~= "table" then
            addError(errors, "unknown_character", path .. ".characterId", "다음 상대를 찾을 수 없습니다.")
        end
        if not deepEqual(spec.playerCardIds, playerCardIds) then
            addError(errors, "battle_deck_mismatch", path .. ".playerCardIds", "전투 사양의 덱이 진행 상태 덱과 다릅니다.")
        end
        if not deepEqual(spec.perkIds, perkIds) then
            addError(errors, "battle_perk_mismatch", path .. ".perkIds", "전투 사양의 퍽이 진행 상태와 다릅니다.")
        end
        if not isAsciiId(spec.environmentId)
            or type(staticData.environments[spec.environmentId]) ~= "table" then
            addError(errors, "unknown_environment", path .. ".environmentId", "다음 전투 환경을 찾을 수 없습니다.")
        end
        if not isAsciiId(spec.lineId)
            or type(staticData.subwayLines[spec.lineId]) ~= "table" then
            addError(errors, "unknown_line", path .. ".lineId", "다음 전투 노선을 찾을 수 없습니다.")
        end
        if not isInteger(spec.turnLimit, 1) then
            addError(errors, "invalid_turn_limit", path .. ".turnLimit", "다음 전투 제한 턴이 올바르지 않습니다.")
        end
        local stationCount = validateIdArray(
            spec.stationIds,
            path .. ".stationIds",
            errors,
            2,
            nil,
            true
        )
        if stationCount ~= nil and isInteger(spec.turnLimit, 1) then
            if stationCount ~= spec.turnLimit + 1 then
                addError(errors, "transit_length_mismatch", path .. ".stationIds", "다음 전투 역 수는 제한 턴보다 하나 많아야 합니다.")
            end
            local transit = {
                algorithm = "tokyo_subway_segment_v1",
                lineId = spec.lineId,
                stationIds = spec.stationIds,
            }
            validateTransit(transit, path, staticData, spec.turnLimit, errors)
        end
    end

    local function validateCanonicalInputs(runState, setupState, staticInput)
        local errors = {}
        validateJsonSafe(runState, "$.runState", errors)
        validateJsonSafe(setupState, "$.setupState", errors)
        local staticData = normalizeStaticData(staticInput)
        if type(staticData) ~= "table"
            or getmetatable(staticData) ~= nil
            or type(staticData.registry) ~= "table"
            or type(staticData.registry.actionTags) ~= "table"
            or type(staticData.registry.mechanisms) ~= "table"
            or type(staticData.registry.moods) ~= "table"
            or type(staticData.cards) ~= "table"
            or type(staticData.traits) ~= "table"
            or type(staticData.environments) ~= "table"
            or type(staticData.subwayLines) ~= "table"
            or type(staticData.characters) ~= "table" then
            addError(errors, "missing_static_data", "$.staticData", "검증된 전체 정적 데이터가 필요합니다.")
            return nil, errors
        end
        if #errors > 0 then return nil, errors end

        if type(setupState) ~= "table" or getmetatable(setupState) ~= nil then
            addError(errors, "invalid_setup_state", "$.setupState", "gameSetupV1 상태가 필요합니다.")
        else
            if setupState.schemaVersion ~= SCHEMA_VERSION then
                addError(errors, "unsupported_setup_schema", "$.setupState.schemaVersion", "지원하지 않는 gameSetup 스키마입니다.")
            end
            if setupState.kind ~= SETUP_KIND then
                addError(errors, "invalid_setup_kind", "$.setupState.kind", "gameSetupV1 상태가 아닙니다.")
            end
            if not isRuntimeId(setupState.setupId) then
                addError(errors, "invalid_setup_id", "$.setupState.setupId", "setupId가 올바르지 않습니다.")
            end
            if setupState.phase ~= "battleReady" then
                addError(errors, "setup_not_battle_ready", "$.setupState.phase", "완료된 초기 설정 상태가 필요합니다.")
            end
        end

        if type(runState) ~= "table" or getmetatable(runState) ~= nil then
            addError(errors, "invalid_run_state", "$.runState", "runProgressionV1 상태가 필요합니다.")
            return nil, errors
        end
        checkAllowedKeys(runState, {
            schemaVersion = true,
            kind = true,
            setupId = true,
            phase = true,
            sessionNumber = true,
            rng = true,
            playerCardIds = true,
            perkIds = true,
            stats = true,
            sessions = true,
            lastSettlement = true,
            rewardOffer = true,
            characterOffer = true,
            battleSpec = true,
        }, "$.runState", errors)
        if runState.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_run_schema", "$.runState.schemaVersion", "지원하지 않는 진행 상태 스키마입니다.")
        end
        if runState.kind ~= STATE_KIND then
            addError(errors, "invalid_run_kind", "$.runState.kind", "runProgressionV1 상태가 아닙니다.")
        end
        if not isRuntimeId(runState.setupId)
            or (type(setupState) == "table" and runState.setupId ~= setupState.setupId) then
            addError(errors, "run_setup_mismatch", "$.runState.setupId", "진행 상태와 초기 설정의 setupId가 다릅니다.")
        end
        if VALID_PHASES[runState.phase] ~= true then
            addError(errors, "invalid_run_phase", "$.runState.phase", "지원하지 않는 진행 상태 phase입니다.")
        end
        if not isInteger(runState.sessionNumber, 1) then
            addError(errors, "invalid_session_number", "$.runState.sessionNumber", "세션 번호는 1 이상의 정수여야 합니다.")
        end
        if type(runState.rng) ~= "table" or getmetatable(runState.rng) ~= nil then
            addError(errors, "invalid_rng", "$.runState.rng", "진행 RNG가 일반 테이블이 아닙니다.")
        else
            checkAllowedKeys(runState.rng, { seed = true, cursor = true }, "$.runState.rng", errors)
            if not isInteger(runState.rng.seed, 0) then
                addError(errors, "invalid_rng_seed", "$.runState.rng.seed", "진행 RNG seed가 올바르지 않습니다.")
            end
            if not isInteger(runState.rng.cursor, 0) then
                addError(errors, "invalid_rng_cursor", "$.runState.rng.cursor", "진행 RNG cursor가 올바르지 않습니다.")
            end
        end

        local deckCount = getArrayLength(runState.playerCardIds, "$.runState.playerCardIds", errors)
        local cardCopies = {}
        if deckCount ~= nil then
            if deckCount < DECK_MIN or deckCount > DECK_MAX then
                addError(errors, "invalid_deck_size", "$.runState.playerCardIds", "덱은 10장 이상 20장 이하여야 합니다.")
            end
            for index = 1, deckCount do
                local cardId = runState.playerCardIds[index]
                local card = staticData.cards[cardId]
                if not isAsciiId(cardId)
                    or type(card) ~= "table"
                    or card.owner ~= "player" then
                    addError(errors, "unknown_player_card", "$.runState.playerCardIds[" .. index .. "]", "플레이어 카드를 찾을 수 없습니다.")
                else
                    cardCopies[cardId] = (cardCopies[cardId] or 0) + 1
                    if cardCopies[cardId] > CARD_COPY_LIMIT then
                        addError(errors, "card_copy_limit", "$.runState.playerCardIds[" .. index .. "]", "같은 카드는 최대 두 장까지 보유할 수 있습니다.")
                    end
                end
            end
        end

        local perkCount = getArrayLength(runState.perkIds, "$.runState.perkIds", errors)
        if perkCount ~= nil then
            if perkCount ~= 0 then
                addError(errors, "unsupported_perks", "$.runState.perkIds", "현재 진행 버전의 perkIds는 빈 배열이어야 합니다.")
            end
        end

        if type(runState.stats) ~= "table" or getmetatable(runState.stats) ~= nil then
            addError(errors, "invalid_stats", "$.runState.stats", "누적 전적이 일반 테이블이 아닙니다.")
        else
            checkAllowedKeys(runState.stats, {
                completed = true,
                victories = true,
                defeats = true,
            }, "$.runState.stats", errors)
            for _, field in ipairs({ "completed", "victories", "defeats" }) do
                if not isInteger(runState.stats[field], 0) then
                    addError(errors, "invalid_stat", "$.runState.stats." .. field, "누적 전적은 0 이상의 정수여야 합니다.")
                end
            end
            if isInteger(runState.stats.completed, 0)
                and isInteger(runState.stats.victories, 0)
                and isInteger(runState.stats.defeats, 0)
                and runState.stats.completed ~= runState.stats.victories + runState.stats.defeats then
                addError(errors, "stats_total_mismatch", "$.runState.stats", "완료 세션 수가 승리와 패배의 합과 다릅니다.")
            end
        end

        local sessionCount = getArrayLength(runState.sessions, "$.runState.sessions", errors)
        if sessionCount ~= nil then
            if sessionCount < 1 or sessionCount > 999 then
                addError(errors, "invalid_session_count", "$.runState.sessions", "세션 기록은 1개 이상 999개 이하여야 합니다.")
            end
            if type(runState.stats) == "table"
                and isInteger(runState.stats.completed, 0)
                and sessionCount ~= runState.stats.completed then
                addError(errors, "session_count_mismatch", "$.runState.sessions", "세션 영수증 수와 완료 전적이 다릅니다.")
            end
            local victories = 0
            local defeats = 0
            for index = 1, sessionCount do
                local receipt = runState.sessions[index]
                local receiptPath = "$.runState.sessions[" .. index .. "]"
                validateSessionReceipt(receipt, receiptPath, staticData, errors)
                if type(receipt) == "table" then
                    if receipt.status == "victory" then victories = victories + 1 end
                    if receipt.status == "defeat" then defeats = defeats + 1 end
                    if index < sessionCount then
                        if receipt.rewardChoice == nil or receipt.nextCharacterId == nil then
                            addError(errors, "incomplete_historical_session", receiptPath, "이전 세션에는 보상과 다음 상대 선택이 모두 기록되어야 합니다.")
                        end
                    elseif runState.phase == "reward" then
                        if receipt.rewardChoice ~= nil or receipt.nextCharacterId ~= nil then
                            addError(errors, "phase_receipt_mismatch", receiptPath, "보상 단계의 최근 세션에는 아직 선택 기록이 없어야 합니다.")
                        end
                    elseif runState.phase == "characterSelect" then
                        if receipt.rewardChoice == nil or receipt.nextCharacterId ~= nil then
                            addError(errors, "phase_receipt_mismatch", receiptPath, "상대 선택 단계에는 보상 기록만 있어야 합니다.")
                        end
                    elseif runState.phase == "battleReady"
                        and (receipt.rewardChoice == nil or receipt.nextCharacterId == nil) then
                        addError(errors, "phase_receipt_mismatch", receiptPath, "전투 준비 단계에는 보상과 다음 상대 선택이 기록되어야 합니다.")
                    end
                end
            end
            if type(runState.stats) == "table" then
                if isInteger(runState.stats.victories, 0) and victories ~= runState.stats.victories then
                    addError(errors, "victory_count_mismatch", "$.runState.stats.victories", "영수증에서 계산한 승리 수와 다릅니다.")
                end
                if isInteger(runState.stats.defeats, 0) and defeats ~= runState.stats.defeats then
                    addError(errors, "defeat_count_mismatch", "$.runState.stats.defeats", "영수증에서 계산한 패배 수와 다릅니다.")
                end
            end
        end

        validateSettlement(runState.lastSettlement, "$.runState.lastSettlement", staticData, errors)
        if sessionCount ~= nil and sessionCount > 0
            and type(runState.sessions[sessionCount]) == "table"
            and not deepEqual(
                runState.lastSettlement,
                settlementFromSession(runState.sessions[sessionCount])
            ) then
            addError(errors, "last_settlement_mismatch", "$.runState.lastSettlement", "최근 정산이 마지막 세션 영수증과 다릅니다.")
        end
        if sessionCount ~= nil and VALID_PHASES[runState.phase] == true then
            local expectedSessionNumber = runState.phase == "battleReady"
                and sessionCount + 1
                or sessionCount
            if runState.sessionNumber ~= expectedSessionNumber then
                addError(
                    errors,
                    "session_number_mismatch",
                    "$.runState.sessionNumber",
                    "현재 단계의 세션 번호가 정산 기록 수와 다릅니다."
                )
            end
        end

        if runState.phase == "reward" then
            validateRewardOffer(
                runState.rewardOffer,
                "$.runState.rewardOffer",
                cardCopies,
                deckCount or 0,
                staticData,
                errors
            )
            if runState.characterOffer ~= nil
                or runState.battleSpec ~= nil then
                addError(errors, "unexpected_phase_field", "$.runState", "보상 단계에 다음 상대 또는 전투 사양을 둘 수 없습니다.")
            end
        elseif runState.phase == "characterSelect" then
            validateCharacterOffer(
                runState.characterOffer,
                "$.runState.characterOffer",
                staticData,
                errors
            )
            if runState.rewardOffer ~= nil
                or runState.battleSpec ~= nil then
                addError(errors, "unexpected_phase_field", "$.runState", "상대 선택 단계에 보상 제안 또는 전투 사양을 둘 수 없습니다.")
            end
        elseif runState.phase == "battleReady" then
            if runState.rewardOffer ~= nil or runState.characterOffer ~= nil then
                addError(errors, "unexpected_phase_field", "$.runState", "전투 준비 단계에 제안을 둘 수 없습니다.")
            end
            validateBattleSpec(
                runState.battleSpec,
                "$.runState.battleSpec",
                runState.playerCardIds,
                runState.perkIds,
                staticData,
                errors
            )
            local selectedCharacterId = type(runState.battleSpec) == "table"
                and runState.battleSpec.characterId
                or nil
            if not isAsciiId(selectedCharacterId)
                or type(staticData.characters[selectedCharacterId]) ~= "table" then
                addError(errors, "unknown_selected_character", "$.runState.battleSpec.characterId", "선택한 다음 상대를 찾을 수 없습니다.")
            end
        end

        if #errors > 0 then return nil, errors end
        return staticData, nil
    end

    local function lookupStation(line, stationId)
        for _, routePath in ipairs(type(line) == "table" and line.paths or {}) do
            for _, station in ipairs(type(routePath) == "table" and routePath.stations or {}) do
                if type(station) == "table" and station.id == stationId then
                    return station
                end
            end
        end
        return nil
    end

    local function stationView(station)
        return {
            id = station.id,
            code = station.code,
            name = station.name,
        }
    end

    local function buildRouteView(settlement, staticData, errors)
        local transit = settlement.transit
        local line = staticData.subwayLines[transit.lineId]
        if type(line) ~= "table" then
            addError(errors, "unknown_line", "$.result.route", "정산 노선을 찾을 수 없습니다.")
            return nil
        end
        local ids = transit.stationIds
        local reachedIndex = math.min(#ids, settlement.turnNumber + 1)
        local startStation = lookupStation(line, ids[1])
        local reachedStation = lookupStation(line, ids[reachedIndex])
        local destinationStation = lookupStation(line, ids[#ids])
        if type(startStation) ~= "table"
            or type(reachedStation) ~= "table"
            or type(destinationStation) ~= "table" then
            addError(errors, "unknown_route_station", "$.result.route", "정산 이동 구간의 역 정보를 찾을 수 없습니다.")
            return nil
        end
        return {
            lineId = line.id,
            lineName = line.name,
            lineCode = line.code,
            lineColor = line.color,
            operatorName = line.operatorName,
            startStation = stationView(startStation),
            reachedStation = stationView(reachedStation),
            destinationStation = stationView(destinationStation),
        }
    end

    local function buildResultView(runState, staticData, errors)
        local settlement = runState.lastSettlement
        local character = staticData.characters[settlement.characterId]
        local environment = staticData.environments[settlement.environmentId]
        if type(character) ~= "table" or type(environment) ~= "table" then
            addError(errors, "missing_result_reference", "$.result", "최근 세션의 공개 참조를 찾을 수 없습니다.")
            return nil
        end
        local route = buildRouteView(settlement, staticData, errors)
        if route == nil then return nil end
        local statusLabel = settlement.status == "victory" and "승리" or "패배"
        local headline = settlement.status == "victory"
            and character.name .. "의 저항을 무너뜨렸습니다"
            or character.name .. " 공략에 실패했습니다"
        return {
            sessionNumber = runState.stats.completed,
            battleId = settlement.battleId,
            status = settlement.status,
            statusLabel = statusLabel,
            headline = headline,
            reasonCode = settlement.reasonCode,
            reasonLabel = REASON_LABELS[settlement.reasonCode],
            character = {
                id = character.id,
                name = character.name,
            },
            turnNumber = settlement.turnNumber,
            turnLimit = settlement.turnLimit,
            finalStealth = settlement.finalStealth,
            finalResistance = settlement.finalResistance,
            environment = {
                id = environment.id,
                name = environment.name,
            },
            route = route,
        }
    end

    local function buildCardView(slot, cardId, ownedCopies, staticData, errors)
        local path = "$.rewardOffer.cards[" .. slot .. "]"
        local card = staticData.cards[cardId]
        if type(card) ~= "table" or card.owner ~= "player" or card.id ~= cardId then
            addError(errors, "unknown_reward_card", path .. ".cardId", "보상 카드 정의를 찾을 수 없습니다.")
            return nil
        end
        local presentation, callError = callRuntime(
            "viewBuilder",
            "buildCardPresentation",
            card,
            staticData.registry,
            path
        )
        if callError then
            errors[#errors + 1] = callError
            return nil
        end
        if presentation.ok ~= true or type(presentation.card) ~= "table" then
            appendNestedErrors(errors, path, presentation)
            return nil
        end
        if type(card.base) ~= "table"
            or not isFinite(card.base.stealthCost)
            or not isFinite(card.base.resistanceDamage) then
            addError(errors, "invalid_card_base", path, "보상 카드의 기본 수치를 표시할 수 없습니다.")
            return nil
        end
        return {
            slot = slot,
            cardId = presentation.card.cardId,
            name = presentation.card.name,
            descriptionSegments = presentation.card.descriptionSegments,
            ruleLines = presentation.card.ruleLines,
            actionTag = presentation.card.actionTag,
            mechanisms = presentation.card.mechanisms,
            baseStealthCost = card.base.stealthCost,
            baseResistanceDamage = card.base.resistanceDamage,
            ownedCopies = ownedCopies,
        }
    end

    local function buildRewardOfferView(runState, staticData, errors)
        local offer = runState.rewardOffer
        local result = {
            kind = offer.kind,
            interactionToken = offer.interactionToken,
            cards = {},
        }
        if offer.kind == "card" then
            local copies = {}
            for _, cardId in ipairs(runState.playerCardIds) do
                copies[cardId] = (copies[cardId] or 0) + 1
            end
            for slot, cardId in ipairs(offer.cardIds) do
                local cardView = buildCardView(slot, cardId, copies[cardId] or 0, staticData, errors)
                if cardView ~= nil then result.cards[#result.cards + 1] = cardView end
            end
        end
        result.count = #result.cards
        return result
    end

    local function buildAppearanceSummary(profile, path, errors)
        if type(profile) ~= "table" or type(profile.appearance) ~= "table" then
            addError(errors, "missing_public_appearance", path, "공개 외형 정보를 찾을 수 없습니다.")
            return nil
        end
        local appearance = profile.appearance
        local parts = {}
        local function appendText(value, suffix)
            if type(value) == "string" and value ~= "" then
                parts[#parts + 1] = value .. (suffix or "")
            end
        end
        local function appendNumber(value, suffix)
            if isFinite(value) then parts[#parts + 1] = tostring(value) .. suffix end
        end
        appendText(appearance.hairColor, " 머리")
        appendText(appearance.eyeColor, " 눈")
        appendText(appearance.skin)
        appendNumber(appearance.height, "cm")
        appendNumber(appearance.weight, "kg")
        appendText(appearance.threeSize)
        appendText(appearance.style)
        if #parts == 0 then
            addError(errors, "empty_public_appearance", path, "표시할 공개 외형 요약이 없습니다.")
            return nil
        end
        return table.concat(parts, " · ")
    end

    local function buildCharacterView(slot, characterId, staticData, errors)
        local path = "$.characterOffer.characters[" .. slot .. "]"
        local character = staticData.characters[characterId]
        if type(character) ~= "table"
            or character.id ~= characterId
            or type(character.name) ~= "string"
            or character.name == "" then
            addError(errors, "unknown_character", path .. ".characterId", "제안 캐릭터를 찾을 수 없습니다.")
            return nil
        end
        local profile = character.publicProfile
        local battle = character.battle
        if type(profile) ~= "table" or type(battle) ~= "table" then
            addError(errors, "missing_character_public_data", path, "캐릭터 공개 정보를 표시할 수 없습니다.")
            return nil
        end
        local appearanceSummary = buildAppearanceSummary(profile, path .. ".appearanceSummary", errors)
        local mood = staticData.registry.moods[battle.startingMood]
        if type(mood) ~= "table" or type(mood.label) ~= "string" or mood.label == "" then
            addError(errors, "unknown_starting_mood", path .. ".startingMood", "시작 무드를 찾을 수 없습니다.")
            return nil
        end
        local traits = {}
        for index, traitId in ipairs(type(battle.traitIds) == "table" and battle.traitIds or {}) do
            local trait = staticData.traits[traitId]
            if type(trait) ~= "table"
                or trait.owner ~= "character"
                or trait.visibility ~= "public"
                or type(trait.name) ~= "string"
                or type(trait.description) ~= "string" then
                addError(errors, "invalid_public_trait", path .. ".traits[" .. index .. "]", "공개 특징을 표시할 수 없습니다.")
            else
                traits[#traits + 1] = {
                    id = trait.id,
                    name = trait.name,
                    description = trait.description,
                }
            end
        end
        return {
            slot = slot,
            characterId = character.id,
            name = character.name,
            age = profile.age,
            occupation = profile.occupation,
            appearanceSummary = appearanceSummary,
            startingResistance = battle.startingResistance,
            startingMood = {
                id = mood.id,
                label = mood.label,
            },
            baseDrawCount = battle.baseDrawCount,
            maxHandSize = battle.maxHandSize,
            traits = traits,
        }
    end

    local function buildCharacterOfferView(runState, staticData, errors)
        local characters = {}
        for slot, characterId in ipairs(runState.characterOffer.characterIds) do
            local characterView = buildCharacterView(slot, characterId, staticData, errors)
            if characterView ~= nil then characters[#characters + 1] = characterView end
        end
        return {
            interactionToken = runState.characterOffer.interactionToken,
            characters = characters,
        }
    end

    local function validateString(value, path, errors)
        if type(value) ~= "string" or value == "" then
            addError(errors, "invalid_text", path, "비어 있지 않은 문자열이어야 합니다.")
        end
    end

    local function validateStationView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_station_view", path, "역 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, { id = true, code = true, name = true }, path, errors)
        if not isAsciiId(value.id) then
            addError(errors, "invalid_station_id", path .. ".id", "역 ID가 올바르지 않습니다.")
        end
        validateString(value.code, path .. ".code", errors)
        validateString(value.name, path .. ".name", errors)
    end

    local function validateTagView(value, path, errors, expectedKind)
        if type(value) ~= "table" then
            addError(errors, "invalid_tag_view", path, "태그 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            kind = true,
            id = true,
            label = true,
            tagKind = true,
            tooltip = true,
        }, path, errors)
        if value.kind ~= "tag" or not isAsciiId(value.id) then
            addError(errors, "invalid_tag_identity", path, "태그 View 식별자가 올바르지 않습니다.")
        end
        if value.tagKind ~= "action" and value.tagKind ~= "mechanism" then
            addError(errors, "invalid_tag_kind", path .. ".tagKind", "태그 종류가 올바르지 않습니다.")
        elseif expectedKind ~= nil and value.tagKind ~= expectedKind then
            addError(errors, "tag_kind_mismatch", path .. ".tagKind", "이 위치의 태그 종류가 다릅니다.")
        end
        validateString(value.label, path .. ".label", errors)
        validateString(value.tooltip, path .. ".tooltip", errors)
    end

    local function validateSegments(value, path, errors)
        local length = getArrayLength(value, path, errors)
        if length == nil then return end
        for index = 1, length do
            local segment = value[index]
            local segmentPath = path .. "[" .. index .. "]"
            if type(segment) ~= "table" then
                addError(errors, "invalid_segment", segmentPath, "문장 조각이 테이블이 아닙니다.")
            elseif segment.kind == "text" then
                checkAllowedKeys(segment, { kind = true, value = true }, segmentPath, errors)
                validateString(segment.value, segmentPath .. ".value", errors)
            elseif segment.kind == "tag" then
                validateTagView(segment, segmentPath, errors)
            else
                addError(errors, "invalid_segment_kind", segmentPath .. ".kind", "문장 조각 종류가 올바르지 않습니다.")
            end
        end
    end

    local function validateRuleLines(value, path, errors)
        local length = getArrayLength(value, path, errors)
        if length == nil then return end
        if length < 1 then
            addError(errors, "empty_rule_lines", path, "카드 규칙은 한 줄 이상이어야 합니다.")
        end
        for index = 1, length do
            local line = value[index]
            local linePath = path .. "[" .. index .. "]"
            if type(line) ~= "table" then
                addError(errors, "invalid_rule_line", linePath, "규칙 줄이 테이블이 아닙니다.")
            else
                checkAllowedKeys(line, { segments = true }, linePath, errors)
                validateSegments(line.segments, linePath .. ".segments", errors)
            end
        end
    end

    local function validateCardView(card, path, expectedSlot, errors)
        if type(card) ~= "table" then
            addError(errors, "invalid_card_view", path, "보상 카드 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(card, {
            slot = true,
            cardId = true,
            name = true,
            descriptionSegments = true,
            ruleLines = true,
            actionTag = true,
            mechanisms = true,
            baseStealthCost = true,
            baseResistanceDamage = true,
            ownedCopies = true,
        }, path, errors)
        if card.slot ~= expectedSlot then
            addError(errors, "card_slot_mismatch", path .. ".slot", "카드 슬롯이 배열 순서와 다릅니다.")
        end
        if not isAsciiId(card.cardId) then
            addError(errors, "invalid_card_id", path .. ".cardId", "카드 ID가 올바르지 않습니다.")
        end
        validateString(card.name, path .. ".name", errors)
        validateSegments(card.descriptionSegments, path .. ".descriptionSegments", errors)
        validateRuleLines(card.ruleLines, path .. ".ruleLines", errors)
        validateTagView(card.actionTag, path .. ".actionTag", errors, "action")
        local mechanismCount = getArrayLength(card.mechanisms, path .. ".mechanisms", errors)
        if mechanismCount ~= nil then
            local seen = {}
            for index = 1, mechanismCount do
                local mechanism = card.mechanisms[index]
                validateTagView(mechanism, path .. ".mechanisms[" .. index .. "]", errors, "mechanism")
                if type(mechanism) == "table" and type(mechanism.id) == "string" then
                    if seen[mechanism.id] then
                        addError(errors, "duplicate_mechanism", path .. ".mechanisms[" .. index .. "]", "메커니즘이 중복되었습니다.")
                    end
                    seen[mechanism.id] = true
                end
            end
        end
        if not isFinite(card.baseStealthCost) or card.baseStealthCost < 0 then
            addError(errors, "invalid_stealth_cost", path .. ".baseStealthCost", "기본 은폐 비용이 올바르지 않습니다.")
        end
        if not isFinite(card.baseResistanceDamage) or card.baseResistanceDamage < 0 then
            addError(errors, "invalid_resistance_damage", path .. ".baseResistanceDamage", "기본 저항 피해가 올바르지 않습니다.")
        end
        if not isInteger(card.ownedCopies, 0, CARD_COPY_LIMIT - 1) then
            addError(errors, "invalid_owned_copies", path .. ".ownedCopies", "보상 카드 보유 수는 0 또는 1이어야 합니다.")
        end
    end

    local function validateCharacterView(character, path, expectedSlot, errors)
        if type(character) ~= "table" then
            addError(errors, "invalid_character_view", path, "캐릭터 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(character, {
            slot = true,
            characterId = true,
            name = true,
            age = true,
            occupation = true,
            appearanceSummary = true,
            startingResistance = true,
            startingMood = true,
            baseDrawCount = true,
            maxHandSize = true,
            traits = true,
        }, path, errors)
        if character.slot ~= expectedSlot then
            addError(errors, "character_slot_mismatch", path .. ".slot", "캐릭터 슬롯이 배열 순서와 다릅니다.")
        end
        if not isAsciiId(character.characterId) then
            addError(errors, "invalid_character_id", path .. ".characterId", "캐릭터 ID가 올바르지 않습니다.")
        end
        validateString(character.name, path .. ".name", errors)
        if not isInteger(character.age, 1) then
            addError(errors, "invalid_character_age", path .. ".age", "캐릭터 나이가 올바르지 않습니다.")
        end
        validateString(character.occupation, path .. ".occupation", errors)
        validateString(character.appearanceSummary, path .. ".appearanceSummary", errors)
        if not isFinite(character.startingResistance) or character.startingResistance <= 0 then
            addError(errors, "invalid_starting_resistance", path .. ".startingResistance", "시작 저항은 양수여야 합니다.")
        end
        if type(character.startingMood) ~= "table" then
            addError(errors, "invalid_starting_mood", path .. ".startingMood", "시작 무드 View가 필요합니다.")
        else
            checkAllowedKeys(character.startingMood, { id = true, label = true }, path .. ".startingMood", errors)
            if not isAsciiId(character.startingMood.id) then
                addError(errors, "invalid_mood_id", path .. ".startingMood.id", "무드 ID가 올바르지 않습니다.")
            end
            validateString(character.startingMood.label, path .. ".startingMood.label", errors)
        end
        if not isInteger(character.baseDrawCount, 1)
            or not isInteger(character.maxHandSize, 1)
            or (isInteger(character.baseDrawCount, 1)
                and isInteger(character.maxHandSize, 1)
                and character.baseDrawCount > character.maxHandSize) then
            addError(errors, "invalid_character_hand_values", path, "드로우와 손패 상한이 올바르지 않습니다.")
        end
        local traitCount = getArrayLength(character.traits, path .. ".traits", errors)
        if traitCount ~= nil then
            local seen = {}
            for index = 1, traitCount do
                local trait = character.traits[index]
                local traitPath = path .. ".traits[" .. index .. "]"
                if type(trait) ~= "table" then
                    addError(errors, "invalid_trait_view", traitPath, "특징 View가 테이블이 아닙니다.")
                else
                    checkAllowedKeys(trait, { id = true, name = true, description = true }, traitPath, errors)
                    if not isAsciiId(trait.id) then
                        addError(errors, "invalid_trait_id", traitPath .. ".id", "특징 ID가 올바르지 않습니다.")
                    elseif seen[trait.id] then
                        addError(errors, "duplicate_trait", traitPath .. ".id", "특징이 중복되었습니다.")
                    else
                        seen[trait.id] = true
                    end
                    validateString(trait.name, traitPath .. ".name", errors)
                    validateString(trait.description, traitPath .. ".description", errors)
                end
            end
        end
    end

    local function validateRunProgressionView(view)
        local errors = {}
        validateJsonSafe(view, "$", errors)
        if #errors > 0 then return failure(errors) end
        if type(view) ~= "table" or getmetatable(view) ~= nil then
            addError(errors, "invalid_view_root", "$", "runProgressionView 최상위 값은 일반 테이블이어야 합니다.")
            return failure(errors)
        end
        checkAllowedKeys(view, {
            schemaVersion = true,
            kind = true,
            phase = true,
            sessionIndex = true,
            stats = true,
            deck = true,
            result = true,
            rewardOffer = true,
            characterOffer = true,
            selectedCharacter = true,
        }, "$", errors)
        if view.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_schema", "$.schemaVersion", "지원하지 않는 runProgressionView 스키마입니다.")
        end
        if view.kind ~= VIEW_KIND then
            addError(errors, "invalid_view_kind", "$.kind", "View kind가 runProgressionView가 아닙니다.")
        end
        if VALID_PHASES[view.phase] ~= true then
            addError(errors, "invalid_phase", "$.phase", "지원하지 않는 View phase입니다.")
        end
        if not isInteger(view.sessionIndex, 1) then
            addError(errors, "invalid_session_index", "$.sessionIndex", "세션 순번은 1 이상의 정수여야 합니다.")
        end

        if type(view.stats) ~= "table" then
            addError(errors, "invalid_stats", "$.stats", "누적 전적 View가 필요합니다.")
        else
            checkAllowedKeys(view.stats, {
                completed = true,
                victories = true,
                defeats = true,
            }, "$.stats", errors)
            for _, field in ipairs({ "completed", "victories", "defeats" }) do
                if not isInteger(view.stats[field], 0) then
                    addError(errors, "invalid_stat", "$.stats." .. field, "누적 전적은 0 이상의 정수여야 합니다.")
                end
            end
            if isInteger(view.stats.completed, 0)
                and isInteger(view.stats.victories, 0)
                and isInteger(view.stats.defeats, 0)
                and view.stats.completed ~= view.stats.victories + view.stats.defeats then
                addError(errors, "stats_total_mismatch", "$.stats", "완료 수가 승리와 패배 합과 다릅니다.")
            end
        end

        if type(view.deck) ~= "table" then
            addError(errors, "invalid_deck", "$.deck", "덱 요약 View가 필요합니다.")
        else
            checkAllowedKeys(view.deck, { count = true, limit = true }, "$.deck", errors)
            if not isInteger(view.deck.count, DECK_MIN, DECK_MAX) then
                addError(errors, "invalid_deck_count", "$.deck.count", "덱 수는 10장 이상 20장 이하여야 합니다.")
            end
            if view.deck.limit ~= DECK_MAX then
                addError(errors, "invalid_deck_limit", "$.deck.limit", "덱 상한 표시는 20이어야 합니다.")
            end
        end

        if type(view.result) ~= "table" then
            addError(errors, "invalid_result", "$.result", "최근 세션 결과 View가 필요합니다.")
        else
            checkAllowedKeys(view.result, {
                sessionNumber = true,
                battleId = true,
                status = true,
                statusLabel = true,
                headline = true,
                reasonCode = true,
                reasonLabel = true,
                character = true,
                turnNumber = true,
                turnLimit = true,
                finalStealth = true,
                finalResistance = true,
                environment = true,
                route = true,
            }, "$.result", errors)
            if not isInteger(view.result.sessionNumber, 1) then
                addError(errors, "invalid_result_session", "$.result.sessionNumber", "결과 세션 번호가 올바르지 않습니다.")
            elseif type(view.stats) == "table"
                and isInteger(view.stats.completed, 0)
                and view.result.sessionNumber ~= view.stats.completed then
                addError(errors, "result_session_mismatch", "$.result.sessionNumber", "결과 세션 번호와 완료 전적이 다릅니다.")
            end
            if not isRuntimeId(view.result.battleId) then
                addError(errors, "invalid_result_battle", "$.result.battleId", "결과 battleId가 올바르지 않습니다.")
            end
            if VALID_OUTCOMES[view.result.status] ~= true then
                addError(errors, "invalid_result_status", "$.result.status", "결과 상태가 올바르지 않습니다.")
            end
            validateString(view.result.statusLabel, "$.result.statusLabel", errors)
            validateString(view.result.headline, "$.result.headline", errors)
            if REASON_LABELS[view.result.reasonCode] == nil then
                addError(errors, "invalid_result_reason", "$.result.reasonCode", "결과 종료 사유가 올바르지 않습니다.")
            end
            validateString(view.result.reasonLabel, "$.result.reasonLabel", errors)
            if type(view.result.character) ~= "table" then
                addError(errors, "invalid_result_character", "$.result.character", "결과 상대 View가 필요합니다.")
            else
                checkAllowedKeys(view.result.character, { id = true, name = true }, "$.result.character", errors)
                if not isAsciiId(view.result.character.id) then
                    addError(errors, "invalid_character_id", "$.result.character.id", "결과 상대 ID가 올바르지 않습니다.")
                end
                validateString(view.result.character.name, "$.result.character.name", errors)
            end
            if not isInteger(view.result.turnNumber, 1)
                or not isInteger(view.result.turnLimit, 1)
                or (isInteger(view.result.turnNumber, 1)
                    and isInteger(view.result.turnLimit, 1)
                    and view.result.turnNumber > view.result.turnLimit) then
                addError(errors, "invalid_result_turn", "$.result", "결과 턴 수치가 올바르지 않습니다.")
            end
            if not isFinite(view.result.finalStealth)
                or not isFinite(view.result.finalResistance) then
                addError(errors, "invalid_result_resources", "$.result", "최종 자원 수치가 올바르지 않습니다.")
            end
            if type(view.result.environment) ~= "table" then
                addError(errors, "invalid_result_environment", "$.result.environment", "결과 환경 View가 필요합니다.")
            else
                checkAllowedKeys(view.result.environment, { id = true, name = true }, "$.result.environment", errors)
                if not isAsciiId(view.result.environment.id) then
                    addError(errors, "invalid_environment_id", "$.result.environment.id", "환경 ID가 올바르지 않습니다.")
                end
                validateString(view.result.environment.name, "$.result.environment.name", errors)
            end
            if type(view.result.route) ~= "table" then
                addError(errors, "invalid_route_view", "$.result.route", "결과 노선 View가 필요합니다.")
            else
                checkAllowedKeys(view.result.route, {
                    lineId = true,
                    lineName = true,
                    lineCode = true,
                    lineColor = true,
                    operatorName = true,
                    startStation = true,
                    reachedStation = true,
                    destinationStation = true,
                }, "$.result.route", errors)
                if not isAsciiId(view.result.route.lineId) then
                    addError(errors, "invalid_line_id", "$.result.route.lineId", "노선 ID가 올바르지 않습니다.")
                end
                for _, field in ipairs({ "lineName", "lineCode", "lineColor", "operatorName" }) do
                    validateString(view.result.route[field], "$.result.route." .. field, errors)
                end
                validateStationView(view.result.route.startStation, "$.result.route.startStation", errors)
                validateStationView(view.result.route.reachedStation, "$.result.route.reachedStation", errors)
                validateStationView(view.result.route.destinationStation, "$.result.route.destinationStation", errors)
            end
        end

        if view.phase == "reward" then
            if type(view.rewardOffer) ~= "table" then
                addError(errors, "missing_reward_offer", "$.rewardOffer", "보상 단계에는 보상 제안 View가 필요합니다.")
            else
                checkAllowedKeys(view.rewardOffer, {
                    kind = true,
                    interactionToken = true,
                    count = true,
                    cards = true,
                }, "$.rewardOffer", errors)
                if view.rewardOffer.kind ~= "card" and view.rewardOffer.kind ~= "none" then
                    addError(errors, "invalid_reward_kind", "$.rewardOffer.kind", "보상 종류가 올바르지 않습니다.")
                end
                if not isInteractionToken(view.rewardOffer.interactionToken) then
                    addError(errors, "invalid_interaction_token", "$.rewardOffer.interactionToken", "보상 token이 올바르지 않습니다.")
                end
                local cardCount = getArrayLength(view.rewardOffer.cards, "$.rewardOffer.cards", errors)
                if cardCount ~= nil then
                    if view.rewardOffer.count ~= cardCount then
                        addError(errors, "reward_count_mismatch", "$.rewardOffer.count", "보상 카드 수 요약이 배열과 다릅니다.")
                    end
                    if view.rewardOffer.kind == "card"
                        and (cardCount < 1 or cardCount > REWARD_OFFER_MAX) then
                        addError(errors, "invalid_reward_card_count", "$.rewardOffer.cards", "카드 보상은 한 장 이상 세 장 이하여야 합니다.")
                    elseif view.rewardOffer.kind == "none" and cardCount ~= 0 then
                        addError(errors, "unexpected_reward_cards", "$.rewardOffer.cards", "none 보상에는 카드가 없어야 합니다.")
                    end
                    local seenCards = {}
                    for index = 1, cardCount do
                        local card = view.rewardOffer.cards[index]
                        validateCardView(card, "$.rewardOffer.cards[" .. index .. "]", index, errors)
                        if type(card) == "table" and type(card.cardId) == "string" then
                            if seenCards[card.cardId] then
                                addError(errors, "duplicate_reward_card", "$.rewardOffer.cards[" .. index .. "]", "보상 카드가 중복되었습니다.")
                            end
                            seenCards[card.cardId] = true
                        end
                    end
                end
            end
            if view.characterOffer ~= nil or view.selectedCharacter ~= nil then
                addError(errors, "unexpected_phase_view", "$", "보상 단계에 상대 선택 View를 둘 수 없습니다.")
            end
        elseif view.phase == "characterSelect" then
            if type(view.characterOffer) ~= "table" then
                addError(errors, "missing_character_offer", "$.characterOffer", "상대 선택 View가 필요합니다.")
            else
                checkAllowedKeys(view.characterOffer, {
                    interactionToken = true,
                    characters = true,
                }, "$.characterOffer", errors)
                if not isInteractionToken(view.characterOffer.interactionToken) then
                    addError(errors, "invalid_interaction_token", "$.characterOffer.interactionToken", "상대 선택 token이 올바르지 않습니다.")
                end
                local characterCount = getArrayLength(view.characterOffer.characters, "$.characterOffer.characters", errors)
                if characterCount ~= nil then
                    if characterCount ~= CHARACTER_OFFER_SIZE then
                        addError(errors, "invalid_character_offer_size", "$.characterOffer.characters", "다음 상대는 정확히 세 명이어야 합니다.")
                    end
                    local seenCharacters = {}
                    for index = 1, characterCount do
                        local character = view.characterOffer.characters[index]
                        validateCharacterView(character, "$.characterOffer.characters[" .. index .. "]", index, errors)
                        if type(character) == "table" and type(character.characterId) == "string" then
                            if seenCharacters[character.characterId] then
                                addError(errors, "duplicate_character", "$.characterOffer.characters[" .. index .. "]", "같은 상대가 중복되었습니다.")
                            end
                            seenCharacters[character.characterId] = true
                        end
                    end
                end
            end
            if view.rewardOffer ~= nil or view.selectedCharacter ~= nil then
                addError(errors, "unexpected_phase_view", "$", "상대 선택 단계에 보상 또는 선택 완료 View를 둘 수 없습니다.")
            end
        elseif view.phase == "battleReady" then
            if type(view.selectedCharacter) ~= "table" then
                addError(errors, "missing_selected_character", "$.selectedCharacter", "선택 완료 상대 View가 필요합니다.")
            else
                checkAllowedKeys(view.selectedCharacter, { characterId = true, name = true }, "$.selectedCharacter", errors)
                if not isAsciiId(view.selectedCharacter.characterId) then
                    addError(errors, "invalid_character_id", "$.selectedCharacter.characterId", "선택 상대 ID가 올바르지 않습니다.")
                end
                validateString(view.selectedCharacter.name, "$.selectedCharacter.name", errors)
            end
            if view.rewardOffer ~= nil or view.characterOffer ~= nil then
                addError(errors, "unexpected_phase_view", "$", "전투 준비 단계에 제안 View를 둘 수 없습니다.")
            end
        end

        if #errors > 0 then return failure(errors) end
        return success("valid", true)
    end

    local function buildCanonicalView(runState, setupState, staticInput)
        local staticData, inputErrors = validateCanonicalInputs(runState, setupState, staticInput)
        if inputErrors then return failure(inputErrors) end
        local errors = {}
        local statsCopy, statsError = cloneJson(runState.stats, "$.stats")
        if statsError then return failure({ statsError }) end
        local resultView = buildResultView(runState, staticData, errors)
        local view = {
            schemaVersion = SCHEMA_VERSION,
            kind = VIEW_KIND,
            phase = runState.phase,
            sessionIndex = runState.sessionNumber,
            stats = statsCopy,
            deck = {
                count = #runState.playerCardIds,
                limit = DECK_MAX,
            },
            result = resultView,
        }
        if runState.phase == "reward" then
            view.rewardOffer = buildRewardOfferView(runState, staticData, errors)
        elseif runState.phase == "characterSelect" then
            view.characterOffer = buildCharacterOfferView(runState, staticData, errors)
        elseif runState.phase == "battleReady" then
            local characterId = type(runState.battleSpec) == "table"
                and runState.battleSpec.characterId
                or nil
            local character = staticData.characters[characterId]
            if type(character) ~= "table" then
                addError(errors, "unknown_selected_character", "$.selectedCharacter", "선택한 상대 공개 정보를 찾을 수 없습니다.")
            else
                view.selectedCharacter = {
                    characterId = character.id,
                    name = character.name,
                }
            end
        end
        if #errors > 0 then return failure(errors) end
        local validation = validateRunProgressionView(view)
        if validation.ok ~= true then return validation end
        return success("view", view)
    end

    local function buildPublic(runInput, setupInput, staticInput)
        local setupReport, setupCallError = callRuntime(
            "gameSetup",
            "validate",
            setupInput,
            staticInput
        )
        if setupCallError then return failure({ setupCallError }) end
        if setupReport.ok ~= true or type(setupReport.state) ~= "table" then
            local errors = {}
            appendNestedErrors(errors, "$.setupState", setupReport)
            return failure(errors)
        end
        if not deepEqual(setupInput, setupReport.state) then
            return failure({
                {
                    code = "setup_validation_mismatch",
                    path = "$.setupState",
                    message = "gameSetup.validate의 canonical 상태가 입력과 정확히 일치하지 않습니다.",
                },
            })
        end

        local runReport, runCallError = callRuntime(
            "runProgression",
            "validate",
            runInput,
            setupReport.state,
            staticInput
        )
        if runCallError then return failure({ runCallError }) end
        if runReport.ok ~= true or type(runReport.state) ~= "table" then
            local errors = {}
            appendNestedErrors(errors, "$.runState", runReport)
            return failure(errors)
        end
        if not deepEqual(runInput, runReport.state) then
            return failure({
                {
                    code = "run_validation_mismatch",
                    path = "$.runState",
                    message = "runProgression.validate의 canonical 상태가 입력과 정확히 일치하지 않습니다.",
                },
            })
        end
        return buildCanonicalView(runReport.state, setupReport.state, staticInput)
    end

    local function capabilityAllows(capability)
        if type(capability) ~= "function" then return false end
        local ok, allowed = pcall(capability, "runProgressionViewCanonicalV1")
        return ok and allowed == true
    end

    local arguments = { ... }
    if action == "validate" then
        return validateRunProgressionView(arguments[1])
    elseif action == "build" then
        return buildPublic(arguments[1], arguments[2], arguments[3])
    elseif action == "_buildCanonical" then
        if not capabilityAllows(arguments[4]) then
            return failure({
                {
                    code = "internal_action_denied",
                    path = "$.action",
                    message = "내부 canonical View 작업에 접근할 수 없습니다.",
                },
            })
        end
        return buildCanonicalView(arguments[1], arguments[2], arguments[3])
    end
    return failure({
        {
            code = "unknown_action",
            path = "$.action",
            message = "지원하지 않는 runProgressionView 작업입니다: " .. tostring(action),
        },
    })
end)

]],
    [[[
stateSchema
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local MAX_SAFE_INTEGER = 9007199254740991
    local MAX_PLAN_CAPACITY = 16
    local CHARACTER_SCORE_SCALE = 3
    local FINGERPRINT_ALGORITHM = "canonical_poly131_137_receipt_v2"
    local DRAFT_FINGERPRINT_ALGORITHM = "canonical_poly131_137_v1"
    local PENDING_INTEGRITY_ALGORITHM = "canonical_poly131_137_pending_v1"

    local VALID_STATUS = {
        active = true,
        victory = true,
        defeat = true,
    }

    local VALID_OWNER = {
        player = true,
        character = true,
    }

    local VALID_ZONE = {
        deck = true,
        hand = true,
        used = true,
        discard = true,
        removed = true,
        plan = true,
    }

    local function addError(errors, code, path, message)
        table.insert(errors, {
            code = code,
            path = path,
            message = message,
        })
    end

    local function result(errors, value)
        return {
            ok = #errors == 0,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
            value = #errors == 0 and value or nil,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isSafeInteger(value, minimum)
        return isInteger(value, minimum)
            and math.abs(value) <= MAX_SAFE_INTEGER
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function objectPath(path, key)
        if type(key) == "string" and string.match(key, "^[A-Za-z_][A-Za-z0-9_]*$") then
            return path .. "." .. key
        end
        return path .. "[" .. string.format("%q", tostring(key)) .. "]"
    end

    local function inspectTable(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "expected_table", path, "테이블이어야 합니다.")
            return nil
        end

        local numericCount = 0
        local maximum = 0
        local hasNumeric = false
        local hasString = false
        local stringKeys = {}

        for key in pairs(value) do
            if type(key) == "number" then
                hasNumeric = true
                numericCount = numericCount + 1
                if not isInteger(key, 1) then
                    addError(errors, "invalid_array_index", path, "배열 인덱스는 1 이상의 정수여야 합니다.")
                    return nil
                end
                if key > maximum then
                    maximum = key
                end
            elseif type(key) == "string" then
                hasString = true
                table.insert(stringKeys, key)
            else
                addError(errors, "invalid_object_key", path, "객체 키는 문자열이어야 합니다.")
                return nil
            end
        end

        if hasNumeric and hasString then
            addError(errors, "mixed_table", path, "숫자 인덱스와 문자열 키를 함께 사용할 수 없습니다.")
            return nil
        end

        if hasNumeric then
            if numericCount ~= maximum then
                addError(errors, "sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다.")
                return nil
            end
            return "array", maximum
        end

        if hasString then
            table.sort(stringKeys)
            return "object", stringKeys
        end

        return "array", 0
    end

    local function validateJsonSafe(value, path, errors, active)
        local valueType = type(value)
        if valueType == "string" or valueType == "boolean" then
            return
        end
        if valueType == "number" then
            if not isFinite(value) then
                addError(errors, "non_finite_number", path, "NaN과 무한대는 저장할 수 없습니다.")
            end
            return
        end
        if valueType ~= "table" then
            addError(errors, "unsupported_type", path, "JSON 상태에 저장할 수 없는 자료형입니다: " .. valueType)
            return
        end
        if getmetatable(value) ~= nil then
            addError(errors, "metatable_not_allowed", path, "상태 테이블에는 메타테이블을 사용할 수 없습니다.")
            return
        end

        active = active or {}
        if active[value] then
            addError(errors, "circular_reference", path, "순환 참조가 있는 테이블은 저장할 수 없습니다.")
            return
        end

        active[value] = true
        local kind, shape = inspectTable(value, path, errors)
        if kind == "array" then
            for index = 1, shape do
                validateJsonSafe(value[index], path .. "[" .. index .. "]", errors, active)
            end
        elseif kind == "object" then
            for _, key in ipairs(shape) do
                validateJsonSafe(value[key], objectPath(path, key), errors, active)
            end
        end
        active[value] = nil
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" then
            return
        end
        for key in pairs(value) do
            if type(key) ~= "string" or not allowed[key] then
                addError(errors, "unknown_field", objectPath(path, key), "허용되지 않은 필드입니다.")
            end
        end
    end

    local function getArrayLength(value, path, errors)
        local kind, length = inspectTable(value, path, errors)
        if kind ~= "array" then
            if kind ~= nil then
                addError(errors, "expected_array", path, "연속 배열이어야 합니다.")
            end
            return nil
        end
        return length
    end

    local function validateIdArray(value, path, errors, idValidator)
        local length = getArrayLength(value, path, errors)
        if length == nil then
            return
        end

        local seen = {}
        for index = 1, length do
            local item = value[index]
            if not idValidator(item) then
                addError(errors, "invalid_id", path .. "[" .. index .. "]", "올바른 ID 문자열이 아닙니다.")
            else
                if seen[item] then
                    addError(errors, "duplicate_id", path .. "[" .. index .. "]", "같은 ID가 중복되었습니다: " .. item)
                end
                seen[item] = true
            end
        end
    end

    local function normalizeStaticData(staticData)
        if type(staticData) ~= "table" or getmetatable(staticData) ~= nil then
            return staticData
        end
        local data = rawget(staticData, "data")
        if type(data) == "table" and getmetatable(data) == nil then
            return data
        end
        return staticData
    end

    local function isPlainTableTree(value, active, seen)
        if type(value) ~= "table" then
            return true
        end
        if getmetatable(value) ~= nil then
            return false
        end

        active = active or {}
        seen = seen or {}
        if active[value] then
            return false
        end
        if seen[value] then
            return true
        end

        active[value] = true
        for key, item in pairs(value) do
            if not isPlainTableTree(key, active, seen)
                or not isPlainTableTree(item, active, seen) then
                active[value] = nil
                return false
            end
        end
        active[value] = nil
        seen[value] = true
        return true
    end

    local function fingerprintFailure(code, path, message)
        error({
            code = code,
            path = path,
            message = message,
        }, 0)
    end

    local function inspectCanonicalTable(value, path)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            fingerprintFailure("invalid_table", path, "fingerprint 대상은 일반 테이블이어야 합니다.")
        end

        local numericCount = 0
        local maximum = 0
        local hasNumeric = false
        local hasString = false
        local stringKeys = {}
        for key in pairs(value) do
            if type(key) == "number" then
                hasNumeric = true
                numericCount = numericCount + 1
                if not isInteger(key, 1) then
                    fingerprintFailure("invalid_array_index", path, "배열 인덱스는 1 이상의 정수여야 합니다.")
                end
                if key > maximum then
                    maximum = key
                end
            elseif type(key) == "string" then
                hasString = true
                table.insert(stringKeys, key)
            else
                fingerprintFailure("invalid_object_key", path, "객체 키는 문자열이어야 합니다.")
            end
        end
        if hasNumeric and hasString then
            fingerprintFailure("mixed_table", path, "숫자 인덱스와 문자열 키를 함께 사용할 수 없습니다.")
        end
        if hasNumeric and numericCount ~= maximum then
            fingerprintFailure("sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다.")
        end
        table.sort(stringKeys)
        return hasNumeric, maximum, stringKeys
    end

    local function canonicalJson(value, path, active)
        local valueType = type(value)
        if valueType == "nil" then
            return "n"
        end
        if valueType == "boolean" then
            return value and "t" or "f"
        end
        if valueType == "number" then
            if not isFinite(value) then
                fingerprintFailure("non_finite_number", path, "NaN과 무한대는 fingerprint에 사용할 수 없습니다.")
            end
            return "d" .. string.format("%.17g", value) .. ";"
        end
        if valueType == "string" then
            return "s" .. tostring(#value) .. ":" .. value
        end
        if valueType ~= "table" then
            fingerprintFailure("unsupported_type", path, "fingerprint에 사용할 수 없는 자료형입니다: " .. valueType)
        end

        active = active or {}
        if active[value] then
            fingerprintFailure("circular_reference", path, "순환 참조가 있는 값은 fingerprint에 사용할 수 없습니다.")
        end
        active[value] = true

        local isArray, length, stringKeys = inspectCanonicalTable(value, path)
        local parts = {}
        if isArray then
            parts[1] = "["
            for index = 1, length do
                parts[#parts + 1] = canonicalJson(value[index], path .. "[" .. index .. "]", active)
            end
            parts[#parts + 1] = "]"
        else
            parts[1] = "{"
            for _, key in ipairs(stringKeys) do
                parts[#parts + 1] = "k" .. tostring(#key) .. ":" .. key
                parts[#parts + 1] = canonicalJson(value[key], objectPath(path, key), active)
            end
            parts[#parts + 1] = "}"
        end
        active[value] = nil
        return table.concat(parts)
    end

    local function fingerprintAuthorityState(state)
        local authorityState = {}
        for key, value in pairs(state) do
            if key == "turnStartReceipt" and type(value) == "table" then
                local receipt = {}
                for receiptKey, receiptValue in pairs(value) do
                    if receiptKey ~= "authorityFingerprint" then
                        receipt[receiptKey] = receiptValue
                    end
                end
                authorityState[key] = receipt
            else
                authorityState[key] = value
            end
        end

        local ok, canonical = pcall(canonicalJson, authorityState, "$", {})
        if not ok then
            if type(canonical) == "table" and canonical.code and canonical.path and canonical.message then
                return nil, canonical
            end
            return nil, {
                code = "fingerprint_failed",
                path = "$",
                message = "전투 상태 fingerprint 생성에 실패했습니다: " .. tostring(canonical),
            }
        end

        local hashA = 0
        local hashB = 0
        for index = 1, #canonical do
            local byte = string.byte(canonical, index)
            hashA = (hashA * 131 + byte) % 2147483647
            hashB = (hashB * 137 + byte) % 2147483629
        end
        return {
            algorithm = FINGERPRINT_ALGORITHM,
            length = #canonical,
            hashA = hashA,
            hashB = hashB,
        }, nil
    end

    local function fingerprintDraftAuthorityState(state)
        local ok, canonical = pcall(canonicalJson, state, "$", {})
        if not ok then
            if type(canonical) == "table" and canonical.code and canonical.path and canonical.message then
                return nil, canonical
            end
            return nil, {
                code = "fingerprint_failed",
                path = "$",
                message = "드래프트 권위 상태 fingerprint 생성에 실패했습니다: " .. tostring(canonical),
            }
        end

        local hashA = 0
        local hashB = 0
        for index = 1, #canonical do
            local byte = string.byte(canonical, index)
            hashA = (hashA * 131 + byte) % 2147483647
            hashB = (hashB * 137 + byte) % 2147483629
        end
        return {
            algorithm = DRAFT_FINGERPRINT_ALGORITHM,
            length = #canonical,
            hashA = hashA,
            hashB = hashB,
        }, nil
    end

    local function fingerprintPendingTurn(pending)
        local payload = {}
        for key, value in pairs(pending) do
            if key ~= "integrity" then
                payload[key] = value
            end
        end
        local ok, canonical = pcall(canonicalJson, payload, "$", {})
        if not ok then
            if type(canonical) == "table" and canonical.code and canonical.path and canonical.message then
                return nil, canonical
            end
            return nil, {
                code = "fingerprint_failed",
                path = "$.integrity",
                message = "pendingTurn 무결성 fingerprint 생성에 실패했습니다: " .. tostring(canonical),
            }
        end

        local hashA = 0
        local hashB = 0
        for index = 1, #canonical do
            local byte = string.byte(canonical, index)
            hashA = (hashA * 131 + byte) % 2147483647
            hashB = (hashB * 137 + byte) % 2147483629
        end
        return {
            algorithm = PENDING_INTEGRITY_ALGORITHM,
            length = #canonical,
            hashA = hashA,
            hashB = hashB,
        }, nil
    end

    local function hasCompleteStaticData(staticData)
        return type(staticData) == "table"
            and getmetatable(staticData) == nil
            and type(rawget(staticData, "registry")) == "table"
            and type(rawget(staticData, "cards")) == "table"
            and type(rawget(staticData, "traits")) == "table"
            and type(rawget(staticData, "environments")) == "table"
            and type(rawget(staticData, "subwayLines")) == "table"
            and type(rawget(staticData, "characters")) == "table"
            and isPlainTableTree(staticData)
    end

    local function cardHasMechanism(card, mechanismId)
        if type(card) ~= "table" or type(card.mechanisms) ~= "table" then
            return false
        end
        for _, id in ipairs(card.mechanisms) do
            if id == mechanismId then
                return true
            end
        end
        return false
    end

    local function appendNestedErrors(target, prefix, nested)
        if type(nested) ~= "table" or type(nested.errors) ~= "table" then
            addError(target, "validation_failed", prefix, "하위 스키마 검증 결과가 올바르지 않습니다.")
            return
        end
        for _, item in ipairs(nested.errors) do
            local suffix = tostring(item.path or "$")
            if string.sub(suffix, 1, 1) == "$" then
                suffix = string.sub(suffix, 2)
            end
            addError(
                target,
                tostring(item.code or "validation_failed"),
                prefix .. suffix,
                tostring(item.message or "하위 스키마 검증에 실패했습니다.")
            )
        end
    end

    local function validatePlanSlot(slot, side, path, errors, instances, staticData, currentTurn)
        if type(slot) ~= "table" then
            addError(errors, "invalid_plan_slot", path, "계획 슬롯이 테이블이 아닙니다.")
            return
        end

        local occupied = slot.occupied
        checkAllowedKeys(slot, {
            occupied = true,
            cardInstanceId = true,
            cardId = true,
            placedTurn = true,
            durationIncludesPlacementTurn = true,
            remainingTurns = true,
            remainingCharges = true,
            revealed = true,
            effectChoiceId = true,
        }, path, errors)

        if occupied ~= true then
            addError(errors, "invalid_plan_occupied", path .. ".occupied", "planSlots에는 occupied = true인 점유 슬롯만 저장할 수 있습니다.")
            return
        end
        if not isRuntimeId(slot.cardInstanceId) then
            addError(errors, "invalid_instance_id", path .. ".cardInstanceId", "계획 카드 인스턴스 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(slot.cardId) then
            addError(errors, "invalid_card_id", path .. ".cardId", "계획 카드 ID가 올바르지 않습니다.")
        end
        if not isInteger(slot.placedTurn, 1) then
            addError(errors, "invalid_placed_turn", path .. ".placedTurn", "배치 턴은 1 이상의 정수여야 합니다.")
        elseif isInteger(currentTurn, 1) and slot.placedTurn > currentTurn then
            addError(errors, "future_placed_turn", path .. ".placedTurn", "계획 배치 턴은 현재 턴보다 클 수 없습니다.")
        end
        if slot.revealed ~= true and slot.revealed ~= false then
            addError(errors, "invalid_revealed", path .. ".revealed", "revealed는 불리언이어야 합니다.")
        end
        if slot.effectChoiceId ~= nil and not isAsciiId(slot.effectChoiceId) then
            addError(errors, "invalid_effect_choice_id", path .. ".effectChoiceId", "계획 효과 선택지 ID가 올바르지 않습니다.")
        end
        if slot.durationIncludesPlacementTurn ~= nil
            and type(slot.durationIncludesPlacementTurn) ~= "boolean" then
            addError(
                errors,
                "invalid_plan_duration_policy",
                path .. ".durationIncludesPlacementTurn",
                "배치 턴 포함 여부는 불리언이어야 합니다."
            )
        elseif slot.durationIncludesPlacementTurn == true and slot.remainingTurns == nil then
            addError(
                errors,
                "plan_duration_policy_requires_duration",
                path .. ".durationIncludesPlacementTurn",
                "배치 턴을 포함하는 계획에는 남은 지속시간이 필요합니다."
            )
        end

        local hasLifetime = false
        if slot.remainingTurns ~= nil then
            hasLifetime = true
            if not isInteger(slot.remainingTurns, 1) then
                addError(errors, "invalid_remaining_turns", path .. ".remainingTurns", "점유된 계획의 남은 지속 턴은 1 이상의 정수여야 합니다.")
            end
        end
        if slot.remainingCharges ~= nil then
            hasLifetime = true
            if not isInteger(slot.remainingCharges, 1) then
                addError(errors, "invalid_remaining_charges", path .. ".remainingCharges", "점유된 계획의 남은 충전은 1 이상의 정수여야 합니다.")
            end
        end
        if not hasLifetime then
            addError(errors, "missing_plan_lifetime", path, "점유된 계획에는 제한된 수명이 필요합니다.")
        end

        local instance = instances[slot.cardInstanceId]
        if not instance then
            addError(errors, "missing_plan_instance", path .. ".cardInstanceId", "계획 카드 인스턴스를 찾을 수 없습니다.")
        else
            if instance.owner ~= side then
                addError(errors, "plan_owner_mismatch", path .. ".cardInstanceId", "계획 슬롯과 카드 소유자가 다릅니다.")
            end
            if instance.zone ~= "plan" then
                addError(errors, "plan_zone_mismatch", path .. ".cardInstanceId", "계획 카드 인스턴스의 zone이 plan이 아닙니다.")
            end
            if instance.cardId ~= slot.cardId then
                addError(errors, "plan_card_mismatch", path .. ".cardId", "계획 슬롯과 카드 인스턴스의 카드 ID가 다릅니다.")
            end
        end

        local cards = type(staticData) == "table" and staticData.cards or nil
        local card = type(cards) == "table" and cards[slot.cardId] or nil
        if card and not cardHasMechanism(card, "plan") then
            addError(errors, "plan_mechanism_missing", path .. ".cardId", "계획 슬롯의 카드에 plan 메커니즘이 없습니다.")
        elseif card then
            local matchedChoice = nil
            for _, choice in ipairs(type(card.effectChoices) == "table" and card.effectChoices or {}) do
                if choice.id == slot.effectChoiceId then matchedChoice = choice end
            end
            if type(card.effectChoices) == "table" and matchedChoice == nil then
                addError(errors, "missing_plan_effect_choice", path .. ".effectChoiceId", "선택형 계획에 유효한 효과 선택값이 없습니다.")
            elseif matchedChoice ~= nil and matchedChoice.placesPlan == false then
                addError(errors, "invalid_plan_effect_choice", path .. ".effectChoiceId", "즉시 발동 선택지는 계획 슬롯에 저장할 수 없습니다.")
            elseif type(card.effectChoices) ~= "table" and slot.effectChoiceId ~= nil then
                addError(errors, "unexpected_plan_effect_choice", path .. ".effectChoiceId", "선택지가 없는 계획에 효과 선택값이 있습니다.")
            end
            local planData = type(card.mechanismData) == "table" and card.mechanismData.plan or nil
            local expectedIncludesPlacementTurn = type(planData) == "table"
                and planData.durationIncludesPlacementTurn == true
            if (slot.durationIncludesPlacementTurn == true) ~= expectedIncludesPlacementTurn then
                addError(
                    errors,
                    "plan_duration_policy_mismatch",
                    path .. ".durationIncludesPlacementTurn",
                    "계획 슬롯의 배치 턴 포함 정책이 정적 카드 정의와 다릅니다."
                )
            end

            local initialDurationTurns = type(planData) == "table" and planData.durationTurns or nil
            if initialDurationTurns ~= nil and slot.remainingTurns == nil then
                addError(
                    errors,
                    "plan_remaining_turns_missing",
                    path .. ".remainingTurns",
                    "정적 카드 정의에 지속시간이 있는 활성 계획에는 remainingTurns가 필요합니다."
                )
            elseif slot.remainingTurns ~= nil then
                if initialDurationTurns == nil then
                    addError(
                        errors,
                        "plan_remaining_turns_undefined",
                        path .. ".remainingTurns",
                        "정적 카드 정의에 지속시간이 없는 계획은 remainingTurns를 가질 수 없습니다."
                    )
                elseif isInteger(slot.remainingTurns, 1)
                    and isInteger(initialDurationTurns, 1)
                    and slot.remainingTurns > initialDurationTurns then
                    addError(
                        errors,
                        "plan_remaining_turns_exceeded",
                        path .. ".remainingTurns",
                        "계획의 남은 지속시간은 정적 카드 정의의 초기 지속시간을 초과할 수 없습니다."
                    )
                end
            end

            local initialCharges = type(planData) == "table" and planData.charges or nil
            if initialCharges ~= nil and slot.remainingCharges == nil then
                addError(
                    errors,
                    "plan_remaining_charges_missing",
                    path .. ".remainingCharges",
                    "정적 카드 정의에 충전이 있는 활성 계획에는 remainingCharges가 필요합니다."
                )
            elseif slot.remainingCharges ~= nil then
                if initialCharges == nil then
                    addError(
                        errors,
                        "plan_remaining_charges_undefined",
                        path .. ".remainingCharges",
                        "정적 카드 정의에 충전이 없는 계획은 remainingCharges를 가질 수 없습니다."
                    )
                elseif isInteger(slot.remainingCharges, 1)
                    and isInteger(initialCharges, 1)
                    and slot.remainingCharges > initialCharges then
                    addError(
                        errors,
                        "plan_remaining_charges_exceeded",
                        path .. ".remainingCharges",
                        "계획의 남은 충전은 정적 카드 정의의 초기 충전을 초과할 수 없습니다."
                    )
                end
            end
        end
    end

    local function validatePlanSlots(
        slots,
        capacity,
        side,
        path,
        errors,
        instances,
        staticData,
        currentTurn
    )
        local capacityPath = "$." .. side .. ".planCapacity"
        local capacityValid = isSafeInteger(capacity, 1) and capacity <= MAX_PLAN_CAPACITY
        if not capacityValid then
            addError(errors, "invalid_plan_capacity", capacityPath, "계획 용량은 1 이상 16 이하의 정수여야 합니다.")
        end

        local slotCount = getArrayLength(slots, path, errors)
        if slotCount == nil then
            return
        end
        if capacityValid and slotCount > capacity then
            addError(errors, "plan_capacity_exceeded", path, "점유 계획 수가 계획 용량을 초과했습니다.")
        end

        local seenInstanceIds = {}
        for index = 1, slotCount do
            local slot = slots[index]
            local slotPath = path .. "[" .. index .. "]"
            validatePlanSlot(slot, side, slotPath, errors, instances, staticData, currentTurn)
            if type(slot) == "table" and isRuntimeId(slot.cardInstanceId) then
                if seenInstanceIds[slot.cardInstanceId] then
                    addError(
                        errors,
                        "duplicate_plan_slot",
                        slotPath .. ".cardInstanceId",
                        "같은 계획 카드 인스턴스를 둘 이상의 슬롯에 저장할 수 없습니다."
                    )
                else
                    seenInstanceIds[slot.cardInstanceId] = true
                end

                local instance = instances[slot.cardInstanceId]
                if instance and instance.owner == side and instance.zone == "plan"
                    and instance.position ~= index then
                    addError(
                        errors,
                        "plan_position_mismatch",
                        slotPath .. ".cardInstanceId",
                        "plan 영역 position은 planSlots 배열 인덱스와 일치해야 합니다."
                    )
                end
            end
        end
    end

    local function validateTurnStartEventSource(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_event_source", path, "턴 시작 사건의 source가 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            kind = true,
            id = true,
            side = true,
            instanceId = true,
        }, path, errors)
        if not isAsciiId(value.kind) then
            addError(errors, "invalid_event_source", path .. ".kind", "사건 source.kind는 lower_snake_case여야 합니다.")
        end
        if not isAsciiId(value.id) then
            addError(errors, "invalid_event_source", path .. ".id", "사건 source.id는 lower_snake_case여야 합니다.")
        end
        if value.side ~= nil and not VALID_OWNER[value.side] then
            addError(errors, "invalid_event_side", path .. ".side", "사건 source.side는 player 또는 character여야 합니다.")
        end
        if value.instanceId ~= nil and not isRuntimeId(value.instanceId) then
            addError(errors, "invalid_instance_id", path .. ".instanceId", "사건 source.instanceId가 올바르지 않습니다.")
        end
    end

    local function validateTurnStartEventCause(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_event_cause", path, "턴 시작 사건의 cause가 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            kind = true,
            resolutionId = true,
            eventId = true,
        }, path, errors)
        if not isAsciiId(value.kind) then
            addError(errors, "invalid_event_cause", path .. ".kind", "사건 cause.kind는 lower_snake_case여야 합니다.")
        end
        if value.resolutionId ~= nil and not isRuntimeId(value.resolutionId) then
            addError(errors, "invalid_resolution_id", path .. ".resolutionId", "사건 cause.resolutionId가 올바르지 않습니다.")
        end
        if value.eventId ~= nil and not isRuntimeId(value.eventId) then
            addError(errors, "invalid_event_id", path .. ".eventId", "사건 cause.eventId가 올바르지 않습니다.")
        end
    end

    local function validateTurnStartEvents(events, turnId, path, errors)
        local eventCount = getArrayLength(events, path, errors)
        if eventCount == nil then
            return
        end

        for index = 1, eventCount do
            local event = events[index]
            local eventPath = path .. "[" .. index .. "]"
            if type(event) ~= "table" then
                addError(errors, "invalid_turn_start_event", eventPath, "턴 시작 사건이 객체가 아닙니다.")
            else
                checkAllowedKeys(event, {
                    eventId = true,
                    sequence = true,
                    type = true,
                    phase = true,
                    resolutionId = true,
                    side = true,
                    source = true,
                    cause = true,
                    payload = true,
                }, eventPath, errors)

                if event.sequence ~= index then
                    addError(errors, "invalid_event_sequence", eventPath .. ".sequence", "턴 시작 사건 sequence는 배열 순서와 일치해야 합니다.")
                end
                if isRuntimeId(turnId) then
                    local expectedEventId = turnId .. "-event-" .. string.format("%03d", index)
                    if event.eventId ~= expectedEventId then
                        addError(errors, "invalid_event_id", eventPath .. ".eventId", "턴 시작 사건 ID가 turnId와 순번에 일치하지 않습니다.")
                    end
                elseif not isRuntimeId(event.eventId) then
                    addError(errors, "invalid_event_id", eventPath .. ".eventId", "턴 시작 사건 ID가 올바르지 않습니다.")
                end
                if not isAsciiId(event.type) then
                    addError(errors, "invalid_event_type", eventPath .. ".type", "사건 type은 lower_snake_case여야 합니다.")
                end
                if event.phase ~= "turn_start" then
                    addError(errors, "invalid_event_phase", eventPath .. ".phase", "turnStartReceipt 사건 phase는 turn_start여야 합니다.")
                end
                if event.resolutionId ~= nil and not isRuntimeId(event.resolutionId) then
                    addError(errors, "invalid_resolution_id", eventPath .. ".resolutionId", "사건 resolutionId가 올바르지 않습니다.")
                end
                if event.side ~= nil and not VALID_OWNER[event.side] then
                    addError(errors, "invalid_event_side", eventPath .. ".side", "사건 side는 player 또는 character여야 합니다.")
                end

                validateTurnStartEventSource(event.source, eventPath .. ".source", errors)
                if event.cause ~= nil then
                    validateTurnStartEventCause(event.cause, eventPath .. ".cause", errors)
                end
                if event.payload ~= nil then
                    local payloadKind = inspectTable(event.payload, eventPath .. ".payload", errors)
                    if payloadKind ~= "object" then
                        addError(errors, "invalid_event_payload", eventPath .. ".payload", "사건 payload는 비어 있지 않은 JSON 객체여야 합니다.")
                    end
                end
            end
        end
    end

    local function rngEqual(left, right)
        return type(left) == "table"
            and type(right) == "table"
            and left.seed == right.seed
            and left.cursor == right.cursor
    end

    local function validateReceiptRng(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_receipt_rng", path, "영수증 RNG가 객체가 아닙니다.")
            return false
        end
        checkAllowedKeys(value, {
            seed = true,
            cursor = true,
        }, path, errors)
        local valid = true
        if not isSafeInteger(value.seed, 0) then
            addError(errors, "invalid_receipt_rng", path .. ".seed", "영수증 RNG seed는 0 이상의 안전한 정수여야 합니다.")
            valid = false
        end
        if not isSafeInteger(value.cursor, 0) then
            addError(errors, "invalid_receipt_rng", path .. ".cursor", "영수증 RNG cursor는 0 이상의 안전한 정수여야 합니다.")
            valid = false
        end
        return valid
    end

    local function validateAuthorityFingerprint(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_authority_fingerprint", path, "권위 상태 fingerprint가 객체가 아닙니다.")
            return false
        end
        checkAllowedKeys(value, {
            algorithm = true,
            length = true,
            hashA = true,
            hashB = true,
        }, path, errors)

        local valid = true
        if value.algorithm ~= FINGERPRINT_ALGORITHM then
            addError(
                errors,
                "invalid_fingerprint_algorithm",
                path .. ".algorithm",
                "지원하지 않는 권위 상태 fingerprint 알고리즘입니다."
            )
            valid = false
        end
        for _, field in ipairs({ "length", "hashA", "hashB" }) do
            if not isSafeInteger(value[field], 0) then
                addError(
                    errors,
                    "invalid_authority_fingerprint",
                    path .. "." .. field,
                    "권위 상태 fingerprint 수치는 0 이상의 안전한 정수여야 합니다."
                )
                valid = false
            end
        end
        return valid
    end

    local function validateDrawReport(report, side, state, path, errors)
        if type(report) ~= "table" then
            addError(errors, "invalid_draw_receipt", path, "기본 드로우 영수증이 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(report, {
            requested = true,
            drawnInstanceIds = true,
            rngBefore = true,
            rngAfter = true,
        }, path, errors)

        local ownerState = type(state) == "table" and state[side] or nil
        local expectedRequested = type(ownerState) == "table" and ownerState.baseDrawCount or nil
        if not isInteger(report.requested, 1) then
            addError(errors, "invalid_draw_requested", path .. ".requested", "기본 드로우 요청 수는 1 이상의 정수여야 합니다.")
        elseif isInteger(expectedRequested, 1) and report.requested ~= expectedRequested then
            addError(
                errors,
                "receipt_draw_count_mismatch",
                path .. ".requested",
                "기본 드로우 요청 수가 현재 진영의 baseDrawCount와 다릅니다."
            )
        end

        local drawnCount = getArrayLength(report.drawnInstanceIds, path .. ".drawnInstanceIds", errors)
        if drawnCount ~= nil then
            validateIdArray(report.drawnInstanceIds, path .. ".drawnInstanceIds", errors, isRuntimeId)
            if isInteger(report.requested, 1) and drawnCount > report.requested then
                addError(errors, "draw_count_exceeded", path .. ".drawnInstanceIds", "실제 드로우 수가 요청 수보다 많습니다.")
            end
        end

        local beforeValid = validateReceiptRng(report.rngBefore, path .. ".rngBefore", errors)
        local afterValid = validateReceiptRng(report.rngAfter, path .. ".rngAfter", errors)
        if beforeValid and afterValid then
            if report.rngAfter.seed ~= report.rngBefore.seed then
                addError(errors, "receipt_rng_seed_changed", path .. ".rngAfter.seed", "드로우 중 RNG seed가 바뀔 수 없습니다.")
            end
            if report.rngAfter.cursor < report.rngBefore.cursor then
                addError(errors, "receipt_rng_reversed", path .. ".rngAfter.cursor", "드로우 중 RNG cursor가 이전으로 돌아갈 수 없습니다.")
            end
        end
    end

    local function validateDraws(draws, state, path, errors)
        if type(draws) ~= "table" then
            addError(errors, "invalid_draw_receipts", path, "기본 드로우 영수증 묶음이 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(draws, {
            player = true,
            character = true,
        }, path, errors)
        validateDrawReport(draws.player, "player", state, path .. ".player", errors)
        validateDrawReport(draws.character, "character", state, path .. ".character", errors)

        local playerAfter = type(draws.player) == "table" and draws.player.rngAfter or nil
        local characterBefore = type(draws.character) == "table" and draws.character.rngBefore or nil
        if type(playerAfter) == "table"
            and type(characterBefore) == "table"
            and not rngEqual(playerAfter, characterBefore) then
            addError(
                errors,
                "receipt_rng_discontinuity",
                path .. ".character.rngBefore",
                "캐릭터 드로우 RNG 시작점이 플레이어 드로우 종료점과 다릅니다."
            )
        end
    end

    local function validateCandidateTotals(totals, path, errors)
        if type(totals) ~= "table" then
            addError(errors, "invalid_selection_totals", path, "후보 효과 합계가 객체가 아닙니다.")
            return
        end
        local fields = {
            "recoverResistance",
            "loseStealth",
            "damageResistance",
            "recoverStealth",
        }
        checkAllowedKeys(totals, {
            recoverResistance = true,
            loseStealth = true,
            damageResistance = true,
            recoverStealth = true,
        }, path, errors)
        for _, field in ipairs(fields) do
            if not isFinite(totals[field]) or totals[field] < 0 then
                addError(
                    errors,
                    "invalid_selection_total",
                    path .. "." .. field,
                    "후보 효과 합계는 0 이상의 유한한 숫자여야 합니다."
                )
            end
        end
    end

    local function projectHistoryContext(history)
        if type(runScript) ~= "function" then return nil end
        local ok, report = pcall(runScript, triggerId, "battleHistory", "context", history)
        if not ok or type(report) ~= "table" or report.ok ~= true or type(report.context) ~= "table" then
            return nil
        end
        return report.context
    end

    local function validateHistoryContext(value, path, errors)
        if type(runScript) ~= "function" then
            addError(errors, "history_context_validation_unavailable", path, "전투 이력 컨텍스트 검증기를 찾을 수 없습니다.")
            return
        end
        local ok, report = pcall(runScript, triggerId, "battleHistory", "validateContext", value)
        if not ok or type(report) ~= "table" then
            addError(errors, "history_context_validation_failed", path, "전투 이력 컨텍스트 검증 호출에 실패했습니다.")
        elseif report.ok ~= true then
            appendNestedErrors(errors, path, report)
        end
    end

    local function validateSelectionContext(context, path, errors, staticData)
        if type(context) ~= "table" then
            addError(errors, "invalid_selection_context", path, "선택 시점 컨텍스트가 객체가 아닙니다.")
            return nil
        end
        checkAllowedKeys(context, {
            turnNumber = true,
            player = true,
            character = true,
            characterHand = true,
            history = true,
        }, path, errors)
        if not isInteger(context.turnNumber, 1) then
            addError(errors, "invalid_turn_number", path .. ".turnNumber", "선택 시점 턴 번호는 1 이상의 정수여야 합니다.")
        end
        validateHistoryContext(context.history, path .. ".history", errors)

        if type(context.player) ~= "table" then
            addError(errors, "invalid_selection_context", path .. ".player", "선택 시점 플레이어 컨텍스트가 객체가 아닙니다.")
        else
            checkAllowedKeys(context.player, {
                stealth = true,
                handCount = true,
            }, path .. ".player", errors)
            if not isFinite(context.player.stealth) then
                addError(errors, "invalid_selection_context", path .. ".player.stealth", "선택 시점 은폐가 유한한 숫자가 아닙니다.")
            end
            if not isSafeInteger(context.player.handCount, 0) then
                addError(errors, "invalid_selection_context", path .. ".player.handCount", "선택 시점 플레이어 손패 수가 안전한 비음수 정수가 아닙니다.")
            end
        end

        if type(context.character) ~= "table" then
            addError(errors, "invalid_selection_context", path .. ".character", "선택 시점 캐릭터 컨텍스트가 객체가 아닙니다.")
        else
            checkAllowedKeys(context.character, {
                resistance = true,
                mood = true,
                moodTokens = true,
            }, path .. ".character", errors)
            if not isFinite(context.character.resistance) then
                addError(errors, "invalid_selection_context", path .. ".character.resistance", "선택 시점 저항이 유한한 숫자가 아닙니다.")
            end
            if not isAsciiId(context.character.mood) then
                addError(errors, "invalid_selection_context", path .. ".character.mood", "선택 시점 무드 ID가 올바르지 않습니다.")
            end
            local moodTokens = context.character.moodTokens
            local moods = type(staticData) == "table"
                and type(staticData.registry) == "table"
                and type(staticData.registry.moods) == "table"
                and staticData.registry.moods
                or nil
            if type(moodTokens) ~= "table" or getmetatable(moodTokens) ~= nil then
                addError(errors, "invalid_selection_context", path .. ".character.moodTokens", "선택 시점 무드 토큰이 객체가 아닙니다.")
            else
                for moodId in pairs(moods or {}) do
                    if moodTokens[moodId] == nil then
                        addError(errors, "invalid_mood_token_count", path .. ".character.moodTokens." .. moodId, "선택 시점 무드 토큰 수가 올바르지 않습니다.")
                    end
                end
                for moodId, count in pairs(moodTokens) do
                    if not isAsciiId(moodId) then
                        addError(errors, "invalid_mood", path .. ".character.moodTokens." .. tostring(moodId), "선택 시점 무드 토큰 ID가 올바르지 않습니다.")
                    elseif moods ~= nil and moods[moodId] == nil then
                        addError(errors, "unknown_mood", path .. ".character.moodTokens." .. tostring(moodId), "선택 시점에 등록되지 않은 무드 토큰이 있습니다.")
                    elseif not isSafeInteger(count, 0) then
                        addError(errors, "invalid_mood_token_count", path .. ".character.moodTokens." .. moodId, "선택 시점 무드 토큰 수가 올바르지 않습니다.")
                    end
                end
            end
        end

        local handCount = getArrayLength(context.characterHand, path .. ".characterHand", errors)
        local seen = {}
        if handCount ~= nil then
            for index = 1, handCount do
                local entry = context.characterHand[index]
                local entryPath = path .. ".characterHand[" .. index .. "]"
                if type(entry) ~= "table" then
                    addError(errors, "invalid_selection_hand_entry", entryPath, "선택 시점 손패 항목이 객체가 아닙니다.")
                else
                    checkAllowedKeys(entry, {
                        instanceId = true,
                        cardId = true,
                        actionTag = true,
                        handPosition = true,
                    }, entryPath, errors)
                    if not isRuntimeId(entry.instanceId) then
                        addError(errors, "invalid_instance_id", entryPath .. ".instanceId", "선택 시점 손패 인스턴스 ID가 올바르지 않습니다.")
                    elseif seen[entry.instanceId] then
                        addError(errors, "duplicate_id", entryPath .. ".instanceId", "선택 시점 손패 인스턴스 ID가 중복되었습니다.")
                    else
                        seen[entry.instanceId] = true
                    end
                    if not isAsciiId(entry.cardId) then
                        addError(errors, "invalid_card_id", entryPath .. ".cardId", "선택 시점 손패 카드 ID가 올바르지 않습니다.")
                    end
                    if not isAsciiId(entry.actionTag) then
                        addError(errors, "invalid_action_tag", entryPath .. ".actionTag", "선택 시점 손패 행동 태그가 올바르지 않습니다.")
                    end
                    if entry.handPosition ~= index then
                        addError(errors, "invalid_hand_position", entryPath .. ".handPosition", "선택 시점 캐릭터 손패 위치는 안정 순서의 1부터 연속되어야 합니다.")
                    end
                end
            end
        end
        return handCount
    end

    local function validateSelectionCandidate(candidate, path, errors)
        if type(candidate) ~= "table" then
            addError(errors, "invalid_selection_candidate", path, "캐릭터 선택 후보가 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(candidate, {
            instanceId = true,
            cardId = true,
            actionTag = true,
            handPosition = true,
            score = true,
            projectedPlayerStealth = true,
            lethal = true,
            weight = true,
            moodScore = true,
            totals = true,
            planChargesEvaluated = true,
        }, path, errors)

        if not isRuntimeId(candidate.instanceId) then
            addError(errors, "invalid_instance_id", path .. ".instanceId", "후보 카드 인스턴스 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(candidate.cardId) then
            addError(errors, "invalid_card_id", path .. ".cardId", "후보 카드 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(candidate.actionTag) then
            addError(errors, "invalid_action_tag", path .. ".actionTag", "후보 행동 태그가 올바르지 않습니다.")
        end
        if not isInteger(candidate.handPosition, 1) then
            addError(errors, "invalid_hand_position", path .. ".handPosition", "후보 손패 위치는 1 이상의 정수여야 합니다.")
        end
        if not isSafeInteger(candidate.score) then
            addError(errors, "invalid_selection_score", path .. ".score", "후보 점수는 안전한 정수여야 합니다.")
        end
        if not isFinite(candidate.projectedPlayerStealth) then
            addError(errors, "invalid_projected_stealth", path .. ".projectedPlayerStealth", "예상 플레이어 은폐가 유한한 숫자가 아닙니다.")
        end
        if candidate.lethal ~= true and candidate.lethal ~= false then
            addError(errors, "invalid_lethal_flag", path .. ".lethal", "lethal은 불리언이어야 합니다.")
        elseif isFinite(candidate.projectedPlayerStealth)
            and candidate.lethal ~= (candidate.projectedPlayerStealth <= 0) then
            addError(errors, "lethal_projection_mismatch", path .. ".lethal", "lethal 값이 예상 플레이어 은폐와 다릅니다.")
        end
        if not isSafeInteger(candidate.weight, 0) then
            addError(errors, "invalid_selection_weight", path .. ".weight", "후보 가중치는 0 이상의 안전한 정수여야 합니다.")
        end
        if not isSafeInteger(candidate.moodScore) then
            addError(errors, "invalid_mood_score", path .. ".moodScore", "후보 무드 점수는 안전한 정수여야 합니다.")
        end

        validateCandidateTotals(candidate.totals, path .. ".totals", errors)
        if not isSafeInteger(candidate.planChargesEvaluated, 0) then
            addError(
                errors,
                "invalid_plan_charge_count",
                path .. ".planChargesEvaluated",
                "평가한 계획 충전 수는 0 이상의 안전한 정수여야 합니다."
            )
        end
    end

    local function validateSelectionDraw(draw, path, errors)
        if type(draw) ~= "table" then
            addError(errors, "invalid_selection_draw", path, "선택 추첨 영수증이 객체가 아닙니다.")
            return
        end

        if draw.kind == "pass" then
            checkAllowedKeys(draw, { kind = true }, path, errors)
        elseif draw.kind == "single" then
            checkAllowedKeys(draw, { kind = true, totalWeight = true }, path, errors)
            if not isSafeInteger(draw.totalWeight, 1) then
                addError(errors, "invalid_draw_weight", path .. ".totalWeight", "단독 후보 가중치는 1 이상의 안전한 정수여야 합니다.")
            end
        elseif draw.kind == "weighted" then
            checkAllowedKeys(draw, {
                kind = true,
                totalWeight = true,
                roll = true,
            }, path, errors)
            if not isSafeInteger(draw.totalWeight, 1) then
                addError(errors, "invalid_draw_weight", path .. ".totalWeight", "가중 추첨의 총 가중치는 1 이상의 안전한 정수여야 합니다.")
            end
            if not isSafeInteger(draw.roll, 1) then
                addError(errors, "invalid_draw_roll", path .. ".roll", "가중 추첨 roll은 1 이상의 안전한 정수여야 합니다.")
            elseif isSafeInteger(draw.totalWeight, 1) and draw.roll > draw.totalWeight then
                addError(errors, "invalid_draw_roll", path .. ".roll", "가중 추첨 roll이 총 가중치를 초과합니다.")
            end
        else
            checkAllowedKeys(draw, {
                kind = true,
                totalWeight = true,
                roll = true,
            }, path, errors)
            addError(errors, "invalid_selection_draw", path .. ".kind", "알 수 없는 선택 추첨 방식입니다.")
        end
    end

    local function findStateInstance(state, instanceId)
        if type(state) ~= "table" or type(state.cardInstances) ~= "table" then
            return nil
        end
        for _, instance in ipairs(state.cardInstances) do
            if type(instance) == "table" and instance.instanceId == instanceId then
                return instance
            end
        end
        return nil
    end

    local function countStateZone(state, owner, zone)
        local count = 0
        for _, instance in ipairs(type(state) == "table" and type(state.cardInstances) == "table" and state.cardInstances or {}) do
            if type(instance) == "table" and instance.owner == owner and instance.zone == zone then
                count = count + 1
            end
        end
        return count
    end

    local function buildExpectedSelectionContext(state, events, staticData)
        local revealEventIds = {}
        for _, event in ipairs(type(events) == "table" and events or {}) do
            if type(event) == "table" and event.type == "action_tag_revealed" and isRuntimeId(event.eventId) then
                revealEventIds[event.eventId] = true
            end
        end

        local playerStealth = type(state.player) == "table" and state.player.stealth or nil
        local playerHandCount = countStateZone(state, "player", "hand")
        local characterResistance = type(state.character) == "table" and state.character.resistance or nil
        local characterMood = type(state.character) == "table" and state.character.mood or nil
        local characterMoodTokens = {}
        local stateMoodTokens = type(state.character) == "table" and type(state.character.moodTokens) == "table"
            and state.character.moodTokens
            or {}
        local registryMoods = type(staticData) == "table"
            and type(staticData.registry) == "table"
            and type(staticData.registry.moods) == "table"
            and staticData.registry.moods
            or {}
        for moodId in pairs(registryMoods) do
            characterMoodTokens[moodId] = stateMoodTokens[moodId] or 0
        end
        local postSelectionCharacterDraws = {}

        if type(events) == "table" then
            for index = #events, 1, -1 do
                local event = events[index]
                local causedByReveal = type(event) == "table"
                    and event.type == "effect_applied"
                    and type(event.cause) == "table"
                    and revealEventIds[event.cause.eventId] == true
                local payload = causedByReveal and event.payload or nil
                if type(payload) == "table" then
                    if (payload.op == "lose_stealth" or payload.op == "recover_stealth")
                        and payload.target == "player"
                        and isFinite(payload.before) then
                        playerStealth = payload.before
                    elseif (payload.op == "recover_resistance" or payload.op == "damage_resistance")
                        and payload.target == "character"
                        and isFinite(payload.before) then
                        characterResistance = payload.before
                    elseif payload.op == "draw_cards" and payload.target == "player" then
                        local drawnCount = type(payload.drawnInstanceIds) == "table" and #payload.drawnInstanceIds or 0
                        playerHandCount = playerHandCount - drawnCount
                    elseif payload.op == "draw_cards" and payload.target == "character" then
                        for _, instanceId in ipairs(type(payload.drawnInstanceIds) == "table" and payload.drawnInstanceIds or {}) do
                            postSelectionCharacterDraws[instanceId] = true
                        end
                    elseif (payload.op == "add_mood_token" or payload.op == "remove_mood_token")
                        and payload.target == "character"
                        and isAsciiId(payload.mood)
                        and isSafeInteger(payload.before, 0) then
                        characterMoodTokens[payload.mood] = payload.before
                    end
                end
            end
        end

        local hand = {}
        for sourceIndex, instance in ipairs(type(state.cardInstances) == "table" and state.cardInstances or {}) do
            if type(instance) == "table"
                and instance.owner == "character"
                and instance.zone == "hand"
                and not postSelectionCharacterDraws[instance.instanceId] then
                hand[#hand + 1] = {
                    instance = instance,
                    sourceIndex = sourceIndex,
                }
            end
        end
        table.sort(hand, function(left, right)
            if left.instance.position ~= right.instance.position then
                return left.instance.position < right.instance.position
            end
            if left.instance.instanceId ~= right.instance.instanceId then
                return left.instance.instanceId < right.instance.instanceId
            end
            return left.sourceIndex < right.sourceIndex
        end)

        local characterHand = {}
        for index, entry in ipairs(hand) do
            local instance = entry.instance
            local card = type(staticData) == "table" and type(staticData.cards) == "table" and staticData.cards[instance.cardId] or nil
            characterHand[index] = {
                instanceId = instance.instanceId,
                cardId = instance.cardId,
                actionTag = type(card) == "table" and card.actionTag or nil,
                handPosition = instance.position,
            }
        end

        return {
            turnNumber = state.turnNumber,
            player = {
                stealth = playerStealth,
                handCount = playerHandCount,
            },
            character = {
                resistance = characterResistance,
                mood = characterMood,
                moodTokens = characterMoodTokens,
            },
            characterHand = characterHand,
            history = projectHistoryContext(state.history),
        }
    end

    local function historyContextEqual(left, right, seen)
        if type(left) ~= type(right) then return false end
        if type(left) ~= "table" then return left == right end
        seen = seen or {}
        if seen[left] ~= nil then return seen[left] == right end
        seen[left] = right
        for key, value in pairs(left) do
            if not historyContextEqual(value, right[key], seen) then return false end
        end
        for key in pairs(right) do
            if left[key] == nil then return false end
        end
        return true
    end

    local function selectionContextEqual(left, right)
        if type(left) ~= "table" or type(right) ~= "table"
            or left.turnNumber ~= right.turnNumber
            or type(left.player) ~= "table" or type(right.player) ~= "table"
            or left.player.stealth ~= right.player.stealth
            or left.player.handCount ~= right.player.handCount
            or type(left.character) ~= "table" or type(right.character) ~= "table"
            or left.character.resistance ~= right.character.resistance
            or left.character.mood ~= right.character.mood
            or not historyContextEqual(left.character.moodTokens, right.character.moodTokens)
            or not historyContextEqual(left.history, right.history)
            or type(left.characterHand) ~= "table" or type(right.characterHand) ~= "table"
            or #left.characterHand ~= #right.characterHand then
            return false
        end
        for index, expected in ipairs(right.characterHand) do
            local actual = left.characterHand[index]
            if type(actual) ~= "table"
                or actual.instanceId ~= expected.instanceId
                or actual.cardId ~= expected.cardId
                or actual.actionTag ~= expected.actionTag
                or actual.handPosition ~= expected.handPosition then
                return false
            end
        end
        return true
    end

    local function callReceiptValidator(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, "스크립트 실행기를 찾을 수 없습니다."
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, tostring(report)
        end
        if type(report) ~= "table" then
            return nil, "하위 검증기가 테이블 결과를 반환하지 않았습니다."
        end
        return report, nil
    end

    local function validateCharacterSelection(selection, state, staticData, referencesValidated, events, path, errors)
        if type(selection) ~= "table" then
            addError(errors, "invalid_character_selection_receipt", path, "캐릭터 선택 영수증이 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(selection, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            turnNumber = true,
            characterId = true,
            selectionContext = true,
            candidates = true,
            weightedPoolInstanceIds = true,
            lethalPriorityApplied = true,
            weightOffset = true,
            rngBefore = true,
            rngAfter = true,
            draw = true,
            selectedInstanceId = true,
            selectedCardId = true,
            publicActionTag = true,
        }, path, errors)

        if selection.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "invalid_selection_schema", path .. ".schemaVersion", "지원하지 않는 캐릭터 선택 영수증 스키마입니다.")
        end
        if selection.kind ~= "characterIntentSelection" then
            addError(errors, "invalid_selection_kind", path .. ".kind", "kind는 characterIntentSelection이어야 합니다.")
        end
        if not isRuntimeId(selection.battleId) then
            addError(errors, "invalid_battle_id", path .. ".battleId", "선택 영수증 battleId가 올바르지 않습니다.")
        elseif selection.battleId ~= state.battleId then
            addError(errors, "selection_battle_mismatch", path .. ".battleId", "선택 영수증 battleId가 현재 전투와 다릅니다.")
        end
        if not isInteger(selection.turnNumber, 1) then
            addError(errors, "invalid_turn_number", path .. ".turnNumber", "선택 영수증 턴 번호는 1 이상의 정수여야 합니다.")
        elseif selection.turnNumber ~= state.turnNumber then
            addError(errors, "selection_turn_mismatch", path .. ".turnNumber", "선택 영수증 턴 번호가 현재 전투와 다릅니다.")
        end
        if not isAsciiId(selection.characterId) then
            addError(errors, "invalid_character_id", path .. ".characterId", "선택 영수증 캐릭터 ID가 올바르지 않습니다.")
        elseif type(state.character) == "table" and selection.characterId ~= state.character.characterId then
            addError(errors, "selection_character_mismatch", path .. ".characterId", "선택 영수증 캐릭터 ID가 현재 전투와 다릅니다.")
        end

        local contextPath = path .. ".selectionContext"
        local contextHandCount = validateSelectionContext(selection.selectionContext, contextPath, errors, staticData)
        if type(selection.selectionContext) == "table" then
            if selection.selectionContext.turnNumber ~= selection.turnNumber then
                addError(errors, "selection_context_turn_mismatch", contextPath .. ".turnNumber", "선택 시점 컨텍스트의 턴 번호가 선택 영수증과 다릅니다.")
            end
            local contextMood = type(selection.selectionContext.character) == "table"
                and selection.selectionContext.character.mood
                or nil
            if referencesValidated and isAsciiId(contextMood) then
                local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
                if type(moods) ~= "table" or moods[contextMood] == nil then
                    addError(errors, "unknown_mood", contextPath .. ".character.mood", "선택 시점 무드가 정적 레지스트리에 없습니다.")
                end
            end
            local expectedContext = referencesValidated and buildExpectedSelectionContext(state, events, staticData) or nil
            if expectedContext ~= nil and not selectionContextEqual(selection.selectionContext, expectedContext) then
                addError(
                    errors,
                    "selection_context_state_mismatch",
                    contextPath,
                    "선택 시점 컨텍스트가 현재 상태와 행동 태그 공개 이후 효과를 역산한 결과와 다릅니다."
                )
            end
        end

        local candidateCount = getArrayLength(selection.candidates, path .. ".candidates", errors)
        local candidateById = {}
        local positionSeen = {}
        if candidateCount ~= nil then
            for index = 1, candidateCount do
                local candidate = selection.candidates[index]
                local candidatePath = path .. ".candidates[" .. index .. "]"
                validateSelectionCandidate(candidate, candidatePath, errors)
                if type(candidate) == "table" then
                    if isRuntimeId(candidate.instanceId) then
                        if candidateById[candidate.instanceId] then
                            addError(errors, "duplicate_selection_candidate", candidatePath .. ".instanceId", "후보 인스턴스 ID가 중복되었습니다.")
                        else
                            candidateById[candidate.instanceId] = candidate
                        end
                    end
                    if isInteger(candidate.handPosition, 1) then
                        if positionSeen[candidate.handPosition] then
                            addError(errors, "duplicate_hand_position", candidatePath .. ".handPosition", "후보 손패 위치가 중복되었습니다.")
                        end
                        positionSeen[candidate.handPosition] = true
                    end
                end
            end
        end

        if candidateCount ~= nil and contextHandCount ~= nil then
            if candidateCount ~= contextHandCount then
                addError(errors, "selection_candidate_count_mismatch", path .. ".candidates", "후보 목록이 선택 시점 캐릭터 손패 전체와 장수가 다릅니다.")
            end
            local comparisonCount = math.min(candidateCount, contextHandCount)
            for index = 1, comparisonCount do
                local candidate = selection.candidates[index]
                local handEntry = selection.selectionContext.characterHand[index]
                local candidatePath = path .. ".candidates[" .. index .. "]"
                if type(candidate) == "table" and type(handEntry) == "table" then
                    if candidate.instanceId ~= handEntry.instanceId
                        or candidate.cardId ~= handEntry.cardId
                        or candidate.actionTag ~= handEntry.actionTag
                        or candidate.handPosition ~= handEntry.handPosition then
                        addError(errors, "selection_candidate_hand_mismatch", candidatePath, "후보의 순서·인스턴스·카드·행동 태그·위치가 선택 시점 손패와 다릅니다.")
                    end
                    local totals = candidate.totals
                    if type(totals) == "table"
                        and isFinite(totals.recoverResistance)
                        and isFinite(totals.loseStealth)
                        and isFinite(totals.damageResistance)
                        and isFinite(totals.recoverStealth)
                        and isSafeInteger(candidate.moodScore) then
                        local directScore = totals.recoverResistance
                            + totals.loseStealth
                            - totals.damageResistance
                            - totals.recoverStealth
                        local expectedScore = directScore * CHARACTER_SCORE_SCALE + candidate.moodScore
                        if candidate.score ~= expectedScore then
                            addError(errors, "selection_score_mismatch", candidatePath .. ".score", "후보 점수가 직접 효과와 무드 평가 합계와 다릅니다.")
                        end
                        local contextStealth = type(selection.selectionContext.player) == "table"
                            and selection.selectionContext.player.stealth
                            or nil
                        if isFinite(contextStealth) then
                            local expectedStealth = contextStealth
                                - totals.loseStealth
                                + totals.recoverStealth
                            if candidate.projectedPlayerStealth ~= expectedStealth then
                                addError(errors, "selection_projection_mismatch", candidatePath .. ".projectedPlayerStealth", "예상 플레이어 은폐가 선택 시점 효과 합계와 다릅니다.")
                            end
                        end
                    end
                    if referencesValidated and isAsciiId(candidate.cardId) then
                        local card = staticData.cards[candidate.cardId]
                        local expectedCharges = 0
                        if type(card) == "table"
                            and type(card.mechanisms) == "table" then
                            for _, mechanismId in ipairs(card.mechanisms) do
                                if mechanismId == "plan" then
                                    local plan = type(card.mechanismData) == "table" and card.mechanismData.plan or nil
                                    expectedCharges = type(plan) == "table" and plan.charges or nil
                                    break
                                end
                            end
                        end
                        if candidate.planChargesEvaluated ~= expectedCharges then
                            addError(errors, "selection_plan_charges_mismatch", candidatePath .. ".planChargesEvaluated", "평가한 계획 충전 수가 정적 카드 정의와 다릅니다.")
                        end
                    end
                end
            end
        end

        if referencesValidated and type(selection.selectionContext) == "table" then
            local replayReport, replayCallError = callReceiptValidator(
                "characterSelector",
                "validateReceipt",
                staticData,
                selection
            )
            if replayCallError ~= nil then
                addError(errors, "selection_replay_unavailable", path, "캐릭터 선택 효과 재생 검증을 실행할 수 없습니다: " .. replayCallError)
            elseif replayReport.ok ~= true then
                local nestedErrors = type(replayReport.errors) == "table" and replayReport.errors or {}
                if #nestedErrors == 0 then
                    addError(errors, "selection_replay_failed", path, "캐릭터 선택 효과 재생 검증이 실패했습니다.")
                else
                    for _, nested in ipairs(nestedErrors) do
                        local nestedPath = type(nested) == "table" and nested.path or "$"
                        if type(nestedPath) == "string" and string.sub(nestedPath, 1, 9) == "$.receipt" then
                            nestedPath = path .. string.sub(nestedPath, 10)
                        else
                            nestedPath = path
                        end
                        addError(
                            errors,
                            type(nested) == "table" and tostring(nested.code) or "selection_replay_failed",
                            nestedPath,
                            type(nested) == "table" and tostring(nested.message) or "캐릭터 선택 효과 재생 검증이 실패했습니다."
                        )
                    end
                end
            elseif replayReport.valid ~= true then
                addError(errors, "selection_replay_failed", path, "캐릭터 선택 효과 재생 검증기가 valid 결과를 반환하지 않았습니다.")
            end
        end

        validateIdArray(selection.weightedPoolInstanceIds, path .. ".weightedPoolInstanceIds", errors, isRuntimeId)
        local poolCount = type(selection.weightedPoolInstanceIds) == "table" and #selection.weightedPoolInstanceIds or 0
        local poolIdSet = {}
        for index, instanceId in ipairs(type(selection.weightedPoolInstanceIds) == "table" and selection.weightedPoolInstanceIds or {}) do
            if candidateById[instanceId] == nil then
                addError(errors, "unknown_selection_pool_candidate", path .. ".weightedPoolInstanceIds[" .. index .. "]", "가중 추첨 후보가 candidates에 없습니다.")
            elseif poolIdSet[instanceId] then
                addError(errors, "duplicate_selection_pool_candidate", path .. ".weightedPoolInstanceIds[" .. index .. "]", "가중 추첨 후보가 중복되었습니다.")
            else
                poolIdSet[instanceId] = true
            end
        end

        if selection.lethalPriorityApplied ~= true and selection.lethalPriorityApplied ~= false then
            addError(errors, "invalid_lethal_priority", path .. ".lethalPriorityApplied", "lethalPriorityApplied는 불리언이어야 합니다.")
        end
        local beforeValid = validateReceiptRng(selection.rngBefore, path .. ".rngBefore", errors)
        local afterValid = validateReceiptRng(selection.rngAfter, path .. ".rngAfter", errors)
        if beforeValid and afterValid then
            if selection.rngAfter.seed ~= selection.rngBefore.seed then
                addError(errors, "receipt_rng_seed_changed", path .. ".rngAfter.seed", "캐릭터 선택 중 RNG seed가 바뀔 수 없습니다.")
            end
            if selection.rngAfter.cursor < selection.rngBefore.cursor then
                addError(errors, "receipt_rng_reversed", path .. ".rngAfter.cursor", "캐릭터 선택 중 RNG cursor가 이전으로 돌아갈 수 없습니다.")
            end
        end
        validateSelectionDraw(selection.draw, path .. ".draw", errors)

        local intent = type(state) == "table" and state.characterIntent or nil
        local intentIds = type(intent) == "table" and intent.cardInstanceIds or nil
        local selected = selection.selectedInstanceId ~= nil
        if not selected then
            if selection.selectedCardId ~= nil
                or selection.publicActionTag ~= nil
                or selection.weightOffset ~= nil then
                addError(errors, "selection_pass_field_conflict", path, "패스 영수증에는 선택 카드 필드를 둘 수 없습니다.")
            end
            if type(selection.draw) ~= "table" or selection.draw.kind ~= "pass" then
                addError(errors, "selection_pass_draw_mismatch", path .. ".draw", "패스 영수증의 draw.kind는 pass여야 합니다.")
            end
            if candidateCount ~= nil and candidateCount ~= 0 then
                addError(errors, "selection_pass_has_candidates", path .. ".candidates", "패스 영수증에는 후보가 없어야 합니다.")
            end
            if poolCount ~= 0 then
                addError(errors, "selection_pass_has_pool", path .. ".weightedPoolInstanceIds", "패스 영수증에는 가중 추첨 후보가 없어야 합니다.")
            end
            if selection.lethalPriorityApplied ~= false then
                addError(errors, "selection_pass_lethal_priority", path .. ".lethalPriorityApplied", "패스에는 치명 우선순위를 적용할 수 없습니다.")
            end
            if beforeValid and afterValid and not rngEqual(selection.rngBefore, selection.rngAfter) then
                addError(errors, "selection_pass_consumed_rng", path .. ".rngAfter", "패스는 RNG를 소비할 수 없습니다.")
            end
            if type(intentIds) ~= "table" or #intentIds ~= 0 or (type(intent) == "table" and intent.publicActionTag ~= nil) then
                addError(errors, "character_selection_intent_mismatch", "$.characterIntent", "패스 영수증과 현재 characterIntent가 다릅니다.")
            end
            return
        end

        if not isRuntimeId(selection.selectedInstanceId) then
            addError(errors, "invalid_instance_id", path .. ".selectedInstanceId", "선택한 카드 인스턴스 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(selection.selectedCardId) then
            addError(errors, "invalid_card_id", path .. ".selectedCardId", "선택한 카드 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(selection.publicActionTag) then
            addError(errors, "invalid_action_tag", path .. ".publicActionTag", "선택한 공개 행동 태그가 올바르지 않습니다.")
        end
        if not isSafeInteger(selection.weightOffset, 0) then
            addError(errors, "invalid_selection_weight_offset", path .. ".weightOffset", "점수 가중치 평행이동 값은 0 이상의 안전한 정수여야 합니다.")
        end
        if type(selection.draw) ~= "table"
            or (selection.draw.kind ~= "single" and selection.draw.kind ~= "weighted") then
            addError(errors, "selection_selected_draw_mismatch", path .. ".draw", "선택 영수증은 single 또는 weighted 추첨을 사용해야 합니다.")
        end
        if candidateCount == 0 then
            addError(errors, "selection_missing_candidates", path .. ".candidates", "선택 영수증에는 후보가 필요합니다.")
        end
        if poolCount == 0 then
            addError(errors, "selection_missing_weighted_pool", path .. ".weightedPoolInstanceIds", "선택 영수증에는 가중 추첨 후보가 필요합니다.")
        end

        local selectedCandidate = candidateById[selection.selectedInstanceId]
        if selectedCandidate == nil then
            addError(errors, "selected_candidate_missing", path .. ".selectedInstanceId", "선택한 인스턴스가 candidates에 없습니다.")
        else
            if selectedCandidate.cardId ~= selection.selectedCardId then
                addError(errors, "selected_card_mismatch", path .. ".selectedCardId", "선택 카드 ID가 후보와 다릅니다.")
            end
            if selectedCandidate.actionTag ~= selection.publicActionTag then
                addError(errors, "selected_action_tag_mismatch", path .. ".publicActionTag", "선택 행동 태그가 후보와 다릅니다.")
            end
        end

        local anyLethal = false
        if type(selection.candidates) == "table" then
            for _, candidate in ipairs(selection.candidates) do
                if type(candidate) == "table" and candidate.lethal == true then
                    anyLethal = true
                    break
                end
            end
        end
        if (selection.lethalPriorityApplied == true) ~= anyLethal then
            addError(errors, "lethal_priority_mismatch", path .. ".lethalPriorityApplied", "치명 우선순위가 후보의 lethal 값과 다릅니다.")
        end

        local expectedPool = {}
        local expectedPoolSet = {}
        local minimumPoolScore = nil
        local anyPositivePoolScore = false
        if type(selection.candidates) == "table" then
            for _, candidate in ipairs(selection.candidates) do
                if type(candidate) == "table"
                    and isRuntimeId(candidate.instanceId)
                    and isSafeInteger(candidate.score)
                    and (not anyLethal or candidate.lethal == true) then
                    expectedPool[#expectedPool + 1] = candidate.instanceId
                    expectedPoolSet[candidate.instanceId] = true
                    if minimumPoolScore == nil or candidate.score < minimumPoolScore then
                        minimumPoolScore = candidate.score
                    end
                    if candidate.score > 0 then
                        anyPositivePoolScore = true
                    end
                end
            end
        end

        local poolMatches = #expectedPool == poolCount
        if poolMatches then
            for index = 1, poolCount do
                if expectedPool[index] ~= selection.weightedPoolInstanceIds[index] then
                    poolMatches = false
                    break
                end
            end
        end
        if not poolMatches then
            addError(errors, "selection_weighted_pool_mismatch", path .. ".weightedPoolInstanceIds", "가중 추첨 후보 배열이 치명 우선순위 결과와 다릅니다.")
        end

        local expectedOffset = nil
        if minimumPoolScore ~= nil then
            expectedOffset = anyPositivePoolScore and 0 or (1 - minimumPoolScore)
            if not isSafeInteger(expectedOffset, 0) then
                addError(errors, "invalid_selection_weight_offset", path .. ".weightOffset", "후보 점수에서 안전한 평행이동 값을 계산할 수 없습니다.")
            elseif selection.weightOffset ~= expectedOffset then
                addError(errors, "selection_weight_offset_mismatch", path .. ".weightOffset", "점수 가중치 평행이동 값이 후보 점수와 다릅니다.")
            end
        end

        local totalWeight = 0
        if type(selection.candidates) == "table" then
            for index, candidate in ipairs(selection.candidates) do
                if type(candidate) == "table" and isSafeInteger(candidate.score) then
                    local expectedWeight = 0
                    if expectedPoolSet[candidate.instanceId] and isSafeInteger(expectedOffset, 0) then
                        local adjusted = candidate.score + expectedOffset
                        if isSafeInteger(adjusted) and adjusted > 0 then
                            expectedWeight = adjusted
                        end
                    end
                    if candidate.weight ~= expectedWeight then
                        addError(errors, "selection_weight_mismatch", path .. ".candidates[" .. index .. "].weight", "후보 가중치가 총효과 점수 정책과 다릅니다.")
                    end
                    if expectedPoolSet[candidate.instanceId] and isSafeInteger(expectedWeight, 0) then
                        if isSafeInteger(totalWeight + expectedWeight, 0) then
                            totalWeight = totalWeight + expectedWeight
                        else
                            addError(errors, "selection_total_weight_overflow", path .. ".candidates", "가중 추첨 총합이 안전한 정수 범위를 벗어났습니다.")
                        end
                    end
                end
            end
        end
        if totalWeight <= 0 and poolCount > 0 then
            addError(errors, "selection_zero_total_weight", path .. ".candidates", "가중 추첨 후보의 총 가중치는 1 이상이어야 합니다.")
        end
        if selectedCandidate ~= nil and not expectedPoolSet[selection.selectedInstanceId] then
            addError(errors, "selected_candidate_outside_pool", path .. ".selectedInstanceId", "선택된 카드는 가중 추첨 후보에 포함되어야 합니다.")
        end

        local draw = selection.draw
        if type(draw) == "table" and draw.kind == "single" then
            if poolCount ~= 1 or selection.weightedPoolInstanceIds[1] ~= selection.selectedInstanceId then
                addError(errors, "single_draw_mismatch", path .. ".draw", "single 추첨은 유일한 가중 추첨 후보를 선택해야 합니다.")
            elseif draw.totalWeight ~= totalWeight then
                addError(errors, "draw_weight_mismatch", path .. ".draw.totalWeight", "single 총 가중치가 후보 가중치와 다릅니다.")
            end
            if beforeValid and afterValid and not rngEqual(selection.rngBefore, selection.rngAfter) then
                addError(errors, "single_selection_consumed_rng", path .. ".rngAfter", "single 선택은 RNG를 소비할 수 없습니다.")
            end
        elseif type(draw) == "table" and draw.kind == "weighted" then
            if poolCount < 2 then
                addError(errors, "weighted_draw_missing_candidates", path .. ".weightedPoolInstanceIds", "weighted 추첨에는 후보가 둘 이상 필요합니다.")
            end
            if draw.totalWeight ~= totalWeight then
                addError(errors, "draw_weight_mismatch", path .. ".draw.totalWeight", "weighted 총 가중치가 추첨 후보 가중치 합과 다릅니다.")
            end
            if isSafeInteger(draw.roll, 1) then
                local cumulative = 0
                local rolledInstanceId = nil
                for _, instanceId in ipairs(type(selection.weightedPoolInstanceIds) == "table" and selection.weightedPoolInstanceIds or {}) do
                    local candidate = candidateById[instanceId]
                    if candidate and isSafeInteger(candidate.weight, 0) then
                        cumulative = cumulative + candidate.weight
                        if candidate.weight > 0 and draw.roll <= cumulative then
                            rolledInstanceId = instanceId
                            break
                        end
                    end
                end
                if rolledInstanceId ~= selection.selectedInstanceId then
                    addError(errors, "weighted_result_mismatch", path .. ".selectedInstanceId", "weighted roll 결과와 선택 인스턴스가 다릅니다.")
                end
            end
            if beforeValid and isSafeInteger(totalWeight, 1) then
                local rngReplay, rngReplayCallError = callReceiptValidator(
                    "deterministicRng",
                    "nextInteger",
                    selection.rngBefore,
                    1,
                    totalWeight
                )
                if rngReplayCallError ~= nil then
                    addError(errors, "selection_rng_replay_unavailable", path .. ".draw", "선택 RNG를 재생할 수 없습니다: " .. rngReplayCallError)
                elseif rngReplay.ok ~= true then
                    addError(errors, "selection_rng_replay_failed", path .. ".draw", "결정적 선택 RNG 재생이 실패했습니다.")
                else
                    if rngReplay.value ~= draw.roll then
                        addError(errors, "selection_roll_replay_mismatch", path .. ".draw.roll", "기록된 roll이 rngBefore와 총 가중치의 결정적 재생 결과와 다릅니다.")
                    end
                    if afterValid and not rngEqual(rngReplay.rng, selection.rngAfter) then
                        addError(errors, "selection_rng_after_replay_mismatch", path .. ".rngAfter", "기록된 rngAfter가 결정적 가중 추첨 재생 결과와 다릅니다.")
                    end
                end
            end
            if beforeValid and afterValid and selection.rngAfter.cursor <= selection.rngBefore.cursor then
                addError(errors, "weighted_selection_rng_missing", path .. ".rngAfter.cursor", "weighted 선택은 RNG cursor를 전진시켜야 합니다.")
            end
        end

        if type(intentIds) ~= "table"
            or #intentIds ~= 1
            or intentIds[1] ~= selection.selectedInstanceId
            or type(intent) ~= "table"
            or intent.publicActionTag ~= selection.publicActionTag then
            addError(errors, "character_selection_intent_mismatch", "$.characterIntent", "선택 영수증과 현재 characterIntent가 다릅니다.")
        end

        local instance = findStateInstance(state, selection.selectedInstanceId)
        if instance == nil
            or instance.owner ~= "character"
            or instance.zone ~= "hand"
            or instance.cardId ~= selection.selectedCardId then
            addError(errors, "selected_instance_mismatch", path .. ".selectedInstanceId", "선택 인스턴스가 현재 캐릭터 손패·카드와 일치하지 않습니다.")
        end
        if referencesValidated and isAsciiId(selection.selectedCardId) then
            local card = staticData.cards[selection.selectedCardId]
            if type(card) ~= "table"
                or card.owner ~= "character"
                or card.actionTag ~= selection.publicActionTag then
                addError(errors, "selected_static_card_mismatch", path .. ".selectedCardId", "선택 카드와 정적 카드 행동 태그가 일치하지 않습니다.")
            end
        end
    end

    local function validateTurnStartReceipt(receipt, state, staticData, referencesValidated, errors)
        local path = "$.turnStartReceipt"
        if type(receipt) ~= "table" then
            addError(errors, "invalid_turn_start_receipt", path, "turnStartReceipt가 객체가 아닙니다.")
            return
        end

        checkAllowedKeys(receipt, {
            schemaVersion = true,
            kind = true,
            turnId = true,
            turnNumber = true,
            authorityFingerprint = true,
            draws = true,
            characterSelection = true,
            baseline = true,
            transient = true,
            events = true,
        }, path, errors)
        if receipt.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "invalid_receipt_schema", path .. ".schemaVersion", "지원하지 않는 turnStartReceipt 스키마입니다.")
        end
        if receipt.kind ~= "turnStartReceipt" then
            addError(errors, "invalid_receipt_kind", path .. ".kind", "kind는 turnStartReceipt여야 합니다.")
        end
        if not isRuntimeId(receipt.turnId) then
            addError(errors, "invalid_turn_id", path .. ".turnId", "turnStartReceipt turnId가 올바르지 않습니다.")
        elseif state.lastCommittedTurnId == receipt.turnId then
            addError(errors, "turn_already_committed", path .. ".turnId", "이미 확정한 turnId를 현재 턴 초기화에 사용할 수 없습니다.")
        end
        if not isInteger(receipt.turnNumber, 1) then
            addError(errors, "invalid_turn_number", path .. ".turnNumber", "turnStartReceipt 턴 번호는 1 이상의 정수여야 합니다.")
        elseif receipt.turnNumber ~= state.turnNumber then
            addError(errors, "receipt_turn_mismatch", path .. ".turnNumber", "turnStartReceipt 턴 번호가 현재 전투 턴과 다릅니다.")
        end
        if state.status ~= "active" then
            addError(errors, "receipt_requires_active", path, "turnStartReceipt는 active 전투 상태에만 존재할 수 있습니다.")
        end

        local fingerprintPath = path .. ".authorityFingerprint"
        local fingerprintValid = validateAuthorityFingerprint(receipt.authorityFingerprint, fingerprintPath, errors)
        if fingerprintValid then
            local expectedFingerprint, fingerprintError = fingerprintAuthorityState(state)
            if fingerprintError then
                addError(errors, fingerprintError.code, fingerprintError.path, fingerprintError.message)
            elseif receipt.authorityFingerprint.algorithm ~= expectedFingerprint.algorithm
                or receipt.authorityFingerprint.length ~= expectedFingerprint.length
                or receipt.authorityFingerprint.hashA ~= expectedFingerprint.hashA
                or receipt.authorityFingerprint.hashB ~= expectedFingerprint.hashB then
                addError(
                    errors,
                    "receipt_authority_mismatch",
                    fingerprintPath,
                    "turnStartReceipt가 현재 권위 battleState와 일치하지 않습니다."
                )
            end
        end

        validateDraws(receipt.draws, state, path .. ".draws", errors)
        validateCharacterSelection(
            receipt.characterSelection,
            state,
            staticData,
            referencesValidated,
            receipt.events,
            path .. ".characterSelection",
            errors
        )
        local characterDrawAfter = type(receipt.draws) == "table"
            and type(receipt.draws.character) == "table"
            and receipt.draws.character.rngAfter
            or nil
        local selectionRngBefore = type(receipt.characterSelection) == "table"
            and receipt.characterSelection.rngBefore
            or nil
        if type(characterDrawAfter) == "table"
            and type(selectionRngBefore) == "table"
            and not rngEqual(characterDrawAfter, selectionRngBefore) then
            addError(
                errors,
                "receipt_rng_discontinuity",
                path .. ".characterSelection.rngBefore",
                "캐릭터 선택 RNG 시작점이 캐릭터 드로우 종료점과 다릅니다."
            )
        end

        local baseline = receipt.baseline
        if type(baseline) ~= "table" then
            addError(errors, "invalid_receipt_baseline", path .. ".baseline", "turnStartReceipt baseline이 객체가 아닙니다.")
        else
            checkAllowedKeys(baseline, {
                stealth = true,
                resistance = true,
                mood = true,
                moodTokens = true,
            }, path .. ".baseline", errors)
            if not isFinite(baseline.stealth) then
                addError(errors, "invalid_receipt_baseline", path .. ".baseline.stealth", "baseline 은폐가 유한한 숫자가 아닙니다.")
            end
            if not isFinite(baseline.resistance) then
                addError(errors, "invalid_receipt_baseline", path .. ".baseline.resistance", "baseline 저항이 유한한 숫자가 아닙니다.")
            end
            if not isAsciiId(baseline.mood) then
                addError(errors, "invalid_receipt_baseline", path .. ".baseline.mood", "baseline 무드 ID가 올바르지 않습니다.")
            elseif referencesValidated then
                local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
                if type(moods) ~= "table" or not moods[baseline.mood] then
                    addError(errors, "unknown_mood", path .. ".baseline.mood", "baseline 무드가 레지스트리에 없습니다.")
                end
            end
            if type(baseline.moodTokens) ~= "table" then
                addError(errors, "invalid_receipt_baseline", path .. ".baseline.moodTokens", "baseline 무드 토큰이 객체가 아닙니다.")
            elseif referencesValidated then
                local moods = staticData.registry.moods
                for moodId in pairs(moods) do
                    if not isSafeInteger(baseline.moodTokens[moodId], 0) then
                        addError(errors, "invalid_mood_token_count", path .. ".baseline.moodTokens." .. moodId, "무드 토큰 수는 0 이상의 안전한 정수여야 합니다.")
                    end
                end
                for moodId in pairs(baseline.moodTokens) do
                    if not moods[moodId] then
                        addError(errors, "unknown_mood", path .. ".baseline.moodTokens." .. tostring(moodId), "등록되지 않은 무드의 토큰입니다.")
                    end
                end
            end
        end

        local transient = receipt.transient
        if type(transient) ~= "table" then
            addError(errors, "invalid_receipt_transient", path .. ".transient", "turnStartReceipt transient가 객체가 아닙니다.")
        else
            checkAllowedKeys(transient, {
                skipRemaining = true,
                forcedMoodRequests = true,
            }, path .. ".transient", errors)

            local skipRemaining = transient.skipRemaining
            if type(skipRemaining) ~= "table" then
                addError(errors, "invalid_skip_state", path .. ".transient.skipRemaining", "skipRemaining이 객체가 아닙니다.")
            else
                checkAllowedKeys(skipRemaining, {
                    player = true,
                    character = true,
                }, path .. ".transient.skipRemaining", errors)
                for _, side in ipairs({ "player", "character" }) do
                    if skipRemaining[side] ~= true and skipRemaining[side] ~= false then
                        addError(errors, "invalid_skip_state", path .. ".transient.skipRemaining." .. side, "skipRemaining 값은 불리언이어야 합니다.")
                    end
                end
            end

            local forcedRequestCount = getArrayLength(
                transient.forcedMoodRequests,
                path .. ".transient.forcedMoodRequests",
                errors
            )
            if forcedRequestCount then
                for index = 1, forcedRequestCount do
                    local request = transient.forcedMoodRequests[index]
                    local requestPath = path .. ".transient.forcedMoodRequests[" .. index .. "]"
                    if type(request) ~= "table" then
                        addError(errors, "invalid_forced_mood_request", requestPath, "무드 강제 변경 요청이 객체가 아닙니다.")
                    else
                        checkAllowedKeys(request, {
                            mood = true,
                            cause = true,
                        }, requestPath, errors)
                        if not isAsciiId(request.mood) then
                            addError(errors, "invalid_forced_mood_request", requestPath .. ".mood", "강제 변경 무드 ID가 올바르지 않습니다.")
                        elseif referencesValidated and not staticData.registry.moods[request.mood] then
                            addError(errors, "unknown_mood", requestPath .. ".mood", "강제 변경 무드가 레지스트리에 없습니다.")
                        end
                        if not isAsciiId(request.cause) then
                            addError(errors, "invalid_forced_mood_cause", requestPath .. ".cause", "강제 변경 cause는 lower_snake_case여야 합니다.")
                        end
                    end
                end
            end
        end

        validateTurnStartEvents(receipt.events, receipt.turnId, path .. ".events", errors)
    end

    local function subwayStationsAdjacent(line, leftId, rightId)
        for _, routePath in ipairs(type(line) == "table" and line.paths or {}) do
            local stations = routePath.stations
            for index = 1, #stations - 1 do
                local left = stations[index].id
                local right = stations[index + 1].id
                if (left == leftId and right == rightId)
                    or (left == rightId and right == leftId) then
                    return true
                end
            end
            if routePath.circular == true and #stations > 1 then
                local first = stations[1].id
                local last = stations[#stations].id
                if (first == leftId and last == rightId)
                    or (first == rightId and last == leftId) then
                    return true
                end
            end
        end
        return false
    end

    local function subwayStationExists(line, stationId)
        for _, routePath in ipairs(type(line) == "table" and line.paths or {}) do
            for _, station in ipairs(routePath.stations or {}) do
                if station.id == stationId then
                    return true
                end
            end
        end
        return false
    end

    local function transitEqual(left, right)
        if type(left) ~= "table" or type(right) ~= "table"
            or left.algorithm ~= right.algorithm
            or left.lineId ~= right.lineId
            or type(left.stationIds) ~= "table"
            or type(right.stationIds) ~= "table"
            or #left.stationIds ~= #right.stationIds then
            return false
        end
        for index = 1, #left.stationIds do
            if left.stationIds[index] ~= right.stationIds[index] then
                return false
            end
        end
        return true
    end

    local function validateTransit(transit, turnLimit, staticData, errors)
        local path = "$.transit"
        if type(transit) ~= "table" then
            addError(errors, "invalid_transit", path, "전투 이동 구간이 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(transit, {
            algorithm = true,
            lineId = true,
            stationIds = true,
        }, path, errors)
        if transit.algorithm ~= "tokyo_subway_segment_v1" then
            addError(errors, "invalid_transit_algorithm", path .. ".algorithm", "지원하지 않는 지하철 여정 알고리즘입니다.")
        end
        if not isAsciiId(transit.lineId) then
            addError(errors, "invalid_transit_line_id", path .. ".lineId", "지하철 노선 ID가 올바르지 않습니다.")
        end
        local stationCount = getArrayLength(transit.stationIds, path .. ".stationIds", errors)
        if stationCount ~= nil then
            if isInteger(turnLimit, 1) and stationCount ~= turnLimit + 1 then
                addError(errors, "transit_length_mismatch", path .. ".stationIds", "이동 역 수는 제한 턴보다 하나 많아야 합니다.")
            end
            local seen = {}
            for index = 1, stationCount do
                local stationId = transit.stationIds[index]
                if not isAsciiId(stationId) then
                    addError(errors, "invalid_transit_station_id", path .. ".stationIds[" .. index .. "]", "이동 역 ID가 올바르지 않습니다.")
                elseif seen[stationId] then
                    addError(errors, "duplicate_transit_station", path .. ".stationIds[" .. index .. "]", "한 여정에서 같은 역을 두 번 지날 수 없습니다.")
                else
                    seen[stationId] = true
                end
            end
        end

        if type(staticData) == "table" and type(staticData.subwayLines) == "table" then
            local line = staticData.subwayLines[transit.lineId]
            if type(line) ~= "table" then
                addError(errors, "unknown_transit_line", path .. ".lineId", "정적 DB에서 지하철 노선을 찾을 수 없습니다.")
            elseif stationCount ~= nil then
                for index = 1, stationCount do
                    local stationId = transit.stationIds[index]
                    if isAsciiId(stationId) and not subwayStationExists(line, stationId) then
                        addError(errors, "unknown_transit_station", path .. ".stationIds[" .. index .. "]", "선택 노선에서 이동 역을 찾을 수 없습니다.")
                    end
                    if index > 1 then
                        local previousId = transit.stationIds[index - 1]
                        if isAsciiId(previousId)
                            and isAsciiId(stationId)
                            and not subwayStationsAdjacent(line, previousId, stationId) then
                            addError(errors, "non_adjacent_transit_station", path .. ".stationIds[" .. index .. "]", "이동 구간에 서로 인접하지 않은 역이 있습니다.")
                        end
                    end
                end
            end
        end
    end

    local function validateBattleState(state, staticData)
        local errors = {}
        local staticDataProvided = staticData ~= nil
        staticData = normalizeStaticData(staticData)
        local referencesValidated = hasCompleteStaticData(staticData)

        if staticDataProvided and not referencesValidated then
            addError(errors, "invalid_static_data", "$", "전달한 정적 데이터가 전체 참조 검증에 필요한 컬렉션을 갖추지 못했습니다.")
        end
        if not referencesValidated then
            staticData = nil
        end

        if type(state) ~= "table" then
            addError(errors, "invalid_state", "$", "battleState가 테이블이 아닙니다.")
            return result(errors)
        end

        validateJsonSafe(state, "$", errors)
        if #errors > 0 then
            local report = result(errors)
            report.referencesValidated = referencesValidated
            return report
        end
        checkAllowedKeys(state, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            status = true,
            turnNumber = true,
            turnLimit = true,
            environmentId = true,
            transit = true,
            lastCommittedTurnId = true,
            rng = true,
            player = true,
            character = true,
            cardInstances = true,
            selection = true,
            characterIntent = true,
            history = true,
            turnStartReceipt = true,
        }, "$", errors)

        if state.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_schema", "$.schemaVersion", "지원하지 않는 battleState 스키마 버전입니다.")
        end
        if state.kind ~= "battleState" then
            addError(errors, "invalid_kind", "$.kind", "kind는 battleState여야 합니다.")
        end
        if not isRuntimeId(state.battleId) then
            addError(errors, "invalid_battle_id", "$.battleId", "battleId가 올바르지 않습니다.")
        end
        if not VALID_STATUS[state.status] then
            addError(errors, "invalid_status", "$.status", "알 수 없는 전투 상태입니다.")
        end
        if not isInteger(state.turnNumber, 1) then
            addError(errors, "invalid_turn_number", "$.turnNumber", "현재 턴은 1 이상의 정수여야 합니다.")
        end
        if not isInteger(state.turnLimit, 7) or state.turnLimit > 12 then
            addError(errors, "invalid_turn_limit", "$.turnLimit", "제한 턴은 7 이상 12 이하의 정수여야 합니다.")
        elseif isInteger(state.turnNumber, 1) and state.turnNumber > state.turnLimit then
            addError(errors, "turn_over_limit", "$.turnNumber", "현재 턴이 제한 턴을 초과했습니다.")
        end
        if not isAsciiId(state.environmentId) then
            addError(errors, "invalid_environment_id", "$.environmentId", "환경 ID가 올바르지 않습니다.")
        end
        validateTransit(state.transit, state.turnLimit, staticData, errors)
        if state.lastCommittedTurnId ~= nil and not isRuntimeId(state.lastCommittedTurnId) then
            addError(errors, "invalid_turn_id", "$.lastCommittedTurnId", "마지막 확정 턴 ID가 올바르지 않습니다.")
        end

        if type(state.rng) ~= "table" then
            addError(errors, "invalid_rng", "$.rng", "rng가 테이블이 아닙니다.")
        else
            checkAllowedKeys(state.rng, { seed = true, cursor = true }, "$.rng", errors)
            if not isSafeInteger(state.rng.seed, 0) then
                addError(errors, "invalid_rng_seed", "$.rng.seed", "난수 시드는 0 이상이고 안전한 숫자 범위 안의 정수여야 합니다.")
            end
            if not isSafeInteger(state.rng.cursor, 0) then
                addError(errors, "invalid_rng_cursor", "$.rng.cursor", "난수 커서는 0 이상이고 안전한 숫자 범위 안의 정수여야 합니다.")
            end
        end

        if type(state.player) ~= "table" then
            addError(errors, "invalid_player", "$.player", "player가 테이블이 아닙니다.")
        else
            checkAllowedKeys(state.player, {
                stealth = true,
                baseDrawCount = true,
                maxHandSize = true,
                perkIds = true,
                planCapacity = true,
                planSlots = true,
            }, "$.player", errors)
            if not isFinite(state.player.stealth) then
                addError(errors, "invalid_stealth", "$.player.stealth", "은폐는 유한한 숫자여야 합니다.")
            end
            if not isInteger(state.player.baseDrawCount, 1) then
                addError(errors, "invalid_base_draw_count", "$.player.baseDrawCount", "기본 드로우 수는 1 이상의 정수여야 합니다.")
            end
            if not isInteger(state.player.maxHandSize, 1) then
                addError(errors, "invalid_hand_size", "$.player.maxHandSize", "최대 손패는 1 이상의 정수여야 합니다.")
            end
            if isInteger(state.player.baseDrawCount, 1)
                and isInteger(state.player.maxHandSize, 1)
                and state.player.baseDrawCount > state.player.maxHandSize then
                addError(errors, "draw_exceeds_hand_limit", "$.player.baseDrawCount", "기본 드로우 수는 최대 손패보다 클 수 없습니다.")
            end
            validateIdArray(state.player.perkIds, "$.player.perkIds", errors, isAsciiId)
        end

        if type(state.character) ~= "table" then
            addError(errors, "invalid_character", "$.character", "character가 테이블이 아닙니다.")
        else
            checkAllowedKeys(state.character, {
                characterId = true,
                resistance = true,
                mood = true,
                moodTokens = true,
                traitIds = true,
                baseDrawCount = true,
                maxHandSize = true,
                planCapacity = true,
                planSlots = true,
            }, "$.character", errors)
            if not isAsciiId(state.character.characterId) then
                addError(errors, "invalid_character_id", "$.character.characterId", "캐릭터 ID가 올바르지 않습니다.")
            end
            if not isFinite(state.character.resistance) then
                addError(errors, "invalid_resistance", "$.character.resistance", "저항은 유한한 숫자여야 합니다.")
            end
            if not isAsciiId(state.character.mood) then
                addError(errors, "invalid_mood", "$.character.mood", "무드 ID가 올바르지 않습니다.")
            end
            if state.character.moodTokens ~= nil then
                if type(state.character.moodTokens) ~= "table" then
                    addError(errors, "invalid_mood_tokens", "$.character.moodTokens", "무드 토큰이 객체가 아닙니다.")
                elseif referencesValidated then
                    local moods = staticData.registry.moods
                    for moodId in pairs(moods) do
                        if not isSafeInteger(state.character.moodTokens[moodId], 0) then
                            addError(errors, "invalid_mood_token_count", "$.character.moodTokens." .. moodId, "무드 토큰 수는 0 이상의 안전한 정수여야 합니다.")
                        end
                    end
                    for moodId in pairs(state.character.moodTokens) do
                        if not moods[moodId] then
                            addError(errors, "unknown_mood", "$.character.moodTokens." .. tostring(moodId), "등록되지 않은 무드의 토큰입니다.")
                        end
                    end
                end
            end
            if not isInteger(state.character.baseDrawCount, 1) then
                addError(errors, "invalid_base_draw_count", "$.character.baseDrawCount", "기본 드로우 수는 1 이상의 정수여야 합니다.")
            end
            if not isInteger(state.character.maxHandSize, 1) then
                addError(errors, "invalid_hand_size", "$.character.maxHandSize", "최대 손패는 1 이상의 정수여야 합니다.")
            end
            if isInteger(state.character.baseDrawCount, 1)
                and isInteger(state.character.maxHandSize, 1)
                and state.character.baseDrawCount > state.character.maxHandSize then
                addError(errors, "draw_exceeds_hand_limit", "$.character.baseDrawCount", "기본 드로우 수는 최대 손패보다 클 수 없습니다.")
            end
            validateIdArray(state.character.traitIds, "$.character.traitIds", errors, isAsciiId)
        end

        local instances = {}
        local positions = {}
        local instanceCount = getArrayLength(state.cardInstances, "$.cardInstances", errors)
        if instanceCount then
            for index = 1, instanceCount do
                local item = state.cardInstances[index]
                local path = "$.cardInstances[" .. index .. "]"
                if type(item) ~= "table" then
                    addError(errors, "invalid_card_instance", path, "카드 인스턴스가 테이블이 아닙니다.")
                else
                    checkAllowedKeys(item, {
                        instanceId = true,
                        cardId = true,
                        owner = true,
                        zone = true,
                        position = true,
                        temporaryModifiers = true,
                    }, path, errors)
                    if not isRuntimeId(item.instanceId) then
                        addError(errors, "invalid_instance_id", path .. ".instanceId", "카드 인스턴스 ID가 올바르지 않습니다.")
                    elseif instances[item.instanceId] then
                        addError(errors, "duplicate_instance_id", path .. ".instanceId", "카드 인스턴스 ID가 중복되었습니다.")
                    else
                        instances[item.instanceId] = item
                    end
                    if not isAsciiId(item.cardId) then
                        addError(errors, "invalid_card_id", path .. ".cardId", "카드 ID가 올바르지 않습니다.")
                    end
                    if not VALID_OWNER[item.owner] then
                        addError(errors, "invalid_owner", path .. ".owner", "카드 소유자가 올바르지 않습니다.")
                    end
                    if not VALID_ZONE[item.zone] then
                        addError(errors, "invalid_zone", path .. ".zone", "카드 영역이 올바르지 않습니다.")
                    end
                    if not isInteger(item.position, 1) then
                        addError(errors, "invalid_position", path .. ".position", "카드 위치는 1 이상의 정수여야 합니다.")
                    elseif VALID_OWNER[item.owner] and VALID_ZONE[item.zone] then
                        local group = item.owner .. ":" .. item.zone
                        positions[group] = positions[group] or {}
                        positions[group][item.position] = (positions[group][item.position] or 0) + 1
                    end
                    if item.temporaryModifiers ~= nil then
                        local modifierCount = getArrayLength(item.temporaryModifiers, path .. ".temporaryModifiers", errors)
                        if modifierCount and modifierCount > 0 then
                            addError(
                                errors,
                                "temporary_modifier_schema_pending",
                                path .. ".temporaryModifiers",
                                "임시 카드 보정 스키마가 확정되기 전에는 빈 배열만 허용합니다."
                            )
                        end
                    end

                    local cards = type(staticData) == "table" and staticData.cards or nil
                    local card = type(cards) == "table" and cards[item.cardId] or nil
                    if type(cards) == "table" and not card then
                        addError(errors, "unknown_card", path .. ".cardId", "정적 DB에서 카드를 찾을 수 없습니다.")
                    elseif card and card.owner ~= item.owner then
                        addError(errors, "card_owner_mismatch", path .. ".owner", "정적 카드와 인스턴스의 소유자가 다릅니다.")
                    end
                end
            end
        end

        for group, groupPositions in pairs(positions) do
            local count = 0
            local maximum = 0
            for position, occurrence in pairs(groupPositions) do
                count = count + occurrence
                if position > maximum then
                    maximum = position
                end
                if occurrence > 1 then
                    addError(errors, "duplicate_position", "$.cardInstances", group .. " 영역의 position이 중복되었습니다: " .. position)
                end
            end
            if count ~= maximum then
                addError(errors, "non_contiguous_positions", "$.cardInstances", group .. " 영역의 position이 1부터 이어지지 않습니다.")
            end
            if group == "player:hand"
                and type(state.player) == "table"
                and isInteger(state.player.maxHandSize, 1)
                and count > state.player.maxHandSize then
                addError(errors, "hand_limit_exceeded", "$.cardInstances", "플레이어 손패가 최대 손패를 초과했습니다.")
            elseif group == "character:hand"
                and type(state.character) == "table"
                and isInteger(state.character.maxHandSize, 1)
                and count > state.character.maxHandSize then
                addError(errors, "hand_limit_exceeded", "$.cardInstances", "캐릭터 손패가 최대 손패를 초과했습니다.")
            end
        end

        if type(state.player) == "table" then
            validatePlanSlots(
                state.player.planSlots,
                state.player.planCapacity,
                "player",
                "$.player.planSlots",
                errors,
                instances,
                staticData,
                state.turnNumber
            )
        end
        if type(state.character) == "table" then
            validatePlanSlots(
                state.character.planSlots,
                state.character.planCapacity,
                "character",
                "$.character.planSlots",
                errors,
                instances,
                staticData,
                state.turnNumber
            )
        end

        for instanceId, instance in pairs(instances) do
            if instance.zone == "plan" and VALID_OWNER[instance.owner] then
                local ownerState = instance.owner == "player" and state.player or state.character
                local slots = type(ownerState) == "table" and ownerState.planSlots or nil
                local slot = type(slots) == "table" and slots[instance.position] or nil
                if type(slot) ~= "table"
                    or slot.occupied ~= true
                    or slot.cardInstanceId ~= instanceId then
                    addError(
                        errors,
                        "orphan_plan_instance",
                        "$.cardInstances",
                        "plan 영역의 카드 인스턴스는 같은 진영의 점유 슬롯과 정확히 연결되어야 합니다: " .. instanceId
                    )
                end
            end
        end

        if type(state.selection) ~= "table" then
            addError(errors, "invalid_selection", "$.selection", "selection이 테이블이 아닙니다.")
        else
            checkAllowedKeys(state.selection, { playerCardInstanceIds = true }, "$.selection", errors)
            validateIdArray(state.selection.playerCardInstanceIds, "$.selection.playerCardInstanceIds", errors, isRuntimeId)
            if type(state.selection.playerCardInstanceIds) == "table" then
                local mainActionCount = 0
                local mainActionIndex = nil
                for index, instanceId in ipairs(state.selection.playerCardInstanceIds) do
                    local instance = instances[instanceId]
                    if not instance or instance.owner ~= "player" or instance.zone ~= "hand" then
                        addError(errors, "invalid_selected_card", "$.selection.playerCardInstanceIds[" .. index .. "]", "선택 카드는 플레이어 손패에 있어야 합니다.")
                    elseif referencesValidated then
                        local card = staticData.cards[instance.cardId]
                        if card and not cardHasMechanism(card, "chain") then
                            mainActionCount = mainActionCount + 1
                            mainActionIndex = index
                        end
                    end
                end
                if mainActionCount > 1 then
                    addError(errors, "multiple_player_main_actions", "$.selection.playerCardInstanceIds", "플레이어 선택에는 주 행동을 둘 이상 넣을 수 없습니다.")
                elseif mainActionIndex and mainActionIndex ~= #state.selection.playerCardInstanceIds then
                    addError(errors, "player_main_action_not_last", "$.selection.playerCardInstanceIds", "연계 카드는 주 행동보다 앞에 있어야 합니다.")
                end
            end
        end

        if type(state.characterIntent) ~= "table" then
            addError(errors, "invalid_character_intent", "$.characterIntent", "characterIntent가 테이블이 아닙니다.")
        else
            checkAllowedKeys(state.characterIntent, {
                cardInstanceIds = true,
                publicActionTag = true,
            }, "$.characterIntent", errors)
            validateIdArray(state.characterIntent.cardInstanceIds, "$.characterIntent.cardInstanceIds", errors, isRuntimeId)

            local intentCount = type(state.characterIntent.cardInstanceIds) == "table"
                and #state.characterIntent.cardInstanceIds
                or 0
            if intentCount == 0 then
                if state.characterIntent.publicActionTag ~= nil then
                    addError(errors, "orphan_public_action", "$.characterIntent.publicActionTag", "선택 카드가 없으면 공개 행동 태그도 없어야 합니다.")
                end
            elseif not isAsciiId(state.characterIntent.publicActionTag) then
                addError(errors, "missing_public_action", "$.characterIntent.publicActionTag", "캐릭터 선택의 공개 행동 태그가 필요합니다.")
            end

            local mainCards = {}
            local mainCardIndex = nil
            if type(state.characterIntent.cardInstanceIds) == "table" then
                for index, instanceId in ipairs(state.characterIntent.cardInstanceIds) do
                    local instance = instances[instanceId]
                    if not instance or instance.owner ~= "character" or instance.zone ~= "hand" then
                        addError(errors, "invalid_intent_card", "$.characterIntent.cardInstanceIds[" .. index .. "]", "캐릭터 선택 카드는 캐릭터 손패에 있어야 합니다.")
                    else
                        local cards = type(staticData) == "table" and staticData.cards or nil
                        local card = type(cards) == "table" and cards[instance.cardId] or nil
                        if card and not cardHasMechanism(card, "chain") then
                            table.insert(mainCards, card)
                            mainCardIndex = index
                        end
                    end
                end
            end

            if type(staticData) == "table" and intentCount > 0 then
                if #mainCards ~= 1 then
                    addError(errors, "invalid_character_main_action", "$.characterIntent.cardInstanceIds", "캐릭터 선택에는 주 행동 카드가 정확히 하나 있어야 합니다.")
                elseif mainCardIndex ~= intentCount then
                    addError(errors, "character_main_action_not_last", "$.characterIntent.cardInstanceIds", "캐릭터 연계 카드는 주 행동보다 앞에 있어야 합니다.")
                elseif mainCards[1].actionTag ~= state.characterIntent.publicActionTag then
                    addError(errors, "public_action_mismatch", "$.characterIntent.publicActionTag", "공개 행동 태그가 실제 주 행동과 다릅니다.")
                end
            end

            local registry = type(staticData) == "table" and staticData.registry or nil
            local actionTags = type(registry) == "table" and registry.actionTags or nil
            local publicAction = type(actionTags) == "table" and actionTags[state.characterIntent.publicActionTag] or nil
            if state.characterIntent.publicActionTag ~= nil and type(actionTags) == "table" then
                if not publicAction then
                    addError(errors, "unknown_public_action", "$.characterIntent.publicActionTag", "등록되지 않은 행동 태그입니다.")
                elseif publicAction.owner ~= "character" then
                    addError(errors, "public_action_owner_mismatch", "$.characterIntent.publicActionTag", "캐릭터 행동 태그가 아닙니다.")
                end
            end
        end

        if type(staticData) == "table" then
            if type(staticData.environments) == "table" and not staticData.environments[state.environmentId] then
                addError(errors, "unknown_environment", "$.environmentId", "정적 DB에서 환경을 찾을 수 없습니다.")
            end
            if type(state.character) == "table" then
                if type(staticData.characters) == "table" and not staticData.characters[state.character.characterId] then
                    addError(errors, "unknown_character", "$.character.characterId", "정적 DB에서 캐릭터를 찾을 수 없습니다.")
                end
                if type(staticData.registry) == "table"
                    and type(staticData.registry.moods) == "table"
                    and not staticData.registry.moods[state.character.mood] then
                    addError(errors, "unknown_mood", "$.character.mood", "등록되지 않은 무드입니다.")
                end
                if type(staticData.traits) == "table" and type(state.character.traitIds) == "table" then
                    for index, traitId in ipairs(state.character.traitIds) do
                        if not staticData.traits[traitId] then
                            addError(errors, "unknown_trait", "$.character.traitIds[" .. index .. "]", "정적 DB에서 특징을 찾을 수 없습니다.")
                        end
                    end
                end
            end
        end

        local historyReport, historyCallError = callReceiptValidator(
            "battleHistory",
            "validate",
            state.history,
            state,
            staticData
        )
        if historyCallError ~= nil then
            addError(errors, "history_validation_unavailable", "$.history", "전투 이력 검증을 실행할 수 없습니다: " .. historyCallError)
        elseif historyReport.ok ~= true then
            appendNestedErrors(errors, "$.history", historyReport)
        end

        if state.turnStartReceipt ~= nil then
            validateTurnStartReceipt(state.turnStartReceipt, state, staticData, referencesValidated, errors)
        end

        if type(state.player) == "table" and type(state.character) == "table"
            and isFinite(state.player.stealth) and isFinite(state.character.resistance) then
            if state.character.resistance <= 0 and state.status ~= "victory" then
                addError(errors, "victory_priority", "$.status", "저항이 0 이하이면 동시 은폐 소진보다 승리를 우선해야 합니다.")
            elseif state.character.resistance > 0 and state.player.stealth <= 0 and state.status ~= "defeat" then
                addError(errors, "defeat_required", "$.status", "은폐가 0 이하이면 패배 상태여야 합니다.")
            elseif state.status == "active" and (state.character.resistance <= 0 or state.player.stealth <= 0) then
                addError(errors, "active_outcome_conflict", "$.status", "종료 수치에서 active 상태를 유지할 수 없습니다.")
            elseif state.status == "victory" and state.character.resistance > 0 then
                addError(errors, "invalid_victory", "$.status", "저항이 남아 있으면 승리 상태일 수 없습니다.")
            elseif state.status == "defeat"
                and state.player.stealth > 0
                and isInteger(state.turnNumber, 1)
                and isInteger(state.turnLimit, 1)
                and state.turnNumber < state.turnLimit then
                addError(errors, "invalid_defeat", "$.status", "은폐가 남고 제한 턴 전이면 패배 상태일 수 없습니다.")
            end
        end

        local report = result(errors, state)
        report.referencesValidated = referencesValidated
        return report
    end

    local function fingerprintBattleState(state, staticData)
        local validation = validateBattleState(state, staticData)
        if not validation.ok then
            return validation
        end
        if validation.referencesValidated ~= true then
            local errors = {}
            addError(
                errors,
                "static_references_not_validated",
                "$.staticData",
                "battleState fingerprint에는 전체 정적 데이터 참조 검증이 필요합니다."
            )
            local report = result(errors)
            report.referencesValidated = false
            return report
        end

        local authorityFingerprint, fingerprintError = fingerprintAuthorityState(state)
        if fingerprintError then
            local errors = {}
            addError(errors, fingerprintError.code, fingerprintError.path, fingerprintError.message)
            local report = result(errors)
            report.referencesValidated = true
            return report
        end
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            referencesValidated = true,
            fingerprint = authorityFingerprint,
        }
    end

    local function sealTurnStartReceipt(state, staticData)
        local errors = {}
        if type(state) ~= "table" or type(state.turnStartReceipt) ~= "table" then
            addError(errors, "missing_unsealed_turn_receipt", "$.turnStartReceipt", "봉인할 turnStartReceipt가 없습니다.")
            return result(errors)
        end
        if state.turnStartReceipt.authorityFingerprint ~= nil then
            addError(errors, "turn_receipt_already_sealed", "$.turnStartReceipt.authorityFingerprint", "이미 authorityFingerprint가 있는 영수증은 다시 봉인할 수 없습니다.")
            return result(errors)
        end

        local authorityFingerprint, fingerprintError = fingerprintAuthorityState(state)
        if fingerprintError then
            addError(errors, fingerprintError.code, fingerprintError.path, fingerprintError.message)
            return result(errors)
        end

        local function cloneValue(value, path, active)
            local valueType = type(value)
            if valueType == "nil" or valueType == "string" or valueType == "boolean" then
                return value, nil
            end
            if valueType == "number" then
                if not isFinite(value) then
                    return nil, { code = "non_finite_number", path = path, message = "NaN과 무한대는 봉인 상태에 사용할 수 없습니다." }
                end
                return value, nil
            end
            if valueType ~= "table" or getmetatable(value) ~= nil then
                return nil, { code = "unsupported_type", path = path, message = "봉인 상태에 사용할 수 없는 값입니다." }
            end
            active = active or {}
            if active[value] then
                return nil, { code = "circular_reference", path = path, message = "순환 참조가 있는 상태는 봉인할 수 없습니다." }
            end
            active[value] = true
            local copy = {}
            for key, item in pairs(value) do
                local itemCopy, itemError = cloneValue(item, objectPath(path, key), active)
                if itemError then
                    active[value] = nil
                    return nil, itemError
                end
                copy[key] = itemCopy
            end
            active[value] = nil
            return copy, nil
        end

        local sealedState, cloneError = cloneValue(state, "$", {})
        if cloneError then
            addError(errors, cloneError.code, cloneError.path, cloneError.message)
            return result(errors)
        end
        sealedState.turnStartReceipt.authorityFingerprint = authorityFingerprint

        local reportFingerprint, reportFingerprintError = cloneValue(
            authorityFingerprint,
            "$.fingerprint",
            {}
        )
        if reportFingerprintError then
            addError(
                errors,
                reportFingerprintError.code,
                reportFingerprintError.path,
                reportFingerprintError.message
            )
            return result(errors)
        end

        local validation = validateBattleState(sealedState, staticData)
        if not validation.ok then
            return validation
        end
        if validation.referencesValidated ~= true then
            addError(errors, "static_references_not_validated", "$.staticData", "turnStartReceipt 봉인에는 전체 정적 데이터 참조 검증이 필요합니다.")
            local report = result(errors)
            report.referencesValidated = false
            return report
        end
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            referencesValidated = true,
            state = sealedState,
            fingerprint = reportFingerprint,
        }
    end

    local function validateEventEnvelope(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_event_envelope", path, "사건 묶음이 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, { schemaVersion = true, events = true }, path, errors)
        if value.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_schema", path .. ".schemaVersion", "지원하지 않는 사건 묶음 스키마입니다.")
        end
        getArrayLength(value.events, path .. ".events", errors)
    end

    local function arraysEqual(left, right)
        if type(left) ~= "table" or type(right) ~= "table" or #left ~= #right then
            return false
        end
        for index = 1, #left do
            if left[index] ~= right[index] then
                return false
            end
        end
        return true
    end

    local function dataEqual(left, right, seen)
        if type(left) ~= type(right) then return false end
        if type(left) ~= "table" then return left == right end
        if getmetatable(left) ~= nil or getmetatable(right) ~= nil then return false end
        seen = seen or {}
        if seen[left] ~= nil then return seen[left] == right end
        seen[left] = right
        for key, value in pairs(left) do
            if not dataEqual(value, right[key], seen) then return false end
        end
        for key in pairs(right) do
            if left[key] == nil then return false end
        end
        return true
    end

    local function fingerprintsEqual(left, right)
        return type(left) == "table"
            and type(right) == "table"
            and left.algorithm == right.algorithm
            and left.length == right.length
            and left.hashA == right.hashA
            and left.hashB == right.hashB
    end

    local function validateDraftFingerprint(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_projection_fingerprint", path, "projection 원본 fingerprint가 객체가 아닙니다.")
            return false
        end
        checkAllowedKeys(value, {
            algorithm = true,
            length = true,
            hashA = true,
            hashB = true,
        }, path, errors)
        local valid = true
        if value.algorithm ~= DRAFT_FINGERPRINT_ALGORITHM then
            addError(errors, "invalid_projection_fingerprint_algorithm", path .. ".algorithm", "지원하지 않는 projection 원본 fingerprint 알고리즘입니다.")
            valid = false
        end
        for _, field in ipairs({ "length", "hashA", "hashB" }) do
            if not isSafeInteger(value[field], 0) then
                addError(errors, "invalid_projection_fingerprint", path .. "." .. field, "projection 원본 fingerprint 수치는 0 이상의 안전한 정수여야 합니다.")
                valid = false
            end
        end
        return valid
    end

    local function validatePendingIntegrity(pending, errors)
        local path = "$.integrity"
        local value = pending.integrity
        if type(value) ~= "table" then
            addError(errors, "missing_pending_integrity", path, "pendingTurn에는 전체 저장값 무결성 영수증이 필요합니다.")
            return
        end
        checkAllowedKeys(value, {
            algorithm = true,
            length = true,
            hashA = true,
            hashB = true,
        }, path, errors)

        local valid = true
        if value.algorithm ~= PENDING_INTEGRITY_ALGORITHM then
            addError(errors, "invalid_pending_integrity_algorithm", path .. ".algorithm", "지원하지 않는 pendingTurn 무결성 알고리즘입니다.")
            valid = false
        end
        for _, field in ipairs({ "length", "hashA", "hashB" }) do
            if not isSafeInteger(value[field], 0) then
                addError(errors, "invalid_pending_integrity", path .. "." .. field, "pendingTurn 무결성 수치는 0 이상의 안전한 정수여야 합니다.")
                valid = false
            end
        end
        if not valid then
            return
        end

        local expected, fingerprintError = fingerprintPendingTurn(pending)
        if fingerprintError then
            addError(errors, fingerprintError.code, fingerprintError.path, fingerprintError.message)
        elseif not fingerprintsEqual(value, expected) then
            addError(errors, "pending_integrity_mismatch", path, "pendingTurn 저장값이 생성 뒤 변경되었습니다.")
        end
    end

    local function validateProjectionReceiptShape(receipt, path, errors)
        if type(receipt) ~= "table" then
            addError(errors, "invalid_projection_receipt", path, "projectionReceipt가 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(receipt, {
            schemaVersion = true,
            kind = true,
            mode = true,
            selectedCardInstanceIds = true,
            effectChoiceByInstanceId = true,
            source = true,
            projectedRng = true,
        }, path, errors)
        if receipt.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_projection_receipt_schema", path .. ".schemaVersion", "지원하지 않는 projectionReceipt 스키마입니다.")
        end
        if receipt.kind ~= "turnDraftProjectionReceipt" then
            addError(errors, "invalid_projection_receipt_kind", path .. ".kind", "kind는 turnDraftProjectionReceipt여야 합니다.")
        end
        if receipt.mode ~= "pass" and receipt.mode ~= "chain_pass" and receipt.mode ~= "action" then
            addError(errors, "invalid_projection_mode", path .. ".mode", "알 수 없는 projection mode입니다.")
        end
        validateIdArray(receipt.selectedCardInstanceIds, path .. ".selectedCardInstanceIds", errors, isRuntimeId)
        if receipt.effectChoiceByInstanceId ~= nil and type(receipt.effectChoiceByInstanceId) ~= "table" then
            addError(errors, "invalid_effect_choice_map", path .. ".effectChoiceByInstanceId", "효과 선택값은 객체여야 합니다.")
        else
            local selected = {}
            for _, instanceId in ipairs(type(receipt.selectedCardInstanceIds) == "table" and receipt.selectedCardInstanceIds or {}) do
                selected[instanceId] = true
            end
            for instanceId, choiceId in pairs(receipt.effectChoiceByInstanceId or {}) do
                if not isRuntimeId(instanceId) or not selected[instanceId]
                    or not isAsciiId(choiceId) then
                    addError(errors, "invalid_effect_choice", path .. ".effectChoiceByInstanceId." .. tostring(instanceId), "봉인된 효과 선택값이 올바르지 않습니다.")
                end
            end
        end
        local selectedCount = type(receipt.selectedCardInstanceIds) == "table" and #receipt.selectedCardInstanceIds or 0
        if receipt.mode == "pass" and selectedCount ~= 0 then
            addError(errors, "projection_pass_has_selection", path .. ".selectedCardInstanceIds", "pass projection에는 등록 카드가 없어야 합니다.")
        elseif (receipt.mode == "chain_pass" or receipt.mode == "action") and selectedCount == 0 then
            addError(errors, "projection_mode_missing_selection", path .. ".selectedCardInstanceIds", "카드가 있는 projection mode에는 등록 카드가 필요합니다.")
        end

        local source = receipt.source
        if type(source) ~= "table" then
            addError(errors, "invalid_projection_source", path .. ".source", "projection 원본 표식이 객체가 아닙니다.")
        else
            checkAllowedKeys(source, {
                battleId = true,
                status = true,
                turnNumber = true,
                lastCommittedTurnId = true,
                rng = true,
                fingerprint = true,
            }, path .. ".source", errors)
            if not isRuntimeId(source.battleId) then
                addError(errors, "invalid_battle_id", path .. ".source.battleId", "projection 원본 battleId가 올바르지 않습니다.")
            end
            if source.status ~= "active" then
                addError(errors, "invalid_projection_source_status", path .. ".source.status", "projection 원본 상태는 active여야 합니다.")
            end
            if not isInteger(source.turnNumber, 1) then
                addError(errors, "invalid_turn_number", path .. ".source.turnNumber", "projection 원본 턴 번호가 올바르지 않습니다.")
            end
            if source.lastCommittedTurnId ~= nil and not isRuntimeId(source.lastCommittedTurnId) then
                addError(errors, "invalid_turn_id", path .. ".source.lastCommittedTurnId", "projection 원본 마지막 확정 턴 ID가 올바르지 않습니다.")
            end
            validateReceiptRng(source.rng, path .. ".source.rng", errors)
            validateDraftFingerprint(source.fingerprint, path .. ".source.fingerprint", errors)
        end
        validateReceiptRng(receipt.projectedRng, path .. ".projectedRng", errors)
        if type(source) == "table" and type(source.rng) == "table" and type(receipt.projectedRng) == "table" then
            if receipt.projectedRng.seed ~= source.rng.seed then
                addError(errors, "projection_rng_seed_changed", path .. ".projectedRng.seed", "projection 중 RNG seed가 바뀔 수 없습니다.")
            end
            if isInteger(source.rng.cursor, 0)
                and isInteger(receipt.projectedRng.cursor, 0)
                and receipt.projectedRng.cursor < source.rng.cursor then
                addError(errors, "projection_rng_reversed", path .. ".projectedRng.cursor", "projection RNG cursor가 이전으로 돌아갈 수 없습니다.")
            end
        end
    end

    local function validatePendingTurn(pending, staticData)
        local errors = {}
        local staticDataProvided = staticData ~= nil
        staticData = normalizeStaticData(staticData)
        local referencesValidated = hasCompleteStaticData(staticData)

        if staticDataProvided and not referencesValidated then
            addError(errors, "invalid_static_data", "$", "전달한 정적 데이터가 전체 참조 검증에 필요한 컬렉션을 갖추지 못했습니다.")
        end
        if not referencesValidated then
            staticData = nil
        end

        if type(pending) ~= "table" then
            addError(errors, "invalid_pending_turn", "$", "pendingTurn이 테이블이 아닙니다.")
            return result(errors)
        end

        validateJsonSafe(pending, "$", errors)
        if #errors > 0 then
            local report = result(errors)
            report.referencesValidated = referencesValidated
            return report
        end
        checkAllowedKeys(pending, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            turnId = true,
            status = true,
            beforeState = true,
            projectionReceipt = true,
            selectedCards = true,
            turnResult = true,
            afterState = true,
            integrity = true,
        }, "$", errors)

        if pending.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_schema", "$.schemaVersion", "지원하지 않는 pendingTurn 스키마 버전입니다.")
        end
        if pending.kind ~= "pendingTurn" then
            addError(errors, "invalid_kind", "$.kind", "kind는 pendingTurn이어야 합니다.")
        end
        if not isRuntimeId(pending.battleId) then
            addError(errors, "invalid_battle_id", "$.battleId", "battleId가 올바르지 않습니다.")
        end
        if not isRuntimeId(pending.turnId) then
            addError(errors, "invalid_turn_id", "$.turnId", "turnId가 올바르지 않습니다.")
        end
        if pending.status ~= "awaitingOutput" then
            addError(errors, "invalid_pending_status", "$.status", "대기 트랜잭션 상태는 awaitingOutput이어야 합니다.")
        end

        local beforeResult = validateBattleState(pending.beforeState, staticData)
        if not beforeResult.ok then
            appendNestedErrors(errors, "$.beforeState", beforeResult)
        end
        local afterResult = validateBattleState(pending.afterState, staticData)
        if not afterResult.ok then
            appendNestedErrors(errors, "$.afterState", afterResult)
        end

        validateProjectionReceiptShape(pending.projectionReceipt, "$.projectionReceipt", errors)

        if type(pending.selectedCards) ~= "table" then
            addError(errors, "invalid_selected_cards", "$.selectedCards", "selectedCards가 테이블이 아닙니다.")
        else
            checkAllowedKeys(pending.selectedCards, { player = true, character = true }, "$.selectedCards", errors)
            validateIdArray(pending.selectedCards.player, "$.selectedCards.player", errors, isRuntimeId)
            validateIdArray(pending.selectedCards.character, "$.selectedCards.character", errors, isRuntimeId)
        end

        if type(pending.turnResult) ~= "table" then
            addError(errors, "invalid_turn_result", "$.turnResult", "turnResult가 테이블이 아닙니다.")
        else
            checkAllowedKeys(pending.turnResult, {
                events = true,
                publicResult = true,
                llmEvent = true,
            }, "$.turnResult", errors)

            getArrayLength(pending.turnResult.events, "$.turnResult.events", errors)
            validateEventEnvelope(pending.turnResult.publicResult, "$.turnResult.publicResult", errors)
            validateEventEnvelope(pending.turnResult.llmEvent, "$.turnResult.llmEvent", errors)
        end

        if type(pending.turnResult) == "table" and type(pending.afterState) == "table" then
            local history = pending.afterState.history
            local turns = type(history) == "table" and history.turns or nil
            local lastEntry = type(turns) == "table" and turns[#turns] or nil
            if type(lastEntry) ~= "table" or lastEntry.turnId ~= pending.turnId then
                addError(errors, "pending_history_turn_mismatch", "$.afterState.history.turns", "afterState 전투 이력의 마지막 턴이 pendingTurn과 다릅니다.")
            elseif not dataEqual(lastEntry.publicResult, pending.turnResult.publicResult) then
                addError(errors, "pending_history_public_result_mismatch", "$.afterState.history.turns", "전투 이력의 공개 로그와 pendingTurn 공개 결과가 다릅니다.")
            end
        end

        if type(pending.beforeState) == "table" and type(pending.afterState) == "table" then
            if pending.beforeState.battleId ~= pending.battleId then
                addError(errors, "before_battle_mismatch", "$.beforeState.battleId", "beforeState의 전투 ID가 다릅니다.")
            end
            if pending.afterState.battleId ~= pending.battleId then
                addError(errors, "after_battle_mismatch", "$.afterState.battleId", "afterState의 전투 ID가 다릅니다.")
            end
            if pending.beforeState.lastCommittedTurnId == pending.turnId then
                addError(errors, "turn_already_committed", "$.beforeState.lastCommittedTurnId", "beforeState에 이미 같은 턴이 반영되었습니다.")
            end
            if pending.afterState.lastCommittedTurnId ~= pending.turnId then
                addError(errors, "after_turn_not_marked", "$.afterState.lastCommittedTurnId", "afterState에 대기 턴 ID가 기록되어야 합니다.")
            end
            if pending.beforeState.status ~= "active" then
                addError(errors, "before_state_not_active", "$.beforeState.status", "종료된 전투에서 새 대기 턴을 만들 수 없습니다.")
            end
            local beforeSelection = type(pending.beforeState.selection) == "table"
                and pending.beforeState.selection.playerCardInstanceIds
                or nil
            if type(beforeSelection) ~= "table" or #beforeSelection ~= 0 then
                addError(errors, "pending_authority_selection_not_empty", "$.beforeState.selection.playerCardInstanceIds", "pendingTurn의 권위 beforeState에는 플레이어 드래프트 선택을 저장할 수 없습니다.")
            end
            local startReceipt = pending.beforeState.turnStartReceipt
            if type(startReceipt) ~= "table" then
                addError(errors, "pending_missing_turn_start_receipt", "$.beforeState.turnStartReceipt", "pendingTurn beforeState에는 봉인된 turnStartReceipt가 필요합니다.")
            elseif startReceipt.turnId ~= pending.turnId then
                addError(errors, "pending_turn_id_mismatch", "$.turnId", "pendingTurn turnId가 beforeState.turnStartReceipt와 다릅니다.")
            end
            if pending.afterState.turnStartReceipt ~= nil then
                addError(errors, "pending_after_turn_receipt_present", "$.afterState.turnStartReceipt", "해결된 afterState에는 turnStartReceipt를 남길 수 없습니다.")
            end
            local afterSelection = type(pending.afterState.selection) == "table"
                and pending.afterState.selection.playerCardInstanceIds
                or nil
            if type(afterSelection) ~= "table" or #afterSelection ~= 0 then
                addError(errors, "pending_after_selection_not_empty", "$.afterState.selection.playerCardInstanceIds", "해결된 afterState에는 플레이어 선택을 남길 수 없습니다.")
            end
            local afterIntent = pending.afterState.characterIntent
            local afterIntentIds = type(afterIntent) == "table" and afterIntent.cardInstanceIds or nil
            if type(afterIntentIds) ~= "table" or #afterIntentIds ~= 0 then
                addError(errors, "pending_after_character_intent_not_empty", "$.afterState.characterIntent.cardInstanceIds", "해결된 afterState에는 캐릭터 선택을 남길 수 없습니다.")
            end
            if type(afterIntent) == "table" and afterIntent.publicActionTag ~= nil then
                addError(errors, "pending_after_public_action_present", "$.afterState.characterIntent.publicActionTag", "해결된 afterState에는 공개 행동 태그를 남길 수 없습니다.")
            end
            if isInteger(pending.beforeState.turnNumber, 1)
                and isInteger(pending.afterState.turnNumber, 1)
                and pending.afterState.turnNumber < pending.beforeState.turnNumber then
                addError(errors, "turn_number_reversed", "$.afterState.turnNumber", "afterState의 턴 번호가 이전으로 돌아갈 수 없습니다.")
            elseif isInteger(pending.beforeState.turnNumber, 1)
                and isInteger(pending.afterState.turnNumber, 1)
                and pending.afterState.turnNumber > pending.beforeState.turnNumber + 1 then
                addError(errors, "turn_number_skipped", "$.afterState.turnNumber", "한 번의 대기 트랜잭션에서 턴을 둘 이상 건너뛸 수 없습니다.")
            end
            if pending.afterState.turnLimit ~= pending.beforeState.turnLimit then
                addError(errors, "turn_limit_changed", "$.afterState.turnLimit", "한 턴 판정 중 제한 턴을 바꿀 수 없습니다.")
            end
            if pending.afterState.environmentId ~= pending.beforeState.environmentId then
                addError(errors, "environment_changed", "$.afterState.environmentId", "한 턴 판정 중 환경을 바꿀 수 없습니다.")
            end
            if not transitEqual(pending.afterState.transit, pending.beforeState.transit) then
                addError(errors, "transit_changed", "$.afterState.transit", "한 턴 판정 중 지하철 이동 구간을 바꿀 수 없습니다.")
            end
            local beforeCharacter = type(pending.beforeState.character) == "table" and pending.beforeState.character.characterId or nil
            local afterCharacter = type(pending.afterState.character) == "table" and pending.afterState.character.characterId or nil
            if afterCharacter ~= beforeCharacter then
                addError(errors, "character_changed", "$.afterState.character.characterId", "한 전투의 캐릭터를 턴 판정 중 바꿀 수 없습니다.")
            end
            local beforeRng = pending.beforeState.rng
            local afterRng = pending.afterState.rng
            if type(beforeRng) == "table" and type(afterRng) == "table" then
                if afterRng.seed ~= beforeRng.seed then
                    addError(errors, "rng_seed_changed", "$.afterState.rng.seed", "한 전투의 난수 시드를 턴 판정 중 바꿀 수 없습니다.")
                end
                if isInteger(beforeRng.cursor, 0)
                    and isInteger(afterRng.cursor, 0)
                    and afterRng.cursor < beforeRng.cursor then
                    addError(errors, "rng_cursor_reversed", "$.afterState.rng.cursor", "난수 커서는 이전으로 돌아갈 수 없습니다.")
                end
            end

            local projectionReceipt = pending.projectionReceipt
            if type(projectionReceipt) == "table" then
                local source = projectionReceipt.source
                if type(source) == "table" then
                    if source.battleId ~= pending.battleId
                        or source.battleId ~= pending.beforeState.battleId then
                        addError(errors, "projection_battle_mismatch", "$.projectionReceipt.source.battleId", "projectionReceipt battleId가 pendingTurn 권위 상태와 다릅니다.")
                    end
                    if source.status ~= pending.beforeState.status then
                        addError(errors, "projection_status_mismatch", "$.projectionReceipt.source.status", "projectionReceipt 상태가 beforeState와 다릅니다.")
                    end
                    if source.turnNumber ~= pending.beforeState.turnNumber then
                        addError(errors, "projection_turn_mismatch", "$.projectionReceipt.source.turnNumber", "projectionReceipt 턴 번호가 beforeState와 다릅니다.")
                    end
                    if source.lastCommittedTurnId ~= pending.beforeState.lastCommittedTurnId then
                        addError(errors, "projection_commit_mismatch", "$.projectionReceipt.source.lastCommittedTurnId", "projectionReceipt 마지막 확정 턴 ID가 beforeState와 다릅니다.")
                    end
                    if not rngEqual(source.rng, pending.beforeState.rng) then
                        addError(errors, "projection_rng_mismatch", "$.projectionReceipt.source.rng", "projectionReceipt 시작 RNG가 beforeState와 다릅니다.")
                    end
                    local expectedFingerprint, fingerprintError = fingerprintDraftAuthorityState(pending.beforeState)
                    if fingerprintError then
                        addError(errors, fingerprintError.code, fingerprintError.path, fingerprintError.message)
                    elseif not fingerprintsEqual(source.fingerprint, expectedFingerprint) then
                        addError(errors, "projection_fingerprint_mismatch", "$.projectionReceipt.source.fingerprint", "projectionReceipt fingerprint가 beforeState 전체와 다릅니다.")
                    end
                end
                local projectedRng = projectionReceipt.projectedRng
                if type(projectedRng) == "table"
                    and type(afterRng) == "table"
                    and isInteger(projectedRng.cursor, 0)
                    and isInteger(afterRng.cursor, 0)
                    and afterRng.cursor < projectedRng.cursor then
                    addError(errors, "after_rng_before_projection", "$.afterState.rng.cursor", "afterState RNG cursor는 선택 projection이 소비한 위치보다 이전일 수 없습니다.")
                end
            end

            if type(pending.selectedCards) == "table" then
                local selected = type(projectionReceipt) == "table"
                    and projectionReceipt.selectedCardInstanceIds
                    or nil
                local intent = type(pending.beforeState.characterIntent) == "table"
                    and pending.beforeState.characterIntent.cardInstanceIds
                    or nil
                if not arraysEqual(pending.selectedCards.player, selected) then
                    addError(errors, "player_selection_mismatch", "$.selectedCards.player", "projectionReceipt의 플레이어 선택과 다릅니다.")
                end
                if not arraysEqual(pending.selectedCards.character, intent) then
                    addError(errors, "character_selection_mismatch", "$.selectedCards.character", "beforeState의 캐릭터 선택과 다릅니다.")
                end
            end
        end

        validatePendingIntegrity(pending, errors)

        local report = result(errors, pending)
        report.referencesValidated = referencesValidated
        report.projectionReplayValidated = false
        return report
    end

    local function cloneJson(value, active)
        local valueType = type(value)
        if valueType ~= "table" then
            if valueType == "string" or valueType == "number" or valueType == "boolean" or valueType == "nil" then
                return value
            end
            error("unsupported type: " .. valueType)
        end
        if getmetatable(value) ~= nil then
            error("metatable is not allowed")
        end
        active = active or {}
        if active[value] then
            error("circular reference")
        end
        active[value] = true
        local copy = {}
        for key, item in pairs(value) do
            copy[cloneJson(key, active)] = cloneJson(item, active)
        end
        active[value] = nil
        return copy
    end

    local function constructBattleState(options, staticData)
        if type(options) ~= "table" then
            local errors = {}
            addError(errors, "invalid_options", "$", "battleState 생성 사양이 테이블이 아닙니다.")
            return result(errors)
        end

        local ok, state = pcall(function()
            local value = cloneJson(options)
            value.schemaVersion = SCHEMA_VERSION
            value.kind = "battleState"
            local normalizedStaticData = normalizeStaticData(staticData)
            if type(value.character) == "table" and value.character.moodTokens == nil
                and type(normalizedStaticData) == "table"
                and type(normalizedStaticData.registry) == "table"
                and type(normalizedStaticData.registry.moods) == "table" then
                value.character.moodTokens = {}
                for moodId in pairs(normalizedStaticData.registry.moods) do
                    value.character.moodTokens[moodId] = 0
                end
            end
            if value.history == nil then
                value.history = {
                    schemaVersion = SCHEMA_VERSION,
                    kind = "battleHistory",
                    turns = {},
                }
            end
            return value
        end)

        if not ok then
            local errors = {}
            addError(errors, "construct_failed", "$", "battleState 생성에 실패했습니다: " .. tostring(state))
            return result(errors)
        end

        local validation = validateBattleState(state, staticData)
        if not validation.ok then
            return validation
        end
        local report = result({}, state)
        report.referencesValidated = validation.referencesValidated
        return report
    end

    local function constructPendingTurn(spec, staticData)
        if type(spec) ~= "table" then
            local errors = {}
            addError(errors, "invalid_spec", "$", "pendingTurn 생성 사양이 테이블이 아닙니다.")
            return result(errors)
        end

        local ok, pending = pcall(function()
            local value = cloneJson(spec)
            value.schemaVersion = SCHEMA_VERSION
            value.kind = "pendingTurn"
            value.status = "awaitingOutput"
            value.integrity = nil
            return value
        end)

        if not ok then
            local errors = {}
            addError(errors, "construct_failed", "$", "pendingTurn 생성에 실패했습니다: " .. tostring(pending))
            return result(errors)
        end

        local integrity, integrityError = fingerprintPendingTurn(pending)
        if integrityError then
            local errors = {}
            addError(errors, integrityError.code, integrityError.path, integrityError.message)
            return result(errors)
        end
        pending.integrity = integrity

        local validation = validatePendingTurn(pending, staticData)
        if not validation.ok then
            return validation
        end
        local report = result({}, pending)
        report.referencesValidated = validation.referencesValidated
        report.projectionReplayValidated = false
        return report
    end

    local arguments = { ... }
    if action == "newBattleState" then
        return constructBattleState(arguments[1], arguments[2])
    elseif action == "validateBattleState" then
        return validateBattleState(arguments[1], arguments[2])
    elseif action == "fingerprintBattleState" then
        return fingerprintBattleState(arguments[1], arguments[2])
    elseif action == "sealTurnStartReceipt" then
        return sealTurnStartReceipt(arguments[1], arguments[2])
    elseif action == "newPendingTurn" then
        return constructPendingTurn(arguments[1], arguments[2])
    elseif action == "validatePendingTurn" then
        return validatePendingTurn(arguments[1], arguments[2])
    end

    local errors = {}
    addError(errors, "unknown_action", "$", "지원하지 않는 상태 스키마 작업입니다: " .. tostring(action))
    return result(errors)
end)

]],
    [[[
staticData
]]] = [[
(function()
    local STATIC_CACHE_MAX_ENTRIES = 4
    local MAX_PLAN_CAPACITY = 16
    local DIAGNOSTIC_SCOPE = "helltrain.staticData"
    local STATIC_BASE_LORE_ORDER = {
        "GameRegistry.db",
        "PlayerCards.db",
        "CharacterCards.db",
        "CharTraits.db",
        "Environments.db",
        "TokyoSubwayLines.db",
        "CharacterList.db",
    }
    local staticCacheEntries = {}
    local staticCacheClock = 0
    local staticCacheStats = {
        requests = 0,
        captures = 0,
        fastHits = 0,
        hits = 0,
        misses = 0,
        validations = 0,
        failedValidations = 0,
        evictions = 0,
        clears = 0,
    }

    -- 호스트 진단 출력은 print 한 줄로 통일한다. DB 본문이나 프로필은 남기지
    -- 않고 로어 이름, 개수, 헤더와 오류 경로만 기록한다.
    local function diagnosticsEnabled(depth)
        return type(DEBUG) == "number" and depth <= DEBUG
    end

    local function diagnosticText(value)
        return tostring(value):gsub("[\r\n]+", " ")
    end

    local function emitDiagnostic(depth, event, fields)
        if not diagnosticsEnabled(depth) then
            return
        end

        if type(print) ~= "function" then
            return
        end

        local parts = {
            "[" .. DIAGNOSTIC_SCOPE .. "]",
            "depth=" .. tostring(depth),
            "event=" .. diagnosticText(event),
        }
        local fieldOrder = {
            "action", "forceRefresh", "cachedEntries", "cache", "ok",
            "lore", "status", "entryCount", "error", "entryIndex",
            "schemaVersion", "kindType", "kind", "code", "path", "message",
            "expectedKind", "actualKindType", "actualKind", "errorCount",
            "cards", "traits", "environments", "subwayLines", "characters",
        }
        for _, key in ipairs(fieldOrder) do
            local value = type(fields) == "table" and fields[key] or nil
            if value ~= nil then
                parts[#parts + 1] = key .. "=" .. diagnosticText(value)
            end
        end
        pcall(print, table.concat(parts, " | "))
    end

    -- 캐시의 canonical snapshot을 호출자에게 직접 노출하지 않는다. 함수는 정적
    -- DB callback이므로 identity를 유지하고, 모든 table은 alias가 없도록 복제한다.
    local function cloneStaticValue(value, seen)
        if type(value) ~= "table" then
            return value
        end

        seen = seen or {}
        if seen[value] ~= nil then
            return seen[value]
        end

        local copy = {}
        seen[value] = copy
        for key, item in pairs(value) do
            copy[cloneStaticValue(key, seen)] = cloneStaticValue(item, seen)
        end
        return copy
    end

    -- getLoreBooks 결과의 metadata는 DB 판정에 사용하지 않는다. 개발/강제 refresh
    -- 경로에서는 content와 순서 전체를 비교해 context 오염과 stale hit를 막는다.
    -- production fast path의 배포 무효화는 main의 RUNTIME_BUNDLE_REVISION 계약이다.
    local function captureStaticLore(triggerId, captured, loreName)
        if captured[loreName] ~= nil then
            return
        end

        local ok, lores = pcall(getLoreBooks, triggerId, loreName)
        local source = {
            status = ok and type(lores) or "read_error",
            entries = {},
        }
        if not ok then
            source.error = tostring(lores)
        elseif type(lores) == "table" then
            for _, lore in ipairs(lores) do
                if type(lore) == "table" and type(lore.content) == "string" then
                    table.insert(source.entries, {
                        valid = true,
                        content = lore.content,
                    })
                else
                    table.insert(source.entries, {
                        valid = false,
                        loreType = type(lore),
                        contentType = type(lore) == "table" and type(lore.content) or "none",
                    })
                end
            end
        end
        captured[loreName] = source
        table.insert(captured.order, loreName)

        emitDiagnostic(source.status == "read_error" and 1 or 2, "lore_capture", {
            lore = loreName,
            status = source.status,
            entryCount = #source.entries,
            error = source.error,
        })
    end

    local function captureBaseStaticLores(triggerId)
        staticCacheStats.captures = staticCacheStats.captures + 1
        local captured = {
            order = {},
        }
        for _, loreName in ipairs(STATIC_BASE_LORE_ORDER) do
            captureStaticLore(triggerId, captured, loreName)
        end
        return captured
    end

    local function sameStaticLoreSource(leftSource, rightSource)
        if leftSource == nil
            or rightSource == nil
            or leftSource.status ~= rightSource.status
            or leftSource.error ~= rightSource.error
            or #leftSource.entries ~= #rightSource.entries then
            return false
        end
        for index, leftEntry in ipairs(leftSource.entries) do
            local rightEntry = rightSource.entries[index]
            if rightEntry == nil
                or leftEntry.valid ~= rightEntry.valid
                or leftEntry.content ~= rightEntry.content
                or leftEntry.loreType ~= rightEntry.loreType
                or leftEntry.contentType ~= rightEntry.contentType then
                return false
            end
        end
        return true
    end

    local function sameStaticLoreCapture(left, right)
        if type(left.order) ~= "table"
            or type(right.order) ~= "table"
            or #left.order ~= #right.order then
            return false
        end
        for index, loreName in ipairs(left.order) do
            if right.order[index] ~= loreName
                or not sameStaticLoreSource(left[loreName], right[loreName]) then
                return false
            end
        end
        return true
    end

    local function findCachedDynamicLoreOrder(captured)
        for _, entry in ipairs(staticCacheEntries) do
            local sameBase = true
            for _, loreName in ipairs(STATIC_BASE_LORE_ORDER) do
                if not sameStaticLoreSource(entry.sources[loreName], captured[loreName]) then
                    sameBase = false
                    break
                end
            end
            if sameBase then
                local dynamicOrder = {}
                for index = #STATIC_BASE_LORE_ORDER + 1, #entry.sources.order do
                    table.insert(dynamicOrder, entry.sources.order[index])
                end
                return dynamicOrder
            end
        end
        return nil
    end

    local function findStaticCacheEntry(captured)
        for _, entry in ipairs(staticCacheEntries) do
            if sameStaticLoreCapture(entry.sources, captured) then
                staticCacheClock = staticCacheClock + 1
                entry.lastUsed = staticCacheClock
                entry.hits = entry.hits + 1
                return entry
            end
        end
        return nil
    end

    local function storeStaticCacheEntry(captured, report)
        if #staticCacheEntries >= STATIC_CACHE_MAX_ENTRIES then
            local oldestIndex = 1
            for index = 2, #staticCacheEntries do
                if staticCacheEntries[index].lastUsed < staticCacheEntries[oldestIndex].lastUsed then
                    oldestIndex = index
                end
            end
            table.remove(staticCacheEntries, oldestIndex)
            staticCacheStats.evictions = staticCacheStats.evictions + 1
        end

        staticCacheClock = staticCacheClock + 1
        table.insert(staticCacheEntries, {
            sources = captured,
            report = report,
            lastUsed = staticCacheClock,
            hits = 0,
        })
    end

    local function clearStaticCache()
        local removed = #staticCacheEntries
        staticCacheEntries = {}
        staticCacheStats.clears = staticCacheStats.clears + 1
        return removed
    end

    local function getStaticCacheDiagnostics()
        local diagnostics = {
            maxEntries = STATIC_CACHE_MAX_ENTRIES,
            entries = #staticCacheEntries,
            requests = staticCacheStats.requests,
            captures = staticCacheStats.captures,
            fastHits = staticCacheStats.fastHits,
            hits = staticCacheStats.hits,
            misses = staticCacheStats.misses,
            validations = staticCacheStats.validations,
            failedValidations = staticCacheStats.failedValidations,
            evictions = staticCacheStats.evictions,
            clears = staticCacheStats.clears,
            cached = {},
        }
        for _, entry in ipairs(staticCacheEntries) do
            table.insert(diagnostics.cached, {
                hits = entry.hits,
                lastUsed = entry.lastUsed,
                counts = cloneStaticValue(entry.report.counts),
            })
        end
        return diagnostics
    end

    return function(triggerId, action)
    local SUPPORTED_SCHEMA_VERSION = 1

    local SOURCES = {
        registry = {
            kind = "gameRegistry",
            collection = nil,
            lores = { "GameRegistry.db" },
        },
        cards = {
            kind = "cardDatabase",
            collection = "cards",
            lores = { "PlayerCards.db", "CharacterCards.db" },
        },
        traits = {
            kind = "traitDatabase",
            collection = "traits",
            lores = { "CharTraits.db" },
        },
        environments = {
            kind = "environmentDatabase",
            collection = "environments",
            lores = { "Environments.db" },
        },
        subwayLines = {
            kind = "subwayLineDatabase",
            collection = "subwayLines",
            lores = { "TokyoSubwayLines.db" },
        },
        characterList = {
            kind = "characterList",
            collection = "characters",
            lores = { "CharacterList.db" },
        },
    }
    local RESERVED_CHARACTER_DATABASES = {
        ["GameRegistry.db"] = true,
        ["PlayerCards.db"] = true,
        ["CharacterCards.db"] = true,
        ["CharTraits.db"] = true,
        ["Environments.db"] = true,
        ["TokyoSubwayLines.db"] = true,
        ["CharacterList.db"] = true,
    }

    local function addError(errors, code, path, message)
        table.insert(errors, {
            code = code,
            path = path,
            message = message,
        })
        emitDiagnostic(1, "validation_error", {
            code = code,
            path = path,
            message = message,
        })
    end

    local function countEntries(value)
        if type(value) ~= "table" then
            return 0
        end

        local count = 0
        for _ in pairs(value) do
            count = count + 1
        end
        return count
    end

    local function isArray(value)
        if type(value) ~= "table" then
            return false
        end

        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if type(key) ~= "number" or key < 1 or key % 1 ~= 0 then
                return false
            end
            count = count + 1
            if key > maximum then
                maximum = key
            end
        end

        return count == maximum
    end

    local function isFiniteNonNegative(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
            and value >= 0
    end

    local function isPositiveInteger(value)
        return isFiniteNonNegative(value)
            and value >= 1
            and value % 1 == 0
    end

    local function isFiniteInteger(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
            and value % 1 == 0
    end

    local function isPlanCapacity(value)
        return isPositiveInteger(value) and value <= MAX_PLAN_CAPACITY
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isCharacterDatabaseName(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z][A-Za-z0-9_]*%.db$") ~= nil
    end

    local function makeDatabaseEnvironment()
        return {
            ipairs = ipairs,
            next = next,
            pairs = pairs,
            tonumber = tonumber,
            tostring = tostring,
            type = type,
        }
    end

    local function loadLoreModules(loreName, errors, captured)
        local source = captured[loreName]
        if source == nil or source.status == "read_error" then
            addError(
                errors,
                "lore_read_error",
                loreName,
                source and source.error or "정적 DB 로어북을 읽을 수 없습니다."
            )
            return {}
        end
        if source.status ~= "table" or #source.entries == 0 then
            addError(errors, "missing_lore", loreName, "정적 DB 로어북을 찾을 수 없습니다.")
            return {}
        end

        local modules = {}
        for index, lore in ipairs(source.entries) do
            if lore.valid ~= true then
                addError(errors, "invalid_lore", loreName .. "[" .. index .. "]", "로어북 내용이 문자열이 아닙니다.")
            else
                local chunk, compileError = load(
                    lore.content,
                    "static_db:" .. loreName .. ":" .. index,
                    "t",
                    makeDatabaseEnvironment()
                )

                if not chunk then
                    addError(errors, "compile_error", loreName .. "[" .. index .. "]", tostring(compileError))
                else
                    local ok, result = pcall(chunk)
                    if not ok then
                        addError(errors, "load_error", loreName .. "[" .. index .. "]", tostring(result))
                    elseif type(result) ~= "table" then
                        addError(errors, "invalid_module", loreName .. "[" .. index .. "]", "DB 청크가 테이블을 반환하지 않았습니다.")
                    else
                        table.insert(modules, result)
                        emitDiagnostic(2, "module_loaded", {
                            lore = loreName,
                            entryIndex = index,
                            schemaVersion = tostring(result.schemaVersion),
                            kindType = type(result.kind),
                            kind = type(result.kind) == "string" and result.kind or tostring(result.kind),
                        })
                    end
                end
            end
        end

        return modules
    end

    local function validateModuleHeader(module, expectedKind, path, errors)
        if module.schemaVersion ~= SUPPORTED_SCHEMA_VERSION then
            addError(errors, "unsupported_schema", path .. ".schemaVersion", "지원하지 않는 스키마 버전입니다.")
        end

        if module.kind ~= expectedKind then
            local actualKind = type(module.kind) == "string" and module.kind or tostring(module.kind)
            emitDiagnostic(1, "module_header_mismatch", {
                path = path .. ".kind",
                expectedKind = expectedKind,
                actualKindType = type(module.kind),
                actualKind = actualKind,
            })
            addError(
                errors,
                "unexpected_kind",
                path .. ".kind",
                "예상한 DB 종류와 다릅니다. (expected="
                    .. tostring(expectedKind)
                    .. ", actual="
                    .. actualKind
                    .. ")"
            )
        end
    end

    local function loadSingleModule(source, errors, captured)
        local loaded = nil

        for _, loreName in ipairs(source.lores) do
            local modules = loadLoreModules(loreName, errors, captured)
            for index, module in ipairs(modules) do
                local path = loreName .. "[" .. index .. "]"
                validateModuleHeader(module, source.kind, path, errors)

                if loaded then
                    addError(errors, "duplicate_module", path, "단일 DB가 여러 번 등록되었습니다.")
                else
                    loaded = module
                end
            end
        end

        return loaded
    end

    local function loadMergedCollection(source, errors, captured)
        local merged = {}
        local origins = {}

        for _, loreName in ipairs(source.lores) do
            local modules = loadLoreModules(loreName, errors, captured)
            for index, module in ipairs(modules) do
                local modulePath = loreName .. "[" .. index .. "]"
                validateModuleHeader(module, source.kind, modulePath, errors)

                local collection = module[source.collection]
                if type(collection) ~= "table" then
                    addError(errors, "missing_collection", modulePath .. "." .. source.collection, "DB 컬렉션이 없습니다.")
                else
                    for id, definition in pairs(collection) do
                        local itemPath = modulePath .. "." .. source.collection .. "." .. tostring(id)
                        if merged[id] ~= nil then
                            addError(
                                errors,
                                "duplicate_id",
                                itemPath,
                                "이미 " .. tostring(origins[id]) .. "에서 정의된 ID입니다."
                            )
                        else
                            merged[id] = definition
                            origins[id] = itemPath
                        end
                    end
                end
            end
        end

        return merged
    end

    local function sortedAsciiKeys(collection)
        local keys = {}
        if type(collection) == "table" then
            for key in pairs(collection) do
                if isAsciiId(key) then
                    table.insert(keys, key)
                end
            end
        end
        table.sort(keys)
        return keys
    end

    local function collectCharacterDatabaseNames(characterList)
        local names = {}
        local seen = {}
        for _, characterId in ipairs(sortedAsciiKeys(characterList)) do
            local entry = characterList[characterId]
            local database = type(entry) == "table" and entry.database or nil
            if isCharacterDatabaseName(database)
                and RESERVED_CHARACTER_DATABASES[database] ~= true
                and seen[database] ~= true then
                seen[database] = true
                table.insert(names, database)
            end
        end
        return names
    end

    local function validateCharacterList(characterList, errors)
        if type(characterList) ~= "table" then
            addError(errors, "missing_character_list", "characterList", "캐릭터 목록이 없습니다.")
            return
        end
        if next(characterList) == nil then
            addError(errors, "empty_character_list", "characterList", "캐릭터 목록이 비어 있습니다.")
            return
        end

        local firstCharacterByDatabase = {}
        for key, entry in pairs(characterList) do
            local path = "characterList." .. tostring(key)
            if not isAsciiId(key) or type(entry) ~= "table" or entry.id ~= key then
                addError(errors, "invalid_character_list_id", path, "캐릭터 목록 키와 내부 ID가 올바르지 않습니다.")
            else
                for field in pairs(entry) do
                    if field ~= "id" and field ~= "database" then
                        addError(
                            errors,
                            "unexpected_character_list_field",
                            path .. "." .. tostring(field),
                            "캐릭터 목록에는 id와 database만 사용할 수 있습니다."
                        )
                    end
                end

                if not isCharacterDatabaseName(entry.database) then
                    addError(
                        errors,
                        "invalid_character_database_name",
                        path .. ".database",
                        "개별 캐릭터 DB 이름은 영문자로 시작하고 영문자, 숫자, 밑줄만 사용한 .db 파일명이어야 합니다."
                    )
                elseif RESERVED_CHARACTER_DATABASES[entry.database] == true then
                    addError(
                        errors,
                        "reserved_character_database_name",
                        path .. ".database",
                        "공용 정적 DB 이름은 개별 캐릭터 DB로 사용할 수 없습니다."
                    )
                else
                    local firstId = firstCharacterByDatabase[entry.database]
                    if firstId ~= nil then
                        addError(
                            errors,
                            "duplicate_character_database",
                            path .. ".database",
                            "개별 캐릭터 DB '" .. entry.database .. "'는 이미 characterList."
                                .. firstId .. ".database에서 사용되었습니다."
                        )
                    else
                        firstCharacterByDatabase[entry.database] = key
                    end
                end
            end
        end
    end

    local function loadCharacterDefinitions(characterList, errors, captured)
        local characters = {}
        for _, characterId in ipairs(sortedAsciiKeys(characterList)) do
            local entry = characterList[characterId]
            local database = type(entry) == "table" and entry.database or nil
            if isCharacterDatabaseName(database)
                and RESERVED_CHARACTER_DATABASES[database] ~= true then
                local modules = loadLoreModules(database, errors, captured)
                if #modules > 1 then
                    addError(
                        errors,
                        "duplicate_character_module",
                        database,
                        "개별 캐릭터 DB는 하나의 로어 엔트리만 등록할 수 있습니다."
                    )
                end

                for index, module in ipairs(modules) do
                    local modulePath = database .. "[" .. index .. "]"
                    validateModuleHeader(module, "characterDatabase", modulePath, errors)
                    local collection = module.characters
                    if type(collection) ~= "table" then
                        addError(errors, "missing_collection", modulePath .. ".characters", "캐릭터 DB 컬렉션이 없습니다.")
                    else
                        local definition = collection[characterId]
                        if definition == nil then
                            addError(
                                errors,
                                "missing_listed_character",
                                modulePath .. ".characters." .. characterId,
                                "캐릭터 목록에 등록된 ID의 정의가 개별 DB에 없습니다."
                            )
                        elseif characters[characterId] == nil then
                            characters[characterId] = definition
                        end

                        for definedId in pairs(collection) do
                            if definedId ~= characterId then
                                addError(
                                    errors,
                                    "unlisted_character_definition",
                                    modulePath .. ".characters." .. tostring(definedId),
                                    "개별 캐릭터 DB에는 목록에서 연결한 캐릭터 한 명만 정의할 수 있습니다."
                                )
                            end
                        end
                    end
                end
            end
        end
        return characters
    end

    local function validateRegistryCollection(collection, path, errors, ownerRequired)
        if type(collection) ~= "table" then
            addError(errors, "missing_registry", path, "레지스트리 컬렉션이 없습니다.")
            return
        end

        for key, entry in pairs(collection) do
            local entryPath = path .. "." .. tostring(key)
            if not isAsciiId(key) then
                addError(errors, "invalid_id", entryPath, "레지스트리 키는 ASCII ID여야 합니다.")
            end
            if type(entry) ~= "table" or entry.id ~= key then
                addError(errors, "id_mismatch", entryPath, "레지스트리 키와 내부 ID가 다릅니다.")
            elseif ownerRequired and entry.owner ~= "player" and entry.owner ~= "character" then
                addError(errors, "invalid_owner", entryPath .. ".owner", "행동 태그 소유자가 올바르지 않습니다.")
            end
        end
    end

    local function validateRegistry(registry, errors)
        if type(registry) ~= "table" then
            addError(errors, "missing_registry", "registry", "중앙 게임 레지스트리가 없습니다.")
            return
        end

        validateRegistryCollection(registry.actionTags, "registry.actionTags", errors, true)
        validateRegistryCollection(registry.mechanisms, "registry.mechanisms", errors, false)
        validateRegistryCollection(registry.moods, "registry.moods", errors, false)
        validateRegistryCollection(registry.events, "registry.events", errors, false)
        validateRegistryCollection(registry.effectOps, "registry.effectOps", errors, false)

        if type(registry.actionTags) == "table" and type(registry.mechanisms) == "table" then
            for id in pairs(registry.actionTags) do
                if registry.mechanisms[id] then
                    addError(errors, "registry_id_collision", "registry." .. id, "행동 태그와 메커니즘 ID가 중복됩니다.")
                end
            end
        end
    end

    local function hasTagToken(description, id)
        return type(description) == "string"
            and type(id) == "string"
            and string.find(description, "::tag[" .. id .. "]::", 1, true) ~= nil
    end

    local function validateTagTokens(text, path, registry, errors)
        if type(text) ~= "string" then
            return
        end

        local remainder = string.gsub(text, "::tag%[[a-z][a-z0-9_]*%]::", "")
        if string.find(remainder, "::tag[", 1, true) then
            addError(errors, "malformed_tag_token", path, "형식이 잘못된 태그 토큰이 있습니다.")
        end

        for tagId in string.gmatch(text, "::tag%[([a-z][a-z0-9_]*)%]::") do
            local knownAction = type(registry) == "table"
                and type(registry.actionTags) == "table"
                and registry.actionTags[tagId]
            local knownMechanism = type(registry) == "table"
                and type(registry.mechanisms) == "table"
                and registry.mechanisms[tagId]

            if not knownAction and not knownMechanism then
                addError(errors, "unknown_tag_token", path, "등록되지 않은 태그 토큰입니다: " .. tagId)
            end
        end
    end

    local function validateNarration(card, path, isPlan, errors)
        if type(card.narration) ~= "table" then
            addError(errors, "missing_narration", path .. ".narration", "카드 묘사가 없습니다.")
            return
        end

        if isPlan then
            if type(card.narration.planPlaced) ~= "table"
                or type(card.narration.planPlaced.actorAction) ~= "string"
                or card.narration.planPlaced.actorAction == "" then
                addError(errors, "missing_plan_placed_narration", path .. ".narration.planPlaced", "계획 배치 묘사가 없습니다.")
            end
            if type(card.narration.planTriggered) ~= "table"
                or type(card.narration.planTriggered.actorAction) ~= "string"
                or card.narration.planTriggered.actorAction == "" then
                addError(errors, "missing_plan_triggered_narration", path .. ".narration.planTriggered", "계획 발동 묘사가 없습니다.")
            end
        elseif type(card.narration.play) ~= "table"
            or type(card.narration.play.actorAction) ~= "string"
            or card.narration.play.actorAction == "" then
            addError(errors, "missing_play_narration", path .. ".narration.play", "카드 사용 묘사가 없습니다.")
        end
    end

    local function validatePlanSelectionAssumption(card, plan, path, registry, errors)
        local assumption = plan.selectionAssumption
        if card.owner == "character" and assumption == nil then
            addError(
                errors,
                "missing_plan_selection_assumption",
                path .. ".selectionAssumption",
                "캐릭터 계획에는 선택 점수용 발동 가정이 필요합니다."
            )
            return
        end
        if assumption == nil then
            return
        end
        if card.owner ~= "character" then
            addError(
                errors,
                "unexpected_plan_selection_assumption",
                path .. ".selectionAssumption",
                "선택 점수용 계획 발동 가정은 캐릭터 카드에만 사용할 수 있습니다."
            )
        end
        if type(assumption) ~= "table" then
            addError(
                errors,
                "invalid_plan_selection_assumption",
                path .. ".selectionAssumption",
                "계획 선택 가정이 테이블이 아닙니다."
            )
            return
        end

        for field in pairs(assumption) do
            if field ~= "event" and field ~= "chargePolicy" then
                addError(
                    errors,
                    "unexpected_plan_selection_assumption_field",
                    path .. ".selectionAssumption." .. tostring(field),
                    "계획 선택 가정에 허용되지 않은 필드가 있습니다."
                )
            end
        end

        local event = assumption.event
        local eventPath = path .. ".selectionAssumption.event"
        if type(event) ~= "table" then
            addError(errors, "invalid_plan_selection_event", eventPath, "계획 선택 가정 사건이 테이블이 아닙니다.")
        else
            for field in pairs(event) do
                if field ~= "type" and field ~= "side" then
                    addError(
                        errors,
                        "unexpected_plan_selection_event_field",
                        eventPath .. "." .. tostring(field),
                        "계획 선택 가정 사건에는 type과 side만 사용할 수 있습니다."
                    )
                end
            end
            if type(registry) ~= "table"
                or type(registry.events) ~= "table"
                or type(event.type) ~= "string"
                or not registry.events[event.type] then
                addError(errors, "unknown_plan_selection_event", eventPath .. ".type", "등록되지 않은 계획 선택 가정 사건입니다.")
            end
            if event.side ~= "player" and event.side ~= "character" then
                addError(errors, "invalid_plan_selection_side", eventPath .. ".side", "계획 선택 가정 진영이 올바르지 않습니다.")
            end
        end

        if assumption.chargePolicy ~= "all" then
            addError(
                errors,
                "invalid_plan_selection_charge_policy",
                path .. ".selectionAssumption.chargePolicy",
                "캐릭터 계획 선택 점수는 모든 충전을 합산해야 합니다."
            )
        end
        if not isPositiveInteger(plan.charges) then
            addError(
                errors,
                "plan_selection_requires_charges",
                path .. ".charges",
                "캐릭터 계획 선택 점수에는 양의 충전 수가 필요합니다."
            )
        end
    end

    local function validateCards(cards, registry, errors)
        if type(cards) ~= "table" then
            addError(errors, "missing_cards", "cards", "카드 컬렉션이 없습니다.")
            return
        end

        for key, card in pairs(cards) do
            local path = "cards." .. tostring(key)
            if not isAsciiId(key) then
                addError(errors, "invalid_id", path, "카드 키는 ASCII ID여야 합니다.")
            end

            if type(card) ~= "table" then
                addError(errors, "invalid_card", path, "카드 정의가 테이블이 아닙니다.")
            else
                if card.id ~= key then
                    addError(errors, "id_mismatch", path .. ".id", "카드 키와 내부 ID가 다릅니다.")
                end
                if card.owner ~= "player" and card.owner ~= "character" then
                    addError(errors, "invalid_owner", path .. ".owner", "카드 소유자가 올바르지 않습니다.")
                end
                if type(card.name) ~= "string" or card.name == "" then
                    addError(errors, "missing_name", path .. ".name", "카드 이름이 없습니다.")
                end
                if type(card.description) ~= "string" or card.description == "" then
                    addError(errors, "missing_description", path .. ".description", "카드 설명이 없습니다.")
                end
                validateTagTokens(card.description, path .. ".description", registry, errors)

                local action = type(registry) == "table"
                    and type(registry.actionTags) == "table"
                    and registry.actionTags[card.actionTag]
                    or nil
                if not action then
                    addError(errors, "unknown_action_tag", path .. ".actionTag", "등록되지 않은 행동 태그입니다.")
                elseif action.owner ~= card.owner then
                    addError(errors, "action_owner_mismatch", path .. ".actionTag", "행동 태그 소유자와 카드 소유자가 다릅니다.")
                end
                if not hasTagToken(card.description, card.actionTag) then
                    addError(errors, "missing_action_token", path .. ".description", "설명에 자신의 행동 태그 토큰이 없습니다.")
                end

                if not isArray(card.mechanisms) then
                    addError(errors, "invalid_mechanisms", path .. ".mechanisms", "메커니즘 목록이 배열이 아닙니다.")
                else
                    local seenMechanisms = {}
                    for index, mechanismId in ipairs(card.mechanisms) do
                        local mechanismPath = path .. ".mechanisms[" .. index .. "]"
                        if type(registry) ~= "table"
                            or type(registry.mechanisms) ~= "table"
                            or not registry.mechanisms[mechanismId] then
                            addError(errors, "unknown_mechanism", mechanismPath, "등록되지 않은 메커니즘입니다.")
                        end
                        if seenMechanisms[mechanismId] then
                            addError(errors, "duplicate_mechanism", mechanismPath, "같은 메커니즘이 중복되었습니다.")
                        end
                        seenMechanisms[mechanismId] = true
                        if not hasTagToken(card.description, mechanismId) then
                            addError(errors, "missing_mechanism_token", path .. ".description", "설명에 메커니즘 태그 토큰이 없습니다.")
                        end
                    end

                    if type(card.mechanismData) == "table" then
                        for mechanismId in pairs(card.mechanismData) do
                            if not seenMechanisms[mechanismId] then
                                addError(errors, "orphan_mechanism_data", path .. ".mechanismData." .. tostring(mechanismId), "보유하지 않은 메커니즘의 설정입니다.")
                            end
                        end
                    end

                    local hasPlan = seenMechanisms.plan == true
                    local plan = type(card.mechanismData) == "table" and card.mechanismData.plan or nil
                    if hasPlan then
                        if type(plan) ~= "table" then
                            addError(errors, "missing_plan_data", path .. ".mechanismData.plan", "계획 설정이 없습니다.")
                        else
                            if plan.durationTurns ~= nil and not isPositiveInteger(plan.durationTurns) then
                                addError(errors, "invalid_plan_duration", path .. ".mechanismData.plan.durationTurns", "계획 지속 턴은 1 이상의 정수여야 합니다.")
                            end
                            if plan.durationIncludesPlacementTurn ~= nil
                                and type(plan.durationIncludesPlacementTurn) ~= "boolean" then
                                addError(
                                    errors,
                                    "invalid_plan_duration_policy",
                                    path .. ".mechanismData.plan.durationIncludesPlacementTurn",
                                    "배치 턴 포함 여부는 불리언이어야 합니다."
                                )
                            elseif plan.durationIncludesPlacementTurn == true
                                and not isPositiveInteger(plan.durationTurns) then
                                addError(
                                    errors,
                                    "plan_duration_policy_requires_duration",
                                    path .. ".mechanismData.plan.durationIncludesPlacementTurn",
                                    "배치 턴을 포함하려면 양의 durationTurns가 필요합니다."
                                )
                            end
                            if plan.charges ~= nil and not isPositiveInteger(plan.charges) then
                                addError(errors, "invalid_plan_charges", path .. ".mechanismData.plan.charges", "계획 충전은 1 이상의 정수여야 합니다.")
                            end
                            local hasLifetime = isPositiveInteger(plan.durationTurns)
                                or isPositiveInteger(plan.charges)
                                or type(plan.expires) == "function"
                            if not hasLifetime then
                                addError(errors, "unlimited_plan", path .. ".mechanismData.plan", "계획 수명이 제한되지 않았습니다.")
                            end
                            if type(plan.trigger) ~= "function" then
                                addError(errors, "invalid_plan_trigger", path .. ".mechanismData.plan.trigger", "계획 조건이 함수가 아닙니다.")
                            end
                            if type(plan.resolve) ~= "function" then
                                addError(errors, "invalid_plan_resolve", path .. ".mechanismData.plan.resolve", "계획 효과가 함수가 아닙니다.")
                            end
                            validatePlanSelectionAssumption(
                                card,
                                plan,
                                path .. ".mechanismData.plan",
                                registry,
                                errors
                            )
                        end
                    elseif plan ~= nil then
                        addError(errors, "unexpected_plan_data", path .. ".mechanismData.plan", "계획 메커니즘이 없는 카드에 계획 설정이 있습니다.")
                    end

                    local selectionPreview = card.selectionPreview
                    if selectionPreview ~= nil then
                        local previewPath = path .. ".selectionPreview"
                        if card.owner ~= "player" or not seenMechanisms.chain then
                            addError(errors, "preview_requires_player_chain", previewPath, "선택 단계 효과는 플레이어 연계 카드에만 선언할 수 있습니다.")
                        end
                        if card.resolve ~= nil then
                            addError(errors, "preview_with_resolve", path .. ".resolve", "선택 단계 효과 카드에는 v1 resolve를 함께 둘 수 없습니다.")
                        end
                        if type(selectionPreview) ~= "table" then
                            addError(errors, "invalid_selection_preview", previewPath, "선택 단계 효과 정책이 테이블이 아닙니다.")
                        else
                            for field in pairs(selectionPreview) do
                                if field ~= "effects" then
                                    addError(errors, "unexpected_preview_field", previewPath .. "." .. tostring(field), "선택 단계 효과 정책에 허용되지 않은 필드가 있습니다.")
                                end
                            end

                            if not isArray(selectionPreview.effects) or #selectionPreview.effects == 0 then
                                addError(errors, "invalid_preview_effects", previewPath .. ".effects", "선택 단계 효과는 비어 있지 않은 배열이어야 합니다.")
                            else
                                local seenEffectIds = {}
                                for effectIndex, effect in ipairs(selectionPreview.effects) do
                                    local effectPath = previewPath .. ".effects[" .. effectIndex .. "]"
                                    if type(effect) ~= "table" then
                                        addError(errors, "invalid_preview_effect", effectPath, "선택 단계 효과가 테이블이 아닙니다.")
                                    else
                                        for field in pairs(effect) do
                                            if field ~= "id" and field ~= "op" and field ~= "target" and field ~= "amount" then
                                                addError(errors, "unexpected_preview_effect_field", effectPath .. "." .. tostring(field), "선택 단계 효과에 허용되지 않은 필드가 있습니다.")
                                            end
                                        end
                                        if not isAsciiId(effect.id) then
                                            addError(errors, "invalid_preview_effect_id", effectPath .. ".id", "선택 단계 효과 ID는 ASCII ID여야 합니다.")
                                        elseif seenEffectIds[effect.id] then
                                            addError(errors, "duplicate_preview_effect_id", effectPath .. ".id", "선택 단계 효과 ID가 중복되었습니다.")
                                        else
                                            seenEffectIds[effect.id] = true
                                        end

                                        local registeredOp = type(registry) == "table"
                                            and type(registry.effectOps) == "table"
                                            and registry.effectOps[effect.op]
                                            or nil
                                        if not registeredOp then
                                            addError(errors, "unknown_preview_op", effectPath .. ".op", "등록되지 않은 선택 단계 효과 작업입니다.")
                                        elseif effect.op ~= "draw_cards" then
                                            addError(errors, "unsupported_preview_op", effectPath .. ".op", "선택 단계 효과 v1은 draw_cards만 지원합니다.")
                                        end
                                        if effect.target ~= "player" then
                                            addError(errors, "invalid_preview_target", effectPath .. ".target", "선택 단계 드로우 대상은 player여야 합니다.")
                                        end
                                        if not isPositiveInteger(effect.amount) then
                                            addError(errors, "invalid_preview_amount", effectPath .. ".amount", "선택 단계 드로우 수량은 1 이상의 정수여야 합니다.")
                                        end
                                    end
                                end
                            end
                        end
                    end

                    validateNarration(card, path, hasPlan, errors)
                    if hasPlan and type(card.effectChoices) == "table" then
                        local hasImmediateChoice = false
                        for _, choice in ipairs(card.effectChoices) do
                            if type(choice) == "table" and choice.placesPlan == false then
                                hasImmediateChoice = true
                            end
                        end
                        if hasImmediateChoice
                            and (type(card.narration) ~= "table"
                                or type(card.narration.play) ~= "table"
                                or type(card.narration.play.actorAction) ~= "string"
                                or card.narration.play.actorAction == "") then
                            addError(errors, "missing_immediate_choice_narration", path .. ".narration.play", "즉시 발동 선택지가 있는 계획 카드에는 사용 묘사가 필요합니다.")
                        end
                    end
                end

                if type(card.base) ~= "table" then
                    addError(errors, "missing_base", path .. ".base", "카드 기본 수치가 없습니다.")
                else
                    if not isFiniteNonNegative(card.base.stealthCost) then
                        addError(errors, "invalid_stealth_cost", path .. ".base.stealthCost", "기본 은폐 비용이 0 이상의 유한한 숫자가 아닙니다.")
                    end
                    if not isFiniteNonNegative(card.base.resistanceDamage) then
                        addError(errors, "invalid_resistance_damage", path .. ".base.resistanceDamage", "기본 저항 피해가 0 이상의 유한한 숫자가 아닙니다.")
                    end
                end

                if not isArray(card.rules) or #card.rules == 0 then
                    addError(errors, "invalid_rules", path .. ".rules", "카드 규칙 문장이 비어 있습니다.")
                else
                    for index, rule in ipairs(card.rules) do
                        if type(rule) ~= "string" or rule == "" then
                            addError(errors, "invalid_rule", path .. ".rules[" .. index .. "]", "카드 규칙이 빈 문자열이거나 문자열이 아닙니다.")
                        else
                            validateTagTokens(rule, path .. ".rules[" .. index .. "]", registry, errors)
                        end
                    end
                end
                if card.canPlay ~= nil and type(card.canPlay) ~= "function" then
                    addError(errors, "invalid_can_play", path .. ".canPlay", "사용 조건이 함수가 아닙니다.")
                end
                if card.resolve ~= nil and type(card.resolve) ~= "function" then
                    addError(errors, "invalid_resolve", path .. ".resolve", "카드 효과가 함수가 아닙니다.")
                end
                if card.effectChoices ~= nil then
                    local choicesPath = path .. ".effectChoices"
                    if card.owner ~= "player" then
                        addError(errors, "choice_requires_player", choicesPath, "효과 선택지는 플레이어 카드에만 선언할 수 있습니다.")
                    end
                    if not isArray(card.effectChoices) or #card.effectChoices < 2 then
                        addError(errors, "invalid_effect_choices", choicesPath, "효과 선택지는 2개 이상의 배열이어야 합니다.")
                    else
                        local seenChoiceIds = {}
                        for choiceIndex, choice in ipairs(card.effectChoices) do
                            local choicePath = choicesPath .. "[" .. choiceIndex .. "]"
                            if type(choice) ~= "table" then
                                addError(errors, "invalid_effect_choice", choicePath, "효과 선택지가 테이블이 아닙니다.")
                            else
                                for field in pairs(choice) do
                                    if field ~= "id"
                                        and field ~= "label"
                                        and field ~= "description"
                                        and field ~= "unavailableText"
                                        and field ~= "canSelect"
                                        and field ~= "placesPlan" then
                                        addError(errors, "unexpected_effect_choice_field", choicePath .. "." .. tostring(field), "효과 선택지에 허용되지 않은 필드가 있습니다.")
                                    end
                                end
                                if not isAsciiId(choice.id) then
                                    addError(errors, "invalid_effect_choice_id", choicePath .. ".id", "효과 선택지 ID는 ASCII ID여야 합니다.")
                                elseif seenChoiceIds[choice.id] then
                                    addError(errors, "duplicate_effect_choice_id", choicePath .. ".id", "효과 선택지 ID가 중복되었습니다.")
                                else
                                    seenChoiceIds[choice.id] = true
                                end
                                if type(choice.label) ~= "string" or choice.label == "" then
                                    addError(errors, "invalid_effect_choice_label", choicePath .. ".label", "효과 선택지 표시명이 필요합니다.")
                                end
                                if type(choice.description) ~= "string" or choice.description == "" then
                                    addError(errors, "invalid_effect_choice_description", choicePath .. ".description", "효과 선택지 설명이 필요합니다.")
                                else
                                    validateTagTokens(choice.description, choicePath .. ".description", registry, errors)
                                end
                                if choice.unavailableText ~= nil
                                    and (type(choice.unavailableText) ~= "string" or choice.unavailableText == "") then
                                    addError(errors, "invalid_effect_choice_unavailable_text", choicePath .. ".unavailableText", "비활성 안내는 비어 있지 않은 문자열이어야 합니다.")
                                end
                                if choice.canSelect ~= nil and type(choice.canSelect) ~= "function" then
                                    addError(errors, "invalid_effect_choice_predicate", choicePath .. ".canSelect", "효과 선택 가능 조건이 함수가 아닙니다.")
                                end
                                if choice.placesPlan ~= nil then
                                    if type(choice.placesPlan) ~= "boolean" then
                                        addError(errors, "invalid_effect_choice_plan_flag", choicePath .. ".placesPlan", "계획 배치 여부는 불리언이어야 합니다.")
                                    elseif not hasMechanism(card, "plan") then
                                        addError(errors, "effect_choice_plan_without_mechanism", choicePath .. ".placesPlan", "계획 메커니즘이 없는 카드에는 계획 배치 선택을 선언할 수 없습니다.")
                                    end
                                end
                            end
                        end
                    end
                end
                if card.moodEffects ~= nil then
                    if type(card.moodEffects) ~= "table" then
                        addError(errors, "invalid_mood_effects", path .. ".moodEffects", "무드 효과가 테이블이 아닙니다.")
                    else
                        for moodId, callback in pairs(card.moodEffects) do
                            if type(registry) ~= "table"
                                or type(registry.moods) ~= "table"
                                or not registry.moods[moodId] then
                                addError(errors, "unknown_mood", path .. ".moodEffects." .. tostring(moodId), "등록되지 않은 무드입니다.")
                            end
                            if type(callback) ~= "function" then
                                addError(errors, "invalid_mood_callback", path .. ".moodEffects." .. tostring(moodId), "무드 효과가 함수가 아닙니다.")
                            end
                        end
                    end
                end
            end
        end
    end

    local function validateTraits(traits, errors)
        if type(traits) ~= "table" then
            addError(errors, "missing_traits", "traits", "특징 컬렉션이 없습니다.")
            return
        end

        for key, trait in pairs(traits) do
            local path = "traits." .. tostring(key)
            if not isAsciiId(key) or type(trait) ~= "table" or trait.id ~= key then
                addError(errors, "invalid_trait_id", path, "특징 키와 내부 ID가 올바르지 않습니다.")
            else
                if trait.owner ~= "player" and trait.owner ~= "character" then
                    addError(errors, "invalid_owner", path .. ".owner", "특징 소유자가 올바르지 않습니다.")
                end
                if trait.visibility ~= "public" and trait.visibility ~= "hidden" then
                    addError(errors, "invalid_visibility", path .. ".visibility", "특징 공개 범위가 올바르지 않습니다.")
                end
                if type(trait.name) ~= "string" or trait.name == "" then
                    addError(errors, "missing_name", path .. ".name", "특징 이름이 없습니다.")
                end
                if type(trait.description) ~= "string" or trait.description == "" then
                    addError(errors, "missing_description", path .. ".description", "특징 설명이 없습니다.")
                end
                if not isArray(trait.rules) or #trait.rules == 0 then
                    addError(errors, "invalid_rules", path .. ".rules", "특징 규칙 문장이 비어 있습니다.")
                end
                if trait.modifiers ~= nil then
                    local modifiersPath = path .. ".modifiers"
                    if not isArray(trait.modifiers) then
                        addError(errors, "invalid_trait_modifiers", modifiersPath, "특징 보정은 연속 배열이어야 합니다.")
                    else
                        for index, modifier in ipairs(trait.modifiers) do
                            local modifierPath = modifiersPath .. "[" .. index .. "]"
                            if type(modifier) ~= "table" then
                                addError(
                                    errors,
                                    "invalid_trait_modifier",
                                    modifierPath,
                                    "특징 보정 항목은 객체여야 합니다."
                                )
                            else
                                local allowed = {
                                    stat = true,
                                    operation = true,
                                    amount = true,
                                }
                                for field in pairs(modifier) do
                                    if not allowed[field] then
                                        addError(
                                            errors,
                                            "unknown_trait_modifier_field",
                                            modifierPath .. "." .. tostring(field),
                                            "특징 보정에 허용되지 않은 필드가 있습니다."
                                        )
                                    end
                                end
                                if modifier.stat ~= "planCapacity" then
                                    addError(
                                        errors,
                                        "unsupported_trait_modifier_stat",
                                        modifierPath .. ".stat",
                                        "현재 특징 보정은 planCapacity만 지원합니다."
                                    )
                                end
                                if modifier.operation ~= "add" then
                                    addError(
                                        errors,
                                        "unsupported_trait_modifier_operation",
                                        modifierPath .. ".operation",
                                        "planCapacity 특징 보정은 add 연산만 지원합니다."
                                    )
                                end
                                if not isFiniteInteger(modifier.amount) then
                                    addError(
                                        errors,
                                        "invalid_trait_modifier_amount",
                                        modifierPath .. ".amount",
                                        "planCapacity 특징 보정량은 유한한 정수여야 합니다."
                                    )
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    local function validateEnvironments(environments, registry, errors)
        if type(environments) ~= "table" then
            addError(errors, "missing_environments", "environments", "환경 컬렉션이 없습니다.")
            return
        end

        for key, environment in pairs(environments) do
            local path = "environments." .. tostring(key)
            if not isAsciiId(key) or type(environment) ~= "table" or environment.id ~= key then
                addError(errors, "invalid_environment_id", path, "환경 키와 내부 ID가 올바르지 않습니다.")
            else
                if type(environment.name) ~= "string" or environment.name == "" then
                    addError(errors, "missing_name", path .. ".name", "환경 이름이 없습니다.")
                end
                if type(environment.description) ~= "string" or environment.description == "" then
                    addError(errors, "missing_description", path .. ".description", "환경 설명이 없습니다.")
                end
                if not isArray(environment.rules) or #environment.rules == 0 then
                    addError(errors, "invalid_rules", path .. ".rules", "환경 규칙 문장이 비어 있습니다.")
                end
                if not isArray(environment.triggers) or #environment.triggers == 0 then
                    addError(errors, "invalid_triggers", path .. ".triggers", "환경 트리거가 비어 있습니다.")
                else
                    for index, trigger in ipairs(environment.triggers) do
                        local triggerPath = path .. ".triggers[" .. index .. "]"
                        if type(trigger) ~= "table" then
                            addError(errors, "invalid_trigger", triggerPath, "환경 트리거가 테이블이 아닙니다.")
                        else
                            if type(registry) ~= "table"
                                or type(registry.events) ~= "table"
                                or not registry.events[trigger.event] then
                                addError(errors, "unknown_event", triggerPath .. ".event", "등록되지 않은 사건입니다.")
                            end
                            if trigger.side ~= "player" and trigger.side ~= "character" then
                                addError(errors, "invalid_side", triggerPath .. ".side", "트리거 진영이 올바르지 않습니다.")
                            end
                            if type(trigger.resolve) ~= "function" then
                                addError(errors, "invalid_resolve", triggerPath .. ".resolve", "환경 효과가 함수가 아닙니다.")
                            end
                        end
                    end
                end
            end
        end
    end

    local function validateSubwayLines(subwayLines, errors)
        if type(subwayLines) ~= "table" then
            addError(errors, "missing_subway_lines", "subwayLines", "지하철 노선 컬렉션이 없습니다.")
            return
        end
        if next(subwayLines) == nil then
            addError(errors, "empty_subway_lines", "subwayLines", "지하철 노선 컬렉션이 비어 있습니다.")
            return
        end

        for key, line in pairs(subwayLines) do
            local linePath = "subwayLines." .. tostring(key)
            if not isAsciiId(key) or type(line) ~= "table" or line.id ~= key then
                addError(errors, "invalid_subway_line_id", linePath, "노선 키와 내부 ID가 올바르지 않습니다.")
            else
                if not isAsciiId(line.operatorId) then
                    addError(errors, "invalid_subway_operator_id", linePath .. ".operatorId", "운영사 ID가 올바르지 않습니다.")
                end
                if type(line.operatorName) ~= "string" or line.operatorName == "" then
                    addError(errors, "missing_subway_operator_name", linePath .. ".operatorName", "운영사 표시명이 없습니다.")
                end
                if type(line.name) ~= "string" or line.name == "" then
                    addError(errors, "missing_subway_line_name", linePath .. ".name", "노선 표시명이 없습니다.")
                end
                if type(line.code) ~= "string"
                    or string.match(line.code, "^[A-Z]$") == nil then
                    addError(errors, "invalid_subway_line_code", linePath .. ".code", "노선 코드는 영문 대문자 한 글자여야 합니다.")
                end
                if type(line.color) ~= "string"
                    or string.match(line.color, "^#%x%x%x%x%x%x$") == nil then
                    addError(errors, "invalid_subway_line_color", linePath .. ".color", "노선 색상은 #RRGGBB 형식이어야 합니다.")
                end

                if not isArray(line.paths) or #line.paths == 0 then
                    addError(errors, "invalid_subway_paths", linePath .. ".paths", "노선 경로 목록이 비어 있습니다.")
                else
                    local pathIds = {}
                    local stationDefinitions = {}
                    local supportsMinimum = false
                    local supportsMaximum = false
                    for pathIndex, routePath in ipairs(line.paths) do
                        local pathPath = linePath .. ".paths[" .. pathIndex .. "]"
                        if type(routePath) ~= "table" then
                            addError(errors, "invalid_subway_path", pathPath, "노선 경로가 테이블이 아닙니다.")
                        else
                            if not isAsciiId(routePath.id) then
                                addError(errors, "invalid_subway_path_id", pathPath .. ".id", "노선 경로 ID가 올바르지 않습니다.")
                            elseif pathIds[routePath.id] then
                                addError(errors, "duplicate_subway_path_id", pathPath .. ".id", "노선 경로 ID가 중복되었습니다.")
                            else
                                pathIds[routePath.id] = true
                            end
                            if type(routePath.circular) ~= "boolean" then
                                addError(errors, "invalid_subway_path_circular", pathPath .. ".circular", "순환 경로 여부는 불리언이어야 합니다.")
                            end
                            if not isArray(routePath.stations) or #routePath.stations < 2 then
                                addError(errors, "invalid_subway_stations", pathPath .. ".stations", "경로에는 두 개 이상의 역이 필요합니다.")
                            else
                                if routePath.circular == true or #routePath.stations >= 8 then
                                    supportsMinimum = true
                                end
                                if routePath.circular == true or #routePath.stations >= 13 then
                                    supportsMaximum = true
                                end
                                local stationIds = {}
                                for stationIndex, station in ipairs(routePath.stations) do
                                    local stationPath = pathPath .. ".stations[" .. stationIndex .. "]"
                                    if type(station) ~= "table" then
                                        addError(errors, "invalid_subway_station", stationPath, "역 정의가 테이블이 아닙니다.")
                                    else
                                        if not isAsciiId(station.id) then
                                            addError(errors, "invalid_subway_station_id", stationPath .. ".id", "역 ID가 올바르지 않습니다.")
                                        elseif stationIds[station.id] then
                                            addError(errors, "duplicate_subway_station_id", stationPath .. ".id", "한 경로 안에서 역 ID가 중복되었습니다.")
                                        else
                                            stationIds[station.id] = true
                                        end
                                        if type(station.code) ~= "string"
                                            or string.match(station.code, "^[A-Za-z]+[0-9][0-9]$") == nil then
                                            addError(errors, "invalid_subway_station_code", stationPath .. ".code", "역 코드는 영문자와 두 자리 숫자로 구성해야 합니다.")
                                        end
                                        if type(station.name) ~= "string" or station.name == "" then
                                            addError(errors, "missing_subway_station_name", stationPath .. ".name", "역 표시명이 없습니다.")
                                        end

                                        local previous = stationDefinitions[station.id]
                                        if previous ~= nil
                                            and (previous.code ~= station.code or previous.name ~= station.name) then
                                            addError(errors, "subway_station_definition_conflict", stationPath, "같은 역 ID의 코드나 표시명이 경로마다 다릅니다.")
                                        elseif previous == nil and isAsciiId(station.id) then
                                            stationDefinitions[station.id] = {
                                                code = station.code,
                                                name = station.name,
                                            }
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if not supportsMinimum then
                        addError(errors, "subway_line_too_short", linePath .. ".paths", "이 노선에는 7턴 여정을 만들 수 있는 경로가 없습니다.")
                    end
                    if not supportsMaximum then
                        addError(errors, "subway_line_missing_maximum_route", linePath .. ".paths", "이 노선에는 12턴 여정을 만들 수 있는 경로가 없습니다.")
                    end
                end
            end
        end
    end

    local function validateCharacters(characters, cards, traits, registry, errors)
        if type(characters) ~= "table" then
            addError(errors, "missing_characters", "characters", "캐릭터 컬렉션이 없습니다.")
            return
        end

        local namedCharacters = {}

        for key, character in pairs(characters) do
            local path = "characters." .. tostring(key)
            if not isAsciiId(key) or type(character) ~= "table" or character.id ~= key then
                addError(errors, "invalid_character_id", path, "캐릭터 키와 내부 ID가 올바르지 않습니다.")
            else
                if type(character.name) ~= "string" or character.name == "" then
                    addError(errors, "missing_name", path .. ".name", "캐릭터 이름이 없습니다.")
                else
                    table.insert(namedCharacters, {
                        id = key,
                        name = character.name,
                    })
                end
                if type(character.publicProfile) ~= "table" then
                    addError(errors, "missing_public_profile", path .. ".publicProfile", "공개 프로필이 없습니다.")
                end
                if character.privateProfile ~= nil and type(character.privateProfile) ~= "table" then
                    addError(errors, "invalid_private_profile", path .. ".privateProfile", "비공개 프로필이 테이블이 아닙니다.")
                end

                local battle = character.battle
                if type(battle) ~= "table" then
                    addError(errors, "missing_battle", path .. ".battle", "전투 정의가 없습니다.")
                else
                    if not isFiniteNonNegative(battle.startingResistance) or battle.startingResistance == 0 then
                        addError(errors, "invalid_starting_resistance", path .. ".battle.startingResistance", "시작 저항이 양수의 유한한 숫자가 아닙니다.")
                    end
                    if not isPositiveInteger(battle.baseDrawCount) then
                        addError(errors, "invalid_base_draw_count", path .. ".battle.baseDrawCount", "기본 드로우 수는 1 이상의 정수여야 합니다.")
                    end
                    if not isPositiveInteger(battle.maxHandSize) then
                        addError(errors, "invalid_hand_size", path .. ".battle.maxHandSize", "최대 손패는 1 이상의 정수여야 합니다.")
                    end
                    if not isPlanCapacity(battle.planCapacity) then
                        addError(errors, "invalid_plan_capacity", path .. ".battle.planCapacity", "기본 계획 용량은 1 이상 16 이하의 정수여야 합니다.")
                    end
                    if isPositiveInteger(battle.baseDrawCount)
                        and isPositiveInteger(battle.maxHandSize)
                        and battle.baseDrawCount > battle.maxHandSize then
                        addError(errors, "draw_exceeds_hand_limit", path .. ".battle.baseDrawCount", "기본 드로우 수는 최대 손패보다 클 수 없습니다.")
                    end
                    if type(registry) ~= "table"
                        or type(registry.moods) ~= "table"
                        or not registry.moods[battle.startingMood] then
                        addError(errors, "unknown_starting_mood", path .. ".battle.startingMood", "등록되지 않은 시작 무드입니다.")
                    end

                    if not isArray(battle.traitIds) then
                        addError(errors, "invalid_trait_ids", path .. ".battle.traitIds", "특징 ID 목록이 배열이 아닙니다.")
                    else
                        local effectivePlanCapacity = battle.planCapacity
                        for index, traitId in ipairs(battle.traitIds) do
                            local trait = traits[traitId]
                            if not trait or trait.owner ~= "character" then
                                addError(errors, "unknown_character_trait", path .. ".battle.traitIds[" .. index .. "]", "캐릭터 특징을 찾을 수 없습니다.")
                            elseif isFiniteInteger(effectivePlanCapacity) and isArray(trait.modifiers) then
                                for _, modifier in ipairs(trait.modifiers) do
                                    if type(modifier) == "table"
                                        and modifier.stat == "planCapacity"
                                        and modifier.operation == "add"
                                        and isFiniteInteger(modifier.amount) then
                                        effectivePlanCapacity = effectivePlanCapacity + modifier.amount
                                    end
                                end
                            end
                        end
                        if isPlanCapacity(battle.planCapacity)
                            and not isPlanCapacity(effectivePlanCapacity) then
                            addError(
                                errors,
                                "invalid_effective_plan_capacity",
                                path .. ".battle.planCapacity",
                                "기본 계획 용량과 특징 보정의 합은 1 이상 16 이하여야 합니다."
                            )
                        end
                    end

                    if not isArray(battle.deck) or #battle.deck == 0 then
                        addError(errors, "invalid_character_deck", path .. ".battle.deck", "캐릭터 덱이 비어 있거나 배열이 아닙니다.")
                    else
                        for index, cardId in ipairs(battle.deck) do
                            local card = cards[cardId]
                            if not card or card.owner ~= "character" then
                                addError(errors, "invalid_character_card", path .. ".battle.deck[" .. index .. "]", "캐릭터 카드를 찾을 수 없습니다.")
                            end
                        end
                    end

                end
            end
        end

        -- pairs 순서에 따라 중복 오류의 위치가 달라지지 않도록 내부 ID 순으로
        -- 검사한다. 같은 표시 이름은 선택 화면에서 구분할 수 없으므로 정적 데이터
        -- 로딩 자체를 실패시킨다.
        table.sort(namedCharacters, function(left, right)
            return left.id < right.id
        end)
        local firstCharacterByName = {}
        for _, entry in ipairs(namedCharacters) do
            local firstId = firstCharacterByName[entry.name]
            if firstId ~= nil then
                addError(
                    errors,
                    "duplicate_character_name",
                    "characters." .. entry.id .. ".name",
                    "캐릭터 이름 '" .. entry.name .. "'은 이미 characters."
                        .. firstId .. ".name에서 사용되었습니다. 캐릭터 이름은 중복될 수 없습니다."
                )
            else
                firstCharacterByName[entry.name] = entry.id
            end
        end
    end

    local function validateCapturedStaticData(captured, discoveredCharacterList, discoveryErrors)
        local errors = {}
        for _, item in ipairs(discoveryErrors or {}) do
            table.insert(errors, item)
        end
        local registry = loadSingleModule(SOURCES.registry, errors, captured)
        local cards = loadMergedCollection(SOURCES.cards, errors, captured)
        local traits = loadMergedCollection(SOURCES.traits, errors, captured)
        local environments = loadMergedCollection(SOURCES.environments, errors, captured)
        local subwayLines = loadMergedCollection(SOURCES.subwayLines, errors, captured)
        local characterList = discoveredCharacterList
        if characterList == nil then
            characterList = loadMergedCollection(SOURCES.characterList, errors, captured)
        end
        validateCharacterList(characterList, errors)
        local characters = loadCharacterDefinitions(characterList, errors, captured)

        validateRegistry(registry, errors)
        validateCards(cards, registry, errors)
        validateTraits(traits, errors)
        validateEnvironments(environments, registry, errors)
        validateSubwayLines(subwayLines, errors)
        validateCharacters(characters, cards, traits, registry, errors)

        return {
            ok = #errors == 0,
            schemaVersion = SUPPORTED_SCHEMA_VERSION,
            errors = errors,
            counts = {
                cards = countEntries(cards),
                traits = countEntries(traits),
                environments = countEntries(environments),
                subwayLines = countEntries(subwayLines),
                characters = countEntries(characters),
            },
            data = #errors == 0 and {
                registry = registry,
                cards = cards,
                traits = traits,
                environments = environments,
                subwayLines = subwayLines,
                characters = characters,
            } or nil,
        }
    end

    local function loadAndValidateAll(forceRefresh)
        staticCacheStats.requests = staticCacheStats.requests + 1
        emitDiagnostic(2, "validation_requested", {
            forceRefresh = forceRefresh == true,
            cachedEntries = #staticCacheEntries,
        })

        -- main production warm cache는 bundle revision + mode + chat + character별로
        -- handler closure를 분리한다. 따라서 같은 handler의 성공 snapshot은 source를
        -- 다시 읽지 않고 안전하게 재사용할 수 있다. main 없이 직접 실행되는 로컬
        -- 계약 검사는 global이 nil이므로 기존처럼 매번 source identity를 확인한다.
        if forceRefresh ~= true
            and RUNTIME_CACHE_DEVELOPMENT_BYPASS == false
            and #staticCacheEntries > 0 then
            local newest = staticCacheEntries[1]
            for index = 2, #staticCacheEntries do
                if staticCacheEntries[index].lastUsed > newest.lastUsed then
                    newest = staticCacheEntries[index]
                end
            end
            staticCacheClock = staticCacheClock + 1
            newest.lastUsed = staticCacheClock
            newest.hits = newest.hits + 1
            staticCacheStats.fastHits = staticCacheStats.fastHits + 1
            staticCacheStats.hits = staticCacheStats.hits + 1
            emitDiagnostic(2, "validation_cache_hit", {
                cache = "production_fast",
                ok = newest.report.ok == true,
            })
            return cloneStaticValue(newest.report)
        end

        local captured = captureBaseStaticLores(triggerId)
        local discoveredCharacterList = nil
        local discoveryErrors = nil
        local dynamicLoreOrder = findCachedDynamicLoreOrder(captured)
        if dynamicLoreOrder == nil then
            discoveryErrors = {}
            discoveredCharacterList = loadMergedCollection(SOURCES.characterList, discoveryErrors, captured)
            dynamicLoreOrder = collectCharacterDatabaseNames(discoveredCharacterList)
        end
        for _, database in ipairs(dynamicLoreOrder) do
            captureStaticLore(triggerId, captured, database)
        end
        local cached = findStaticCacheEntry(captured)
        if cached ~= nil then
            staticCacheStats.hits = staticCacheStats.hits + 1
            emitDiagnostic(2, "validation_cache_hit", {
                cache = "source_identity",
                ok = cached.report.ok == true,
            })
            return cloneStaticValue(cached.report)
        end

        staticCacheStats.misses = staticCacheStats.misses + 1
        staticCacheStats.validations = staticCacheStats.validations + 1
        local report = validateCapturedStaticData(captured, discoveredCharacterList, discoveryErrors)
        emitDiagnostic(report.ok == true and 2 or 1, "validation_completed", {
            ok = report.ok == true,
            errorCount = #report.errors,
            cards = report.counts.cards,
            traits = report.counts.traits,
            environments = report.counts.environments,
            subwayLines = report.counts.subwayLines,
            characters = report.counts.characters,
        })
        if report.ok == true then
            -- canonical report는 cache 내부에만 남기고 호출자에게는 별도 snapshot을 준다.
            storeStaticCacheEntry(captured, report)
            return cloneStaticValue(report)
        end

        -- 실패한 compile/validation 결과는 수정 후 즉시 다시 검사할 수 있도록 캐시하지 않는다.
        staticCacheStats.failedValidations = staticCacheStats.failedValidations + 1
        return report
    end

    local actions = {
        loadAll = loadAndValidateAll,
        validateAll = function()
            local result = loadAndValidateAll()
            result.data = nil
            return result
        end,
        reloadAll = function()
            return loadAndValidateAll(true)
        end,
        cacheStats = function()
            return {
                ok = true,
                schemaVersion = SUPPORTED_SCHEMA_VERSION,
                errors = {},
                cache = getStaticCacheDiagnostics(),
            }
        end,
        clearCache = function()
            return {
                ok = true,
                schemaVersion = SUPPORTED_SCHEMA_VERSION,
                errors = {},
                removed = clearStaticCache(),
            }
        end,
    }

    emitDiagnostic(2, "request", {
        action = tostring(action),
    })

    local handler = actions[action]
    if not handler then
        return {
            ok = false,
            schemaVersion = SUPPORTED_SCHEMA_VERSION,
            errors = {
                {
                    code = "unknown_action",
                    path = "staticData",
                    message = "지원하지 않는 정적 데이터 작업입니다: " .. tostring(action),
                },
            },
        }
    end

    return handler()
    end
end)()

