    [[[
subwayJourney
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local ALGORITHM = "tokyo_subway_segment_v1"
    local MIN_TURNS = 7
    local MAX_TURNS = 12
    local SEED_MODULUS = 2147483646
    local ROUTE_DOMAIN_OFFSET = 130363
    local MAX_SAFE_INTEGER = 9007199254740991

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            algorithm = ALGORITHM,
            errors = errors,
        }
    end

    local function success(value)
        value.ok = true
        value.schemaVersion = SCHEMA_VERSION
        value.algorithm = ALGORITHM
        value.errors = {}
        return value
    end

    local function isSafeInteger(value, minimum)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
            and value % 1 == 0
            and math.abs(value) <= MAX_SAFE_INTEGER
            and (minimum == nil or value >= minimum)
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function deriveRouteSeed(seed)
        local normalized = seed % SEED_MODULUS
        return ((normalized + ROUTE_DOMAIN_OFFSET) % SEED_MODULUS) + 1
    end

    local function sortedKeys(collection)
        local keys = {}
        for key in pairs(type(collection) == "table" and collection or {}) do
            keys[#keys + 1] = key
        end
        table.sort(keys)
        return keys
    end

    local function copyArray(source)
        local copy = {}
        for index, value in ipairs(source or {}) do
            copy[index] = value
        end
        return copy
    end

    local function nextInteger(rng, minimum, maximum, path)
        if type(runScript) ~= "function" then
            return nil, nil, makeError(
                "runtime_unavailable",
                "$.runtime.deterministicRng",
                "여정 추첨에 필요한 결정적 RNG를 호출할 수 없습니다."
            )
        end
        local ok, report = pcall(
            runScript,
            triggerId,
            "deterministicRng",
            "nextInteger",
            rng,
            minimum,
            maximum
        )
        if not ok then
            return nil, nil, makeError(
                "rng_call_failed",
                "$.runtime.deterministicRng",
                "여정 추첨 RNG 호출에 실패했습니다: " .. tostring(report)
            )
        end
        if type(report) ~= "table" or report.ok ~= true
            or not isSafeInteger(report.value, minimum)
            or report.value > maximum
            or type(report.rng) ~= "table"
            or report.rng.seed ~= rng.seed
            or not isSafeInteger(report.rng.cursor, rng.cursor + 1) then
            return nil, nil, makeError(
                "invalid_rng_result",
                path,
                "여정 추첨 RNG가 올바른 값과 다음 상태를 반환하지 않았습니다."
            )
        end
        return report.value, report.rng, nil
    end

    local function linearCandidates(routePath, turnLimit)
        local candidates = {}
        local stations = routePath.stations
        local lastStart = #stations - turnLimit
        if lastStart < 1 then
            return candidates
        end
        for startIndex = 1, lastStart do
            local forward = {}
            local reverse = {}
            for offset = 0, turnLimit do
                forward[#forward + 1] = stations[startIndex + offset].id
                reverse[#reverse + 1] = stations[startIndex + turnLimit - offset].id
            end
            candidates[#candidates + 1] = forward
            candidates[#candidates + 1] = reverse
        end
        return candidates
    end

    local function circularCandidates(routePath, turnLimit)
        local candidates = {}
        local stations = routePath.stations
        local stationCount = #stations
        if stationCount < turnLimit + 1 then
            return candidates
        end
        for startIndex = 1, stationCount do
            for _, direction in ipairs({ 1, -1 }) do
                local stationIds = {}
                local cursor = startIndex
                for _ = 0, turnLimit do
                    stationIds[#stationIds + 1] = stations[cursor].id
                    cursor = ((cursor - 1 + direction) % stationCount) + 1
                end
                candidates[#candidates + 1] = stationIds
            end
        end
        return candidates
    end

    local function collectLineCandidates(line, turnLimit)
        local candidates = {}
        for _, routePath in ipairs(type(line) == "table" and line.paths or {}) do
            local pathCandidates
            if routePath.circular == true then
                pathCandidates = circularCandidates(routePath, turnLimit)
            else
                pathCandidates = linearCandidates(routePath, turnLimit)
            end
            for _, stationIds in ipairs(pathCandidates) do
                candidates[#candidates + 1] = {
                    pathId = routePath.id,
                    stationIds = stationIds,
                }
            end
        end
        return candidates
    end

    local function build(seed, staticInput)
        if not isSafeInteger(seed, 0) then
            return failure({
                makeError("invalid_seed", "$.seed", "여정 생성 seed는 0 이상의 안전 정수여야 합니다."),
            })
        end
        local staticData = normalizeStaticData(staticInput)
        local subwayLines = type(staticData) == "table" and staticData.subwayLines or nil
        if type(subwayLines) ~= "table" or next(subwayLines) == nil then
            return failure({
                makeError("missing_subway_lines", "$.staticData.subwayLines", "여정 생성에 필요한 지하철 노선 DB가 없습니다."),
            })
        end

        local rng = {
            seed = deriveRouteSeed(seed),
            cursor = 0,
        }
        local turnLimit, nextRng, rngError = nextInteger(
            rng,
            MIN_TURNS,
            MAX_TURNS,
            "$.turnLimit"
        )
        if rngError then
            return failure({ rngError })
        end
        rng = nextRng

        local eligible = {}
        for _, lineId in ipairs(sortedKeys(subwayLines)) do
            local candidates = collectLineCandidates(subwayLines[lineId], turnLimit)
            if #candidates > 0 then
                eligible[#eligible + 1] = {
                    lineId = lineId,
                    candidates = candidates,
                }
            end
        end
        if #eligible == 0 then
            return failure({
                makeError("no_eligible_subway_line", "$.staticData.subwayLines", "추첨된 턴 수에 맞는 지하철 노선이 없습니다."),
            })
        end

        local lineIndex
        lineIndex, nextRng, rngError = nextInteger(
            rng,
            1,
            #eligible,
            "$.lineIndex"
        )
        if rngError then
            return failure({ rngError })
        end
        rng = nextRng
        local selectedLine = eligible[lineIndex]

        local candidateIndex
        candidateIndex, nextRng, rngError = nextInteger(
            rng,
            1,
            #selectedLine.candidates,
            "$.candidateIndex"
        )
        if rngError then
            return failure({ rngError })
        end
        rng = nextRng
        local selected = selectedLine.candidates[candidateIndex]

        return success({
            turnLimit = turnLimit,
            transit = {
                algorithm = ALGORITHM,
                lineId = selectedLine.lineId,
                stationIds = copyArray(selected.stationIds),
            },
            receipt = {
                routeSeed = rng.seed,
                rngCursor = rng.cursor,
                pathId = selected.pathId,
                eligibleLineCount = #eligible,
                candidateCount = #selectedLine.candidates,
            },
        })
    end

    local arguments = { ... }
    if action == "build" then
        return build(arguments[1], arguments[2])
    end
    return failure({
        makeError("unknown_action", "$.action", "지원하지 않는 지하철 여정 작업입니다: " .. tostring(action)),
    })
end)

]],
    [[[
triggerPipeline
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local CATEGORY_ORDER = {
        plan = 1,
        trait = 2,
        perk = 3,
        environment = 4,
    }

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(state, transient, records)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            state = state,
            transient = transient,
            records = records,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isDenseArray(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return false
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return false
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        return count == maximum
    end

    local function cloneData(value, path, active)
        local valueType = type(value)
        if valueType ~= "table" then
            if valueType == "nil"
                or valueType == "string"
                or valueType == "number"
                or valueType == "boolean" then
                if valueType == "number" and not isFinite(value) then
                    return nil, makeError(
                        "non_finite_number",
                        path,
                        "유한하지 않은 숫자는 트리거 파이프라인 데이터에 복제할 수 없습니다."
                    )
                end
                return value, nil
            end
            return nil, makeError(
                "unsupported_type",
                path,
                "트리거 파이프라인 데이터에 복제할 수 없는 자료형입니다: " .. valueType
            )
        end
        if getmetatable(value) ~= nil then
            return nil, makeError(
                "metatable_not_allowed",
                path,
                "메타테이블이 있는 값은 트리거 파이프라인 데이터에 복제할 수 없습니다."
            )
        end
        active = active or {}
        if active[value] then
            return nil, makeError(
                "circular_reference",
                path,
                "순환 참조는 트리거 파이프라인 데이터에 복제할 수 없습니다."
            )
        end
        active[value] = true
        local copy = {}
        for key, item in pairs(value) do
            local keyCopy, keyError = cloneData(key, path .. ".<key>", active)
            if keyError then
                active[value] = nil
                return nil, keyError
            end
            local itemCopy, itemError = cloneData(item, path .. "." .. tostring(key), active)
            if itemError then
                active[value] = nil
                return nil, itemError
            end
            copy[keyCopy] = itemCopy
        end
        active[value] = nil
        return copy, nil
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function appendErrors(target, nested)
        if type(nested) ~= "table" then
            target[#target + 1] = makeError(
                "invalid_nested_error",
                "$",
                "하위 모듈 오류 목록이 올바르지 않습니다."
            )
            return
        end
        for _, item in ipairs(nested) do
            target[#target + 1] = {
                code = tostring(type(item) == "table" and item.code or "nested_error"),
                path = tostring(type(item) == "table" and item.path or "$"),
                message = tostring(
                    type(item) == "table" and item.message
                        or "하위 모듈 작업이 실패했습니다."
                ),
            }
        end
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError(
                    "runtime_unavailable",
                    "$.runtime." .. moduleName,
                    "스크립트 실행기를 찾을 수 없습니다."
                ),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                makeError(
                    "module_call_error",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. " 실행에 실패했습니다: " .. tostring(report)
                ),
            }
        end
        if type(report) ~= "table" then
            return nil, {
                makeError(
                    "invalid_module_result",
                    "$.runtime." .. moduleName,
                    "하위 모듈이 테이블 결과를 반환하지 않았습니다."
                ),
            }
        end
        if report.ok ~= true then
            local errors = {}
            appendErrors(errors, report.errors)
            return nil, errors
        end
        return report, nil
    end

    local function isSide(value)
        return value == "player" or value == "character"
    end

    local function normalizeOptions(options, inputEvent)
        if options == nil then
            options = {}
        end
        if type(options) ~= "table" or getmetatable(options) ~= nil then
            return nil, {
                makeError("invalid_options", "$.options", "트리거 파이프라인 옵션은 일반 테이블이어야 합니다."),
            }
        end

        local errors = {}
        local allowed = {
            phase = true,
            currentCard = true,
            insightSide = true,
            allowGameplayCommands = true,
        }
        for key in pairs(options) do
            if type(key) ~= "string" or not allowed[key] then
                errors[#errors + 1] = makeError(
                    "unexpected_option",
                    "$.options." .. tostring(key),
                    "지원하지 않는 트리거 파이프라인 옵션입니다."
                )
            end
        end

        local phase = options.phase
        if phase == nil and type(inputEvent) == "table" then
            phase = inputEvent.type
        end
        if type(phase) ~= "string" or string.match(phase, "^[a-z][a-z0-9_]*$") == nil then
            errors[#errors + 1] = makeError(
                "invalid_phase",
                "$.options.phase",
                "phase는 lower_snake_case 문자열이어야 합니다."
            )
        end

        if options.insightSide ~= nil and not isSide(options.insightSide) then
            errors[#errors + 1] = makeError(
                "invalid_insight_side",
                "$.options.insightSide",
                "insightSide는 player 또는 character여야 합니다."
            )
        end
        if options.allowGameplayCommands ~= nil and type(options.allowGameplayCommands) ~= "boolean" then
            errors[#errors + 1] = makeError(
                "invalid_allow_gameplay_commands",
                "$.options.allowGameplayCommands",
                "allowGameplayCommands는 불리언이어야 합니다."
            )
        end

        local currentCard = nil
        if options.currentCard ~= nil then
            local value = options.currentCard
            if type(value) ~= "table" or getmetatable(value) ~= nil then
                errors[#errors + 1] = makeError(
                    "invalid_current_card",
                    "$.options.currentCard",
                    "currentCard는 일반 테이블이어야 합니다."
                )
            else
                local cardAllowed = {
                    id = true,
                    instanceId = true,
                    owner = true,
                    actionTag = true,
                    effectChoiceId = true,
                }
                for key in pairs(value) do
                    if type(key) ~= "string" or not cardAllowed[key] then
                        errors[#errors + 1] = makeError(
                            "unexpected_current_card_field",
                            "$.options.currentCard." .. tostring(key),
                            "currentCard에 허용되지 않은 필드가 있습니다."
                        )
                    end
                end
                if type(value.id) ~= "string" or value.id == "" then
                    errors[#errors + 1] = makeError(
                        "invalid_current_card_id",
                        "$.options.currentCard.id",
                        "현재 카드 ID가 없습니다."
                    )
                end
                if type(value.instanceId) ~= "string" or value.instanceId == "" then
                    errors[#errors + 1] = makeError(
                        "invalid_current_instance_id",
                        "$.options.currentCard.instanceId",
                        "현재 카드 인스턴스 ID가 없습니다."
                    )
                end
                if not isSide(value.owner) then
                    errors[#errors + 1] = makeError(
                        "invalid_current_card_owner",
                        "$.options.currentCard.owner",
                        "현재 카드 소유자는 player 또는 character여야 합니다."
                    )
                end
                if value.actionTag ~= nil and (type(value.actionTag) ~= "string" or value.actionTag == "") then
                    errors[#errors + 1] = makeError(
                        "invalid_current_action_tag",
                        "$.options.currentCard.actionTag",
                        "현재 카드 행동 태그가 올바르지 않습니다."
                    )
                end
                if value.effectChoiceId ~= nil
                    and (type(value.effectChoiceId) ~= "string"
                        or string.match(value.effectChoiceId, "^[a-z][a-z0-9_]*$") == nil) then
                    errors[#errors + 1] = makeError("invalid_effect_choice_id", "$.options.currentCard.effectChoiceId", "현재 카드 효과 선택값이 올바르지 않습니다.")
                end
                currentCard = {
                    id = value.id,
                    instanceId = value.instanceId,
                    owner = value.owner,
                    actionTag = value.actionTag,
                    effectChoiceId = value.effectChoiceId,
                }
            end
        end

        if #errors > 0 then
            return nil, errors
        end
        return {
            phase = phase,
            currentCard = currentCard,
            insightSide = options.insightSide,
            allowGameplayCommands = options.allowGameplayCommands ~= false,
        }, nil
    end

    local function validateInputs(staticData, working, inputEvent)
        local errors = {}
        staticData = normalizeStaticData(staticData)
        if type(staticData) ~= "table"
            or getmetatable(staticData) ~= nil
            or type(staticData.registry) ~= "table"
            or type(staticData.registry.events) ~= "table"
            or type(staticData.cards) ~= "table"
            or type(staticData.traits) ~= "table"
            or type(staticData.environments) ~= "table" then
            errors[#errors + 1] = makeError(
                "invalid_static_data",
                "$.staticData",
                "트리거 파이프라인에는 전체 정적 데이터가 필요합니다."
            )
        end

        if type(working) ~= "table" or getmetatable(working) ~= nil then
            errors[#errors + 1] = makeError(
                "invalid_working",
                "$.working",
                "트리거 파이프라인 working 값은 일반 테이블이어야 합니다."
            )
        elseif type(working.state) ~= "table"
            or getmetatable(working.state) ~= nil
            or type(working.state.player) ~= "table"
            or type(working.state.character) ~= "table"
            or type(working.state.cardInstances) ~= "table" then
            errors[#errors + 1] = makeError(
                "invalid_working_state",
                "$.working.state",
                "트리거를 적용할 전투 상태가 올바르지 않습니다."
            )
        elseif working.transient ~= nil
            and (type(working.transient) ~= "table" or getmetatable(working.transient) ~= nil) then
            errors[#errors + 1] = makeError(
                "invalid_transient",
                "$.working.transient",
                "트리거 transient 값은 일반 테이블이어야 합니다."
            )
        end

        if type(inputEvent) ~= "table" or getmetatable(inputEvent) ~= nil then
            errors[#errors + 1] = makeError(
                "invalid_trigger_event",
                "$.inputEvent",
                "트리거 입력 사건은 일반 테이블이어야 합니다."
            )
        elseif type(staticData) == "table" and type(staticData.registry) == "table"
            and type(staticData.registry.events) == "table" then
            if type(inputEvent.type) ~= "string" or not staticData.registry.events[inputEvent.type] then
                errors[#errors + 1] = makeError(
                    "unknown_trigger_event",
                    "$.inputEvent.type",
                    "등록되지 않은 트리거 입력 사건입니다."
                )
            end
            if inputEvent.side ~= nil and not isSide(inputEvent.side) then
                errors[#errors + 1] = makeError(
                    "invalid_event_side",
                    "$.inputEvent.side",
                    "입력 사건 진영은 player 또는 character여야 합니다."
                )
            end
        end

        if #errors > 0 then
            return nil, errors
        end
        return staticData, nil
    end

    local function countZone(state, owner, zone)
        local count = 0
        for _, instance in ipairs(state.cardInstances) do
            if type(instance) == "table" and instance.owner == owner and instance.zone == zone then
                count = count + 1
            end
        end
        return count
    end

    local function buildHistoryContext(history)
        if type(runScript) ~= "function" then
            error("battleHistory.context runtime is unavailable", 0)
        end
        local ok, report = pcall(runScript, triggerId, "battleHistory", "context", history)
        if not ok or type(report) ~= "table" or report.ok ~= true or type(report.context) ~= "table" then
            error("battleHistory.context failed", 0)
        end
        return report.context
    end

    local function buildContext(state, options, planState)
        local intent = type(state.characterIntent) == "table" and state.characterIntent or {}
        local context = {
            turn = state.turnNumber,
            phase = options.phase,
            mood = state.character.mood,
            history = buildHistoryContext(state.history),
            player = {
                stealth = state.player.stealth,
                handCount = countZone(state, "player", "hand"),
            },
            character = {
                resistance = state.character.resistance,
                moodTokens = state.character.moodTokens,
                publicActionTag = intent.publicActionTag,
            },
        }
        if options.currentCard ~= nil then
            context.card = {
                id = options.currentCard.id,
                instanceId = options.currentCard.instanceId,
                owner = options.currentCard.owner,
                actionTag = options.currentCard.actionTag,
            }
            if options.currentCard.effectChoiceId ~= nil then
                context.effectChoiceId = options.currentCard.effectChoiceId
            end
        end
        if planState ~= nil then
            context.plan = {
                cardId = planState.cardId,
                cardInstanceId = planState.cardInstanceId,
                side = planState.side,
                revealed = planState.revealed,
                slotIndex = planState.slotIndex,
            }
            if planState.remainingTurns ~= nil then
                context.plan.remainingTurns = planState.remainingTurns
            end
            if planState.remainingCharges ~= nil then
                context.plan.remainingCharges = planState.remainingCharges
            end
            if planState.effectChoiceId ~= nil then context.effectChoiceId = planState.effectChoiceId end
        end
        return context
    end

    local function sideRank(side, actingSide)
        if actingSide ~= nil and side == actingSide then
            return 1
        end
        if actingSide ~= nil and isSide(side) then
            return 2
        end
        if actingSide == nil and side == "player" then
            return 1
        end
        if actingSide == nil and side == "character" then
            return 2
        end
        return 3
    end

    local function candidateSource(candidate)
        local value = {
            kind = candidate.kind,
            id = candidate.sourceId,
        }
        if candidate.side ~= nil then
            value.side = candidate.side
        end
        if candidate.planState ~= nil then
            value.instanceId = candidate.planState.cardInstanceId
        end
        return value
    end

    local function appendRecord(records, recordType, candidate, payload)
        local record = {
            type = recordType,
            source = candidateSource(candidate),
        }
        if candidate.side ~= nil then
            record.side = candidate.side
        end
        if payload ~= nil then
            record.payload = payload
        end
        records[#records + 1] = record
