    local function success(draft, projection, receipt, interactionToken, fields)
        local report = {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            draft = draft,
            projection = projection,
            receipt = receipt,
            interactionToken = interactionToken,
