        if valueType == "number" then
            if not isFinite(value) then
                cloneFailure("non_finite_number", path, "NaN과 무한대는 turnDraft에 사용할 수 없습니다.")
            end
            return value
        end
        if valueType ~= "table" then
            cloneFailure(
                "unsupported_type",
                path,
                "JSON 상태에 저장할 수 없는 자료형입니다: " .. valueType
            )
