    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function callModule(scriptName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, makeError(
                "missing_run_script",
                "$.runtime",
                "다른 로어북 모듈을 호출할 runScript가 없습니다."
            )
        end

        local ok, report = pcall(runScript, triggerId, scriptName, moduleAction, ...)
        if not ok then
            return nil, makeError(
                "module_call_failed",
                "$.runtime." .. scriptName,
                scriptName .. " 호출에 실패했습니다: " .. tostring(report)
            )
        end
        if type(report) ~= "table" then
            return nil, makeError(
                "invalid_module_result",
                "$.runtime." .. scriptName,
                scriptName .. "가 구조화 결과를 반환하지 않았습니다."
            )
        end
        if report.ok ~= true then
            local first = type(report.errors) == "table" and report.errors[1] or nil
            return nil, makeError(
                "module_rejected",
                "$.runtime." .. scriptName,
                first and (tostring(first.code) .. " at " .. tostring(first.path) .. ": " .. tostring(first.message))
                    or (scriptName .. "가 작업을 거부했습니다.")
            )
        end
        return report, nil
    end

    local function validateAuthority(state, staticData)
        staticData = normalizeStaticData(staticData)
        if type(staticData) ~= "table" then
            return nil, nil, {
                makeError("invalid_static_data", "$.staticData", "turnDraft에는 전체 정적 데이터가 필요합니다."),
            }
        end

        local report, moduleError = callModule("stateSchema", "validateBattleState", state, staticData)
        if moduleError then
            return nil, nil, { moduleError }
        end
        if report.referencesValidated ~= true then
            return nil, nil, {
                makeError(
                    "static_references_not_validated",
                    "$.staticData",
                    "turnDraft는 참조까지 검증된 전체 정적 데이터가 필요합니다."
                ),
            }
        end
        if state.status ~= "active" then
            return nil, nil, {
                makeError("battle_not_active", "$.state.status", "진행 중인 전투에서만 turnDraft를 만들 수 있습니다."),
            }
        end

        local stateCopy, cloneError = cloneValue(state, "$.state")
        if cloneError then
            return nil, nil, { cloneError }
        end
        return stateCopy, staticData, nil
    end

    local function buildSource(state)
        local stateFingerprint, fingerprintError = fingerprint(state)
        if fingerprintError then
            return nil, fingerprintError
        end
        local source = {
            battleId = state.battleId,
            status = state.status,
            turnNumber = state.turnNumber,
            rng = {
                seed = state.rng.seed,
                cursor = state.rng.cursor,
            },
            fingerprint = stateFingerprint,
        }
        if state.lastCommittedTurnId ~= nil then
            source.lastCommittedTurnId = state.lastCommittedTurnId
        end
        return source, nil
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" then
            return
        end
        for key in pairs(value) do
            if type(key) ~= "string" or not allowed[key] then
                table.insert(errors, makeError(
                    "unexpected_field",
                    path .. "." .. tostring(key),
                    "turnDraft 스키마에 없는 필드입니다."
                ))
            end
        end
    end

    local function getArrayLength(value, path, errors)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            table.insert(errors, makeError("invalid_array", path, "연속 배열이어야 합니다."))
            return nil
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                table.insert(errors, makeError("invalid_array", path, "연속 배열이어야 합니다."))
                return nil
            end
            count = count + 1
            if key > maximum then
                maximum = key
            end
        end
        if count ~= maximum then
            table.insert(errors, makeError("sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다."))
            return nil
        end
        return maximum
    end

    local function validateIdArray(value, path, errors)
        local length = getArrayLength(value, path, errors)
        if not length then
            return
        end
        local seen = {}
        for index = 1, length do
            local instanceId = value[index]
            if not isRuntimeId(instanceId) then
                table.insert(errors, makeError(
                    "invalid_instance_id",
                    path .. "[" .. index .. "]",
                    "카드 인스턴스 ID 형식이 올바르지 않습니다."
                ))
            elseif seen[instanceId] then
                table.insert(errors, makeError(
                    "duplicate_instance_id",
                    path .. "[" .. index .. "]",
                    "같은 카드 인스턴스를 중복 등록할 수 없습니다."
                ))
            else
                seen[instanceId] = true
            end
        end
    end

    local function validateRng(value, path, errors)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            table.insert(errors, makeError("invalid_rng", path, "RNG 상태가 일반 테이블이 아닙니다."))
            return
        end
        checkAllowedKeys(value, { seed = true, cursor = true }, path, errors)
        if not isSafeInteger(value.seed, 0) then
            table.insert(errors, makeError("invalid_rng_seed", path .. ".seed", "RNG seed는 0 이상의 안전 정수여야 합니다."))
        end
        if not isSafeInteger(value.cursor, 0) then
            table.insert(errors, makeError("invalid_rng_cursor", path .. ".cursor", "RNG cursor는 0 이상의 안전 정수여야 합니다."))
        end
    end

    local function validatePreviewShape(preview, path, errors)
        if type(preview) ~= "table" or getmetatable(preview) ~= nil then
            table.insert(errors, makeError("invalid_preview", path, "preview가 일반 테이블이 아닙니다."))
            return
        end
        checkAllowedKeys(preview, {
            events = true,
            drawnInstanceIds = true,
            availableDrawnInstanceIds = true,
            rng = true,
        }, path, errors)
        validateIdArray(preview.drawnInstanceIds, path .. ".drawnInstanceIds", errors)
        validateIdArray(preview.availableDrawnInstanceIds, path .. ".availableDrawnInstanceIds", errors)
        validateRng(preview.rng, path .. ".rng", errors)

        local eventCount = getArrayLength(preview.events, path .. ".events", errors)
        if eventCount then
            local sourceSeen = {}
            for index = 1, eventCount do
                local event = preview.events[index]
                local eventPath = path .. ".events[" .. index .. "]"
                if type(event) ~= "table" or getmetatable(event) ~= nil then
                    table.insert(errors, makeError("invalid_preview_event", eventPath, "프리뷰 사건이 일반 테이블이 아닙니다."))
                else
                    checkAllowedKeys(event, {
                        sourceInstanceId = true,
                        drawnInstanceIds = true,
                    }, eventPath, errors)
                    if not isRuntimeId(event.sourceInstanceId) then
                        table.insert(errors, makeError(
                            "invalid_instance_id",
                            eventPath .. ".sourceInstanceId",
                            "프리뷰 원본 카드 ID가 올바르지 않습니다."
                        ))
                    elseif sourceSeen[event.sourceInstanceId] then
                        table.insert(errors, makeError(
                            "duplicate_preview_source",
                            eventPath .. ".sourceInstanceId",
                            "같은 카드의 프리뷰 사건이 중복되었습니다."
                        ))
                    else
                        sourceSeen[event.sourceInstanceId] = true
                    end
                    validateIdArray(event.drawnInstanceIds, eventPath .. ".drawnInstanceIds", errors)
                end
            end
        end
    end

    local function validateDraftShape(draft)
        local errors = {}
        if type(draft) ~= "table" or getmetatable(draft) ~= nil then
            return { makeError("invalid_draft", "$.draft", "turnDraft가 일반 테이블이 아닙니다.") }
        end
        checkAllowedKeys(draft, {
            schemaVersion = true,
            kind = true,
            source = true,
            focusedInstanceId = true,
            registeredCardInstanceIds = true,
            effectChoiceByInstanceId = true,
            preview = true,
        }, "$.draft", errors)
        if draft.schemaVersion ~= SCHEMA_VERSION then
            table.insert(errors, makeError("unsupported_schema", "$.draft.schemaVersion", "지원하지 않는 turnDraft 스키마입니다."))
        end
        if draft.kind ~= "turnDraft" then
            table.insert(errors, makeError("invalid_kind", "$.draft.kind", "kind는 turnDraft여야 합니다."))
        end
        if draft.focusedInstanceId ~= nil and not isRuntimeId(draft.focusedInstanceId) then
            table.insert(errors, makeError(
                "invalid_focus",
                "$.draft.focusedInstanceId",
                "상세 표시 카드 인스턴스 ID가 올바르지 않습니다."
            ))
        end
        validateIdArray(draft.registeredCardInstanceIds, "$.draft.registeredCardInstanceIds", errors)
        if draft.effectChoiceByInstanceId ~= nil then
            if type(draft.effectChoiceByInstanceId) ~= "table" or getmetatable(draft.effectChoiceByInstanceId) ~= nil then
                table.insert(errors, makeError("invalid_effect_choice_map", "$.draft.effectChoiceByInstanceId", "효과 선택값은 일반 객체여야 합니다."))
            else
                for instanceId, choiceId in pairs(draft.effectChoiceByInstanceId) do
                    if not isRuntimeId(instanceId) or type(choiceId) ~= "string"
                        or string.match(choiceId, "^[a-z][a-z0-9_]*$") == nil then
                        table.insert(errors, makeError("invalid_effect_choice", "$.draft.effectChoiceByInstanceId." .. tostring(instanceId), "카드 인스턴스별 효과 선택값이 올바르지 않습니다."))
                    end
                end
            end
        end
        validatePreviewShape(draft.preview, "$.draft.preview", errors)

        local source = draft.source
        if type(source) ~= "table" or getmetatable(source) ~= nil then
            table.insert(errors, makeError("invalid_source", "$.draft.source", "turnDraft 원본 표식이 올바르지 않습니다."))
        else
            checkAllowedKeys(source, {
                battleId = true,
                status = true,
                turnNumber = true,
                lastCommittedTurnId = true,
                rng = true,
                fingerprint = true,
            }, "$.draft.source", errors)
            if not isRuntimeId(source.battleId) then
                table.insert(errors, makeError("invalid_battle_id", "$.draft.source.battleId", "전투 ID가 올바르지 않습니다."))
            end
            if source.status ~= "active" then
                table.insert(errors, makeError("invalid_source_status", "$.draft.source.status", "turnDraft 원본은 active 상태여야 합니다."))
            end
            if not isInteger(source.turnNumber, 1) then
                table.insert(errors, makeError("invalid_turn_number", "$.draft.source.turnNumber", "턴 번호가 올바르지 않습니다."))
            end
            if source.lastCommittedTurnId ~= nil and not isRuntimeId(source.lastCommittedTurnId) then
                table.insert(errors, makeError(
                    "invalid_turn_id",
                    "$.draft.source.lastCommittedTurnId",
                    "마지막 확정 턴 ID가 올바르지 않습니다."
                ))
            end
            validateRng(source.rng, "$.draft.source.rng", errors)

            local stateFingerprint = source.fingerprint
            if type(stateFingerprint) ~= "table" or getmetatable(stateFingerprint) ~= nil then
                table.insert(errors, makeError(
                    "invalid_fingerprint",
                    "$.draft.source.fingerprint",
                    "전투 상태 fingerprint가 올바르지 않습니다."
                ))
            else
                checkAllowedKeys(stateFingerprint, {
                    algorithm = true,
                    length = true,
                    hashA = true,
                    hashB = true,
                }, "$.draft.source.fingerprint", errors)
                if stateFingerprint.algorithm ~= FINGERPRINT_ALGORITHM then
                    table.insert(errors, makeError(
                        "invalid_fingerprint_algorithm",
                        "$.draft.source.fingerprint.algorithm",
                        "지원하지 않는 fingerprint 알고리즘입니다."
                    ))
                end
                for _, field in ipairs({ "length", "hashA", "hashB" }) do
                    if not isSafeInteger(stateFingerprint[field], 0) then
                        table.insert(errors, makeError(
                            "invalid_fingerprint_value",
                            "$.draft.source.fingerprint." .. field,
                            "fingerprint 값은 0 이상의 안전 정수여야 합니다."
                        ))
                    end
                end
            end
        end
        return errors
    end

    local function findInstance(state, instanceId)
        for _, instance in ipairs(state.cardInstances) do
            if instance.instanceId == instanceId then
                return instance
            end
        end
        return nil
    end

    local function findCard(staticData, state, instanceId)
        local instance = findInstance(state, instanceId)
        if not instance then
            return nil, nil
        end
        return instance, staticData.cards[instance.cardId]
    end

    local function hasMechanism(card, mechanismId)
        for _, currentId in ipairs(type(card) == "table" and type(card.mechanisms) == "table" and card.mechanisms or {}) do
            if currentId == mechanismId then
                return true
            end
        end
        return false
    end

    local function copyArray(values)
        local copy = {}
        for index, value in ipairs(values or {}) do
            copy[index] = value
        end
        return copy
    end

    local function copyMap(values)
        local copy = {}
        for key, value in pairs(values or {}) do copy[key] = value end
        return copy
    end

    local function choiceContext(state, card, instance, phase)
        local tokens = {}
        for moodId in pairs(state.character.moodTokens or {}) do
            tokens[moodId] = state.character.moodTokens[moodId]
        end
        return {
            turn = state.turnNumber,
            phase = phase or "player_selection",
            mood = state.character.mood,
            player = {
                stealth = state.player.stealth,
            },
            character = {
                resistance = state.character.resistance,
                moodTokens = tokens,
                publicActionTag = state.characterIntent.publicActionTag,
            },
            card = {
                id = card.id,
                instanceId = instance.instanceId,
                owner = card.owner,
                actionTag = card.actionTag,
            },
        }
    end

    local function appendAll(target, values)
        for _, value in ipairs(values or {}) do
            table.insert(target, value)
        end
    end

    local function emptyPreview(state)
        return {
            events = {},
            drawnInstanceIds = {},
            availableDrawnInstanceIds = {},
            rng = {
                seed = state.rng.seed,
                cursor = state.rng.cursor,
            },
        }
    end

    local function replaySelection(state, staticData, registeredIds, choiceByInstanceId, dropUnavailable)
        local working, cloneError = cloneValue(state, "$.state")
        if cloneError then
            return nil, { cloneError }
        end

        local keptIds = {}
        local keptChoices = {}
        local previewEvents = {}
        local drawnInstanceIds = {}
        local mainActionCount = 0
        local mainActionIndex = nil

        for inputIndex, instanceId in ipairs(registeredIds) do
            local instance, card = findCard(staticData, working, instanceId)
            local available = instance and instance.owner == "player" and instance.zone == "hand"
            if not available then
                if not dropUnavailable then
                    return nil, {
                        makeError(
                            "card_not_available",
                            "$.draft.registeredCardInstanceIds[" .. inputIndex .. "]",
                            "등록 카드는 권위 손패 또는 앞선 프리뷰 드로우에 있어야 합니다."
                        ),
                    }
                end
            elseif type(card) ~= "table" then
                return nil, {
                    makeError(
                        "unknown_card",
                        "$.draft.registeredCardInstanceIds[" .. inputIndex .. "]",
                        "정적 DB에서 등록 카드를 찾을 수 없습니다."
                    ),
                }
            else
                local choices = type(card.effectChoices) == "table" and card.effectChoices or nil
                local choiceId = choiceByInstanceId and choiceByInstanceId[instanceId] or nil
                if choices ~= nil then
                    if choiceId == nil then
                        return nil, { makeError("effect_choice_required", "$.draft.effectChoiceByInstanceId." .. instanceId, "이 카드를 등록하려면 효과를 선택해야 합니다.") }
                    end
                    local choiceReport, choiceError = callModule(
                        "effectEngine",
                        "evaluateEffectChoice",
                        staticData,
                        card.id,
                        choiceId,
                        choiceContext(working, card, instance)
                    )
                    if choiceError then return nil, { choiceError } end
                    if choiceReport.selectable ~= true then
                        return nil, { makeError("effect_choice_unavailable", "$.draft.effectChoiceByInstanceId." .. instanceId, "현재 상태에서는 선택한 효과를 사용할 수 없습니다.") }
                    end
                    keptChoices[instanceId] = choiceId
                elseif choiceId ~= nil then
                    return nil, { makeError("unexpected_effect_choice", "$.draft.effectChoiceByInstanceId." .. instanceId, "효과 선택지가 없는 카드에 선택값이 있습니다.") }
                end
                table.insert(keptIds, instanceId)
                if not hasMechanism(card, "chain") then
                    mainActionCount = mainActionCount + 1
                    mainActionIndex = #keptIds
                    if mainActionCount > 1 then
                        return nil, {
                            makeError(
                                "multiple_main_actions",
                                "$.draft.registeredCardInstanceIds",
                                "주 행동 카드는 하나만 등록할 수 있습니다."
                            ),
                        }
                    end
                end

                local effectReport, effectError = callModule(
                    "effectEngine",
                    "evaluateSelectionPreview",
                    staticData,
                    working,
                    instanceId
                )
                if effectError then
                    return nil, { effectError }
                end

                local moveReport, moveError = callModule(
                    "cardZones",
                    "moveHandToUsed",
                    working,
                    instanceId
                )
                if moveError then
                    return nil, { moveError }
                end
                working = moveReport.state

                if #effectReport.commands > 0 then
                    local eventDrawn = {}
                    for _, command in ipairs(effectReport.commands) do
                        if command.op ~= "draw_cards" or command.target ~= "player" then
                            return nil, {
                                makeError(
                                    "unsupported_preview_command",
                                    "$.runtime.effectEngine",
                                    "turnDraft v1이 적용할 수 없는 선택 프리뷰 명령입니다."
                                ),
                            }
                        end
                        local drawReport, drawError = callModule(
                            "cardZones",
                            "draw",
                            working,
                            "player",
                            command.amount
                        )
                        if drawError then
                            return nil, { drawError }
                        end
                        working = drawReport.state
                        appendAll(eventDrawn, drawReport.drawnInstanceIds)
                        appendAll(drawnInstanceIds, drawReport.drawnInstanceIds)
                    end
                    table.insert(previewEvents, {
                        sourceInstanceId = instanceId,
                        drawnInstanceIds = eventDrawn,
                    })
                end
            end
        end

        if mainActionIndex and mainActionIndex ~= #keptIds then
            return nil, {
                makeError(
                    "main_action_not_last",
                    "$.draft.registeredCardInstanceIds",
                    "연계 카드는 주 행동보다 앞에 있어야 합니다."
                ),
            }
        end

        -- 등록된 프리뷰 카드도 다시 클릭해 취소할 수 있어야 하므로 draft UI에서는
        -- workingState의 used 이동과 무관하게 이 분기에서 뽑힌 카드 전부를 유지한다.
        local availableDrawnInstanceIds = copyArray(drawnInstanceIds)

        working.selection = {
            playerCardInstanceIds = copyArray(keptIds),
        }
        return {
            workingState = working,
            registeredCardInstanceIds = keptIds,
            effectChoiceByInstanceId = keptChoices,
            mainActionCount = mainActionCount,
            preview = {
                events = previewEvents,
                drawnInstanceIds = drawnInstanceIds,
                availableDrawnInstanceIds = availableDrawnInstanceIds,
                rng = {
                    seed = working.rng.seed,
                    cursor = working.rng.cursor,
                },
            },
        }, nil
    end

    local function visibleInstanceSet(state, preview)
        local visible = {}
        for _, instance in ipairs(state.cardInstances) do
            if instance.owner == "player" and instance.zone == "hand" then
                visible[instance.instanceId] = true
            end
        end
        for _, instanceId in ipairs(preview.drawnInstanceIds) do
            visible[instanceId] = true
        end
        return visible
    end

    local function validateInternal(state, staticData, draft)
        local stateCopy, normalizedStaticData, authorityErrors = validateAuthority(state, staticData)
        if authorityErrors then
            return nil, authorityErrors
        end

        local draftCopy, cloneError = cloneValue(draft, "$.draft")
        if cloneError then
            return nil, { cloneError }
        end
        local shapeErrors = validateDraftShape(draftCopy)
        if #shapeErrors > 0 then
            return nil, shapeErrors
        end

        local expectedSource, sourceError = buildSource(stateCopy)
        if sourceError then
            return nil, { sourceError }
        end
        if not deepEqual(draftCopy.source, expectedSource) then
            return nil, {
                makeError(
                    "draft_stale",
                    "$.draft.source",
                    "turnDraft를 만든 뒤 권위 전투 상태가 변경되었습니다. 자동 재기준화하지 않습니다."
                ),
            }
        end

        local replay, replayErrors = replaySelection(
            stateCopy,
            normalizedStaticData,
            draftCopy.registeredCardInstanceIds,
            draftCopy.effectChoiceByInstanceId or {},
            false
        )
        if replayErrors then
            return nil, replayErrors
        end
        if not deepEqual(draftCopy.preview, replay.preview) then
            return nil, {
                makeError(
                    "preview_mismatch",
                    "$.draft.preview",
                    "저장된 선택 프리뷰가 같은 권위 상태에서 다시 계산한 결과와 다릅니다."
                ),
            }
        end
        if not deepEqual(draftCopy.effectChoiceByInstanceId or {}, replay.effectChoiceByInstanceId) then
            return nil, { makeError("effect_choice_mismatch", "$.draft.effectChoiceByInstanceId", "저장된 효과 선택값이 같은 전투 상태에서 재생한 결과와 다릅니다.") }
        end

        if draftCopy.focusedInstanceId ~= nil then
            local visible = visibleInstanceSet(stateCopy, replay.preview)
            if not visible[draftCopy.focusedInstanceId] then
                return nil, {
                    makeError(
                        "focused_card_not_visible",
                        "$.draft.focusedInstanceId",
                        "상세 표시 카드는 현재 손패 또는 프리뷰에 있어야 합니다."
                    ),
                }
            end
        end

        return {
            state = stateCopy,
            staticData = normalizedStaticData,
            draft = draftCopy,
            replay = replay,
        }, nil
    end

    local function buildDraft(state, registeredIds, effectChoiceByInstanceId, focusedInstanceId, replay)
        local source, sourceError = buildSource(state)
        if sourceError then
            return nil, sourceError
        end
        local draft = {
            schemaVersion = SCHEMA_VERSION,
            kind = "turnDraft",
            source = source,
            registeredCardInstanceIds = copyArray(registeredIds),
            effectChoiceByInstanceId = copyMap(effectChoiceByInstanceId),
            preview = replay and replay.preview or emptyPreview(state),
        }
        if focusedInstanceId ~= nil then
            draft.focusedInstanceId = focusedInstanceId
        end
        return draft, nil
    end

    local function newDraft(state, staticData)
        local stateCopy, normalizedStaticData, errors = validateAuthority(state, staticData)
        if errors then
            return failure(errors)
        end
        local replay, replayErrors = replaySelection(stateCopy, normalizedStaticData, {}, {}, false)
        if replayErrors then
            return failure(replayErrors)
        end
        local draft, draftError = buildDraft(stateCopy, {}, {}, nil, replay)
        if draftError then
            return failure({ draftError })
        end
        return success(draft)
    end

    local function validateDraft(state, staticData, draft)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        return success(validated.draft)
    end

    local function interactionTokenForDraft(draft)
        local draftFingerprint, fingerprintError = fingerprint(draft)
        if fingerprintError then
            return nil, fingerprintError
        end
        return table.concat({
            "draftv1",
            tostring(draftFingerprint.length),
            tostring(draftFingerprint.hashA),
            tostring(draftFingerprint.hashB),
        }, "_"), nil
    end

    local function inspectDraft(state, staticData, draft)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local token, tokenError = interactionTokenForDraft(validated.draft)
        if tokenError then
            return failure({ tokenError })
        end
        return success(validated.draft, nil, nil, token)
    end

    local function focusValidated(validated, instanceId)
        if not isRuntimeId(instanceId) then
            return nil, {
                makeError("invalid_instance_id", "$.instanceId", "상세 표시 카드 ID가 올바르지 않습니다."),
            }
        end
        local visible = visibleInstanceSet(validated.state, validated.replay.preview)
        if not visible[instanceId] then
            return nil, {
                makeError(
                    "card_not_visible",
                    "$.instanceId",
                    "상세 표시 카드는 현재 손패 또는 프리뷰에 있어야 합니다."
                ),
            }
        end

        local nextDraft, draftError = buildDraft(
            validated.state,
            validated.draft.registeredCardInstanceIds,
            validated.draft.effectChoiceByInstanceId or {},
            instanceId,
            validated.replay
        )
        if draftError then
            return nil, { draftError }
        end
        return nextDraft, nil
    end

    local function registeredSet(values)
        local set = {}
        for _, instanceId in ipairs(values) do
            set[instanceId] = true
        end
        return set
    end

    local function baseHandSet(state)
        local set = {}
        for _, instance in ipairs(state.cardInstances) do
            if instance.owner == "player" and instance.zone == "hand" then
                set[instance.instanceId] = true
            end
        end
        return set
    end

    local function registerValidated(validated, instanceId, choiceId)
        if not isRuntimeId(instanceId) then
            return nil, {
                makeError("invalid_instance_id", "$.instanceId", "등록 카드 ID가 올바르지 않습니다."),
            }
        end

        local visible = visibleInstanceSet(validated.state, validated.replay.preview)
        if not visible[instanceId] then
            return nil, {
                makeError(
                    "card_not_visible",
                    "$.instanceId",
                    "등록 카드는 현재 손패 또는 프리뷰에 있어야 합니다."
                ),
            }
        end

        local currentIds = validated.draft.registeredCardInstanceIds
        if registeredSet(currentIds)[instanceId] then
            return validated.draft, nil
        end

        local targetInstance, targetCard = findCard(validated.staticData, validated.state, instanceId)
        if not targetInstance then
            targetInstance = findInstance(validated.replay.workingState, instanceId)
            targetCard = targetInstance and validated.staticData.cards[targetInstance.cardId] or nil
        end
        if type(targetCard) ~= "table" then
            return nil, {
                makeError("unknown_card", "$.instanceId", "정적 DB에서 등록 카드를 찾을 수 없습니다."),
            }
        end
        if type(targetCard.effectChoices) == "table" and choiceId == nil then
            return nil, { makeError("effect_choice_required", "$.choiceId", "이 카드를 등록하려면 효과를 선택해야 합니다.") }
        elseif type(targetCard.effectChoices) ~= "table" and choiceId ~= nil then
            return nil, { makeError("unexpected_effect_choice", "$.choiceId", "효과 선택지가 없는 카드입니다.") }
        end

        local originalHand = baseHandSet(validated.state)
        local hasSpeculativeRegisteredCard = false
        for _, currentId in ipairs(currentIds) do
            if not originalHand[currentId] then
                hasSpeculativeRegisteredCard = true
                break
            end
        end

        local nextIds = {}
        local nextChoices = copyMap(validated.draft.effectChoiceByInstanceId or {})
        if originalHand[instanceId] and hasSpeculativeRegisteredCard then
            nextIds = { instanceId }
            nextChoices = {}
        else
            local chainIds = {}
            local mainId = nil
            for _, currentId in ipairs(currentIds) do
                local _, currentCard = findCard(validated.staticData, validated.replay.workingState, currentId)
                if not currentCard then
                    local sourceInstance = findInstance(validated.state, currentId)
                    currentCard = sourceInstance and validated.staticData.cards[sourceInstance.cardId] or nil
                end
                if currentCard and hasMechanism(currentCard, "chain") then
                    table.insert(chainIds, currentId)
                else
                    mainId = currentId
                end
            end

            if hasMechanism(targetCard, "chain") then
                appendAll(nextIds, chainIds)
                table.insert(nextIds, instanceId)
                if mainId then
                    table.insert(nextIds, mainId)
                end
            else
                appendAll(nextIds, chainIds)
                table.insert(nextIds, instanceId)
            end
        end

        if choiceId ~= nil then nextChoices[instanceId] = choiceId end
        local retained = {}
        for _, retainedId in ipairs(nextIds) do retained[retainedId] = true end
        for currentId in pairs(nextChoices) do
            if not retained[currentId] then nextChoices[currentId] = nil end
        end

        local replay, replayErrors = replaySelection(validated.state, validated.staticData, nextIds, nextChoices, false)
        if replayErrors then
            return nil, replayErrors
        end
        local nextDraft, draftError = buildDraft(validated.state, nextIds, replay.effectChoiceByInstanceId, instanceId, replay)
        if draftError then
            return nil, { draftError }
        end
        return nextDraft, nil
    end

    local function cancelValidated(validated, instanceId)
        if not isRuntimeId(instanceId) then
            return nil, {
                makeError("invalid_instance_id", "$.instanceId", "취소 카드 ID가 올바르지 않습니다."),
            }
        end

        local found = false
        local remainingIds = {}
        for _, currentId in ipairs(validated.draft.registeredCardInstanceIds) do
            if currentId == instanceId then
                found = true
            else
                table.insert(remainingIds, currentId)
            end
        end
        if not found then
            return validated.draft, nil
        end

        local replay, replayErrors = replaySelection(
            validated.state,
            validated.staticData,
            remainingIds,
            validated.draft.effectChoiceByInstanceId or {},
            true
        )
        if replayErrors then
            return nil, replayErrors
        end

        local focusedInstanceId = validated.draft.focusedInstanceId
        local visible = visibleInstanceSet(validated.state, replay.preview)
        if focusedInstanceId ~= nil and not visible[focusedInstanceId] then
            focusedInstanceId = nil
        end
        local nextDraft, draftError = buildDraft(
            validated.state,
            replay.registeredCardInstanceIds,
            replay.effectChoiceByInstanceId,
            focusedInstanceId,
            replay
        )
        if draftError then
            return nil, { draftError }
        end
        return nextDraft, nil
    end

    local function clickValidated(validated, instanceId)
        if not isRuntimeId(instanceId) then
            return nil, {
                makeError("invalid_instance_id", "$.instanceId", "클릭 카드 ID가 올바르지 않습니다."),
            }
        end

        if registeredSet(validated.draft.registeredCardInstanceIds)[instanceId] then
            return cancelValidated(validated, instanceId)
        end
        return registerValidated(validated, instanceId, nil)
    end

    local function runValidatedTransition(validated, interactionAction, instanceId, choiceId)
        if interactionAction == "click" then
            return clickValidated(validated, instanceId)
        elseif interactionAction == "register" then
            return registerValidated(validated, instanceId, nil)
        elseif interactionAction == "cancel" then
            return cancelValidated(validated, instanceId)
        elseif interactionAction == "choose" then
            return registerValidated(validated, instanceId, choiceId)
        end
        return nil, {
            makeError(
                "invalid_interaction_action",
                "$.interaction.action",
                "카드 상호작용 작업은 click, register, cancel, choose 중 하나여야 합니다."
            ),
        }
    end

    local function applyInteraction(state, staticData, draft, interaction)
        if type(interaction) ~= "table" or getmetatable(interaction) ~= nil then
            return failure({
                makeError("invalid_interaction", "$.interaction", "카드 상호작용 요청은 일반 객체여야 합니다."),
            })
        end
        local requestErrors = {}
        checkAllowedKeys(interaction, {
            action = true,
            instanceId = true,
            choiceId = true,
            expectedInteractionToken = true,
        }, "$.interaction", requestErrors)
        local interactionAction = rawget(interaction, "action")
        local instanceId = rawget(interaction, "instanceId")
        local choiceId = rawget(interaction, "choiceId")
        local expectedInteractionToken = rawget(interaction, "expectedInteractionToken")
        if interactionAction ~= "click"
            and interactionAction ~= "register"
            and interactionAction ~= "cancel"
            and interactionAction ~= "choose" then
            table.insert(requestErrors, makeError(
                "invalid_interaction_action",
                "$.interaction.action",
                "카드 상호작용 작업은 click, register, cancel, choose 중 하나여야 합니다."
            ))
        end
        if interactionAction == "choose" then
            if type(choiceId) ~= "string" or string.match(choiceId, "^[a-z][a-z0-9_]*$") == nil then
                table.insert(requestErrors, makeError("invalid_effect_choice_id", "$.interaction.choiceId", "효과 선택지 ID가 올바르지 않습니다."))
            end
        elseif choiceId ~= nil then
            table.insert(requestErrors, makeError("unexpected_effect_choice", "$.interaction.choiceId", "choose 작업 외에는 효과 선택값을 보낼 수 없습니다."))
        end
        if not isRuntimeId(instanceId) then
            table.insert(requestErrors, makeError(
                "invalid_instance_id",
                "$.interaction.instanceId",
                "카드 상호작용 인스턴스 ID가 올바르지 않습니다."
            ))
        end
        if type(expectedInteractionToken) ~= "string" or expectedInteractionToken == "" then
            table.insert(requestErrors, makeError(
                "invalid_interaction_token",
                "$.interaction.expectedInteractionToken",
                "비어 있지 않은 draft interaction token이 필요합니다."
            ))
        end
        if #requestErrors > 0 then
            return failure(requestErrors)
        end

        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local currentToken, tokenError = interactionTokenForDraft(validated.draft)
        if tokenError then
            return failure({ tokenError })
        end
        if expectedInteractionToken ~= currentToken then
            return success(validated.draft, nil, nil, currentToken, {
                applied = false,
                stale = true,
                changed = false,
                interactionAction = interactionAction,
            })
        end

        local nextDraft, transitionErrors = runValidatedTransition(
            validated,
            interactionAction,
            instanceId,
            choiceId
        )
        if transitionErrors then
            return failure(transitionErrors)
        end
        local nextToken, nextTokenError = interactionTokenForDraft(nextDraft)
        if nextTokenError then
            return failure({ nextTokenError })
        end
        local changed = not deepEqual(validated.draft, nextDraft)
        return success(nextDraft, nil, nil, nextToken, {
            applied = changed,
            stale = false,
            changed = changed,
            interactionAction = interactionAction,
        })
    end

    local function focusCard(state, staticData, draft, instanceId)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local nextDraft, transitionErrors = focusValidated(validated, instanceId)
        if transitionErrors then
            return failure(transitionErrors)
        end
        return success(nextDraft)
    end

    local function registerCard(state, staticData, draft, instanceId)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local nextDraft, transitionErrors = registerValidated(validated, instanceId)
        if transitionErrors then
            return failure(transitionErrors)
        end
        return success(nextDraft)
    end

    local function cancelCard(state, staticData, draft, instanceId)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local nextDraft, transitionErrors = cancelValidated(validated, instanceId)
        if transitionErrors then
            return failure(transitionErrors)
        end
        return success(nextDraft)
    end

    local function clickCard(state, staticData, draft, instanceId)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end
        local nextDraft, transitionErrors = clickValidated(validated, instanceId)
        if transitionErrors then
            return failure(transitionErrors)
        end
        return success(nextDraft)
    end

    local function buildProjection(state, sourceValue, replay)
        local selectedIds = copyArray(replay.registeredCardInstanceIds)
        local mode = "pass"
        if #selectedIds > 0 then
            mode = replay.mainActionCount == 1 and "action" or "chain_pass"
        end

        local workingState, stateCloneError = cloneValue(replay.workingState, "$.workingState")
        if stateCloneError then
            return nil, stateCloneError
        end
        local preview, previewCloneError = cloneValue(replay.preview, "$.preview")
        if previewCloneError then
            return nil, previewCloneError
        end
        local source, sourceCloneError = cloneValue(sourceValue, "$.source")
        if sourceCloneError then
            return nil, sourceCloneError
        end

        return {
            schemaVersion = SCHEMA_VERSION,
            kind = "turnDraftProjection",
            battleId = state.battleId,
            turnNumber = state.turnNumber,
            mode = mode,
            hasMainAction = replay.mainActionCount == 1,
            passAfterChain = #selectedIds > 0 and replay.mainActionCount == 0,
            selectedCardInstanceIds = selectedIds,
            effectChoiceByInstanceId = copyMap(replay.effectChoiceByInstanceId),
            source = source,
            preview = preview,
            projectedRng = {
                seed = workingState.rng.seed,
                cursor = workingState.rng.cursor,
            },
            workingState = workingState,
        }, nil
    end

    local function project(state, staticData, draft)
        local validated, errors = validateInternal(state, staticData, draft)
        if errors then
            return failure(errors)
        end

        local projection, projectionError = buildProjection(
            validated.state,
            validated.draft.source,
            validated.replay
        )
        if projectionError then
            return failure({ projectionError })
        end
        return success(validated.draft, projection)
    end

    local function validateProjectionShape(projection)
        local errors = {}
        if type(projection) ~= "table" or getmetatable(projection) ~= nil then
            return {
                makeError(
                    "invalid_projection",
                    "$.projection",
                    "turnDraftProjection이 일반 테이블이 아닙니다."
                ),
            }
        end

        checkAllowedKeys(projection, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            turnNumber = true,
            mode = true,
            hasMainAction = true,
            passAfterChain = true,
            selectedCardInstanceIds = true,
            effectChoiceByInstanceId = true,
            source = true,
            preview = true,
            projectedRng = true,
            workingState = true,
        }, "$.projection", errors)
        if projection.schemaVersion ~= SCHEMA_VERSION then
            table.insert(errors, makeError(
                "unsupported_projection_schema",
                "$.projection.schemaVersion",
                "지원하지 않는 turnDraftProjection 스키마입니다."
            ))
        end
        if projection.kind ~= "turnDraftProjection" then
            table.insert(errors, makeError(
                "invalid_projection_kind",
                "$.projection.kind",
                "projection kind는 turnDraftProjection이어야 합니다."
            ))
        end
        if not isRuntimeId(projection.battleId) then
            table.insert(errors, makeError(
                "invalid_battle_id",
                "$.projection.battleId",
                "projection 전투 ID가 올바르지 않습니다."
            ))
        end
        if not isInteger(projection.turnNumber, 1) then
            table.insert(errors, makeError(
                "invalid_turn_number",
                "$.projection.turnNumber",
                "projection 턴 번호가 올바르지 않습니다."
            ))
        end
        if projection.mode ~= "pass"
            and projection.mode ~= "chain_pass"
            and projection.mode ~= "action" then
            table.insert(errors, makeError(
                "invalid_projection_mode",
                "$.projection.mode",
                "알 수 없는 projection mode입니다."
            ))
        end
        if projection.hasMainAction ~= true and projection.hasMainAction ~= false then
            table.insert(errors, makeError(
                "invalid_projection_flag",
                "$.projection.hasMainAction",
                "hasMainAction은 불리언이어야 합니다."
            ))
        end
        if projection.passAfterChain ~= true and projection.passAfterChain ~= false then
            table.insert(errors, makeError(
                "invalid_projection_flag",
                "$.projection.passAfterChain",
                "passAfterChain은 불리언이어야 합니다."
            ))
        end
        validateIdArray(
            projection.selectedCardInstanceIds,
            "$.projection.selectedCardInstanceIds",
            errors
        )
        if type(projection.effectChoiceByInstanceId) ~= "table" or getmetatable(projection.effectChoiceByInstanceId) ~= nil then
            table.insert(errors, makeError("invalid_effect_choice_map", "$.projection.effectChoiceByInstanceId", "projection 효과 선택값은 일반 객체여야 합니다."))
        else
            for instanceId, choiceId in pairs(projection.effectChoiceByInstanceId) do
                if not isRuntimeId(instanceId) or type(choiceId) ~= "string"
                    or string.match(choiceId, "^[a-z][a-z0-9_]*$") == nil then
                    table.insert(errors, makeError("invalid_effect_choice", "$.projection.effectChoiceByInstanceId." .. tostring(instanceId), "projection 효과 선택값이 올바르지 않습니다."))
                end
            end
        end
        if type(projection.source) ~= "table" or getmetatable(projection.source) ~= nil then
            table.insert(errors, makeError(
                "invalid_projection_source",
                "$.projection.source",
                "projection 원본 표식이 올바르지 않습니다."
            ))
        end
        validatePreviewShape(projection.preview, "$.projection.preview", errors)
        validateRng(projection.projectedRng, "$.projection.projectedRng", errors)
        if type(projection.workingState) ~= "table" or getmetatable(projection.workingState) ~= nil then
            table.insert(errors, makeError(
                "invalid_working_state",
                "$.projection.workingState",
                "projection workingState가 일반 테이블이 아닙니다."
            ))
        end
        return errors
    end

    local function validateProjection(state, staticData, projection)
        local stateCopy, normalizedStaticData, authorityErrors = validateAuthority(state, staticData)
        if authorityErrors then
            return failure(authorityErrors)
        end

        local projectionCopy, cloneError = cloneValue(projection, "$.projection")
        if cloneError then
            return failure({ cloneError })
        end
        local shapeErrors = validateProjectionShape(projectionCopy)
        if #shapeErrors > 0 then
            return failure(shapeErrors)
        end

        local expectedSource, sourceError = buildSource(stateCopy)
        if sourceError then
            return failure({ sourceError })
        end
        if not deepEqual(projectionCopy.source, expectedSource) then
            return failure({
                makeError(
                    "projection_stale",
                    "$.projection.source",
                    "projection을 만든 뒤 권위 전투 상태가 변경되었습니다."
                ),
            })
        end

        local replay, replayErrors = replaySelection(
            stateCopy,
            normalizedStaticData,
            projectionCopy.selectedCardInstanceIds,
            projectionCopy.effectChoiceByInstanceId,
            false
        )
        if replayErrors then
            return failure(replayErrors)
        end
        local expectedProjection, projectionError = buildProjection(
            stateCopy,
            expectedSource,
            replay
        )
        if projectionError then
            return failure({ projectionError })
        end
        if not deepEqual(projectionCopy, expectedProjection) then
            return failure({
                makeError(
                    "projection_mismatch",
                    "$.projection",
                    "projection이 권위 상태에서 같은 선택을 재생한 결과와 다릅니다."
                ),
            })
        end
        return success(nil, expectedProjection)
    end

    local function buildProjectionReceipt(projection)
        local selectedIds, selectedError = cloneValue(
            projection.selectedCardInstanceIds,
            "$.projection.selectedCardInstanceIds"
        )
        if selectedError then
            return nil, selectedError
        end
        local source, sourceError = cloneValue(projection.source, "$.projection.source")
        if sourceError then
            return nil, sourceError
        end
        local projectedRng, rngError = cloneValue(projection.projectedRng, "$.projection.projectedRng")
        if rngError then
            return nil, rngError
        end
        local choices, choicesError = cloneValue(projection.effectChoiceByInstanceId, "$.projection.effectChoiceByInstanceId")
        if choicesError then return nil, choicesError end
        return {
            schemaVersion = SCHEMA_VERSION,
            kind = "turnDraftProjectionReceipt",
            mode = projection.mode,
            selectedCardInstanceIds = selectedIds,
            effectChoiceByInstanceId = choices,
            source = source,
            projectedRng = projectedRng,
        }, nil
    end

    local function validateProjectionReceiptShape(receipt)
        local errors = {}
        if type(receipt) ~= "table" or getmetatable(receipt) ~= nil then
            return {
                makeError(
                    "invalid_projection_receipt",
                    "$.receipt",
                    "turnDraftProjectionReceipt가 일반 테이블이 아닙니다."
                ),
            }
        end
        checkAllowedKeys(receipt, {
            schemaVersion = true,
            kind = true,
            mode = true,
            selectedCardInstanceIds = true,
            effectChoiceByInstanceId = true,
            source = true,
            projectedRng = true,
        }, "$.receipt", errors)
        if receipt.schemaVersion ~= SCHEMA_VERSION then
            table.insert(errors, makeError(
                "unsupported_projection_receipt_schema",
                "$.receipt.schemaVersion",
                "지원하지 않는 projection 영수증 스키마입니다."
            ))
        end
        if receipt.kind ~= "turnDraftProjectionReceipt" then
            table.insert(errors, makeError(
                "invalid_projection_receipt_kind",
                "$.receipt.kind",
                "projection 영수증 kind는 turnDraftProjectionReceipt여야 합니다."
            ))
        end
        if receipt.mode ~= "pass"
            and receipt.mode ~= "chain_pass"
            and receipt.mode ~= "action" then
            table.insert(errors, makeError(
                "invalid_projection_mode",
                "$.receipt.mode",
                "알 수 없는 projection 영수증 mode입니다."
            ))
        end
        validateIdArray(
            receipt.selectedCardInstanceIds,
            "$.receipt.selectedCardInstanceIds",
            errors
        )
        if receipt.effectChoiceByInstanceId ~= nil
            and (type(receipt.effectChoiceByInstanceId) ~= "table" or getmetatable(receipt.effectChoiceByInstanceId) ~= nil) then
            table.insert(errors, makeError("invalid_effect_choice_map", "$.receipt.effectChoiceByInstanceId", "projection 영수증 효과 선택값은 일반 객체여야 합니다."))
        else
            for instanceId, choiceId in pairs(receipt.effectChoiceByInstanceId or {}) do
                if not isRuntimeId(instanceId) or type(choiceId) ~= "string"
                    or string.match(choiceId, "^[a-z][a-z0-9_]*$") == nil then
                    table.insert(errors, makeError("invalid_effect_choice", "$.receipt.effectChoiceByInstanceId." .. tostring(instanceId), "projection 영수증 효과 선택값이 올바르지 않습니다."))
                end
            end
        end
        if type(receipt.source) ~= "table" or getmetatable(receipt.source) ~= nil then
            table.insert(errors, makeError(
                "invalid_projection_source",
                "$.receipt.source",
                "projection 영수증 원본 표식이 올바르지 않습니다."
            ))
        end
        validateRng(receipt.projectedRng, "$.receipt.projectedRng", errors)
        return errors
    end

    local function sealProjection(state, staticData, projection)
        local validated = validateProjection(state, staticData, projection)
        if type(validated) ~= "table" or validated.ok ~= true then
            return validated
        end
        local receipt, receiptError = buildProjectionReceipt(validated.projection)
        if receiptError then
            return failure({ receiptError })
        end
        return success(nil, validated.projection, receipt)
    end

    local function validateProjectionReceipt(state, staticData, receipt)
        local stateCopy, normalizedStaticData, authorityErrors = validateAuthority(state, staticData)
        if authorityErrors then
            return failure(authorityErrors)
        end

        local receiptCopy, cloneError = cloneValue(receipt, "$.receipt")
        if cloneError then
            return failure({ cloneError })
        end
        local shapeErrors = validateProjectionReceiptShape(receiptCopy)
        if #shapeErrors > 0 then
            return failure(shapeErrors)
        end
        receiptCopy.effectChoiceByInstanceId = receiptCopy.effectChoiceByInstanceId or {}

        local expectedSource, sourceError = buildSource(stateCopy)
        if sourceError then
            return failure({ sourceError })
        end
        if not deepEqual(receiptCopy.source, expectedSource) then
            return failure({
                makeError(
                    "projection_receipt_stale",
                    "$.receipt.source",
                    "projection 영수증을 만든 뒤 권위 전투 상태가 변경되었습니다."
                ),
            })
        end

        local replay, replayErrors = replaySelection(
            stateCopy,
            normalizedStaticData,
            receiptCopy.selectedCardInstanceIds,
            receiptCopy.effectChoiceByInstanceId,
            false
