(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local MAX_SAFE_INTEGER = 9007199254740991
    local MAX_PLAN_SLOTS = 16

    local KNOWN_EVENT_TYPES = {
        turn_start = true,
        cards_drawn = true,
        character_intent_selected = true,
        action_tag_revealed = true,
        effect_applied = true,
        trigger_suppressed = true,
        trigger_resolved = true,
        plan_changed = true,
        card_declared = true,
        card_resolved = true,
        card_restored = true,
        action_sequence_stopped = true,
        card_zone_changed = true,
        outcome_latched = true,
        mood_evaluated = true,
        turn_cleanup = true,
        session_end = true,
    }

    local RAW_PAYLOAD_KEYS = {
        turn_start = { turnNumber = true },
        cards_drawn = { requested = true, drawnCount = true },
        character_intent_selected = { selected = true },
        action_tag_revealed = { actionTag = true },
        effect_applied = {
            index = true,
            op = true,
            target = true,
            cause = true,
            changed = true,
            amount = true,
            before = true,
            after = true,
            drawnInstanceIds = true,
            scope = true,
            mood = true,
        },
        trigger_suppressed = { inputEventType = true, reasonCode = true, hidden = true },
        trigger_resolved = { inputEventType = true, commandCount = true },
        plan_changed = {
            action = true,
            instanceId = true,
            before = true,
            after = true,
            planSpec = true,
            movedInstanceIds = true,
            discarded = true,
        },
        card_declared = { cardId = true, instanceId = true, finalStealthCost = true, effectChoiceId = true },
        card_resolved = { cardId = true, instanceId = true, finalResistanceDamage = true },
        card_restored = { instanceId = true, reasonCode = true, destination = true },
        action_sequence_stopped = {
            side = true,
            reasonCode = true,
            restoredInstanceIds = true,
            unresolvedInstanceIds = true,
        },
        card_zone_changed = { instanceId = true, origin = true, destination = true },
        outcome_latched = { status = true, reasonCode = true, stealth = true, resistance = true },
        mood_evaluated = {
            before = true,
            after = true,
            applied = true,
            forcedCount = true,
            forceCancelled = true,
            resolution = true,
            targetMood = true,
            tiedMoods = true,
            tokensBefore = true,
            tokensAfter = true,
        },
        turn_cleanup = { before = true, after = true, movedInstanceIds = true, resolvedTurnNumber = true },
        session_end = { status = true },
    }

    local SUPPORTED_EFFECT_OPS = {
        pay_stealth_cost = true,
        damage_resistance = true,
        recover_resistance = true,
        lose_stealth = true,
        recover_stealth = true,
        draw_cards = true,
        skip_actions = true,
        add_mood_token = true,
        remove_mood_token = true,
        force_mood = true,
    }

    local RESOURCE_EFFECT_OPS = {
        pay_stealth_cost = true,
        damage_resistance = true,
        recover_resistance = true,
        lose_stealth = true,
        recover_stealth = true,
    }

    local CATEGORY_ORDER = {
        plan = 1,
        trait = 2,
        perk = 3,
        environment = 4,
    }

    local function makeError(code, path, message)
        return { code = code, path = path, message = message }
    end

    local function failure(errors)
        return { ok = false, schemaVersion = SCHEMA_VERSION, errors = errors }
    end

    local function success(publicResult, llmEvent)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            publicResult = publicResult,
            llmEvent = llmEvent,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isSafeInteger(value, minimum)
        return isInteger(value, minimum) and math.abs(value) <= MAX_SAFE_INTEGER
    end

    local function isDenseArray(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return false
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return false
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        return count == maximum
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and value ~= ""
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_.:-]*$") ~= nil
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isSide(value)
        return value == "player" or value == "character"
    end

    local function isOutcome(value)
        return value == "victory" or value == "defeat"
    end

    local function cloneData(value, path, active)
        local valueType = type(value)
        if valueType == "nil" or valueType == "string" or valueType == "boolean" then
            return value, nil
        end
        if valueType == "number" then
            if not isFinite(value) then
                return nil, makeError("non_finite_number", path, "NaN과 무한대는 사건 입력에 사용할 수 없습니다.")
            end
            return value, nil
        end
        if valueType ~= "table" then
            return nil, makeError("unsupported_type", path, "사건 입력에 사용할 수 없는 자료형입니다: " .. valueType)
        end
        if getmetatable(value) ~= nil then
            return nil, makeError("metatable_not_allowed", path, "사건 입력에는 메타테이블을 사용할 수 없습니다.")
        end
        active = active or {}
        if active[value] then
            return nil, makeError("circular_reference", path, "순환 참조가 있는 사건 입력은 사용할 수 없습니다.")
        end
        active[value] = true
        local copy = {}
        for key, item in pairs(value) do
            local keyType = type(key)
            if keyType ~= "string" and not isInteger(key, 1) then
                active[value] = nil
                return nil, makeError("invalid_key", path, "JSON 사건 입력에는 문자열 키 또는 양의 배열 인덱스만 사용할 수 있습니다.")
            end
            local childPath = type(key) == "number" and (path .. "[" .. key .. "]") or (path .. ".*")
            local itemCopy, itemError = cloneData(item, childPath, active)
            if itemError then
                active[value] = nil
                return nil, itemError
            end
            copy[key] = itemCopy
        end
        active[value] = nil
        return copy, nil
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function appendNestedErrors(target, prefix, report)
        local nested = type(report) == "table" and report.errors or nil
        if type(nested) ~= "table" or #nested == 0 then
            target[#target + 1] = makeError("nested_validation_failed", prefix, "하위 검증이 실패했습니다.")
            return
        end
        for _, item in ipairs(nested) do
            local nestedCode = type(item) == "table" and item.code or nil
            target[#target + 1] = makeError(
                isAsciiId(nestedCode) and nestedCode or "nested_error",
                prefix,
                "하위 검증이 실패했습니다."
            )
        end
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, makeError("runtime_unavailable", "$.runtime." .. moduleName, "스크립트 실행기를 찾을 수 없습니다.")
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, makeError("module_call_error", "$.runtime." .. moduleName, "하위 모듈 호출 중 오류가 발생했습니다.")
        end
        if type(report) ~= "table" then
            return nil, makeError("invalid_module_result", "$.runtime." .. moduleName, "하위 모듈이 테이블을 반환하지 않았습니다.")
        end
        return report, nil
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" then
            return
        end
        for key in pairs(value) do
            if type(key) ~= "string" or allowed[key] ~= true then
                errors[#errors + 1] = makeError("unexpected_field", path, "사건 계약에 없는 필드가 있습니다.")
            end
        end
    end

    local function arraysEqual(left, right)
        if not isDenseArray(left) or not isDenseArray(right) or #left ~= #right then
            return false
        end
        for index = 1, #left do
            if left[index] ~= right[index] then
                return false
            end
        end
        return true
    end

    local function dataEqual(left, right, active)
        if type(left) ~= type(right) then return false end
        if type(left) ~= "table" then return left == right end
        active = active or {}
        if active[left] == right then return true end
        active[left] = right
        for key, value in pairs(left) do
            if not dataEqual(value, right[key], active) then return false end
        end
        for key in pairs(right) do
            if left[key] == nil then return false end
        end
        return true
    end

    local function orderedZoneIds(state, owner, zone)
        local entries = {}
        for index, instance in ipairs(state.cardInstances) do
            if instance.owner == owner and instance.zone == zone then
                entries[#entries + 1] = {
                    instanceId = instance.instanceId,
                    position = instance.position,
                    sourceIndex = index,
                }
            end
        end
        table.sort(entries, function(left, right)
            if left.position ~= right.position then return left.position < right.position end
            if left.instanceId ~= right.instanceId then return left.instanceId < right.instanceId end
            return left.sourceIndex < right.sourceIndex
        end)
        local ids = {}
        for index, entry in ipairs(entries) do ids[index] = entry.instanceId end
        return ids
    end

    local function cleanupSnapshotFromState(state)
        return {
            turnNumber = state.turnNumber,
            player = {
                used = orderedZoneIds(state, "player", "used"),
                hand = orderedZoneIds(state, "player", "hand"),
                discard = orderedZoneIds(state, "player", "discard"),
                planSlots = state.player.planSlots,
            },
            character = {
                used = orderedZoneIds(state, "character", "used"),
                hand = orderedZoneIds(state, "character", "hand"),
                discard = orderedZoneIds(state, "character", "discard"),
                planSlots = state.character.planSlots,
            },
        }
    end

    local function expectedCleanupTransition(before, resolvedTurnNumber, afterTurnNumber)
        local expected = { turnNumber = afterTurnNumber }
        local moved = {}
        for _, side in ipairs({ "player", "character" }) do
            local sideBefore = before[side]
            local planCopy, planError = cloneData(sideBefore.planSlots, "$.turnResolution.events.cleanup.planSlots", {})
            if planError then return nil, nil, planError end
            local sideAfter = { used = {}, hand = {}, discard = {}, planSlots = planCopy }
            expected[side] = sideAfter
            for _, instanceId in ipairs(sideBefore.discard) do sideAfter.discard[#sideAfter.discard + 1] = instanceId end
            for _, zone in ipairs({ "used", "hand" }) do
                for _, instanceId in ipairs(sideBefore[zone]) do
                    sideAfter.discard[#sideAfter.discard + 1] = instanceId
                    moved[#moved + 1] = instanceId
                end
            end
        end
        for _, side in ipairs({ "player", "character" }) do
            local retained = {}
            for _, slot in ipairs(expected[side].planSlots) do
                if slot.remainingTurns ~= nil
                    and (slot.placedTurn < resolvedTurnNumber
                        or slot.durationIncludesPlacementTurn == true) then
                    slot.remainingTurns = slot.remainingTurns - 1
                end
                if slot.remainingTurns == 0 then
                    local instanceId = slot.cardInstanceId
                    expected[side].discard[#expected[side].discard + 1] = instanceId
                    moved[#moved + 1] = instanceId
                else
                    retained[#retained + 1] = slot
                end
            end
            expected[side].planSlots = retained
        end
        return expected, moved, nil
    end

    local function findCard(staticData, cardId, side, path, errors)
        local card = type(staticData.cards) == "table" and staticData.cards[cardId] or nil
        if type(card) ~= "table" or card.id ~= cardId then
            errors[#errors + 1] = makeError("unknown_card", path, "사건의 카드 정의를 찾을 수 없습니다.")
            return nil
        end
        if side ~= nil and card.owner ~= side then
            errors[#errors + 1] = makeError("card_owner_mismatch", path, "사건의 카드 소유자와 side가 다릅니다.")
            return nil
        end
        return card
    end

    local function hasMechanism(card, mechanismId)
        for _, current in ipairs(type(card) == "table" and type(card.mechanisms) == "table" and card.mechanisms or {}) do
            if current == mechanismId then
                return true
            end
        end
        return false
    end

    local function findEffectChoice(card, choiceId)
        for _, choice in ipairs(type(card) == "table" and type(card.effectChoices) == "table" and card.effectChoices or {}) do
            if choice.id == choiceId then return choice end
        end
        return nil
    end

    local function validateSource(source, path, errors)
        if type(source) ~= "table" then
            errors[#errors + 1] = makeError("invalid_event_source", path, "사건 source가 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(source, {
            kind = true,
            id = true,
            side = true,
            instanceId = true,
        }, path, errors)
        if not isAsciiId(source.kind) then
            errors[#errors + 1] = makeError("invalid_source_kind", path .. ".kind", "사건 source kind가 올바르지 않습니다.")
        end
        if not isAsciiId(source.id) then
            errors[#errors + 1] = makeError("invalid_source_id", path .. ".id", "사건 source id가 올바르지 않습니다.")
        end
        if source.side ~= nil and source.side ~= "player" and source.side ~= "character" then
            errors[#errors + 1] = makeError("invalid_source_side", path .. ".side", "사건 source side가 올바르지 않습니다.")
        end
        if source.instanceId ~= nil and not isRuntimeId(source.instanceId) then
            errors[#errors + 1] = makeError("invalid_source_instance", path .. ".instanceId", "사건 source instanceId가 올바르지 않습니다.")
        end
    end

    local function validateCause(cause, path, eventResolutionId, errors)
        if cause == nil then
            return
        end
        if type(cause) ~= "table" or getmetatable(cause) ~= nil then
            errors[#errors + 1] = makeError("invalid_event_cause", path, "사건 cause가 일반 객체가 아닙니다.")
            return
        end
        checkAllowedKeys(cause, {
            kind = true,
            resolutionId = true,
            eventId = true,
        }, path, errors)
        if not isAsciiId(cause.kind) then
            errors[#errors + 1] = makeError("invalid_cause_kind", path .. ".kind", "사건 cause kind가 올바르지 않습니다.")
        end
        if cause.resolutionId ~= nil then
            if not isRuntimeId(cause.resolutionId) then
                errors[#errors + 1] = makeError("invalid_cause_resolution", path .. ".resolutionId", "cause resolutionId가 올바르지 않습니다.")
            elseif cause.resolutionId ~= eventResolutionId then
                errors[#errors + 1] = makeError("cause_resolution_mismatch", path .. ".resolutionId", "cause와 사건의 resolutionId가 다릅니다.")
            end
        end
        if cause.eventId ~= nil and not isRuntimeId(cause.eventId) then
            errors[#errors + 1] = makeError("invalid_cause_event", path .. ".eventId", "cause eventId가 올바르지 않습니다.")
        end
    end

    local function validateIdArray(value, path)
        if not isDenseArray(value) then
            return nil, makeError("invalid_id_array", path, "runtime ID 목록이 연속 배열이 아닙니다.")
        end
        local seen = {}
        for index, instanceId in ipairs(value) do
            if not isRuntimeId(instanceId) then
                return nil, makeError("invalid_runtime_id", path .. "[" .. index .. "]", "runtime ID가 올바르지 않습니다.")
            end
            if seen[instanceId] then
                return nil, makeError("duplicate_runtime_id", path .. "[" .. index .. "]", "runtime ID가 중복되었습니다.")
            end
            seen[instanceId] = true
        end
        return true, nil
    end

    local function validatePlanSlotSnapshot(slot, path)
        if type(slot) ~= "table" or getmetatable(slot) ~= nil then
            return nil, makeError("invalid_plan_slot", path, "계획 슬롯 스냅숏이 일반 객체가 아닙니다.")
        end
        local errors = {}
        checkAllowedKeys(slot, {
            occupied = true,
            cardInstanceId = true,
            cardId = true,
            placedTurn = true,
            durationIncludesPlacementTurn = true,
            remainingTurns = true,
            remainingCharges = true,
            revealed = true,
            effectChoiceId = true,
        }, path, errors)
        if #errors > 0 then
            return nil, errors[1]
        end
        if slot.occupied ~= true
            or not isRuntimeId(slot.cardInstanceId)
            or not isAsciiId(slot.cardId)
            or not isInteger(slot.placedTurn, 1)
            or type(slot.revealed) ~= "boolean" then
            return nil, makeError("invalid_plan_slot", path, "점유된 계획 슬롯의 식별 정보가 올바르지 않습니다.")
        end
        if slot.remainingTurns == nil and slot.remainingCharges == nil then
            return nil, makeError("missing_plan_lifetime", path, "점유된 계획에는 지속시간 또는 충전이 필요합니다.")
        end
        if slot.durationIncludesPlacementTurn ~= nil
            and type(slot.durationIncludesPlacementTurn) ~= "boolean" then
            return nil, makeError(
                "invalid_plan_duration_policy",
                path .. ".durationIncludesPlacementTurn",
                "배치 턴 포함 여부가 불리언이 아닙니다."
            )
        end
        if slot.durationIncludesPlacementTurn == true and slot.remainingTurns == nil then
            return nil, makeError(
                "plan_duration_policy_requires_duration",
                path .. ".durationIncludesPlacementTurn",
                "배치 턴을 포함하는 계획에는 남은 지속시간이 필요합니다."
            )
        end
        if slot.remainingTurns ~= nil and not isInteger(slot.remainingTurns, 1) then
            return nil, makeError("invalid_plan_duration", path .. ".remainingTurns", "계획 남은 지속시간이 올바르지 않습니다.")
        end
        if slot.remainingCharges ~= nil and not isInteger(slot.remainingCharges, 1) then
            return nil, makeError("invalid_plan_charges", path .. ".remainingCharges", "계획 남은 충전이 올바르지 않습니다.")
        end
        if slot.effectChoiceId ~= nil and not isAsciiId(slot.effectChoiceId) then
            return nil, makeError("invalid_effect_choice_id", path .. ".effectChoiceId", "계획 효과 선택지 ID가 올바르지 않습니다.")
        end
        return true, nil
    end

    local function validatePlanSlotsSnapshot(slots, path, capacity)
        if not isDenseArray(slots) then
            return nil, makeError("invalid_plan_slots", path, "계획 슬롯 목록이 연속 배열이 아닙니다.")
        end
        if #slots > MAX_PLAN_SLOTS then
            return nil, makeError(
                "plan_slot_limit_exceeded",
                path,
                "계획 슬롯 목록이 지원 상한을 초과했습니다."
            )
        end
        if capacity ~= nil and #slots > capacity then
            return nil, makeError(
                "plan_capacity_exceeded",
                path,
                "계획 슬롯 목록이 해당 진영의 계획 용량을 초과했습니다."
            )
        end
        local seen = {}
        for index, slot in ipairs(slots) do
            local _, slotError = validatePlanSlotSnapshot(slot, path .. "[" .. index .. "]")
            if slotError then
                return nil, slotError
            end
            if seen[slot.cardInstanceId] then
                return nil, makeError("duplicate_plan_instance", path .. "[" .. index .. "].cardInstanceId", "계획 슬롯 인스턴스가 중복되었습니다.")
            end
            seen[slot.cardInstanceId] = true
        end
        return true, nil
    end

    local function validatePlanSpecSnapshot(spec, path)
        if type(spec) ~= "table" or getmetatable(spec) ~= nil then
            return nil, makeError("invalid_plan_spec", path, "계획 배치 명세가 일반 객체가 아닙니다.")
        end
        local errors = {}
        checkAllowedKeys(spec, {
            durationTurns = true,
            durationIncludesPlacementTurn = true,
            charges = true,
            revealed = true,
            effectChoiceId = true,
        }, path, errors)
        if #errors > 0 then
            return nil, errors[1]
        end
        if spec.durationTurns == nil and spec.charges == nil then
            return nil, makeError("missing_plan_lifetime", path, "계획 배치 명세에는 지속시간 또는 충전이 필요합니다.")
        end
        if spec.durationTurns ~= nil and not isInteger(spec.durationTurns, 1) then
            return nil, makeError("invalid_plan_duration", path .. ".durationTurns", "계획 배치 지속시간이 올바르지 않습니다.")
        end
        if spec.durationIncludesPlacementTurn ~= nil
            and type(spec.durationIncludesPlacementTurn) ~= "boolean" then
            return nil, makeError(
                "invalid_plan_duration_policy",
                path .. ".durationIncludesPlacementTurn",
                "계획 배치의 배치 턴 포함 여부가 불리언이 아닙니다."
            )
        end
        if spec.durationIncludesPlacementTurn == true and spec.durationTurns == nil then
            return nil, makeError(
                "plan_duration_policy_requires_duration",
                path .. ".durationIncludesPlacementTurn",
                "배치 턴을 포함하는 계획 배치에는 지속시간이 필요합니다."
            )
        end
        if spec.charges ~= nil and not isInteger(spec.charges, 1) then
            return nil, makeError("invalid_plan_charges", path .. ".charges", "계획 배치 충전이 올바르지 않습니다.")
        end
        if type(spec.revealed) ~= "boolean" then
            return nil, makeError("invalid_plan_revealed", path .. ".revealed", "계획 배치 공개 여부가 불리언이 아닙니다.")
        end
        if spec.effectChoiceId ~= nil and not isAsciiId(spec.effectChoiceId) then
            return nil, makeError("invalid_effect_choice_id", path .. ".effectChoiceId", "계획 효과 선택지 ID가 올바르지 않습니다.")
        end
        return true, nil
    end

    local function validateCleanupSnapshot(snapshot, path, capacities)
        if type(snapshot) ~= "table" or getmetatable(snapshot) ~= nil then
            return nil, makeError("invalid_cleanup_snapshot", path, "턴 정리 스냅숏이 일반 객체가 아닙니다.")
        end
        local errors = {}
        checkAllowedKeys(snapshot, { turnNumber = true, player = true, character = true }, path, errors)
        if #errors > 0 or not isInteger(snapshot.turnNumber, 1) then
            return nil, errors[1] or makeError("invalid_cleanup_turn", path .. ".turnNumber", "턴 정리 번호가 올바르지 않습니다.")
        end
        for _, side in ipairs({ "player", "character" }) do
            local sidePath = path .. "." .. side
            local value = snapshot[side]
            if type(value) ~= "table" or getmetatable(value) ~= nil then
                return nil, makeError("invalid_cleanup_side", sidePath, "턴 정리 진영 스냅숏이 일반 객체가 아닙니다.")
            end
            errors = {}
            checkAllowedKeys(value, { used = true, hand = true, discard = true, planSlots = true }, sidePath, errors)
            if #errors > 0 then
                return nil, errors[1]
            end
            for _, zone in ipairs({ "used", "hand", "discard" }) do
                local _, idError = validateIdArray(value[zone], sidePath .. "." .. zone)
                if idError then
                    return nil, idError
                end
            end
            local capacity = type(capacities) == "table" and capacities[side] or nil
            local _, slotError = validatePlanSlotsSnapshot(
                value.planSlots,
                sidePath .. ".planSlots",
                capacity
            )
            if slotError then
                return nil, slotError
            end
        end
        return true, nil
    end

    local function validateResolution(beforeState, staticData, resolution)
        local errors = {}
        if type(staticData) ~= "table"
            or type(staticData.registry) ~= "table"
            or type(staticData.cards) ~= "table"
            or type(staticData.characters) ~= "table" then
            return nil, { makeError("invalid_static_data", "$.staticData", "전체 정적 데이터가 필요합니다.") }
        end

        local beforeValidation, beforeCallError = callModule("stateSchema", "validateBattleState", beforeState, staticData)
        if beforeCallError then
            return nil, { beforeCallError }
        end
        if beforeValidation.ok ~= true then
            appendNestedErrors(errors, "$.beforeState", beforeValidation)
        elseif beforeValidation.referencesValidated ~= true then
            errors[#errors + 1] = makeError("static_references_not_validated", "$.staticData", "beforeState의 정적 참조 검증이 필요합니다.")
        end

        local resolutionCopy, cloneError = cloneData(resolution, "$.turnResolution", {})
        if cloneError then
            errors[#errors + 1] = cloneError
            return nil, errors
        end
        if type(resolutionCopy) ~= "table" then
            return nil, { makeError("invalid_turn_resolution", "$.turnResolution", "turnResolution이 객체가 아닙니다.") }
        end
        checkAllowedKeys(resolutionCopy, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            turnId = true,
            turnNumber = true,
            source = true,
            selectedCards = true,
            events = true,
            metrics = true,
            afterState = true,
        }, "$.turnResolution", errors)
        if resolutionCopy.schemaVersion ~= SCHEMA_VERSION or resolutionCopy.kind ~= "turnResolution" then
            errors[#errors + 1] = makeError("invalid_turn_resolution", "$.turnResolution", "지원하지 않는 turnResolution입니다.")
        end
        if not isRuntimeId(resolutionCopy.battleId) or resolutionCopy.battleId ~= beforeState.battleId then
            errors[#errors + 1] = makeError("resolution_battle_mismatch", "$.turnResolution.battleId", "turnResolution battleId가 beforeState와 다릅니다.")
        end
        if not isRuntimeId(resolutionCopy.turnId) then
            errors[#errors + 1] = makeError("invalid_turn_id", "$.turnResolution.turnId", "turnResolution turnId가 올바르지 않습니다.")
        end
        local startReceipt = type(beforeState) == "table" and beforeState.turnStartReceipt or nil
        if type(startReceipt) ~= "table" or startReceipt.turnId ~= resolutionCopy.turnId then
            errors[#errors + 1] = makeError("resolution_turn_mismatch", "$.turnResolution.turnId", "turnResolution turnId가 beforeState.turnStartReceipt와 다릅니다.")
        end
        if not isInteger(resolutionCopy.turnNumber, 1) or resolutionCopy.turnNumber ~= beforeState.turnNumber then
            errors[#errors + 1] = makeError("resolution_turn_number_mismatch", "$.turnResolution.turnNumber", "해결 턴 번호가 beforeState와 다릅니다.")
        end
        if type(resolutionCopy.source) ~= "table" then
            errors[#errors + 1] = makeError("invalid_resolution_source", "$.turnResolution.source", "turnResolution source가 없습니다.")
        else
            checkAllowedKeys(resolutionCopy.source, {
                kind = true,
                mode = true,
                authority = true,
                projectedRng = true,
            }, "$.turnResolution.source", errors)
            if resolutionCopy.source.kind ~= "turnDraftProjection"
                or (resolutionCopy.source.mode ~= "pass"
                    and resolutionCopy.source.mode ~= "chain_pass"
                    and resolutionCopy.source.mode ~= "action") then
                errors[#errors + 1] = makeError("invalid_resolution_source", "$.turnResolution.source", "해결 source의 projection mode가 올바르지 않습니다.")
            end
        end
        if type(resolutionCopy.selectedCards) ~= "table"
            or not isDenseArray(resolutionCopy.selectedCards.player)
            or not isDenseArray(resolutionCopy.selectedCards.character) then
            errors[#errors + 1] = makeError("invalid_selected_cards", "$.turnResolution.selectedCards", "선택 카드 배열이 올바르지 않습니다.")
        else
            local _, playerIdsError = validateIdArray(
                resolutionCopy.selectedCards.player,
                "$.turnResolution.selectedCards.player"
            )
            local _, characterIdsError = validateIdArray(
                resolutionCopy.selectedCards.character,
                "$.turnResolution.selectedCards.character"
            )
            if playerIdsError then errors[#errors + 1] = playerIdsError end
            if characterIdsError then errors[#errors + 1] = characterIdsError end
            if type(beforeState.characterIntent) == "table"
                and not arraysEqual(resolutionCopy.selectedCards.character, beforeState.characterIntent.cardInstanceIds) then
                errors[#errors + 1] = makeError("character_selection_mismatch", "$.turnResolution.selectedCards.character", "캐릭터 선택이 beforeState 의도와 다릅니다.")
            end
        end

        local afterValidation, afterCallError = callModule("stateSchema", "validateBattleState", resolutionCopy.afterState, staticData)
        if afterCallError then
            errors[#errors + 1] = afterCallError
        elseif afterValidation.ok ~= true then
            appendNestedErrors(errors, "$.turnResolution.afterState", afterValidation)
        elseif afterValidation.referencesValidated ~= true then
            errors[#errors + 1] = makeError("static_references_not_validated", "$.turnResolution.afterState", "afterState의 정적 참조 검증이 필요합니다.")
        end
        if type(resolutionCopy.afterState) == "table" then
            if resolutionCopy.afterState.battleId ~= resolutionCopy.battleId then
                errors[#errors + 1] = makeError("after_battle_mismatch", "$.turnResolution.afterState.battleId", "afterState battleId가 다릅니다.")
            end
            if resolutionCopy.afterState.lastCommittedTurnId ~= resolutionCopy.turnId then
                errors[#errors + 1] = makeError("after_turn_not_committed", "$.turnResolution.afterState.lastCommittedTurnId", "afterState가 해결 turnId를 확정하지 않았습니다.")
            end
            for _, side in ipairs({ "player", "character" }) do
                local beforeOwner = type(beforeState[side]) == "table" and beforeState[side] or nil
                local afterOwner = type(resolutionCopy.afterState[side]) == "table"
                    and resolutionCopy.afterState[side]
                    or nil
                if beforeOwner ~= nil
                    and afterOwner ~= nil
                    and afterOwner.planCapacity ~= beforeOwner.planCapacity then
                    errors[#errors + 1] = makeError(
                        "plan_capacity_changed",
                        "$.turnResolution.afterState." .. side .. ".planCapacity",
                        "v1 턴 해결은 계획 용량을 변경할 수 없습니다."
                    )
                end
            end
        end

        if not isDenseArray(resolutionCopy.events) then
            errors[#errors + 1] = makeError("invalid_event_array", "$.turnResolution.events", "사건 목록이 연속 배열이 아닙니다.")
        else
            for index, event in ipairs(resolutionCopy.events) do
                local path = "$.turnResolution.events[" .. index .. "]"
                if type(event) ~= "table" then
                    errors[#errors + 1] = makeError("invalid_event", path, "사건이 객체가 아닙니다.")
                else
                    checkAllowedKeys(event, {
                        eventId = true,
                        sequence = true,
                        type = true,
                        phase = true,
                        source = true,
                        payload = true,
                        resolutionId = true,
                        side = true,
                        cause = true,
                    }, path, errors)
                    if event.sequence ~= index then
                        errors[#errors + 1] = makeError("event_sequence_mismatch", path .. ".sequence", "원본 사건 sequence가 연속적이지 않습니다.")
                    end
                    local expectedEventId = tostring(resolutionCopy.turnId) .. "-event-" .. string.format("%03d", index)
                    if event.eventId ~= expectedEventId then
                        errors[#errors + 1] = makeError("event_id_mismatch", path .. ".eventId", "원본 사건 eventId가 turnId와 sequence에 맞지 않습니다.")
                    end
                    if type(event.type) ~= "string" or KNOWN_EVENT_TYPES[event.type] ~= true then
                        errors[#errors + 1] = makeError("unknown_event_type", path .. ".type", "지원하지 않는 원본 사건입니다.")
                    end
                    if type(event.phase) ~= "string" or not isAsciiId(event.phase) then
                        errors[#errors + 1] = makeError("invalid_event_phase", path .. ".phase", "원본 사건 phase가 올바르지 않습니다.")
                    end
                    if event.side ~= nil and event.side ~= "player" and event.side ~= "character" then
                        errors[#errors + 1] = makeError("invalid_event_side", path .. ".side", "원본 사건 side가 올바르지 않습니다.")
                    end
                    if event.resolutionId ~= nil and not isRuntimeId(event.resolutionId) then
                        errors[#errors + 1] = makeError("invalid_resolution_id", path .. ".resolutionId", "원본 사건 resolutionId가 올바르지 않습니다.")
                    end
                    validateSource(event.source, path .. ".source", errors)
                    validateCause(event.cause, path .. ".cause", event.resolutionId, errors)
                    if type(event.payload) ~= "table" then
                        errors[#errors + 1] = makeError("invalid_event_payload", path .. ".payload", "원본 사건 payload가 객체가 아닙니다.")
                    elseif KNOWN_EVENT_TYPES[event.type] then
                        checkAllowedKeys(event.payload, RAW_PAYLOAD_KEYS[event.type], path .. ".payload", errors)
                    end
                    if event.type == "effect_applied" then
                        local op = type(event.payload) == "table" and event.payload.op or nil
                        if type(op) ~= "string" or SUPPORTED_EFFECT_OPS[op] ~= true then
                            errors[#errors + 1] = makeError("unsupported_effect_op", path .. ".payload.op", "지원하지 않는 효과 작업입니다.")
                        end
                    end
                end
            end
        end

        if #errors > 0 then
            return nil, errors
        end
        return resolutionCopy, nil
    end

    local function newEnvelope()
        return { schemaVersion = SCHEMA_VERSION, events = {} }
    end

    local function emit(envelope, eventType, payload)
        envelope.events[#envelope.events + 1] = {
            sequence = #envelope.events + 1,
            type = eventType,
            payload = payload,
        }
    end

    local function copySafeEffect(payload, path, moods)
        if type(payload) ~= "table" or type(payload.changed) ~= "boolean" then
            return nil, makeError("invalid_effect_payload", path, "효과 payload 또는 changed가 올바르지 않습니다.")
        end
        if not isSide(payload.target) then
            return nil, makeError("invalid_effect_target", path .. ".target", "효과 대상이 올바르지 않습니다.")
        end
        local op = payload.op
        local output = {
            op = op,
            target = payload.target,
            changed = payload.changed == true,
        }
        local function requireFinite(field)
            if not isFinite(payload[field]) then
                return nil, makeError("invalid_effect_payload", path .. "." .. field, "효과 수치가 유한하지 않습니다.")
            end
            return payload[field], nil
        end

        if op == "pay_stealth_cost"
            or op == "damage_resistance"
            or op == "recover_resistance"
            or op == "lose_stealth"
            or op == "recover_stealth" then
            local expectedTargets = {
                pay_stealth_cost = "player",
                damage_resistance = "character",
                recover_resistance = "character",
                lose_stealth = "player",
                recover_stealth = "player",
            }
            if payload.target ~= expectedTargets[op] then
                return nil, makeError("effect_target_mismatch", path .. ".target", "자원 효과 대상이 op와 다릅니다.")
            end
            local amount, amountError = requireFinite("amount")
            local before, beforeError = requireFinite("before")
            local after, afterError = requireFinite("after")
            if amountError or beforeError or afterError or amount < 0 then
                return nil, amountError or beforeError or afterError
                    or makeError("invalid_effect_payload", path .. ".amount", "자원 효과량은 0 이상이어야 합니다.")
            end
            local direction = (op == "recover_resistance" or op == "recover_stealth") and 1 or -1
            if after ~= before + direction * amount then
                return nil, makeError("effect_result_mismatch", path .. ".after", "자원 효과 결과가 before·amount와 다릅니다.")
            end
            if payload.changed ~= (before ~= after) then
                return nil, makeError("effect_change_mismatch", path .. ".changed", "자원 효과의 changed가 before/after와 다릅니다.")
            end
            output.amount = amount
            output.before = before
            output.after = after
        elseif op == "draw_cards" then
            local requested, requestedError = requireFinite("amount")
            local _, idError = validateIdArray(payload.drawnInstanceIds, path .. ".drawnInstanceIds")
            if requestedError or not isInteger(requested, 1) or idError
                or #payload.drawnInstanceIds > requested then
                return nil, requestedError or makeError("invalid_effect_payload", path, "드로우 효과 payload가 올바르지 않습니다.")
            end
            output.requested = requested
            output.drawnCount = #payload.drawnInstanceIds
            if payload.changed ~= (#payload.drawnInstanceIds > 0) then
                return nil, makeError("effect_change_mismatch", path .. ".changed", "드로우 효과의 changed가 실제 드로우 수와 다릅니다.")
            end
        elseif op == "skip_actions" then
            if payload.scope ~= "remainingTurn" or type(payload.before) ~= "boolean" or payload.after ~= true then
                return nil, makeError("invalid_effect_payload", path, "행동 생략 효과 payload가 올바르지 않습니다.")
            end
            output.scope = payload.scope
            output.before = payload.before
            output.after = true
            if payload.changed ~= (not payload.before) then
                return nil, makeError("effect_change_mismatch", path .. ".changed", "행동 생략 효과의 changed가 before와 다릅니다.")
            end
        elseif op == "add_mood_token" or op == "remove_mood_token" then
            if payload.target ~= "character" then
                return nil, makeError("effect_target_mismatch", path .. ".target", "무드 토큰 대상은 character여야 합니다.")
            end
            if not isAsciiId(payload.mood) or type(moods) ~= "table" or type(moods[payload.mood]) ~= "table"
                or not isInteger(payload.amount, 1)
                or not isInteger(payload.before, 0)
                or not isInteger(payload.after, 0)
                or payload.after ~= (op == "add_mood_token"
                    and payload.before + payload.amount
                    or math.max(0, payload.before - payload.amount))
                or payload.changed ~= (payload.before ~= payload.after) then
                return nil, makeError("invalid_effect_payload", path, "무드 토큰 효과 payload가 올바르지 않습니다.")
            end
            output.mood = payload.mood
            output.amount = payload.amount
            output.before = payload.before
            output.after = payload.after
        elseif op == "force_mood" then
            if payload.target ~= "character" then
                return nil, makeError("effect_target_mismatch", path .. ".target", "무드 강제 변경 대상은 character여야 합니다.")
            end
            if not isAsciiId(payload.mood) or type(moods) ~= "table" or type(moods[payload.mood]) ~= "table"
                or not isInteger(payload.before, 0)
                or payload.after ~= payload.before + 1
                or payload.changed ~= true then
                return nil, makeError("invalid_effect_payload", path, "무드 강제 변경 요청 payload가 올바르지 않습니다.")
            end
            output.mood = payload.mood
            output.before = payload.before
            output.after = payload.after
        else
            return nil, makeError("unsupported_effect_op", path .. ".op", "지원하지 않는 효과 작업입니다.")
        end

        return output, nil
    end

    local function findPlanSlot(slots, instanceId)
        if not isDenseArray(slots) or not isRuntimeId(instanceId) then
            return nil, nil
        end
        for index, slot in ipairs(slots) do
            if type(slot) == "table" and slot.cardInstanceId == instanceId then
                return slot, index
            end
        end
        return nil, nil
    end

    local function planKnown(side, slot)
        return side == "player"
            or (type(slot) == "table" and slot.occupied == true and slot.revealed == true)
    end

    local function sideRank(side, actingSide)
        if actingSide ~= nil and side == actingSide then
            return 1
        end
        if actingSide ~= nil and isSide(side) then
            return 2
        end
        if actingSide == nil and side == "player" then
            return 1
        end
        if actingSide == nil and side == "character" then
            return 2
        end
        return 3
    end

    local function projectTurn(beforeStateInput, staticInput, resolutionInput)
        local staticData = normalizeStaticData(staticInput)
        local beforeState, beforeCloneError = cloneData(beforeStateInput, "$.beforeState", {})
        if beforeCloneError then
            return failure({ beforeCloneError })
        end
        if type(beforeState) ~= "table" then
            return failure({ makeError("invalid_before_state", "$.beforeState", "beforeState가 객체가 아닙니다.") })
        end
        local resolution, validationErrors = validateResolution(beforeState, staticData, resolutionInput)
        if validationErrors then
            return failure(validationErrors)
        end

        local publicResult = newEnvelope()
        local llmEvent = newEnvelope()
        local mode = resolution.source.mode
        emit(publicResult, "turn_mode", { mode = mode })
        emit(llmEvent, "turn_mode", { mode = mode })

        local startReceipt = beforeState.turnStartReceipt
        local startBaseline = type(startReceipt) == "table" and startReceipt.baseline or nil
        local function initialPlanSlots(side)
            for _, receiptEvent in ipairs(type(startReceipt) == "table" and startReceipt.events or {}) do
                local receiptSide = receiptEvent.side
                    or (type(receiptEvent.source) == "table" and receiptEvent.source.side or nil)
                if receiptEvent.type == "plan_changed" and receiptSide == side
                    and type(receiptEvent.payload) == "table"
                    and type(receiptEvent.payload.before) == "table" then
                    return receiptEvent.payload.before
                end
            end
            return beforeState[side].planSlots
        end
        local trackers = {
            player = {
                slots = initialPlanSlots("player"),
            },
            character = {
                slots = initialPlanSlots("character"),
            },
        }
        for _, side in ipairs({ "player", "character" }) do
            local _, initialSlotsError = validatePlanSlotsSnapshot(
                trackers[side].slots,
                "$.beforeState.turnStartReceipt.events.planSlots." .. side,
                beforeState[side].planCapacity
            )
            if initialSlotsError then
                return failure({ initialSlotsError })
            end
        end
        local startingStealth = type(startBaseline) == "table" and startBaseline.stealth or beforeState.player.stealth
        local startingResistance = type(startBaseline) == "table" and startBaseline.resistance or beforeState.character.resistance
        local trackedStealth = startingStealth
        local trackedResistance = startingResistance
        local trackedMood = type(startBaseline) == "table" and startBaseline.mood or beforeState.character.mood
        local function normalizedMoodTokens(source)
            local counts = {}
            source = type(source) == "table" and source or {}
            for moodId in pairs(staticData.registry.moods) do
                counts[moodId] = source[moodId] or 0
            end
            return counts
        end
        local trackedMoodTokens = normalizedMoodTokens(
            type(startBaseline) == "table" and startBaseline.moodTokens
                or beforeState.character.moodTokens
        )
        local trackedForcedMoodRequests = {}
        local function findBeforeInstance(instanceId)
            for _, instance in ipairs(beforeState.cardInstances) do
                if instance.instanceId == instanceId then return instance end
            end
            return nil
        end
        local function countAuthorityHand(side)
            local count = 0
            for _, instance in ipairs(beforeState.cardInstances) do
                if instance.owner == side and instance.zone == "hand" then count = count + 1 end
            end
            return count
        end
        local function countBeforeHand(side)
            local draw = type(startReceipt.draws) == "table" and startReceipt.draws[side] or nil
            return countAuthorityHand(side) - #(type(draw) == "table" and draw.drawnInstanceIds or {})
        end
        local trackedHandCount = {
            player = countBeforeHand("player"),
            character = countBeforeHand("character"),
        }
        local turnStartSettled = false
        local pendingCosts = {}
        local pendingTriggerEffects = {}
        local pendingPlanSlots = {}
        local pendingPlanMeanings = {}
        local triggerInputs = {}
        local seenTriggerBatches = {}
        local seenTriggerOrder = {}
        local expectedCharacterIntent = beforeState.characterIntent
        local expectedCharacterSelected = #expectedCharacterIntent.cardInstanceIds > 0
        local expectedCharacterActionTag = expectedCharacterIntent.publicActionTag
        local pendingCharacterIntent = false
        local pendingDeclarations = {}
        local sawTurnStart = false
        local sawStartDraw = { player = false, character = false }
        local sawCharacterIntent = false
        local sawMoodEvaluation = false
        local sawCleanup = false
        local sawSessionEnd = false
        local latchedOutcome = nil
        local postCleanupSnapshot = nil
        local triggerPhases = {
            turn_start = true,
            player_card = true,
            character_card = true,
            turn_end = true,
            session_end = true,
        }

        local function triggerInputKey(resolutionId, phase, eventType)
            if resolutionId ~= nil then return "resolution|" .. resolutionId .. "|" .. eventType end
            return "phase|" .. phase .. "|" .. eventType
        end

        local function makeTriggerContext(eventType, phase, currentCard)
            local publicActionTag = beforeState.characterIntent.publicActionTag
            if eventType == "turn_start" then
                -- turnInitializer runs this trigger before character selection.
                publicActionTag = nil
            end
            local context = {
                turn = resolution.turnNumber,
                phase = phase,
                mood = trackedMood,
                player = {
                    stealth = trackedStealth,
                    handCount = trackedHandCount.player,
                },
                character = {
                    resistance = trackedResistance,
                    publicActionTag = publicActionTag,
                },
            }
            if currentCard ~= nil then
                context.card = {
                    id = currentCard.id,
                    instanceId = currentCard.instanceId,
                    owner = currentCard.owner,
                    actionTag = currentCard.actionTag,
                }
            end
            return context
        end

        local function registerTriggerInput(eventType, phase, resolutionId, inputEvent, currentCard, eventId)
            local key = triggerInputKey(resolutionId, phase, eventType)
            if triggerInputs[key] == nil then
                triggerInputs[key] = {
                    event = inputEvent,
                    context = makeTriggerContext(eventType, phase, currentCard),
                    eventId = eventId,
                    plans = {
                        player = trackers.player.slots,
                        character = trackers.character.slots,
                    },
                }
            end
            return triggerInputs[key]
        end

        local function sourceBatchKey(inputKey, kind, sourceId, side, instanceId)
            return inputKey
                .. "|" .. kind
                .. "|" .. tostring(side or "")
                .. "|" .. tostring(instanceId or "")
                .. "|" .. sourceId
        end

        local function triggerBatchKey(inputKey, event)
            return sourceBatchKey(
                inputKey,
                event.source.kind,
                event.source.id,
                event.side or event.source.side,
                event.source.instanceId
            )
        end

        local function requireSource(event, path, expectedKind, expectedId)
            if event.source.kind ~= expectedKind
                or (expectedId ~= nil and event.source.id ~= expectedId) then
                return nil, makeError("event_source_mismatch", path .. ".source", "사건 source가 사건 종류와 다릅니다.")
            end
            return true, nil
        end

        local function requireSideSource(event, path, side)
            if not isSide(side)
                or event.side ~= side
                or event.source.side ~= side then
                return nil, makeError("event_side_mismatch", path, "사건 side와 source.side가 다릅니다.")
            end
            return true, nil
        end

        local function findTriggerDefinition(kind, sourceId, side, path)
            if kind == "plan" then
                local lookupErrors = {}
                local card = findCard(staticData, sourceId, side, path, lookupErrors)
                if #lookupErrors > 0 then
                    return nil, lookupErrors[1]
                end
                local plan = type(card.mechanismData) == "table" and card.mechanismData.plan or nil
                if not hasMechanism(card, "plan") or type(plan) ~= "table" then
                    return nil, makeError("invalid_plan_source", path, "트리거 source가 계획 정의가 아닙니다.")
                end
                return plan, nil
            end

            local collections = {
                trait = staticData.traits,
                perk = staticData.perks,
                environment = staticData.environments,
            }
            local collection = collections[kind]
            local definition = type(collection) == "table" and collection[sourceId] or nil
            if type(definition) ~= "table" or definition.id ~= sourceId then
                return nil, makeError("unknown_trigger_source", path, "트리거 source 정의를 찾을 수 없습니다.")
            end
            local active = kind == "environment" and beforeState.environmentId == sourceId
            local activeIds = kind == "trait" and beforeState.character.traitIds
                or (kind == "perk" and beforeState.player.perkIds or nil)
            for _, activeId in ipairs(type(activeIds) == "table" and activeIds or {}) do
                if activeId == sourceId then active = true break end
            end
            if active ~= true then
                return nil, makeError("inactive_trigger_source", path, "트리거 source가 현재 전투에 활성화되어 있지 않습니다.")
            end
            if not isDenseArray(definition.triggers) or #definition.triggers == 0 then
                return nil, makeError("source_has_no_triggers", path, "트리거 사건 source에 선언된 trigger가 없습니다.")
            end
            local owner = definition.owner
            if kind == "perk" and owner == nil then owner = "player" end
            if kind == "environment" then
                if side ~= nil then
                    return nil, makeError("event_side_mismatch", path, "환경 트리거에는 side가 없어야 합니다.")
                end
            elseif owner ~= side then
                return nil, makeError("event_side_mismatch", path, "트리거 source owner와 side가 다릅니다.")
            end
            return definition, nil
        end

        local function triggerMatchesInput(kind, definition, inputEventType)
            if kind == "plan" then
                return definition.event == nil or definition.event == inputEventType
            end
            for _, spec in ipairs(definition.triggers) do
                if spec.event == inputEventType then
                    return true
                end
            end
            return false
        end

        local function replayTrigger(kind, definition, inputRecord, planSlot, planSide, planSlotIndex, path)
            local context, contextError = cloneData(inputRecord.context, path .. ".context", {})
            if contextError then return nil, nil, contextError end
            if kind == "plan" then
                if type(planSlot) ~= "table" or planSlot.occupied ~= true then
                    return nil, nil, makeError("missing_plan_context", path, "계획 트리거 재현에 필요한 슬롯이 없습니다.")
                end
                context.plan = {
                    cardId = planSlot.cardId,
                    cardInstanceId = planSlot.cardInstanceId,
                    side = planSide,
                    revealed = planSlot.revealed == true,
                    slotIndex = planSlotIndex,
                }
                if planSlot.remainingTurns ~= nil then context.plan.remainingTurns = planSlot.remainingTurns end
                if planSlot.remainingCharges ~= nil then context.plan.remainingCharges = planSlot.remainingCharges end
                if planSlot.effectChoiceId ~= nil then context.effectChoiceId = planSlot.effectChoiceId end
            end

            local specs = kind == "plan" and { definition } or definition.triggers
            local matched = {}
            for _, spec in ipairs(specs) do
                local condition, callError = callModule(
                    "effectEngine",
                    "evaluateTriggerCondition",
                    staticData,
                    spec,
                    context,
                    inputRecord.event
                )
                if callError or type(condition) ~= "table" or condition.ok ~= true then
                    return nil, nil, callError or makeError("trigger_replay_failed", path, "트리거 조건 재현에 실패했습니다.")
                end
                if condition.matched == true then matched[#matched + 1] = spec end
            end
            if #matched ~= 1 then
                return nil, nil, makeError(
                    #matched == 0 and "trigger_condition_mismatch" or "ambiguous_trigger_definition",
                    path,
                    #matched == 0 and "트리거 조건이 현재 입력과 일치하지 않습니다." or "같은 source에서 구분할 수 없는 트리거 정의가 둘 이상 일치합니다."
                )
            end
            local resolved, resolveError = callModule(
                "effectEngine",
                "evaluateTriggerResolve",
                staticData,
                matched[1],
                context,
                inputRecord.event
            )
            if resolveError or type(resolved) ~= "table" or resolved.ok ~= true or not isDenseArray(resolved.commands) then
                return nil, nil, resolveError or makeError("trigger_replay_failed", path, "트리거 명령 재현에 실패했습니다.")
            end
            return resolved.commands, context, nil
        end

        local function triggerCommandMatches(record, command, index)
            if type(record) ~= "table" or type(record.effect) ~= "table" or type(command) ~= "table" then
                return false
            end
            local effect = record.effect
            if record.index ~= index
                or record.cause ~= command.cause
                or effect.op ~= command.op
                or effect.target ~= command.target then
                return false
            end
            if command.op == "damage_resistance"
                or command.op == "recover_resistance"
                or command.op == "lose_stealth"
                or command.op == "recover_stealth" then
                return effect.amount == command.amount
            end
            if command.op == "draw_cards" then return effect.requested == command.amount end
            if command.op == "skip_actions" then return effect.scope == command.scope end
            if command.op == "add_mood_token" or command.op == "remove_mood_token" then
                return effect.mood == command.mood and effect.amount == command.amount
            end
            if command.op == "force_mood" then return effect.mood == command.mood end
            return false
        end

        local function collectExpectedTriggerBatches()
            local expected = {}
            local matchedByInput = {}
            local nextOrdinalByInput = {}
            local function addCandidate(
                inputKey,
                inputRecord,
                kind,
                sourceId,
                side,
                instanceId,
                declarationIndex,
                spec,
                planSlot,
                planSlotIndex
            )
                local context, contextError = cloneData(inputRecord.context, "$.triggerReplay.context", {})
                if contextError then return nil, contextError end
                if planSlot ~= nil then
                    context.plan = {
                        cardId = planSlot.cardId,
                        cardInstanceId = planSlot.cardInstanceId,
                        side = side,
                        revealed = planSlot.revealed == true,
                        slotIndex = planSlotIndex,
                    }
                    if planSlot.remainingTurns ~= nil then context.plan.remainingTurns = planSlot.remainingTurns end
                    if planSlot.remainingCharges ~= nil then context.plan.remainingCharges = planSlot.remainingCharges end
                    if planSlot.effectChoiceId ~= nil then context.effectChoiceId = planSlot.effectChoiceId end
                end
                local condition, callError = callModule(
                    "effectEngine",
                    "evaluateTriggerCondition",
                    staticData,
                    spec,
                    context,
                    inputRecord.event
                )
                if callError or type(condition) ~= "table" or condition.ok ~= true then
                    return nil, callError or makeError("trigger_replay_failed", "$.turnResolution.events", "트리거 조건 재현에 실패했습니다.")
                end
                if condition.matched == true then
                    local key = sourceBatchKey(inputKey, kind, sourceId, side, instanceId)
                    if expected[key] then
                        return nil, makeError("ambiguous_trigger_definition", "$.staticData", "같은 입력과 source에서 둘 이상의 트리거 정의가 일치합니다.")
                    end
                    expected[key] = true
                    local nextOrdinal = (nextOrdinalByInput[inputKey] or 0) + 1
                    nextOrdinalByInput[inputKey] = nextOrdinal
                    matchedByInput[inputKey] = matchedByInput[inputKey] or {
                        actingSide = inputRecord.event.side,
                        candidates = {},
                    }
                    local candidates = matchedByInput[inputKey].candidates
                    candidates[#candidates + 1] = {
                        key = key,
                        categoryOrder = CATEGORY_ORDER[kind],
                        side = side,
                        sourceId = sourceId,
                        declarationIndex = declarationIndex or 1,
                        ordinal = nextOrdinal,
                    }
                end
                return true, nil
            end

            for inputKey, inputRecord in pairs(triggerInputs) do
                for _, side in ipairs({ "player", "character" }) do
                    local slots = inputRecord.plans[side]
                    for slotIndex, slot in ipairs(slots) do
                        local card = staticData.cards[slot.cardId]
                        local plan = type(card) == "table"
                            and type(card.mechanismData) == "table"
                            and card.mechanismData.plan
                            or nil
                        if type(plan) ~= "table" then
                            return nil, makeError("invalid_plan_source", "$.staticData.cards.*.mechanismData.plan", "활성 계획 정의를 찾을 수 없습니다.")
                        end
                        local ok, candidateError = addCandidate(
                            inputKey,
                            inputRecord,
                            "plan",
                            slot.cardId,
                            side,
                            slot.cardInstanceId,
                            slotIndex,
                            plan,
                            slot,
                            slotIndex
                        )
                        if not ok then return nil, candidateError end
                    end
                end
                for _, traitId in ipairs(beforeState.character.traitIds) do
                    local trait = staticData.traits[traitId]
                    for declarationIndex, spec in ipairs(type(trait) == "table" and trait.triggers or {}) do
                        local ok, candidateError = addCandidate(
                            inputKey,
                            inputRecord,
                            "trait",
                            traitId,
                            trait.owner,
                            nil,
                            declarationIndex,
                            spec,
                            nil
                        )
                        if not ok then return nil, candidateError end
                    end
                end
                for _, perkId in ipairs(beforeState.player.perkIds) do
                    local perk = staticData.perks[perkId]
                    for declarationIndex, spec in ipairs(type(perk) == "table" and perk.triggers or {}) do
                        local ok, candidateError = addCandidate(
                            inputKey,
                            inputRecord,
                            "perk",
                            perkId,
                            perk.owner or "player",
                            nil,
                            declarationIndex,
                            spec,
                            nil
                        )
                        if not ok then return nil, candidateError end
                    end
                end
                local environment = staticData.environments[beforeState.environmentId]
                for declarationIndex, spec in ipairs(type(environment) == "table" and environment.triggers or {}) do
                    local ok, candidateError = addCandidate(
                        inputKey,
                        inputRecord,
                        "environment",
                        beforeState.environmentId,
                        nil,
                        nil,
                        declarationIndex,
                        spec,
                        nil
                    )
                    if not ok then return nil, candidateError end
                end
            end
            local orders = {}
            for inputKey, batch in pairs(matchedByInput) do
                table.sort(batch.candidates, function(left, right)
                    if left.categoryOrder ~= right.categoryOrder then
                        return left.categoryOrder < right.categoryOrder
                    end
                    local leftSide = sideRank(left.side, batch.actingSide)
                    local rightSide = sideRank(right.side, batch.actingSide)
                    if leftSide ~= rightSide then
                        return leftSide < rightSide
                    end
                    if left.sourceId ~= right.sourceId then
                        return left.sourceId < right.sourceId
                    end
                    if left.declarationIndex ~= right.declarationIndex then
                        return left.declarationIndex < right.declarationIndex
                    end
                    return left.ordinal < right.ordinal
                end)
                orders[inputKey] = {}
                for index, candidate in ipairs(batch.candidates) do
                    orders[inputKey][index] = candidate.key
                end
            end
            return expected, orders, nil
        end

        local function planKey(event)
            local source = event.source
            return tostring(event.side or source.side or "")
                .. "|" .. tostring(source.kind or "")
                .. "|" .. tostring(source.instanceId or "")
                .. "|" .. tostring(source.id or "")
        end

        local function publicEffectSource(event)
            local source = {
                kind = event.source.kind,
                id = event.source.id,
            }
            if event.source.side ~= nil then
                source.side = event.source.side
            end
            return source
        end

        local function emitEffect(effect, source)
            local publicEffect, cloneError = cloneData(effect, "$.publicEffect", {})
            if cloneError then
                return nil, cloneError
            end
            if RESOURCE_EFFECT_OPS[effect.op] == true
                and effect.changed == true
                and effect.amount > 0 then
                publicEffect.source = source
            end
            emit(publicResult, "effect_applied", publicEffect)
            if effect.changed == true or effect.blocked == true then
                local llmCopy, cloneError = cloneData(effect, "$.llmEffect", {})
                if cloneError then
                    return nil, cloneError
                end
                emit(llmEvent, "effect_applied", llmCopy)
            end
            return true, nil
        end

        local function narration(card, key, side, actionName, identityKnown, required)
            local payload = {
                actor = side,
                action = actionName,
                identityKnown = identityKnown == true,
            }
            if identityKnown ~= true then
                return payload, nil
            end
            local entry = type(card.narration) == "table" and card.narration[key] or nil
            if type(entry) ~= "table" or type(entry.actorAction) ~= "string" or entry.actorAction == "" then
                if required == false then
                    return payload, nil
                end
                return nil, makeError(
                    "missing_card_narration",
                    "$.staticData.cards.*.narration." .. key,
                    "공개된 카드 사건에 필요한 narration.actorAction이 없습니다."
                )
            end
            payload.actorAction = entry.actorAction
            if side == "character" and entry.actorThought ~= nil then
                if type(entry.actorThought) ~= "string" or entry.actorThought == "" then
                    return nil, makeError("invalid_card_narration", "$.staticData.cards.*.narration." .. key .. ".actorThought", "actorThought가 올바르지 않습니다.")
                end
                payload.actorThought = entry.actorThought
            end
            return payload, nil
        end

        local function emitPlan(side, actionName, cardId, identityKnown, remainingTurns, slotIndex, narrationKey, narrationRequired)
            local publicPayload = {
                side = side,
                action = actionName,
                identityKnown = identityKnown == true,
                slotIndex = slotIndex,
            }
            if not isInteger(slotIndex, 1) or slotIndex > MAX_PLAN_SLOTS then
                return nil, makeError("invalid_plan_slot_index", "$.plan.slotIndex", "계획 슬롯 순번이 올바르지 않습니다.")
            end
            local card = nil
            if identityKnown == true and cardId ~= nil then
                local lookupErrors = {}
                card = findCard(staticData, cardId, side, "$.plan.cardId", lookupErrors)
                if #lookupErrors > 0 then
                    return nil, lookupErrors[1]
                end
                publicPayload.cardId = cardId
            end
            if remainingTurns ~= nil then
                if not isInteger(remainingTurns, 0) then
                    return nil, makeError("invalid_plan_duration", "$.plan.remainingTurns", "계획 남은 턴이 올바르지 않습니다.")
                end
                publicPayload.remainingTurns = remainingTurns
            end
            emit(publicResult, "plan_changed", publicPayload)

            local llmPayload
            if narrationKey ~= nil and card ~= nil then
                local narrationError
                llmPayload, narrationError = narration(
                    card,
                    narrationKey,
                    side,
                    actionName,
                    true,
                    narrationRequired
                )
                if narrationError then
                    return nil, narrationError
                end
            else
                llmPayload = {
                    actor = side,
                    action = actionName,
                    identityKnown = identityKnown == true,
                }
            end
            emit(llmEvent, "plan", llmPayload)
            return true, nil
        end

        local function flushTriggerEffects(key)
            local records = pendingTriggerEffects[key] or {}
            pendingTriggerEffects[key] = nil
            for _, record in ipairs(records) do
                local ok, effectError = emitEffect(record.effect, record.source)
                if not ok then
                    return nil, effectError
                end
            end
            return true, nil
        end

        for index, event in ipairs(resolution.events) do
            local payload = event.payload
            local path = "$.turnResolution.events[" .. index .. "]"
            if event.phase == "turn_end"
                and latchedOutcome == nil
                and not (event.type == "outcome_latched" and payload.reasonCode == "turn_limit") then
                registerTriggerInput(
                    "turn_end",
                    "turn_end",
                    nil,
                    { type = "turn_end", turnNumber = resolution.turnNumber },
                    nil,
                    nil
                )
            elseif event.phase == "session_end" then
                registerTriggerInput(
                    "session_end",
                    "session_end",
                    nil,
                    {
                        type = "session_end",
                        status = resolution.afterState.status,
                        turnNumber = resolution.turnNumber,
                    },
                    nil,
                    nil
                )
            end
            if sawCleanup then
                local allowedAfterCleanup = event.type == "plan_changed"
                    or event.type == "trigger_resolved"
                    or event.type == "session_end"
                if resolution.afterState.status == "active"
                    or event.phase ~= "session_end"
                    or not allowedAfterCleanup then
                    return failure({ makeError("invalid_post_cleanup_event", path, "턴 정리 뒤에는 세션 종료 감사 사건만 올 수 있습니다.") })
                end
            elseif sawMoodEvaluation and event.type ~= "turn_cleanup" then
                return failure({ makeError("invalid_turn_tail_order", path, "무드 평가 바로 뒤에 턴 정리가 와야 합니다.") })
            elseif event.phase == "session_end" then
                return failure({ makeError("invalid_turn_tail_order", path, "세션 종료 사건은 턴 정리 뒤에만 올 수 있습니다.") })
            end
            if event.phase ~= "turn_start" and turnStartSettled ~= true then
                local expectedForcedMoodRequests = type(startReceipt) == "table"
                    and type(startReceipt.transient) == "table"
                    and startReceipt.transient.forcedMoodRequests
                    or {}
                if not dataEqual(trackers.player.slots, beforeState.player.planSlots)
                    or not dataEqual(trackers.character.slots, beforeState.character.planSlots)
                    or trackedStealth ~= beforeState.player.stealth
                    or trackedResistance ~= beforeState.character.resistance
                    or trackedMood ~= beforeState.character.mood
                    or not dataEqual(trackedMoodTokens, normalizedMoodTokens(beforeState.character.moodTokens))
                    or not dataEqual(trackedForcedMoodRequests, expectedForcedMoodRequests)
                    or trackedHandCount.player ~= countAuthorityHand("player")
                    or trackedHandCount.character ~= countAuthorityHand("character") then
                    return failure({ makeError("turn_start_replay_mismatch", path, "턴 시작 사건 재생 결과가 beforeState와 다릅니다.") })
                end
                for _, instanceId in ipairs(resolution.selectedCards.player) do
                    local instance = findBeforeInstance(instanceId)
                    if instance ~= nil and instance.zone == "hand" then
                        trackedHandCount.player = trackedHandCount.player - 1
                    end
                end
                turnStartSettled = true
            end
            if event.type == "turn_start" then
                local _, sourceError = requireSource(event, path, "system", "turn_initializer")
                if sourceError or event.phase ~= "turn_start" or event.side ~= nil
                    or sawTurnStart or index ~= 1
                    or not isInteger(payload.turnNumber, 1)
                    or payload.turnNumber ~= resolution.turnNumber then
                    return failure({ makeError("invalid_turn_start", path .. ".payload.turnNumber", "turn_start 턴 번호가 올바르지 않습니다.") })
                end
                sawTurnStart = true
                registerTriggerInput(
                    "turn_start",
                    "turn_start",
                    nil,
                    { type = "turn_start", turnNumber = payload.turnNumber },
                    nil,
                    event.eventId
                )
                emit(publicResult, "turn_started", { turnNumber = payload.turnNumber })
                emit(llmEvent, "turn_context", { turnNumber = payload.turnNumber })
            elseif event.type == "cards_drawn" then
                local _, sourceError = requireSource(event, path, "system", "card_zones")
                local _, sideError = requireSideSource(event, path, event.side)
                local expectedDraw = type(startReceipt.draws) == "table" and startReceipt.draws[event.side] or nil
                if sourceError or sideError or event.phase ~= "turn_start"
                    or sawStartDraw[event.side] == true
                    or type(expectedDraw) ~= "table"
                    or not isInteger(payload.requested, 0)
                    or not isInteger(payload.drawnCount, 0)
                    or payload.drawnCount > payload.requested
                    or payload.requested ~= expectedDraw.requested
                    or not isDenseArray(expectedDraw.drawnInstanceIds)
                    or payload.drawnCount ~= #expectedDraw.drawnInstanceIds then
                    return failure({ sourceError or sideError or makeError("invalid_draw_event", path .. ".payload", "드로우 사건 수치가 올바르지 않습니다.") })
                end
                sawStartDraw[event.side] = true
                trackedHandCount[event.side] = trackedHandCount[event.side] + payload.drawnCount
                if event.side == "player" then
                    emit(publicResult, "player_cards_drawn", {
                        requested = payload.requested,
                        drawnCount = payload.drawnCount,
                    })
                end
            elseif event.type == "character_intent_selected" then
                local _, sourceError = requireSource(event, path, "system", "character_selector")
                local _, sideError = requireSideSource(event, path, "character")
                if sourceError or sideError or event.phase ~= "turn_start"
                    or sawCharacterIntent
                    or type(payload.selected) ~= "boolean"
                    or payload.selected ~= expectedCharacterSelected then
                    return failure({ makeError("invalid_character_intent", path .. ".payload.selected", "캐릭터 의도 selected가 beforeState와 다릅니다.") })
                end
                sawCharacterIntent = true
                if payload.selected then
                    pendingCharacterIntent = true
                else
                    emit(publicResult, "character_intent", { selected = false })
                    emit(llmEvent, "character_intent", { selected = false })
                end
            elseif event.type == "action_tag_revealed" then
                local actionTag = payload.actionTag
                local tag = type(staticData.registry.actionTags) == "table" and staticData.registry.actionTags[actionTag] or nil
                local _, sourceError = requireSource(event, path, "system", "character_selector")
                local _, sideError = requireSideSource(event, path, "character")
                if sourceError or sideError or event.phase ~= "turn_start"
                    or pendingCharacterIntent ~= true
                    or not isAsciiId(actionTag)
                    or actionTag ~= expectedCharacterActionTag
                    or type(tag) ~= "table" or tag.owner ~= "character" then
                    return failure({ makeError("invalid_action_tag_reveal", path .. ".payload.actionTag", "캐릭터 공개 행동 태그가 beforeState·정적 레지스트리와 다릅니다.") })
                end
                emit(publicResult, "character_intent", { selected = true, actionTag = actionTag })
                emit(llmEvent, "character_intent", { selected = true, actionTag = actionTag })
                local selectedInstanceId = expectedCharacterIntent.cardInstanceIds[#expectedCharacterIntent.cardInstanceIds]
                local selectedInstance = findBeforeInstance(selectedInstanceId)
                local selectedCard = selectedInstance and staticData.cards[selectedInstance.cardId] or nil
                if type(selectedCard) ~= "table" then
                    return failure({ makeError("character_intent_card_missing", path, "캐릭터 의도 카드를 찾을 수 없습니다.") })
                end
                registerTriggerInput(
                    "action_tag_revealed",
                    "turn_start",
                    nil,
                    {
                        type = "action_tag_revealed",
                        side = "character",
                        cardId = selectedCard.id,
                        cardInstanceId = selectedInstanceId,
                        actionTag = actionTag,
                    },
                    {
                        id = selectedCard.id,
                        instanceId = selectedInstanceId,
                        owner = "character",
                        actionTag = actionTag,
                    },
                    event.eventId
                )
                pendingCharacterIntent = false
            elseif event.type == "effect_applied" then
                local allowedEffectSources = {
                    card = true,
                    plan = true,
                    trait = true,
                    perk = true,
                    environment = true,
                }
                if allowedEffectSources[event.source.kind] ~= true then
                    return failure({ makeError("invalid_effect_source", path .. ".source.kind", "효과 source 종류가 올바르지 않습니다.") })
                end
                if event.source.kind == "card" or event.source.kind == "plan" then
                    local _, sideError = requireSideSource(event, path, event.source.side)
                    if sideError then
                        return failure({ sideError })
                    end
                end
                local triggerKinds = { plan = true, trait = true, perk = true, environment = true }
                if triggerKinds[event.source.kind] then
                    local triggerDefinition, triggerError = findTriggerDefinition(
                        event.source.kind,
                        event.source.id,
                        event.source.side,
                        path .. ".source.id"
                    )
                    if triggerError then
                        return failure({ triggerError })
                    end
                    if event.source.kind == "environment" then
                        if event.side ~= nil or event.source.side ~= nil then
                            return failure({ makeError("event_side_mismatch", path, "환경 트리거 효과에는 side가 없어야 합니다.") })
                        end
                    else
                        local _, sideError = requireSideSource(event, path, event.source.side)
                        if sideError then
                            return failure({ sideError })
                        end
                    end
                    if triggerPhases[event.phase] ~= true
                        or type(event.cause) ~= "table"
                        or event.cause.kind ~= event.source.kind .. "_trigger" then
                        return failure({ makeError("effect_cause_mismatch", path .. ".cause", "트리거 효과 cause가 source와 다릅니다.") })
                    end
                elseif event.source.kind == "card" then
                    local lookupErrors = {}
                    findCard(staticData, event.source.id, event.source.side, path .. ".source.id", lookupErrors)
                    if #lookupErrors > 0 then
                        return failure(lookupErrors)
                    end
                    if event.phase ~= event.source.side .. "_card" then
                        return failure({ makeError("effect_phase_mismatch", path .. ".phase", "카드 효과 phase가 소유자와 다릅니다.") })
                    end
                end
                if payload.op == "pay_stealth_cost" then
                    if event.source.kind ~= "card" or event.side ~= "player" or event.phase ~= "player_card"
                        or type(event.cause) ~= "table" or event.cause.kind ~= "card_resolution"
                        or payload.index ~= nil or payload.cause ~= nil then
                        return failure({ makeError("invalid_cost_source", path, "은폐 비용 사건의 source 또는 phase가 올바르지 않습니다.") })
                    end
                elseif event.source.kind == "card"
                    and (type(event.cause) ~= "table"
                        or (event.cause.kind ~= "card_base"
                            and event.cause.kind ~= "card_effect"
                            and event.cause.kind ~= "mood_effect")) then
                    return failure({ makeError("effect_cause_mismatch", path .. ".cause", "카드 효과 cause가 올바르지 않습니다.") })
                elseif not isInteger(payload.index, 1) or type(payload.cause) ~= "string" or payload.cause == "" then
                    return failure({ makeError("invalid_effect_audit", path .. ".payload", "효과 index 또는 cause가 올바르지 않습니다.") })
                end
                local effect, effectError = copySafeEffect(
                    payload,
                    path .. ".payload",
                    staticData.registry.moods
                )
                if effectError then
                    return failure({ effectError })
                end
                if payload.op == "add_mood_token" or payload.op == "remove_mood_token" or payload.op == "force_mood" then
                    local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
                    if type(moods) ~= "table"
                        or type(moods[payload.mood]) ~= "table" then
                        return failure({ makeError("unknown_effect_mood", path .. ".payload", "무드 효과가 등록되지 않은 무드를 참조합니다.") })
                    end
                end
                if payload.op == "pay_stealth_cost" or payload.op == "lose_stealth" or payload.op == "recover_stealth" then
                    if effect.before ~= trackedStealth then
                        return failure({ makeError("effect_state_mismatch", path .. ".payload.before", "은폐 효과 before가 앞선 사건 결과와 다릅니다.") })
                    end
                    trackedStealth = effect.after
                elseif payload.op == "damage_resistance" or payload.op == "recover_resistance" then
                    if effect.before ~= trackedResistance then
                        return failure({ makeError("effect_state_mismatch", path .. ".payload.before", "저항 효과 before가 앞선 사건 결과와 다릅니다.") })
                    end
                    trackedResistance = effect.after
                elseif payload.op == "draw_cards" then
                    trackedHandCount[effect.target] = trackedHandCount[effect.target] + effect.drawnCount
                elseif payload.op == "add_mood_token" or payload.op == "remove_mood_token" then
                    if effect.before ~= trackedMoodTokens[effect.mood] then
                        return failure({ makeError("effect_state_mismatch", path .. ".payload.before", "무드 토큰 효과 before가 앞선 토큰 수와 다릅니다.") })
                    end
                    trackedMoodTokens[effect.mood] = effect.after
                elseif payload.op == "force_mood" then
                    if effect.before ~= #trackedForcedMoodRequests then
                        return failure({ makeError("effect_state_mismatch", path .. ".payload.before", "무드 강제 변경 요청 순서가 앞선 요청 수와 다릅니다.") })
                    end
                    trackedForcedMoodRequests[#trackedForcedMoodRequests + 1] = {
                        mood = effect.mood,
                        cause = payload.cause,
                    }
                end
                if payload.op == "pay_stealth_cost" then
                    if event.resolutionId == nil then
                        return failure({ makeError("missing_resolution_id", path .. ".resolutionId", "은폐 비용 사건에는 resolutionId가 필요합니다.") })
                    end
                    if pendingCosts[event.resolutionId] ~= nil then
                        return failure({ makeError("duplicate_card_cost", path .. ".resolutionId", "같은 카드 해결에 은폐 비용 사건이 중복되었습니다.") })
                    end
                    pendingCosts[event.resolutionId] = {
                        effect = effect,
                        source = publicEffectSource(event),
                        cardId = event.source.id,
                        instanceId = event.source.instanceId,
                    }
                elseif triggerKinds[event.source.kind] then
                    local key = planKey(event)
                    pendingTriggerEffects[key] = pendingTriggerEffects[key] or {}
                    pendingTriggerEffects[key][#pendingTriggerEffects[key] + 1] = {
                        effect = effect,
                        source = publicEffectSource(event),
                        index = payload.index,
                        cause = payload.cause,
                    }
                    if event.source.kind == "plan" and pendingPlanSlots[key] == nil then
                        local pendingSlot, pendingSlotIndex = findPlanSlot(
                            trackers[event.source.side].slots,
                            event.source.instanceId
                        )
                        pendingPlanSlots[key] = {
                            slot = pendingSlot,
                            slotIndex = pendingSlotIndex,
                        }
                    end
                else
                    local ok, emitError = emitEffect(effect, publicEffectSource(event))
                    if not ok then
                        return failure({ emitError })
                    end
                end
            elseif event.type == "card_declared" then
                local side = event.side
                if side ~= "player" and side ~= "character" then
                    return failure({ makeError("invalid_card_side", path .. ".side", "card_declared side가 올바르지 않습니다.") })
                end
                local lookupErrors = {}
                local card = findCard(staticData, payload.cardId or event.source.id, side, path .. ".payload.cardId", lookupErrors)
                if #lookupErrors > 0 then
                    return failure(lookupErrors)
                end
                if event.source.kind ~= "card"
                    or event.phase ~= side .. "_card"
                    or event.source.id ~= card.id
                    or event.source.side ~= side
                    or payload.cardId ~= card.id
                    or not isRuntimeId(payload.instanceId)
                    or payload.instanceId ~= event.source.instanceId
                    or not isFinite(payload.finalStealthCost)
                    or payload.finalStealthCost < 0
                    or not isRuntimeId(event.resolutionId)
                    or pendingDeclarations[event.resolutionId] ~= nil then
                    return failure({ makeError("card_event_mismatch", path, "card_declared source와 payload 카드가 다릅니다.") })
                end
                if side == "character" and payload.finalStealthCost ~= 0 then
                    return failure({ makeError("invalid_character_cost", path .. ".payload.finalStealthCost", "캐릭터 카드 비용은 0이어야 합니다.") })
                end
                local effectChoice = findEffectChoice(card, payload.effectChoiceId)
                if side == "player" and type(card.effectChoices) == "table" and effectChoice == nil then
                    return failure({ makeError("missing_effect_choice", path .. ".payload.effectChoiceId", "선택형 플레이어 카드에 유효한 효과 선택값이 없습니다.") })
                elseif (side ~= "player" or type(card.effectChoices) ~= "table") and payload.effectChoiceId ~= nil then
                    return failure({ makeError("unexpected_effect_choice", path .. ".payload.effectChoiceId", "효과 선택지가 없는 카드 선언에 선택값이 있습니다.") })
                end
                local publicPayload = {
                    side = side,
                    actionTag = card.actionTag,
                    stealthCost = payload.finalStealthCost,
                }
                if side == "player" then
                    publicPayload.cardId = card.id
                    if effectChoice ~= nil then publicPayload.effectChoiceId = effectChoice.id end
                end
                emit(publicResult, "card_declared", publicPayload)

                if not hasMechanism(card, "plan") or (effectChoice ~= nil and effectChoice.placesPlan == false) then
                    local llmPayload, narrationError = narration(card, "play", side, "played", true)
                    if narrationError then
                        return failure({ narrationError })
                    end
                    llmPayload.actionTag = card.actionTag
                    emit(llmEvent, "action", llmPayload)
                end

                local costReceipt = pendingCosts[event.resolutionId]
                if side == "player" and costReceipt == nil then
                    return failure({ makeError("missing_card_cost", path, "플레이어 card_declared보다 앞선 은폐 비용 사건이 없습니다.") })
                end
                if side == "character" and costReceipt ~= nil then
                    return failure({ makeError("unexpected_card_cost", path, "캐릭터 카드에는 은폐 비용 사건이 있을 수 없습니다.") })
                end
                if costReceipt ~= nil then
                    if costReceipt.cardId ~= card.id
                        or costReceipt.instanceId ~= payload.instanceId
                        or costReceipt.effect.amount ~= payload.finalStealthCost then
                        return failure({ makeError("card_cost_mismatch", path, "은폐 비용 사건이 선언 카드와 일치하지 않습니다.") })
                    end
                    pendingCosts[event.resolutionId] = nil
                    local ok, emitError = emitEffect(costReceipt.effect, costReceipt.source)
                    if not ok then
                        return failure({ emitError })
                    end
                end
                pendingDeclarations[event.resolutionId] = {
                    side = side,
                    cardId = card.id,
                    instanceId = payload.instanceId,
                    effectChoiceId = payload.effectChoiceId,
                }
                if side == "character" then
                    trackedHandCount.character = trackedHandCount.character - 1
                    if trackedHandCount.character < 0 then
                        return failure({ makeError("hand_count_mismatch", path, "캐릭터 선언 전 손패 수가 올바르지 않습니다.") })
                    end
                end
                registerTriggerInput(
                    "card_declared",
                    event.phase,
                    event.resolutionId,
                    {
                        type = "card_declared",
                        side = side,
                        cardId = card.id,
                        cardInstanceId = payload.instanceId,
                        actionTag = card.actionTag,
                        resolutionId = event.resolutionId,
                        effectChoiceId = payload.effectChoiceId,
                    },
                    {
                        id = card.id,
                        instanceId = payload.instanceId,
                        owner = side,
                        actionTag = card.actionTag,
                        effectChoiceId = payload.effectChoiceId,
                    },
                    event.eventId
                )
            elseif event.type == "card_resolved" then
                local cardId = payload.cardId or event.source.id
                local lookupErrors = {}
                local card = findCard(staticData, cardId, event.side, path .. ".payload.cardId", lookupErrors)
                local declaration = event.resolutionId and pendingDeclarations[event.resolutionId] or nil
                if #lookupErrors > 0
                    or event.source.kind ~= "card"
                    or event.phase ~= tostring(event.side) .. "_card"
                    or event.source.id ~= cardId
                    or event.source.side ~= event.side
                    or not isRuntimeId(payload.instanceId)
                    or payload.instanceId ~= event.source.instanceId
                    or not isFinite(payload.finalResistanceDamage)
                    or payload.finalResistanceDamage < 0
                    or declaration == nil
                    or declaration.side ~= event.side
                    or declaration.cardId ~= cardId
                    or declaration.instanceId ~= payload.instanceId then
                    return failure(#lookupErrors > 0 and lookupErrors or { makeError("card_event_mismatch", path, "card_resolved source와 payload 카드가 다릅니다.") })
                end
                pendingDeclarations[event.resolutionId] = nil
                registerTriggerInput(
                    "card_resolved",
                    event.phase,
                    event.resolutionId,
                    {
                        type = "card_resolved",
                        side = event.side,
                        cardId = card.id,
                        cardInstanceId = payload.instanceId,
                        actionTag = card.actionTag,
                        resolutionId = event.resolutionId,
                        effectChoiceId = declaration.effectChoiceId,
                    },
                    {
                        id = card.id,
                        instanceId = payload.instanceId,
                        owner = event.side,
                        actionTag = card.actionTag,
                        effectChoiceId = declaration.effectChoiceId,
                    },
                    event.eventId
                )
            elseif event.type == "trigger_suppressed" then
                local side = event.side or event.source.side
                local lookupErrors = {}
                local planCard = findCard(staticData, event.source.id, side, path .. ".source.id", lookupErrors)
                local planDefinition = type(planCard) == "table"
                    and type(planCard.mechanismData) == "table"
                    and planCard.mechanismData.plan
                    or nil
                local trackedSlots = trackers[side] and trackers[side].slots or nil
                local trackedSlot, trackedSlotIndex = findPlanSlot(trackedSlots, event.source.instanceId)
                local expectedHidden = type(trackedSlot) == "table"
                    and trackedSlot.occupied == true
                    and trackedSlot.revealed ~= true
                local inputRecord = nil
                local inputKeyValue = nil
                if isAsciiId(payload.inputEventType) then
                    inputKeyValue = triggerInputKey(
                        event.resolutionId,
                        event.phase,
                        payload.inputEventType
                    )
                    inputRecord = triggerInputs[inputKeyValue]
                end
                local inputPlanSlot, inputPlanSlotIndex = nil, nil
                if inputRecord ~= nil and type(inputRecord.plans) == "table" then
                    inputPlanSlot, inputPlanSlotIndex = findPlanSlot(
                        inputRecord.plans[side],
                        event.source.instanceId
                    )
                end
                local _, sideError = requireSideSource(event, path, side)
                if #lookupErrors > 0
                    or sideError
                    or event.source.kind ~= "plan"
                    or not hasMechanism(planCard, "plan")
                    or type(planDefinition) ~= "table"
                    or event.resolutionId == nil
                    or (event.phase ~= "player_card" and event.phase ~= "character_card")
                    or type(event.cause) ~= "table"
                    or event.cause.kind ~= "card_resolution"
                    or inputRecord == nil
                    or (event.cause.eventId ~= nil and event.cause.eventId ~= inputRecord.eventId)
                    or not isAsciiId(payload.inputEventType)
                    or not triggerMatchesInput("plan", planDefinition, payload.inputEventType)
                    or not isAsciiId(payload.reasonCode)
                    or payload.reasonCode ~= "insight"
                    or type(payload.hidden) ~= "boolean"
                    or type(trackedSlot) ~= "table"
                    or trackedSlot.occupied ~= true
                    or trackedSlot.cardId ~= event.source.id
                    or inputPlanSlot == nil
                    or payload.hidden ~= expectedHidden then
                    return failure(#lookupErrors > 0 and lookupErrors or {
                        sideError or makeError("invalid_trigger_suppression", path, "억제 사건의 계획 source 또는 payload가 올바르지 않습니다."),
                    })
                end
                local suppressionContext, suppressionContextError = cloneData(
                    inputRecord.context,
                    path .. ".context",
                    {}
                )
                if suppressionContextError then return failure({ suppressionContextError }) end
                suppressionContext.plan = {
                    cardId = inputPlanSlot.cardId,
                    cardInstanceId = inputPlanSlot.cardInstanceId,
                    side = side,
                    revealed = inputPlanSlot.revealed == true,
                    slotIndex = inputPlanSlotIndex,
                }
                if inputPlanSlot.remainingTurns ~= nil then
                    suppressionContext.plan.remainingTurns = inputPlanSlot.remainingTurns
                end
                if inputPlanSlot.remainingCharges ~= nil then
                    suppressionContext.plan.remainingCharges = inputPlanSlot.remainingCharges
                end
                if inputPlanSlot.effectChoiceId ~= nil then
                    suppressionContext.effectChoiceId = inputPlanSlot.effectChoiceId
                end
                local suppressionCondition, suppressionCallError = callModule(
                    "effectEngine",
                    "evaluateTriggerCondition",
                    staticData,
                    planDefinition,
                    suppressionContext,
                    inputRecord.event
                )
                if suppressionCallError
                    or type(suppressionCondition) ~= "table"
                    or suppressionCondition.ok ~= true
                    or suppressionCondition.matched ~= true then
                    return failure({ suppressionCallError
                        or makeError("trigger_condition_mismatch", path, "억제된 계획 조건이 현재 입력과 일치하지 않습니다.") })
                end
                local suppressionBatchKey = triggerBatchKey(inputKeyValue, event)
                if seenTriggerBatches[suppressionBatchKey] then
                    return failure({ makeError("duplicate_trigger_batch", path, "같은 입력과 source의 트리거 batch가 중복되었습니다.") })
                end
                seenTriggerBatches[suppressionBatchKey] = true
                seenTriggerOrder[inputKeyValue] = seenTriggerOrder[inputKeyValue] or {}
                seenTriggerOrder[inputKeyValue][#seenTriggerOrder[inputKeyValue] + 1] = suppressionBatchKey
                if payload.hidden == true then
                    -- A hidden suppression leaves no public or LLM trace and does not reveal the plan.
                elseif payload.hidden == false then
                    local known = planKnown(side, trackedSlot)
                    if known ~= true
                        or trackedSlot.cardId ~= event.source.id then
                        return failure({ makeError("suppression_visibility_mismatch", path, "공개 억제 계획의 알려진 정체가 source와 다릅니다.") })
                    end
                    local publicPayload = {
                        side = side,
                        reasonCode = payload.reasonCode,
                        identityKnown = known,
                        slotIndex = trackedSlotIndex,
                    }
                    if known then
                        publicPayload.cardId = event.source.id
                    end
                    emit(publicResult, "trigger_suppressed", publicPayload)
                    emit(llmEvent, "plan_suppressed", {
                        actor = side,
                        reasonCode = payload.reasonCode,
                        identityKnown = known,
                    })
                end
            elseif event.type == "trigger_resolved" then
                local allowedTriggerSources = { plan = true, trait = true, perk = true, environment = true }
                local definition, definitionError = findTriggerDefinition(
                    event.source.kind,
                    event.source.id,
                    event.source.side,
                    path .. ".source.id"
                )
                local expectedCause = event.resolutionId ~= nil and "card_resolution" or "turn_event"
                local inputRecord = nil
                local inputKeyValue = nil
                if isAsciiId(payload.inputEventType) then
                    inputKeyValue = triggerInputKey(
                        event.resolutionId,
                        event.phase,
                        payload.inputEventType
                    )
                    inputRecord = triggerInputs[inputKeyValue]
                end
                if allowedTriggerSources[event.source.kind] ~= true
                    or definitionError
                    or triggerPhases[event.phase] ~= true
                    or not isAsciiId(payload.inputEventType)
                    or not isInteger(payload.commandCount, 0)
                    or inputRecord == nil
                    or not triggerMatchesInput(event.source.kind, definition, payload.inputEventType)
                    or type(event.cause) ~= "table"
                    or event.cause.kind ~= expectedCause
                    or (event.cause.eventId ~= nil and event.cause.eventId ~= inputRecord.eventId) then
                    return failure({ definitionError or makeError("invalid_trigger_resolution", path, "트리거 해결 감사 사건이 올바르지 않습니다.") })
                end
                if sawCleanup and (payload.inputEventType ~= "session_end"
                    or payload.commandCount ~= 0
                    or event.resolutionId ~= nil) then
                    return failure({ makeError("invalid_session_end_trigger", path, "세션 종료 트리거는 게임플레이 명령을 가질 수 없습니다.") })
                end
                local resolvedBatchKey = triggerBatchKey(inputKeyValue, event)
                if seenTriggerBatches[resolvedBatchKey] then
                    return failure({ makeError("duplicate_trigger_batch", path, "같은 입력과 source의 트리거 batch가 중복되었습니다.") })
                end
                if event.source.kind == "environment" then
                    if event.side ~= nil or event.source.side ~= nil then
                        return failure({ makeError("event_side_mismatch", path, "환경 트리거에는 side가 없어야 합니다.") })
                    end
                else
                    local _, sideError = requireSideSource(event, path, event.source.side)
                    if sideError then
                        return failure({ sideError })
                    end
                end
                local key = planKey(event)
                local records = pendingTriggerEffects[key] or {}
                local pendingPlan = pendingPlanSlots[key]
                local replayPlanSlot, replayPlanSlotIndex = nil, nil
                if event.source.kind == "plan" then
                    replayPlanSlot, replayPlanSlotIndex = findPlanSlot(
                        inputRecord.plans[event.source.side],
                        event.source.instanceId
                    )
                    if type(pendingPlan) ~= "table"
                        or type(pendingPlan.slot) ~= "table"
                        or pendingPlan.slot.cardInstanceId ~= event.source.instanceId then
                        return failure({ makeError("missing_plan_context", path, "계획 트리거 재현에 필요한 인스턴스 문맥이 없습니다.") })
                    end
                end
                local commands, _, replayError = replayTrigger(
                    event.source.kind,
                    definition,
                    inputRecord,
                    replayPlanSlot,
                    event.source.side,
                    replayPlanSlotIndex,
                    path
                )
                if replayError then return failure({ replayError }) end
                if #records ~= payload.commandCount or #commands ~= payload.commandCount then
                    return failure({ makeError("trigger_command_count_mismatch", path .. ".payload.commandCount", "트리거 명령 수와 효과 사건 수가 다릅니다.") })
                end
                for commandIndex, command in ipairs(commands) do
                    if not triggerCommandMatches(records[commandIndex], command, commandIndex) then
                        return failure({ makeError("trigger_command_mismatch", path, "트리거 효과가 정적 resolve 명령과 다릅니다.") })
                    end
                end
                if event.source.kind == "plan" and pendingPlanMeanings[key] ~= true then
                    return failure({ makeError("missing_plan_meaning", path, "계획 효과보다 앞선 계획 발동 의미 사건이 없습니다.") })
                end
                local flushed, flushError = flushTriggerEffects(key)
                if not flushed then
                    return failure({ flushError })
                end
                pendingPlanMeanings[key] = nil
                pendingPlanSlots[key] = nil
                seenTriggerBatches[resolvedBatchKey] = true
                seenTriggerOrder[inputKeyValue] = seenTriggerOrder[inputKeyValue] or {}
                seenTriggerOrder[inputKeyValue][#seenTriggerOrder[inputKeyValue] + 1] = resolvedBatchKey
                -- Internal audit event; intentionally omitted.
            elseif event.type == "plan_changed" then
                local side = event.side or event.source.side
                local _, sideError = requireSideSource(event, path, side)
                if sideError then
                    return failure({ makeError("invalid_plan_side", path .. ".side", "계획 사건 side가 올바르지 않습니다.") })
                end
                local beforeSlots = payload.before
                local afterSlots = payload.after
                local capacity = beforeState[side].planCapacity
                local _, beforeSlotError = validatePlanSlotsSnapshot(
                    beforeSlots,
                    path .. ".payload.before",
                    capacity
                )
                local _, afterSlotError = validatePlanSlotsSnapshot(
                    afterSlots,
                    path .. ".payload.after",
                    capacity
                )
                local _, movedIdsError = validateIdArray(payload.movedInstanceIds, path .. ".payload.movedInstanceIds")
                if beforeSlotError or afterSlotError or movedIdsError then
                    return failure({ beforeSlotError or afterSlotError or movedIdsError })
                end
                if not dataEqual(beforeSlots, trackers[side].slots) then
                    return failure({ makeError("plan_before_mismatch", path .. ".payload.before", "계획 사건 before가 앞선 계획 상태와 다릅니다.") })
                end
                local cardId = event.source.id
                if payload.action == "triggered" then
                    local lookupErrors = {}
                    local card = findCard(staticData, cardId, side, path .. ".source.id", lookupErrors)
                    local beforeSlot, beforeIndex = findPlanSlot(beforeSlots, event.source.instanceId)
                    local expectedAfter, expectedAfterError = cloneData(beforeSlots, path .. ".payload.before", {})
                    if expectedAfterError then return failure({ expectedAfterError }) end
                    local expectedSlot = beforeIndex and expectedAfter[beforeIndex] or nil
                    if expectedSlot ~= nil then
                        expectedSlot.revealed = true
                        if expectedSlot.remainingCharges ~= nil then
                            expectedSlot.remainingCharges = expectedSlot.remainingCharges - 1
                            if expectedSlot.remainingCharges == 0 then
                                table.remove(expectedAfter, beforeIndex)
                            end
                        end
                    end
                    local afterSlot, afterIndex = findPlanSlot(afterSlots, event.source.instanceId)
                    local discarded = afterSlot == nil
                    if #lookupErrors > 0
                        or event.source.kind ~= "plan"
                        or not hasMechanism(card, "plan")
                        or triggerPhases[event.phase] ~= true
                        or type(event.cause) ~= "table"
                        or event.cause.kind ~= (event.resolutionId ~= nil and "card_resolution" or "turn_event")
                        or payload.instanceId ~= nil
                        or type(payload.discarded) ~= "boolean"
                        or payload.planSpec ~= nil
                        or beforeSlot == nil
                        or beforeSlot.cardId ~= cardId
                        or not dataEqual(afterSlots, expectedAfter)
                        or (afterSlot ~= nil
                            and (afterSlot.cardId ~= cardId
                                or afterSlot.revealed ~= true
                                or afterIndex ~= beforeIndex))
                        or (payload.discarded == true
                            and not arraysEqual(payload.movedInstanceIds, { beforeSlot.cardInstanceId }))
                        or (payload.discarded == false and #payload.movedInstanceIds ~= 0)
                        or payload.discarded ~= discarded then
                        return failure(#lookupErrors > 0 and lookupErrors or {
                            makeError("invalid_plan_trigger", path, "계획 발동 사건이 source·슬롯과 일치하지 않습니다."),
                        })
                    end
                    local key = planKey(event)
                    if pendingPlanSlots[key] == nil then
                        pendingPlanSlots[key] = { slot = beforeSlot, slotIndex = beforeIndex }
                    end
                    local remainingTurns = afterSlot and afterSlot.remainingTurns or nil
                    local ok, planError = emitPlan(
                        side,
                        "triggered",
                        card.id,
                        true,
                        remainingTurns,
                        beforeIndex,
                        "planTriggered",
                        true
                    )
                    if not ok then
                        return failure({ planError })
                    end
                    trackers[side].slots = afterSlots
                    if postCleanupSnapshot ~= nil then
                        postCleanupSnapshot[side].planSlots = afterSlots
                        if payload.discarded == true then
                            postCleanupSnapshot[side].discard[#postCleanupSnapshot[side].discard + 1] = beforeSlot.cardInstanceId
                        end
                    end
                    if pendingPlanMeanings[key] ~= nil then
                        return failure({ makeError("duplicate_plan_meaning", path, "같은 계획 발동 의미 사건이 중복되었습니다.") })
                    end
                    pendingPlanMeanings[key] = true
                elseif payload.action == "placed" then
                    local lookupErrors = {}
                    local placedCard = findCard(staticData, cardId, side, path .. ".source.id", lookupErrors)
                    local placedPlanData = type(placedCard) == "table"
                        and type(placedCard.mechanismData) == "table"
                        and placedCard.mechanismData.plan
                        or nil
                    local expectedIncludesPlacementTurn = type(placedPlanData) == "table"
                        and placedPlanData.durationIncludesPlacementTurn == true
                    local _, planSpecError = validatePlanSpecSnapshot(payload.planSpec, path .. ".payload.planSpec")
                    local planSpec = type(payload.planSpec) == "table" and payload.planSpec or {}
                    local expectedPlanSpec = nil
                    if type(placedPlanData) == "table" then
                        expectedPlanSpec = {
                            revealed = false,
                        }
                        if planSpec.effectChoiceId ~= nil then
                            local planChoice = findEffectChoice(placedCard, planSpec.effectChoiceId)
                            if planChoice == nil or planChoice.placesPlan == false then
                                planSpecError = planSpecError or makeError(
                                    "invalid_plan_effect_choice",
                                    path .. ".payload.planSpec.effectChoiceId",
                                    "계획 배치에 유효하지 않은 효과 선택값입니다."
                                )
                            else
                                expectedPlanSpec.effectChoiceId = planSpec.effectChoiceId
                            end
                        elseif type(placedCard.effectChoices) == "table" then
                            planSpecError = planSpecError or makeError(
                                "missing_plan_effect_choice",
                                path .. ".payload.planSpec.effectChoiceId",
                                "선택형 계획 배치에 효과 선택값이 없습니다."
                            )
                        end
                        if placedPlanData.durationTurns ~= nil then
                            expectedPlanSpec.durationTurns = placedPlanData.durationTurns
                        end
                        if placedPlanData.durationIncludesPlacementTurn ~= nil then
                            expectedPlanSpec.durationIncludesPlacementTurn =
                                placedPlanData.durationIncludesPlacementTurn
                        end
                        if placedPlanData.charges ~= nil then
                            expectedPlanSpec.charges = placedPlanData.charges
                        end
                    end
                    local planSpecStaticError = expectedPlanSpec ~= nil
                        and not dataEqual(planSpec, expectedPlanSpec)
                        and makeError(
                            "plan_spec_static_mismatch",
                            path .. ".payload.planSpec",
                            "계획 배치 명세가 정적 카드 계획 정의와 다릅니다."
                        )
                        or nil
                    local capacity = type(beforeState[side]) == "table" and beforeState[side].planCapacity or nil
                    local expectedAfter, expectedAfterError = cloneData(beforeSlots, path .. ".payload.before", {})
                    if expectedAfterError then return failure({ expectedAfterError }) end
                    local replacedSlot = nil
                    if isInteger(capacity, 1) and #expectedAfter >= capacity then
                        replacedSlot = table.remove(expectedAfter, 1)
                    end
                    local expectedPlacedSlot = {
                        occupied = true,
                        cardInstanceId = payload.instanceId,
                        cardId = cardId,
                        placedTurn = resolution.turnNumber,
                        durationIncludesPlacementTurn = planSpec.durationIncludesPlacementTurn == true,
                        revealed = planSpec.revealed,
                    }
                    if planSpec.durationTurns ~= nil then
                        expectedPlacedSlot.remainingTurns = planSpec.durationTurns
                    end
                    if planSpec.charges ~= nil then
                        expectedPlacedSlot.remainingCharges = planSpec.charges
                    end
                    if planSpec.effectChoiceId ~= nil then
                        expectedPlacedSlot.effectChoiceId = planSpec.effectChoiceId
                    end
                    expectedAfter[#expectedAfter + 1] = expectedPlacedSlot
                    local expectedMovedIds = replacedSlot ~= nil
                        and { replacedSlot.cardInstanceId, payload.instanceId }
                        or { payload.instanceId }
                    local afterSlot, afterIndex = findPlanSlot(afterSlots, payload.instanceId)
                    if #lookupErrors > 0
                        or planSpecError
                        or planSpecStaticError
                        or event.source.kind ~= "card"
                        or not hasMechanism(placedCard, "plan")
                        or event.phase ~= side .. "_card"
                        or event.resolutionId == nil
                        or type(event.cause) ~= "table"
                        or event.cause.kind ~= "card_resolution"
                        or not isRuntimeId(payload.instanceId)
                        or payload.instanceId ~= event.source.instanceId
                        or payload.discarded ~= nil
                        or not isInteger(capacity, 1)
                        or #beforeSlots > capacity
                        or not dataEqual(afterSlots, expectedAfter)
                        or afterSlot == nil
                        or afterIndex ~= #afterSlots
                        or (planSpec.durationIncludesPlacementTurn == true)
                            ~= expectedIncludesPlacementTurn
                        or (side == "character" and planSpec.revealed ~= false)
                        or not arraysEqual(payload.movedInstanceIds, expectedMovedIds) then
                        return failure(#lookupErrors > 0 and lookupErrors or {
                            planSpecError
                                or planSpecStaticError
                                or makeError("invalid_plan_placement", path, "계획 배치 사건이 카드·슬롯과 일치하지 않습니다."),
                        })
                    end
                    if replacedSlot ~= nil then
                        local previousKnown = planKnown(side, replacedSlot)
                        local replaced, replaceError = emitPlan(
                            side,
                            "replaced",
                            replacedSlot.cardId,
                            previousKnown,
                            nil,
                            1,
                            previousKnown and "planExpired" or nil,
                            false
                        )
                        if not replaced then
                            return failure({ replaceError })
                        end
                    end
                    local newCardId = afterSlot.cardId
                    local newKnown = planKnown(side, afterSlot)
                    local remainingTurns = afterSlot.remainingTurns
                    local placed, placeError = emitPlan(
                        side,
                        "placed",
                        newCardId,
                        newKnown,
                        remainingTurns,
                        afterIndex,
                        newKnown and "planPlaced" or nil,
                        true
                    )
                    if not placed then
                        return failure({ placeError })
                    end
                    trackers[side].slots = afterSlots
                else
                    return failure({ makeError("unknown_plan_action", path .. ".payload.action", "지원하지 않는 plan_changed action입니다.") })
                end
            elseif event.type == "card_restored" then
                local lookupErrors = {}
                findCard(staticData, event.source.id, "player", path .. ".source.id", lookupErrors)
                if #lookupErrors > 0
                    or event.source.kind ~= "card"
                    or event.side ~= "player"
                    or event.source.side ~= "player"
                    or event.phase ~= "player_card"
                    or not isRuntimeId(payload.instanceId)
                    or payload.instanceId ~= event.source.instanceId
                    or not isAsciiId(payload.reasonCode)
                    or payload.destination ~= "hand" then
                    return failure(#lookupErrors > 0 and lookupErrors or {
                        makeError("invalid_card_restore", path, "카드 복원 사건이 올바르지 않습니다."),
                    })
                end
                trackedHandCount.player = trackedHandCount.player + 1
                -- Individual instance IDs are private; the following summary event carries a safe count.
            elseif event.type == "action_sequence_stopped" then
                local side = payload.side or event.side
                local hasRestored = payload.restoredInstanceIds ~= nil
                local hasUnresolved = payload.unresolvedInstanceIds ~= nil
                local ids = hasRestored and payload.restoredInstanceIds or payload.unresolvedInstanceIds
                local _, idsError = validateIdArray(ids, path .. ".payload.instances")
                local _, sourceError = requireSource(event, path, "system", "turn_resolver")
                if sourceError
                    or not isSide(side)
                    or event.side ~= side
                    or event.phase ~= side .. "_card"
                    or payload.side ~= side
                    or hasRestored == hasUnresolved
                    or idsError
                    or not isAsciiId(payload.reasonCode) then
                    return failure({ sourceError or idsError or makeError("invalid_stopped_event", path .. ".payload", "중단 카드 사건이 올바르지 않습니다.") })
                end
                local safe = {
                    side = side,
                    reasonCode = payload.reasonCode,
                    count = #ids,
                }
                emit(publicResult, "actions_stopped", safe)
                emit(llmEvent, "actions_stopped", {
                    side = safe.side,
                    reasonCode = safe.reasonCode,
                    count = safe.count,
                })
            elseif event.type == "card_zone_changed" then
                local side = event.side
                local lookupErrors = {}
                findCard(staticData, event.source.id, side, path .. ".source.id", lookupErrors)
                if #lookupErrors > 0
                    or event.source.kind ~= "card"
                    or not isSide(side)
                    or event.source.side ~= side
                    or event.phase ~= side .. "_card"
                    or not isRuntimeId(payload.instanceId)
                    or payload.instanceId ~= event.source.instanceId
                    or payload.origin ~= "used"
                    or payload.destination ~= "removed" then
                    return failure({ makeError("unsupported_zone_change", path .. ".payload.destination", "공개 투영에서 지원하지 않는 카드 영역 이동입니다.") })
                end
                local safe = { side = side }
                if side == "player" then
                    safe.cardId = event.source.id
                end
                emit(publicResult, "card_removed", safe)
            elseif event.type == "outcome_latched" then
                local _, sourceError = requireSource(event, path, "system", "turn_resolver")
                local resourceOutcome = trackedResistance <= 0 and "victory"
                    or (trackedStealth <= 0 and "defeat" or nil)
                local expectedOutcome = resourceOutcome
                local expectedReason = event.phase == "turn_end" and "turn_end_checkpoint" or "card_checkpoint"
                if resourceOutcome == nil
                    and event.phase == "turn_end"
                    and resolution.turnNumber == beforeState.turnLimit then
                    expectedOutcome = "defeat"
                    expectedReason = "turn_limit"
                end
                if sourceError
                    or latchedOutcome ~= nil
                    or (event.phase ~= "player_card" and event.phase ~= "character_card" and event.phase ~= "turn_end")
                    or not isOutcome(payload.status)
                    or payload.status ~= expectedOutcome
                    or not isAsciiId(payload.reasonCode)
                    or payload.reasonCode ~= expectedReason
                    or (event.phase == "turn_end" and event.resolutionId ~= nil)
                    or (event.phase ~= "turn_end" and event.resolutionId == nil)
                    or not isFinite(payload.stealth)
                    or not isFinite(payload.resistance)
                    or payload.stealth ~= trackedStealth
                    or payload.resistance ~= trackedResistance
                    or payload.stealth ~= resolution.afterState.player.stealth
                    or payload.resistance ~= resolution.afterState.character.resistance then
                    return failure({ sourceError or makeError("invalid_outcome", path .. ".payload", "승패 사건 payload가 올바르지 않습니다.") })
                end
                latchedOutcome = payload.status
                local safe = {
                    status = payload.status,
                    reasonCode = payload.reasonCode,
                    stealth = payload.stealth,
                    resistance = payload.resistance,
                }
                emit(publicResult, "outcome", safe)
                emit(llmEvent, "outcome", {
                    status = payload.status,
                    reasonCode = payload.reasonCode,
                })
            elseif event.type == "mood_evaluated" then
                local _, sourceError = requireSource(event, path, "system", "mood_tokens")
                local moods = staticData.registry.moods
                local moodByOrder = {}
                for moodId, mood in pairs(moods) do moodByOrder[mood.order] = moodId end
                local expectedMoodAfter = trackedMood
                local expectedTokensAfter = normalizedMoodTokens(trackedMoodTokens)
                local expectedResolution
                local expectedTargetMood
                local expectedTiedMoods
                local forcedCount = #trackedForcedMoodRequests
                if forcedCount == 1 then
                    expectedResolution = "forced"
                    expectedTargetMood = trackedForcedMoodRequests[1].mood
                    expectedMoodAfter = expectedTargetMood
                else
                    local maximum = 0
                    local leaders = {}
                    for order = 1, #moodByOrder do
                        local moodId = moodByOrder[order]
                        local count = expectedTokensAfter[moodId]
                        if count > maximum then
                            maximum = count
                            leaders = { moodId }
                        elseif count == maximum then
                            leaders[#leaders + 1] = moodId
                        end
                    end
                    if maximum < 3 then
                        expectedResolution = "none"
                    elseif #leaders == 1 then
                        expectedResolution = "token"
                        expectedTargetMood = leaders[1]
                        expectedTokensAfter[expectedTargetMood] = 0
                        expectedMoodAfter = expectedTargetMood
                    else
                        expectedResolution = "tie"
                        expectedTiedMoods = leaders
                        for _, moodId in ipairs(leaders) do
                            expectedTokensAfter[moodId] = expectedTokensAfter[moodId] - 1
                        end
                    end
                end
                local expectedApplied = trackedMood ~= expectedMoodAfter
                if sourceError
                    or sawMoodEvaluation
                    or event.phase ~= "turn_end"
                    or event.side ~= "character"
                    or type(moods) ~= "table"
                    or type(moods[payload.before]) ~= "table"
                    or type(moods[payload.after]) ~= "table"
                    or payload.before ~= trackedMood
                    or payload.after ~= resolution.afterState.character.mood
                    or payload.after ~= expectedMoodAfter
                    or type(payload.applied) ~= "boolean"
                    or payload.applied ~= expectedApplied
                    or payload.forcedCount ~= forcedCount
                    or payload.forceCancelled ~= (forcedCount >= 2)
                    or payload.resolution ~= expectedResolution
                    or payload.targetMood ~= expectedTargetMood
                    or not dataEqual(payload.tiedMoods, expectedTiedMoods)
                    or not dataEqual(payload.tokensBefore, trackedMoodTokens)
                    or not dataEqual(payload.tokensAfter, expectedTokensAfter)
                    or not dataEqual(expectedTokensAfter, normalizedMoodTokens(resolution.afterState.character.moodTokens)) then
                    return failure({ sourceError or makeError("invalid_mood_evaluation", path .. ".payload", "무드 평가 사건 payload가 올바르지 않습니다.") })
                end
                sawMoodEvaluation = true
                trackedMood = payload.after
                trackedMoodTokens = expectedTokensAfter
                local safe = {
                    before = payload.before,
                    after = payload.after,
                    applied = payload.applied == true,
                    forcedCount = payload.forcedCount,
                    forceCancelled = payload.forceCancelled,
                    resolution = payload.resolution,
                    tokensBefore = payload.tokensBefore,
                    tokensAfter = payload.tokensAfter,
                }
                if payload.targetMood ~= nil then safe.targetMood = payload.targetMood end
                if payload.tiedMoods ~= nil then safe.tiedMoods = payload.tiedMoods end
                emit(publicResult, "mood_evaluated", safe)
                if payload.applied == true then
                    emit(llmEvent, "mood_changed", {
                        before = payload.before,
                        after = payload.after,
                        resolution = payload.resolution,
                    })
                end
            elseif event.type == "turn_cleanup" then
                local _, sourceError = requireSource(event, path, "system", "card_zones")
                local capacities = {
                    player = beforeState.player.planCapacity,
                    character = beforeState.character.planCapacity,
                }
                local _, beforeError = validateCleanupSnapshot(
                    payload.before,
                    path .. ".payload.before",
                    capacities
                )
                local _, afterError = validateCleanupSnapshot(
                    payload.after,
                    path .. ".payload.after",
                    capacities
                )
                local _, movedError = validateIdArray(payload.movedInstanceIds, path .. ".payload.movedInstanceIds")
                local expectedAfter, expectedMoved, transitionError
                if beforeError == nil and afterError == nil then
                    expectedAfter, expectedMoved, transitionError = expectedCleanupTransition(
                        payload.before,
                        resolution.turnNumber,
                        payload.after.turnNumber
                    )
                end
                if sourceError
                    or beforeError
                    or afterError
                    or movedError
                    or transitionError
                    or sawCleanup
                    or sawMoodEvaluation ~= true
                    or event.phase ~= "cleanup"
                    or event.side ~= nil
                    or not isInteger(payload.resolvedTurnNumber, 1)
                    or payload.resolvedTurnNumber ~= resolution.turnNumber
                    or payload.before.turnNumber ~= resolution.turnNumber
                    or (resolution.afterState.status == "active"
                        and payload.after.turnNumber ~= resolution.turnNumber + 1)
                    or (resolution.afterState.status ~= "active"
                        and payload.after.turnNumber ~= resolution.turnNumber)
                    or not dataEqual(payload.after, expectedAfter)
                    or not arraysEqual(payload.movedInstanceIds, expectedMoved)
                    or not dataEqual(payload.before.player.planSlots, trackers.player.slots)
                    or not dataEqual(payload.before.character.planSlots, trackers.character.slots)
                    or trackedStealth ~= resolution.afterState.player.stealth
                    or trackedResistance ~= resolution.afterState.character.resistance
                    or trackedMood ~= resolution.afterState.character.mood
                    or not dataEqual(trackedMoodTokens, normalizedMoodTokens(resolution.afterState.character.moodTokens)) then
                    return failure({ sourceError or beforeError or afterError or movedError or transitionError
                        or makeError("invalid_turn_cleanup", path .. ".payload", "턴 정리 사건 payload가 올바르지 않습니다.") })
                end
                sawCleanup = true
                postCleanupSnapshot = payload.after
                trackedHandCount.player = 0
                trackedHandCount.character = 0
                for _, side in ipairs({ "player", "character" }) do
                    local beforeSlots = type(payload.before) == "table"
                        and type(payload.before[side]) == "table"
                        and payload.before[side].planSlots
                        or {}
                    local afterSlots = type(payload.after) == "table"
                        and type(payload.after[side]) == "table"
                        and payload.after[side].planSlots
                        or {}
                    for beforeIndex, beforeSlot in ipairs(beforeSlots) do
                        local afterSlot = findPlanSlot(afterSlots, beforeSlot.cardInstanceId)
                        if afterSlot == nil then
                            local known = planKnown(side, beforeSlot)
                            local expired, expireError = emitPlan(
                                side,
                                "expired",
                                beforeSlot.cardId,
                                known,
                                nil,
                                beforeIndex,
                                known and "planExpired" or nil,
                                false
                            )
                            if not expired then
                                return failure({ expireError })
                            end
                        end
                    end
                    trackers[side].slots = afterSlots
                end
                emit(publicResult, "turn_ended", { turnNumber = payload.resolvedTurnNumber })
            elseif event.type == "session_end" then
                local _, sourceError = requireSource(event, path, "system", "turn_resolver")
                if sourceError
                    or sawSessionEnd
                    or index ~= #resolution.events
                    or event.phase ~= "session_end"
                    or event.side ~= nil
                    or not isOutcome(payload.status)
                    or payload.status ~= resolution.afterState.status then
                    return failure({ sourceError or makeError("invalid_session_end", path .. ".payload.status", "세션 종료 사건이 최종 상태와 다릅니다.") })
                end
                sawSessionEnd = true
                emit(publicResult, "session_ended", { status = payload.status })
                emit(llmEvent, "session_ended", { status = payload.status })
            else
                return failure({ makeError("unknown_event_type", path .. ".type", "지원하지 않는 원본 사건입니다.") })
            end
        end

        if sawTurnStart ~= true then
            return failure({ makeError("missing_turn_start", "$.turnResolution.events", "턴 시작 사건이 없습니다.") })
        end
        if sawCharacterIntent ~= true then
            return failure({ makeError("missing_character_intent", "$.turnResolution.events", "캐릭터 의도 선택 사건이 없습니다.") })
        end
        if sawStartDraw.player ~= true or sawStartDraw.character ~= true then
            return failure({ makeError("missing_start_draw", "$.turnResolution.events", "양측 턴 시작 드로우 사건이 모두 필요합니다.") })
        end
        if pendingCharacterIntent then
            return failure({ makeError("missing_action_tag_reveal", "$.turnResolution.events", "선택된 캐릭터 의도의 공개 행동 태그 사건이 없습니다.") })
        end
        if sawMoodEvaluation ~= true or sawCleanup ~= true then
            return failure({ makeError("incomplete_turn_tail", "$.turnResolution.events", "무드 평가 또는 턴 정리 사건이 없습니다.") })
        end
        if resolution.afterState.status == "active" then
            if latchedOutcome ~= nil or sawSessionEnd then
                return failure({ makeError("active_turn_has_terminal_event", "$.turnResolution.events", "진행 중 상태에 종료 사건이 있습니다.") })
            end
        elseif not isOutcome(resolution.afterState.status)
            or latchedOutcome ~= resolution.afterState.status
            or sawSessionEnd ~= true then
            return failure({ makeError("terminal_event_mismatch", "$.turnResolution.events", "최종 상태와 승패·세션 종료 사건이 일치하지 않습니다.") })
        end
        for _ in pairs(pendingCosts) do
            return failure({ makeError("unmatched_card_cost", "$.turnResolution.events", "card_declared와 짝이 없는 은폐 비용 사건이 있습니다.") })
        end
        for _ in pairs(pendingDeclarations) do
            return failure({ makeError("unmatched_card_declaration", "$.turnResolution.events", "card_resolved와 짝이 없는 카드 선언이 있습니다.") })
        end
        for _, effects in pairs(pendingTriggerEffects) do
            if #effects > 0 then
                return failure({ makeError("unmatched_trigger_effect", "$.turnResolution.events", "trigger_resolved와 짝이 없는 트리거 효과 사건이 있습니다.") })
            end
        end
        for _ in pairs(pendingPlanMeanings) do
            return failure({ makeError("unmatched_plan_meaning", "$.turnResolution.events", "trigger_resolved와 짝이 없는 계획 발동 사건이 있습니다.") })
        end
        local expectedTriggerBatches, expectedTriggerOrder, expectedTriggerError = collectExpectedTriggerBatches()
        if expectedTriggerError then return failure({ expectedTriggerError }) end
        if expectedTriggerBatches == nil then
            return failure({
                expectedTriggerOrder
                    or makeError("trigger_replay_failed", "$.turnResolution.events", "예상 트리거 batch를 재구성하지 못했습니다."),
            })
        end
        for key in pairs(expectedTriggerBatches) do
            if seenTriggerBatches[key] ~= true then
                return failure({ makeError("missing_trigger_batch", "$.turnResolution.events", "조건을 만족한 트리거 batch가 사건 로그에 없습니다.") })
            end
        end
        for key in pairs(seenTriggerBatches) do
            if expectedTriggerBatches[key] ~= true then
                return failure({ makeError("unexpected_trigger_batch", "$.turnResolution.events", "조건과 일치하지 않는 트리거 batch가 사건 로그에 있습니다.") })
            end
        end
        for inputKey, expectedOrder in pairs(expectedTriggerOrder) do
            local seenOrder = seenTriggerOrder[inputKey] or {}
            if not arraysEqual(seenOrder, expectedOrder) then
                return failure({ makeError("trigger_batch_order_mismatch", "$.turnResolution.events", "트리거 batch 순서가 snapshot 정렬 규칙과 다릅니다.") })
            end
        end
        for inputKey, seenOrder in pairs(seenTriggerOrder) do
            if expectedTriggerOrder[inputKey] == nil and #seenOrder > 0 then
                return failure({ makeError("unexpected_trigger_batch_order", "$.turnResolution.events", "예상 입력에 없는 트리거 batch 순서가 기록되었습니다.") })
            end
        end
        local finalCleanupSnapshot = cleanupSnapshotFromState(resolution.afterState)
        if postCleanupSnapshot == nil
            or not dataEqual(postCleanupSnapshot, finalCleanupSnapshot)
            or not dataEqual(trackers.player.slots, resolution.afterState.player.planSlots)
            or not dataEqual(trackers.character.slots, resolution.afterState.character.planSlots) then
            return failure({ makeError("final_state_event_mismatch", "$.turnResolution.events", "사건 재생 결과가 최종 상태와 다릅니다.") })
        end

        return success(publicResult, llmEvent)
    end

    local arguments = { ... }
    if action == "projectTurn" then
        return projectTurn(arguments[1], arguments[2], arguments[3])
    end
    return failure({
        makeError("unknown_action", "$.action", "지원하지 않는 턴 사건 투영 작업입니다."),
    })
end)

]],
    [[[
turnInitializer
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(state, draft, receipt, characterSelection, draws, reused)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            state = state,
            draft = draft,
            receipt = receipt,
            characterSelection = characterSelection,
            draws = draws or {},
            reused = reused == true,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function isDenseArray(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return false
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return false
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        return count == maximum
    end

    local function cloneData(value, path, active)
        local valueType = type(value)
        if valueType == "nil" or valueType == "string" or valueType == "boolean" then
            return value, nil
        end
        if valueType == "number" then
            if not isFinite(value) then
                return nil, makeError("non_finite_number", path, "유한하지 않은 숫자는 턴 초기화 데이터에 복제할 수 없습니다.")
            end
            return value, nil
        end
        if valueType ~= "table" then
            return nil, makeError(
                "unsupported_type",
                path,
                "턴 초기화 데이터에 복제할 수 없는 자료형입니다: " .. valueType
            )
        end
        if getmetatable(value) ~= nil then
            return nil, makeError("metatable_not_allowed", path, "턴 초기화 데이터에는 메타테이블을 사용할 수 없습니다.")
        end

        active = active or {}
        if active[value] then
            return nil, makeError("circular_reference", path, "순환 참조는 턴 초기화 데이터에 복제할 수 없습니다.")
        end
        active[value] = true

        local copy = {}
        for key, item in pairs(value) do
            local keyCopy, keyError = cloneData(key, path .. ".<key>", active)
            if keyError then
                active[value] = nil
                return nil, keyError
            end
            local itemCopy, itemError = cloneData(item, path .. "." .. tostring(key), active)
            if itemError then
                active[value] = nil
                return nil, itemError
            end
            copy[keyCopy] = itemCopy
        end
        active[value] = nil
        return copy, nil
    end

    local function deepEqual(left, right, active)
        if type(left) ~= type(right) then
            return false
        end
        if type(left) ~= "table" then
            return left == right
        end
        if getmetatable(left) ~= nil or getmetatable(right) ~= nil then
            return false
        end
        active = active or {}
        if active[left] ~= nil then
            return active[left] == right
        end
        active[left] = right
        for key, value in pairs(left) do
            if not deepEqual(value, right[key], active) then
                active[left] = nil
                return false
            end
        end
        for key in pairs(right) do
            if left[key] == nil then
                active[left] = nil
                return false
            end
        end
        active[left] = nil
        return true
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function appendErrors(target, source)
        if type(source) ~= "table" then
            target[#target + 1] = makeError("invalid_nested_error", "$", "하위 모듈 오류 목록이 올바르지 않습니다.")
            return
        end
        for _, item in ipairs(source) do
            target[#target + 1] = {
                code = tostring(type(item) == "table" and item.code or "nested_error"),
                path = tostring(type(item) == "table" and item.path or "$"),
                message = tostring(type(item) == "table" and item.message or "하위 모듈 작업이 실패했습니다."),
            }
        end
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError("runtime_unavailable", "$.runtime." .. moduleName, "스크립트 실행기를 찾을 수 없습니다."),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                makeError(
                    "module_call_error",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. " 실행에 실패했습니다: " .. tostring(report)
                ),
            }
        end
        if type(report) ~= "table" or getmetatable(report) ~= nil then
            return nil, {
                makeError("invalid_module_result", "$.runtime." .. moduleName, "하위 모듈이 일반 테이블 결과를 반환하지 않았습니다."),
            }
        end
        if report.ok ~= true then
            local errors = {}
            appendErrors(errors, report.errors)
            return nil, errors
        end
        return report, nil
    end

    local function validateOptions(options, authorityState)
        local errors = {}
        if type(options) ~= "table" or getmetatable(options) ~= nil then
            return nil, {
                makeError("invalid_options", "$.options", "턴 초기화 옵션은 일반 테이블이어야 합니다."),
            }
        end
        for key in pairs(options) do
            if key ~= "turnId" then
                errors[#errors + 1] = makeError(
                    "unexpected_option",
                    "$.options." .. tostring(key),
                    "지원하지 않는 턴 초기화 옵션입니다."
                )
            end
        end
        if not isRuntimeId(options.turnId) then
            errors[#errors + 1] = makeError("invalid_turn_id", "$.options.turnId", "turnId가 올바르지 않습니다.")
        elseif type(authorityState) == "table" and authorityState.lastCommittedTurnId == options.turnId then
            errors[#errors + 1] = makeError(
                "turn_already_committed",
                "$.options.turnId",
                "이미 확정한 turnId를 다시 초기화할 수 없습니다."
            )
        end
        if #errors > 0 then
            return nil, errors
        end
        return { turnId = options.turnId }, nil
    end

    local function source(kind, id, side, instanceId)
        local value = {
            kind = kind,
            id = id,
        }
        if side ~= nil then
            value.side = side
        end
        if instanceId ~= nil then
            value.instanceId = instanceId
        end
        return value
    end

    local function findInstance(state, instanceId)
        for _, instance in ipairs(type(state) == "table" and type(state.cardInstances) == "table" and state.cardInstances or {}) do
            if type(instance) == "table" and instance.instanceId == instanceId then
                return instance
            end
        end
        return nil
    end

    local function validateStateEnvelope(state, path, code, label)
        local errors = {}
        if type(state) ~= "table" or getmetatable(state) ~= nil then
            return false, {
                makeError(code, path, label .. " state가 일반 테이블이 아닙니다."),
            }
        end

        local player = state.player
        local character = state.character
        if type(player) ~= "table" or getmetatable(player) ~= nil then
            errors[#errors + 1] = makeError(code, path .. ".player", label .. " player가 일반 테이블이 아닙니다.")
        else
            if not isFinite(player.stealth) then
                errors[#errors + 1] = makeError(code, path .. ".player.stealth", label .. " player.stealth가 유한한 숫자가 아닙니다.")
            end
            if not isInteger(player.baseDrawCount, 1) then
                errors[#errors + 1] = makeError(code, path .. ".player.baseDrawCount", label .. " player.baseDrawCount가 1 이상의 정수가 아닙니다.")
            end
        end
        if type(character) ~= "table" or getmetatable(character) ~= nil then
            errors[#errors + 1] = makeError(code, path .. ".character", label .. " character가 일반 테이블이 아닙니다.")
        else
            if not isFinite(character.resistance) then
                errors[#errors + 1] = makeError(code, path .. ".character.resistance", label .. " character.resistance가 유한한 숫자가 아닙니다.")
            end
            if not isInteger(character.baseDrawCount, 1) then
                errors[#errors + 1] = makeError(code, path .. ".character.baseDrawCount", label .. " character.baseDrawCount가 1 이상의 정수가 아닙니다.")
            end
        end

        if type(state.rng) ~= "table" or getmetatable(state.rng) ~= nil then
            errors[#errors + 1] = makeError(code, path .. ".rng", label .. " rng가 일반 테이블이 아닙니다.")
        elseif not isInteger(state.rng.seed, 0) or not isInteger(state.rng.cursor, 0) then
            errors[#errors + 1] = makeError(code, path .. ".rng", label .. " rng seed/cursor가 0 이상의 정수가 아닙니다.")
        end
        if type(state.cardInstances) ~= "table" or getmetatable(state.cardInstances) ~= nil then
            errors[#errors + 1] = makeError(code, path .. ".cardInstances", label .. " cardInstances가 일반 테이블이 아닙니다.")
        end

        if #errors > 0 then
            return false, errors
        end
        return true, nil
    end

    local function validateDrawReportEnvelope(report)
        if type(report) ~= "table" or getmetatable(report) ~= nil then
            return false, {
                makeError("invalid_draw_result", "$.runtime.cardZones", "cardZones.draw 결과가 일반 테이블이 아닙니다."),
            }
        end
        local validState, stateErrors = validateStateEnvelope(
            report.state,
            "$.runtime.cardZones.state",
            "invalid_draw_state",
            "cardZones.draw 결과"
        )
        if not validState then
            return false, stateErrors
        end
        if not isDenseArray(report.drawnInstanceIds) then
            return false, {
                makeError(
                    "invalid_draw_result",
                    "$.runtime.cardZones.drawnInstanceIds",
                    "cardZones.draw의 drawnInstanceIds가 연속 배열이 아닙니다."
                ),
            }
        end
        local seen = {}
        for index, instanceId in ipairs(report.drawnInstanceIds) do
            if not isRuntimeId(instanceId) then
                return false, {
                    makeError(
                        "invalid_draw_result",
                        "$.runtime.cardZones.drawnInstanceIds[" .. index .. "]",
                        "cardZones.draw가 올바르지 않은 카드 인스턴스 ID를 반환했습니다."
                    ),
                }
            end
            if seen[instanceId] then
                return false, {
                    makeError(
                        "invalid_draw_result",
                        "$.runtime.cardZones.drawnInstanceIds[" .. index .. "]",
                        "cardZones.draw가 중복 카드 인스턴스 ID를 반환했습니다."
                    ),
                }
            end
            seen[instanceId] = true
        end
        return true, nil
    end

    local function validateSelectorReportEnvelope(report)
        if type(report) ~= "table" or getmetatable(report) ~= nil then
            return false, {
                makeError("invalid_character_selection_result", "$.characterSelection", "캐릭터 선택 결과가 일반 테이블이 아닙니다."),
            }
        end
        local validState, stateErrors = validateStateEnvelope(
            report.state,
            "$.characterSelection.state",
            "invalid_character_selection_state",
            "캐릭터 선택 결과"
        )
        if not validState then
            return false, stateErrors
        end
        if type(report.intent) ~= "table" or getmetatable(report.intent) ~= nil then
            return false, {
                makeError("invalid_character_selection_result", "$.characterSelection.intent", "캐릭터 선택 intent가 일반 테이블이 아닙니다."),
            }
        end
        if type(report.receipt) ~= "table" or getmetatable(report.receipt) ~= nil then
            return false, {
                makeError("invalid_character_selection_result", "$.characterSelection.receipt", "캐릭터 선택 receipt가 일반 테이블이 아닙니다."),
            }
        end
        return true, nil
    end

    local function hasOutcome(state)
        return type(state) == "table"
            and type(state.player) == "table"
            and type(state.character) == "table"
            and isFinite(state.player.stealth)
            and isFinite(state.character.resistance)
            and (state.player.stealth <= 0 or state.character.resistance <= 0)
    end

    local function prepareTurn(authorityState, staticInput, options)
        local normalizedOptions, optionErrors = validateOptions(options, authorityState)
        if optionErrors then
            return failure(optionErrors)
        end
        local staticData = normalizeStaticData(staticInput)

        local validation, validationErrors = callModule(
            "stateSchema",
            "validateBattleState",
            authorityState,
            staticData
        )
        if validationErrors then
            return failure(validationErrors)
        end
        if validation.referencesValidated ~= true then
            return failure({
                makeError("static_references_not_validated", "$.staticData", "턴 초기화에는 전체 정적 데이터 참조 검증이 필요합니다."),
            })
        end
        if authorityState.status ~= "active" then
            return failure({
                makeError("battle_not_active", "$.state.status", "진행 중인 전투만 턴을 초기화할 수 있습니다."),
            })
        end

        local turnId = normalizedOptions.turnId
        if authorityState.turnStartReceipt ~= nil then
            if authorityState.turnStartReceipt.turnId ~= turnId then
                return failure({
                    makeError(
                        "turn_already_initialized",
                        "$.state.turnStartReceipt.turnId",
                        "현재 턴은 다른 turnId로 이미 초기화되었습니다."
                    ),
                })
            end
            local reusedState, stateCloneError = cloneData(authorityState, "$.state")
            if stateCloneError then
                return failure({ stateCloneError })
            end
            local receiptCopy, receiptCloneError = cloneData(authorityState.turnStartReceipt, "$.state.turnStartReceipt")
            if receiptCloneError then
                return failure({ receiptCloneError })
            end
            local selectionCopy, selectionCloneError = cloneData(
                authorityState.turnStartReceipt.characterSelection,
                "$.state.turnStartReceipt.characterSelection"
            )
            if selectionCloneError then
                return failure({ selectionCloneError })
            end
            local drawsCopy, drawsCloneError = cloneData(
                authorityState.turnStartReceipt.draws,
                "$.state.turnStartReceipt.draws"
            )
            if drawsCloneError then
                return failure({ drawsCloneError })
            end
            local draftReport, draftErrors = callModule("turnDraft", "newDraft", reusedState, staticData)
            if draftErrors then
                return failure(draftErrors)
            end
            return success(reusedState, draftReport.draft, receiptCopy, selectionCopy, drawsCopy, true)
        end

        if type(authorityState.selection) ~= "table"
            or not isDenseArray(authorityState.selection.playerCardInstanceIds)
            or #authorityState.selection.playerCardInstanceIds > 0 then
            return failure({
                makeError(
                    "player_selection_not_empty",
                    "$.state.selection.playerCardInstanceIds",
                    "턴 초기화 전 플레이어 선택은 비어 있어야 합니다."
                ),
            })
        end
        if type(authorityState.characterIntent) ~= "table"
            or not isDenseArray(authorityState.characterIntent.cardInstanceIds)
            or #authorityState.characterIntent.cardInstanceIds > 0
            or authorityState.characterIntent.publicActionTag ~= nil then
            return failure({
                makeError(
                    "character_intent_not_empty",
                    "$.state.characterIntent",
                    "턴 초기화 전 캐릭터 의도는 비어 있어야 합니다."
                ),
            })
        end

        local baseline = {
            stealth = authorityState.player.stealth,
            resistance = authorityState.character.resistance,
            mood = authorityState.character.mood,
        }
        local baselineTokens, baselineTokensError = cloneData(
            authorityState.character.moodTokens or {},
            "$.state.character.moodTokens"
        )
        if baselineTokensError then
            return failure({ baselineTokensError })
        end
        for moodId in pairs(staticData.registry.moods) do
            if baselineTokens[moodId] == nil then
                baselineTokens[moodId] = 0
            end
        end
        baseline.moodTokens = baselineTokens
        local state, stateCloneError = cloneData(authorityState, "$.state")
        if stateCloneError then
            return failure({ stateCloneError })
        end
        local transient = {
            skipRemaining = {
                player = false,
                character = false,
            },
            forcedMoodRequests = {},
        }
        local events = {}

        local function appendEvent(eventType, eventSource, payload, side, cause)
            local sequence = #events + 1
            local event = {
                eventId = turnId .. "-event-" .. string.format("%03d", sequence),
                sequence = sequence,
                type = eventType,
                phase = "turn_start",
                source = eventSource,
            }
            if payload ~= nil then
                event.payload = payload
            end
            if side ~= nil then
                event.side = side
            end
            if cause ~= nil then
                event.cause = cause
            end
            events[sequence] = event
            return event
        end

        local function appendPipelineRecords(records, inputEventId)
            if not isDenseArray(records) then
                return false, {
                    makeError("invalid_trigger_records", "$.triggerPipeline.records", "트리거 기록이 연속 배열이 아닙니다."),
                }
            end
            for index, record in ipairs(records) do
                if type(record) ~= "table"
                    or type(record.type) ~= "string"
                    or string.match(record.type, "^[a-z][a-z0-9_]*$") == nil
                    or type(record.source) ~= "table"
                    or type(record.source.kind) ~= "string"
                    or string.match(record.source.kind, "^[a-z][a-z0-9_]*$") == nil
                    or type(record.source.id) ~= "string"
                    or string.match(record.source.id, "^[a-z][a-z0-9_]*$") == nil
                    or record.side ~= record.source.side then
                    return false, {
                        makeError(
                            "invalid_trigger_record",
                            "$.triggerPipeline.records[" .. index .. "]",
                            "트리거 기록 envelope가 올바르지 않습니다."
                        ),
                    }
                end
                local sourceCopy, sourceError = cloneData(record.source, "$.triggerPipeline.records[" .. index .. "].source")
                if sourceError then
                    return false, { sourceError }
                end
                local payloadCopy = nil
                if record.payload ~= nil then
                    local payloadError
                    payloadCopy, payloadError = cloneData(
                        record.payload,
                        "$.triggerPipeline.records[" .. index .. "].payload"
                    )
                    if payloadError then
                        return false, { payloadError }
                    end
                end
                appendEvent(
                    record.type,
                    sourceCopy,
                    payloadCopy,
                    record.side,
                    record.type == "effect_applied" and {
                        kind = record.source.kind .. "_trigger",
                        eventId = inputEventId,
                    } or {
                        kind = "turn_event",
                        eventId = inputEventId,
                    }
                )
            end
            return true, nil
        end

        local function validatePipelineReport(report)
            if type(report) ~= "table" or getmetatable(report) ~= nil then
                return false, {
                    makeError(
                        "invalid_trigger_pipeline_result",
                        "$.runtime.triggerPipeline",
                        "triggerPipeline.run 결과가 일반 테이블이 아닙니다."
                    ),
                }
            end
            local validState, stateErrors = validateStateEnvelope(
                report.state,
                "$.runtime.triggerPipeline.state",
                "invalid_trigger_pipeline_state",
                "triggerPipeline.run 결과"
            )
            if not validState then
                return false, stateErrors
            end
            if type(report.transient) ~= "table"
                or getmetatable(report.transient) ~= nil
                or not isDenseArray(report.records) then
                return false, {
                    makeError(
                        "invalid_trigger_pipeline_result",
                        "$.runtime.triggerPipeline",
                        "triggerPipeline.run 결과의 transient 또는 records가 올바르지 않습니다."
                    ),
                }
            end
            local skipRemaining = report.transient.skipRemaining
            if type(skipRemaining) ~= "table"
                or (skipRemaining.player ~= true and skipRemaining.player ~= false)
                or (skipRemaining.character ~= true and skipRemaining.character ~= false)
                or not isDenseArray(report.transient.forcedMoodRequests) then
                return false, {
                    makeError(
                        "invalid_trigger_pipeline_transient",
                        "$.runtime.triggerPipeline.transient",
                        "triggerPipeline.run 결과의 턴 일시 상태가 올바르지 않습니다."
                    ),
                }
            end
            return true, nil
        end

        local function validateWorkingState(value)
            local workingValidation, workingErrors = callModule(
                "stateSchema",
                "validateBattleState",
                value,
                staticData
            )
            if workingErrors then
                return false, workingErrors
            end
            if workingValidation.referencesValidated ~= true then
                return false, {
                    makeError(
                        "working_references_not_validated",
                        "$.runtime.stateSchema",
                        "턴 초기화 중간 상태의 전체 정적 참조를 검증하지 못했습니다."
                    ),
                }
            end
            return true, nil
        end

        local turnStartEvent = appendEvent(
            "turn_start",
            source("system", "turn_initializer"),
            { turnNumber = state.turnNumber },
            nil,
            { kind = "turn_rule" }
        )
        local turnStartInput = {
            type = "turn_start",
            turnNumber = state.turnNumber,
        }
        local startPipeline, startPipelineErrors = callModule(
            "triggerPipeline",
            "run",
            staticData,
            { state = state, transient = transient },
            turnStartInput,
            { phase = "turn_start" }
        )
        if startPipelineErrors then
            return failure(startPipelineErrors)
        end
        local validPipeline, pipelineShapeErrors = validatePipelineReport(startPipeline)
        if not validPipeline then
            return failure(pipelineShapeErrors)
        end
        state = startPipeline.state
        transient = startPipeline.transient
        local appended, appendRecordErrors = appendPipelineRecords(startPipeline.records, turnStartEvent.eventId)
        if not appended then
            return failure(appendRecordErrors)
        end
        if hasOutcome(state) then
            return failure({
                makeError(
                    "turn_start_outcome_policy_pending",
                    "$.state.status",
                    "턴 시작 효과만으로 승패가 정해질 때의 세션 종료 연결 정책은 아직 지원하지 않습니다."
                ),
            })
        end
        local validWorkingState, workingStateErrors = validateWorkingState(state)
        if not validWorkingState then
            return failure(workingStateErrors)
        end

        local draws = {}
        for _, owner in ipairs({ "player", "character" }) do
            local ownerState = state[owner]
            if type(ownerState) ~= "table" or not isInteger(ownerState.baseDrawCount, 1) then
                return failure({
                    makeError(
                        "invalid_base_draw_count",
                        "$.state." .. owner .. ".baseDrawCount",
                        "기본 드로우 수는 1 이상의 정수여야 합니다."
                    ),
                })
            end
            local rngBefore, rngBeforeError = cloneData(state.rng, "$.state.rng")
            if rngBeforeError then
                return failure({ rngBeforeError })
            end
            local drawReport, drawErrors = callModule(
                "cardZones",
                "draw",
                state,
                owner,
                ownerState.baseDrawCount
            )
            if drawErrors then
                return failure(drawErrors)
            end
            local validDrawReport, drawShapeErrors = validateDrawReportEnvelope(drawReport)
            if not validDrawReport then
                return failure(drawShapeErrors)
            end
            state = drawReport.state
            validWorkingState, workingStateErrors = validateWorkingState(state)
            if not validWorkingState then
                return failure(workingStateErrors)
            end
            local rngAfter, rngAfterError = cloneData(state.rng, "$.state.rng")
            if rngAfterError then
                return failure({ rngAfterError })
            end
            local drawnIds, drawnIdsError = cloneData(drawReport.drawnInstanceIds or {}, "$.drawnInstanceIds")
            if drawnIdsError then
                return failure({ drawnIdsError })
            end
            draws[owner] = {
                requested = ownerState.baseDrawCount,
                drawnInstanceIds = drawnIds,
                rngBefore = rngBefore,
                rngAfter = rngAfter,
            }
            appendEvent(
                "cards_drawn",
                source("system", "card_zones", owner),
                {
                    requested = ownerState.baseDrawCount,
                    drawnCount = #drawnIds,
                },
                owner,
                { kind = "turn_rule" }
            )
        end

        local stateBeforeSelection, stateBeforeSelectionError = cloneData(state, "$.stateBeforeSelection")
        if stateBeforeSelectionError then
            return failure({ stateBeforeSelectionError })
        end
        local selectionRngBefore, selectionRngBeforeError = cloneData(state.rng, "$.state.rng")
        if selectionRngBeforeError then
            return failure({ selectionRngBeforeError })
        end
        local selectionReport, selectionErrors = callModule(
            "characterSelector",
            "selectIntent",
            state,
            staticData
        )
        if selectionErrors then
            return failure(selectionErrors)
        end
        local validSelectionReport, selectionShapeErrors = validateSelectorReportEnvelope(selectionReport)
        if not validSelectionReport then
            return failure(selectionShapeErrors)
        end
        validWorkingState, workingStateErrors = validateWorkingState(selectionReport.state)
        if not validWorkingState then
            return failure(workingStateErrors)
        end
        state = selectionReport.state
        local selectionIntent, selectionIntentError = cloneData(selectionReport.intent, "$.characterSelection.intent")
        if selectionIntentError then
            return failure({ selectionIntentError })
        end
        local selectionReceipt, selectionReceiptError = cloneData(
            selectionReport.receipt,
            "$.characterSelection"
        )
        if selectionReceiptError then
            return failure({ selectionReceiptError })
        end
        local selectionReplay, selectionReplayErrors = callModule(
            "characterSelector",
            "validateReceipt",
            staticData,
            selectionReceipt,
            stateBeforeSelection
        )
        if selectionReplayErrors then
            return failure(selectionReplayErrors)
        end
        if selectionReplay.valid ~= true then
            return failure({
                makeError(
                    "invalid_character_selection_replay",
                    "$.characterSelection",
                    "선택기가 실제 선택 직전 상태에 대한 재생 검증을 완료하지 못했습니다."
                ),
            })
        end
        if type(state.characterIntent) ~= "table"
            or not deepEqual(selectionIntent, state.characterIntent) then
            return failure({
                makeError(
                    "character_selection_intent_mismatch",
                    "$.characterSelection.intent",
                    "선택기가 반환한 intent와 상태의 characterIntent가 일치하지 않습니다."
                ),
            })
        end
        local expectedSelectionState, expectedSelectionStateError = cloneData(
            stateBeforeSelection,
            "$.expectedSelectionState"
        )
        if expectedSelectionStateError then
            return failure({ expectedSelectionStateError })
        end
        local selectedRng, selectedRngError = cloneData(state.rng, "$.characterSelection.state.rng")
        if selectedRngError then
            return failure({ selectedRngError })
        end
        expectedSelectionState.rng = selectedRng
        local expectedIntent, expectedIntentError = cloneData(selectionIntent, "$.characterSelection.intent")
        if expectedIntentError then
            return failure({ expectedIntentError })
        end
        expectedSelectionState.characterIntent = expectedIntent
        if not deepEqual(expectedSelectionState, state) then
            return failure({
                makeError(
                    "character_selection_state_scope_violation",
                    "$.characterSelection.state",
                    "선택기가 RNG와 characterIntent 이외의 권위 상태를 변경했습니다."
                ),
            })
        end
        if selectionReceipt.battleId ~= state.battleId
            or selectionReceipt.turnNumber ~= state.turnNumber
            or selectionReceipt.characterId ~= state.character.characterId then
            return failure({
                makeError(
                    "character_selection_identity_mismatch",
                    "$.characterSelection",
                    "선택 영수증의 전투·턴·캐릭터 식별자가 상태와 일치하지 않습니다."
                ),
            })
        end
        if not deepEqual(selectionReceipt.rngBefore, selectionRngBefore)
            or not deepEqual(selectionReceipt.rngAfter, state.rng) then
            return failure({
                makeError(
                    "character_selection_rng_mismatch",
                    "$.characterSelection.rngAfter",
                    "선택 영수증의 RNG 전이가 실제 선택 상태와 일치하지 않습니다."
                ),
            })
        end

        local selectedInstanceId = selectionReceipt.selectedInstanceId
        local selectedInstance = selectedInstanceId and findInstance(state, selectedInstanceId) or nil
        if selectedInstanceId == nil then
            if not isDenseArray(selectionIntent.cardInstanceIds)
                or #selectionIntent.cardInstanceIds ~= 0
                or selectionIntent.publicActionTag ~= nil
                or selectionReceipt.selectedCardId ~= nil
                or selectionReceipt.publicActionTag ~= nil
                or type(selectionReceipt.draw) ~= "table"
                or selectionReceipt.draw.kind ~= "pass" then
                return failure({
                    makeError(
                        "character_selection_pass_mismatch",
                        "$.characterSelection",
                        "패스 선택 영수증과 characterIntent가 일치하지 않습니다."
                    ),
                })
            end
        elseif not isDenseArray(selectionIntent.cardInstanceIds)
            or #selectionIntent.cardInstanceIds ~= 1
            or selectionIntent.cardInstanceIds[1] ~= selectedInstanceId
            or selectionIntent.publicActionTag ~= selectionReceipt.publicActionTag then
            return failure({
                makeError(
                    "character_selection_selected_mismatch",
                    "$.characterSelection",
                    "선택 영수증과 선택된 characterIntent가 일치하지 않습니다."
                ),
            })
        end
        appendEvent(
            "character_intent_selected",
            source("system", "character_selector", "character"),
            { selected = selectedInstanceId ~= nil },
            "character",
            { kind = "turn_rule" }
        )

        if selectedInstanceId ~= nil then
            if selectedInstance == nil or selectedInstance.owner ~= "character" or selectedInstance.zone ~= "hand" then
                return failure({
                    makeError(
                        "invalid_selected_character_card",
                        "$.characterSelection.selectedInstanceId",
                        "선택기가 캐릭터 손패에 없는 카드를 반환했습니다."
                    ),
                })
            end
            local card = staticData.cards[selectedInstance.cardId]
            if type(card) ~= "table"
                or card.id ~= selectionReceipt.selectedCardId
                or card.actionTag ~= selectionReceipt.publicActionTag then
                return failure({
                    makeError(
                        "selected_action_tag_mismatch",
                        "$.characterSelection.publicActionTag",
                        "선택 카드와 공개 행동 태그가 일치하지 않습니다."
                    ),
                })
            end
            local revealEvent = appendEvent(
                "action_tag_revealed",
                source("system", "character_selector", "character"),
                {
                    actionTag = card.actionTag,
                },
                "character",
                { kind = "turn_rule" }
            )
            local revealInput = {
                type = "action_tag_revealed",
                side = "character",
                cardId = card.id,
                cardInstanceId = selectedInstance.instanceId,
                actionTag = card.actionTag,
            }
            local revealPipeline, revealPipelineErrors = callModule(
                "triggerPipeline",
                "run",
                staticData,
                { state = state, transient = transient },
                revealInput,
                {
                    phase = "turn_start",
                    currentCard = {
                        id = card.id,
                        instanceId = selectedInstance.instanceId,
                        owner = "character",
                        actionTag = card.actionTag,
                    },
                }
            )
            if revealPipelineErrors then
                return failure(revealPipelineErrors)
            end
            validPipeline, pipelineShapeErrors = validatePipelineReport(revealPipeline)
            if not validPipeline then
                return failure(pipelineShapeErrors)
            end
            state = revealPipeline.state
            transient = revealPipeline.transient
            appended, appendRecordErrors = appendPipelineRecords(revealPipeline.records, revealEvent.eventId)
            if not appended then
                return failure(appendRecordErrors)
            end
            if hasOutcome(state) then
                return failure({
                    makeError(
                        "turn_start_outcome_policy_pending",
                        "$.state.status",
                        "행동 태그 공개 효과만으로 승패가 정해질 때의 세션 종료 연결 정책은 아직 지원하지 않습니다."
                    ),
                })
            end
            validWorkingState, workingStateErrors = validateWorkingState(state)
            if not validWorkingState then
                return failure(workingStateErrors)
            end
        end

        local storedTransient = {
            skipRemaining = {
                player = type(transient.skipRemaining) == "table" and transient.skipRemaining.player == true,
                character = type(transient.skipRemaining) == "table" and transient.skipRemaining.character == true,
            },
            forcedMoodRequests = {},
        }
        local forcedRequestsCopy, forcedRequestsError = cloneData(
            transient.forcedMoodRequests or {},
            "$.transient.forcedMoodRequests"
        )
        if forcedRequestsError then
            return failure({ forcedRequestsError })
        end
        storedTransient.forcedMoodRequests = forcedRequestsCopy

        local receiptDraws, receiptDrawsError = cloneData(draws, "$.draws")
        if receiptDrawsError then
            return failure({ receiptDrawsError })
        end
        local receiptSelection, receiptSelectionError = cloneData(
            selectionReceipt,
            "$.characterSelection"
        )
        if receiptSelectionError then
            return failure({ receiptSelectionError })
        end
        local receipt = {
            schemaVersion = SCHEMA_VERSION,
            kind = "turnStartReceipt",
            turnId = turnId,
            turnNumber = state.turnNumber,
            baseline = baseline,
            transient = storedTransient,
            draws = receiptDraws,
            characterSelection = receiptSelection,
            events = events,
        }
        state.turnStartReceipt = receipt

        local sealReport, sealErrors = callModule(
            "stateSchema",
            "sealTurnStartReceipt",
            state,
            staticData
        )
        if sealErrors then
            return failure(sealErrors)
        end
        if type(sealReport.state) ~= "table"
            or type(sealReport.state.turnStartReceipt) ~= "table"
            or type(sealReport.state.turnStartReceipt.authorityFingerprint) ~= "table" then
            return failure({
                makeError("invalid_turn_receipt_seal", "$.state.turnStartReceipt", "stateSchema가 봉인된 턴 영수증 상태를 반환하지 않았습니다."),
            })
        end
        state = sealReport.state
        receipt = state.turnStartReceipt

        local outputValidation, outputValidationErrors = callModule(
            "stateSchema",
            "validateBattleState",
            state,
            staticData
        )
        if outputValidationErrors then
            return failure(outputValidationErrors)
        end
        if outputValidation.referencesValidated ~= true then
            return failure({
                makeError("output_references_not_validated", "$.state", "초기화 결과의 정적 참조를 검증하지 못했습니다."),
            })
        end
        local conservation, conservationErrors = callModule(
            "cardZones",
            "validateConservation",
            authorityState,
            state
        )
        if conservationErrors then
            return failure(conservationErrors)
        end
        local draftReport, draftErrors = callModule("turnDraft", "newDraft", state, staticData)
        if draftErrors then
            return failure(draftErrors)
        end

        local receiptCopy, receiptCopyError = cloneData(receipt, "$.receipt")
        if receiptCopyError then
            return failure({ receiptCopyError })
        end
        local selectionOutput, selectionOutputError = cloneData(
            receipt.characterSelection,
            "$.receipt.characterSelection"
        )
        if selectionOutputError then
            return failure({ selectionOutputError })
        end
        local drawsOutput, drawsOutputError = cloneData(receipt.draws, "$.receipt.draws")
        if drawsOutputError then
            return failure({ drawsOutputError })
        end
        return success(
            state,
            draftReport.draft,
            receiptCopy,
            selectionOutput,
            drawsOutput,
            false
        )
    end

    local arguments = { ... }
    local actions = {
        prepareTurn = prepareTurn,
    }
    local handler = actions[action]
    if not handler then
        return failure({
            makeError("unknown_action", "$.action", "지원하지 않는 턴 초기화 작업입니다: " .. tostring(action)),
        })
    end
    return handler(arguments[1], arguments[2], arguments[3])
end)

]],
    [[[
turnPresentation
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local MAX_PLAN_SLOTS = 16

    local VALID_MODES = {
        pass = true,
        chain_pass = true,
        action = true,
    }

    local VALID_EVENT_TYPES = {
        turn_mode = true,
        turn_started = true,
        player_cards_drawn = true,
        character_intent = true,
        card_declared = true,
        effect_applied = true,
        trigger_suppressed = true,
        plan_changed = true,
        actions_stopped = true,
        card_removed = true,
        outcome = true,
        mood_evaluated = true,
        turn_ended = true,
        session_ended = true,
    }

    local RESOURCE_EFFECTS = {
        pay_stealth_cost = { target = "player", resource = "stealth", direction = -1, noun = "은폐" },
        damage_resistance = { target = "character", resource = "resistance", direction = -1, noun = "상대의 저항" },
        recover_resistance = { target = "character", resource = "resistance", direction = 1, noun = "상대의 저항" },
        lose_stealth = { target = "player", resource = "stealth", direction = -1, noun = "은폐" },
        recover_stealth = { target = "player", resource = "stealth", direction = 1, noun = "은폐" },
    }

    local SOURCE_COLLECTIONS = {
        card = "cards",
        plan = "cards",
        trait = "traits",
        perk = "perks",
        environment = "environments",
    }

    local ACTION_STOP_REASONS = {
        outcome_latched = "승패가 결정되어",
        skip_actions = "남은 행동이 생략되어",
        insufficient_stealth = "은폐가 부족해",
        card_unavailable = "등록한 카드를 사용할 수 없어",
    }

    local OUTCOME_REASONS = {
        card_checkpoint = true,
        turn_end_checkpoint = true,
        turn_limit = true,
    }

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(lastTurn)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            lastTurn = lastTurn,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isSide(value)
        return value == "player" or value == "character"
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function getArrayLength(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return nil
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return nil
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        if count ~= maximum then
            return nil
        end
        return maximum
    end

    local function checkAllowedKeys(value, allowed, path)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return makeError("invalid_object", path, "공개 표시 자료는 일반 객체여야 합니다.")
        end
        for key in pairs(value) do
            if type(key) ~= "string" or allowed[key] ~= true then
                return makeError("unexpected_field", path, "공개 허용 목록 밖의 필드가 있습니다.")
            end
        end
        return nil
    end

    local function nestedFailure(prefix, report)
        local errors = {}
        local nested = type(report) == "table" and report.errors or nil
        if type(nested) == "table" and #nested > 0 then
            for _, item in ipairs(nested) do
                local suffix = type(item) == "table" and item.path or "$"
                if type(suffix) ~= "string" then suffix = "$" end
                if suffix:sub(1, 1) == "$" then
                    suffix = suffix:sub(2)
                else
                    suffix = "." .. suffix
                end
                errors[#errors + 1] = makeError(
                    type(item) == "table" and type(item.code) == "string" and item.code
                        or "nested_validation_failed",
                    prefix .. suffix,
                    "저장된 턴 자료의 하위 검증에 실패했습니다."
                )
            end
        else
            errors[1] = makeError(
                "nested_validation_failed",
                prefix,
                "저장된 턴 자료의 하위 검증에 실패했습니다."
            )
        end
        return errors
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError("runtime_unavailable", "$.runtime", "스크립트 실행기를 찾을 수 없습니다."),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok or type(report) ~= "table" then
            return nil, {
                makeError("module_call_failed", "$.runtime." .. moduleName, "하위 검증 모듈 호출에 실패했습니다."),
            }
        end
        if report.ok ~= true then
            return nil, nestedFailure("$.runtime." .. moduleName, report)
        end
        return report, nil
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function hasCompleteStaticData(staticData)
        return type(staticData) == "table"
            and type(staticData.registry) == "table"
            and type(staticData.registry.actionTags) == "table"
            and type(staticData.registry.moods) == "table"
            and type(staticData.cards) == "table"
            and type(staticData.traits) == "table"
            and type(staticData.environments) == "table"
            and type(staticData.subwayLines) == "table"
            and type(staticData.characters) == "table"
    end

    local function sideLabel(side)
        return side == "player" and "플레이어" or "상대"
    end

    local function numberText(value)
        if value % 1 == 0 then
            return string.format("%.0f", value)
        end
        return tostring(value)
    end

    local function lookupActionLabel(staticData, actionTag, owner, path)
        local definition = staticData.registry.actionTags[actionTag]
        if type(actionTag) ~= "string"
            or type(definition) ~= "table"
            or definition.id ~= actionTag
            or definition.owner ~= owner
            or type(definition.label) ~= "string"
            or definition.label == "" then
            return nil, makeError("unknown_action_tag", path, "공개 행동 태그 라벨을 확인할 수 없습니다.")
        end
        return definition.label, nil
    end

    local function lookupMood(staticData, moodId, path)
        local definition = staticData.registry.moods[moodId]
        if type(moodId) ~= "string"
            or type(definition) ~= "table"
            or definition.id ~= moodId
            or type(definition.label) ~= "string"
            or definition.label == ""
            or not isInteger(definition.order, 1) then
            return nil, makeError("unknown_mood", path, "공개 무드 라벨을 확인할 수 없습니다.")
        end
        return definition, nil
    end

    local function hasMechanism(card, mechanismId)
        local count = getArrayLength(type(card) == "table" and card.mechanisms or nil)
        if count == nil then return false end
        for index = 1, count do
            if card.mechanisms[index] == mechanismId then return true end
        end
        return false
    end

    local function lookupCardName(staticData, cardId, owner, path, requirePlan)
        local card = staticData.cards[cardId]
        if type(cardId) ~= "string"
            or type(card) ~= "table"
            or card.id ~= cardId
            or card.owner ~= owner
            or type(card.name) ~= "string"
            or card.name == ""
            or (requirePlan == true and not hasMechanism(card, "plan")) then
            return nil, nil, makeError("unknown_public_card", path, "공개할 카드 라벨을 확인할 수 없습니다.")
        end
        return card.name, card, nil
    end

    local function buildEffectSource(source, staticData, path)
        local keyError = checkAllowedKeys(source, {
            kind = true,
            id = true,
            side = true,
        }, path)
        if keyError then return nil, keyError end

        local collectionName = SOURCE_COLLECTIONS[source.kind]
        local collection = collectionName and staticData[collectionName] or nil
        local definition = type(collection) == "table" and collection[source.id] or nil
        if not isAsciiId(source.id)
            or type(definition) ~= "table"
            or definition.id ~= source.id then
            return nil, makeError("unknown_effect_source", path, "효과 원인의 공개 정보를 확인할 수 없습니다.")
        end

        if source.kind == "environment" then
            if source.side ~= nil then
                return nil, makeError("invalid_effect_source_side", path .. ".side", "환경 효과 원인에는 진영이 없어야 합니다.")
            end
        else
            local owner = definition.owner
            if source.kind == "perk" and owner == nil then owner = "player" end
            if not isSide(source.side) or owner ~= source.side then
                return nil, makeError("invalid_effect_source_side", path .. ".side", "효과 원인과 진영이 일치하지 않습니다.")
            end
        end
        if source.kind == "plan" and not hasMechanism(definition, "plan") then
            return nil, makeError("invalid_plan_source", path, "계획 효과 원인이 계획 카드가 아닙니다.")
        end
        if type(definition.name) ~= "string" or definition.name == ""
            or type(definition.description) ~= "string" or definition.description == "" then
            return nil, makeError("invalid_effect_source_detail", path, "효과 원인의 이름과 설명이 필요합니다.")
        end
        local ruleCount = getArrayLength(definition.rules)
        if ruleCount == nil or ruleCount == 0 then
            return nil, makeError("invalid_effect_source_rules", path, "효과 원인의 규칙 목록이 올바르지 않습니다.")
        end

        local rules = {}
        for index = 1, ruleCount do
            if type(definition.rules[index]) ~= "string" or definition.rules[index] == "" then
                return nil, makeError("invalid_effect_source_rule", path, "효과 원인의 규칙 문장이 올바르지 않습니다.")
            end
            rules[index] = definition.rules[index]
        end
        local tags = {}
        if source.kind == "card" or source.kind == "plan" then
            tags[1] = definition.actionTag
            for _, mechanismId in ipairs(definition.mechanisms or {}) do
                tags[#tags + 1] = mechanismId
            end
        end

        local safe = {
            kind = source.kind,
            name = definition.name,
            description = definition.description,
            rules = rules,
            tags = tags,
        }
        if source.side ~= nil then safe.side = source.side end
        return safe, nil
    end

    local function summary(sequence, eventType, text)
        return {
            sequence = sequence,
            type = eventType,
            text = text,
        }
    end

    local function validateResourceEffect(payload, path, spec, staticData)
        local keyError = checkAllowedKeys(payload, {
            op = true,
            target = true,
            changed = true,
            amount = true,
            before = true,
            after = true,
            source = true,
        }, path)
        if keyError then return nil, keyError end
        if payload.target ~= spec.target
            or type(payload.changed) ~= "boolean"
            or not isFinite(payload.amount)
            or payload.amount < 0
            or not isFinite(payload.before)
            or not isFinite(payload.after)
            or payload.after ~= payload.before + spec.direction * payload.amount
            or payload.changed ~= (payload.before ~= payload.after) then
            return nil, makeError("invalid_effect_payload", path, "자원 변화 표시값이 서로 일치하지 않습니다.")
        end
        local source = nil
        if payload.changed == true and payload.amount > 0 then
            local sourceError
            source, sourceError = buildEffectSource(payload.source, staticData, path .. ".source")
            if sourceError then return nil, sourceError end
        elseif payload.source ~= nil then
            return nil, makeError("unexpected_effect_source", path .. ".source", "변화가 없는 자원 효과에는 원인 상세정보를 넣을 수 없습니다.")
        end
        local verb = spec.direction < 0 and "감소" or "회복"
        local text = spec.noun .. "이(가) " .. numberText(payload.amount) .. " " .. verb .. "했습니다. ("
            .. numberText(payload.before) .. " → " .. numberText(payload.after) .. ")"
        if payload.changed ~= true then
            text = spec.noun .. "에 변화가 없습니다. (" .. numberText(payload.before) .. ")"
        end
        return text, nil, source
    end

    local function validateEffect(payload, path, staticData)
        if type(payload) ~= "table" or getmetatable(payload) ~= nil then
            return nil, makeError("invalid_effect_payload", path, "효과 표시값이 일반 객체가 아닙니다.")
        end
        local spec = RESOURCE_EFFECTS[payload.op]
        if spec then
            return validateResourceEffect(payload, path, spec, staticData)
        elseif payload.op == "draw_cards" then
            local keyError = checkAllowedKeys(payload, {
                op = true,
                target = true,
                changed = true,
                requested = true,
                drawnCount = true,
            }, path)
            if keyError then return nil, keyError end
            if not isSide(payload.target)
                or type(payload.changed) ~= "boolean"
                or not isInteger(payload.requested, 1)
                or not isInteger(payload.drawnCount, 0)
                or payload.drawnCount > payload.requested
                or payload.changed ~= (payload.drawnCount > 0) then
                return nil, makeError("invalid_effect_payload", path, "드로우 표시값이 서로 일치하지 않습니다.")
            end
            return sideLabel(payload.target) .. "가 카드 " .. tostring(payload.drawnCount)
                .. "장을 더 뽑았습니다. (요청 " .. tostring(payload.requested) .. "장)", nil
        elseif payload.op == "skip_actions" then
            local keyError = checkAllowedKeys(payload, {
                op = true,
                target = true,
                changed = true,
                scope = true,
                before = true,
                after = true,
            }, path)
            if keyError then return nil, keyError end
            if not isSide(payload.target)
                or type(payload.changed) ~= "boolean"
                or payload.scope ~= "remainingTurn"
                or type(payload.before) ~= "boolean"
                or payload.after ~= true
                or payload.changed ~= (payload.before ~= true) then
                return nil, makeError("invalid_effect_payload", path, "행동 생략 표시값이 서로 일치하지 않습니다.")
            end
            if payload.changed then
                return sideLabel(payload.target) .. "의 이번 턴 남은 행동이 생략됩니다.", nil
            end
            return sideLabel(payload.target) .. "의 남은 행동은 이미 생략된 상태입니다.", nil
        elseif payload.op == "add_mood_token" or payload.op == "remove_mood_token" then
            local keyError = checkAllowedKeys(payload, {
                op = true,
                target = true,
                changed = true,
                mood = true,
                amount = true,
                before = true,
                after = true,
            }, path)
            if keyError then return nil, keyError end
            local mood, moodError = lookupMood(staticData, payload.mood, path .. ".mood")
            if moodError then return nil, moodError end
            if payload.target ~= "character"
                or not isInteger(payload.amount, 1)
                or not isInteger(payload.before, 0)
                or not isInteger(payload.after, 0)
                or payload.after ~= (payload.op == "add_mood_token"
                    and payload.before + payload.amount
                    or math.max(0, payload.before - payload.amount))
                or payload.changed ~= (payload.before ~= payload.after) then
                return nil, makeError("invalid_effect_payload", path, "무드 토큰 표시값이 서로 일치하지 않습니다.")
            end
            local verb = payload.op == "add_mood_token" and "생성했습니다" or "제거했습니다"
            return mood.label .. " 토큰을 " .. numberText(payload.amount) .. "개 " .. verb .. ". ("
                .. numberText(payload.before) .. " → " .. numberText(payload.after) .. ")", nil
        elseif payload.op == "force_mood" then
            local keyError = checkAllowedKeys(payload, {
                op = true,
                target = true,
                changed = true,
                mood = true,
                before = true,
                after = true,
            }, path)
            if keyError then return nil, keyError end
            local mood, moodError = lookupMood(staticData, payload.mood, path .. ".mood")
            if moodError then return nil, moodError end
            if payload.target ~= "character"
                or payload.changed ~= true
                or not isInteger(payload.before, 0)
                or payload.after ~= payload.before + 1 then
                return nil, makeError("invalid_effect_payload", path, "무드 강제 변경 요청 표시값이 서로 일치하지 않습니다.")
            end
            return "턴 종료 시 " .. mood.label .. "(으)로 강제 변경하는 효과가 발생했습니다.", nil
        end
        return nil, makeError("unsupported_effect_op", path .. ".op", "공개 표시를 지원하지 않는 효과입니다.")
    end

    local function presentEvent(event, index, turnNumber, staticData)
        local path = "$.pendingTurn.turnResult.publicResult.events[" .. index .. "]"
        local eventError = checkAllowedKeys(event, { sequence = true, type = true, payload = true }, path)
        if eventError then return nil, eventError end
        if event.sequence ~= index then
            return nil, makeError("event_sequence_mismatch", path .. ".sequence", "공개 사건 순번이 연속적이지 않습니다.")
        end
        if VALID_EVENT_TYPES[event.type] ~= true then
            return nil, makeError("unknown_public_event", path .. ".type", "표시 허용 목록에 없는 공개 사건입니다.")
        end
        local payload = event.payload
        if type(payload) ~= "table" or getmetatable(payload) ~= nil then
            return nil, makeError("invalid_public_payload", path .. ".payload", "공개 사건 payload가 일반 객체가 아닙니다.")
        end
        local payloadPath = path .. ".payload"

        if event.type == "turn_mode" then
            local keyError = checkAllowedKeys(payload, { mode = true }, payloadPath)
            if keyError then return nil, keyError end
            if VALID_MODES[payload.mode] ~= true then
                return nil, makeError("invalid_turn_mode", payloadPath .. ".mode", "표시할 턴 모드가 올바르지 않습니다.")
            end
            local texts = {
                pass = "카드를 사용하지 않고 턴을 넘겼습니다.",
                chain_pass = "연계 행동만 사용하고 턴을 넘겼습니다.",
                action = "등록한 카드 행동을 실행했습니다.",
            }
            return summary(index, event.type, texts[payload.mode]), nil
        elseif event.type == "turn_started" then
            local keyError = checkAllowedKeys(payload, { turnNumber = true }, payloadPath)
            if keyError then return nil, keyError end
            if not isInteger(payload.turnNumber, 1) or payload.turnNumber ~= turnNumber then
                return nil, makeError("turn_number_mismatch", payloadPath .. ".turnNumber", "시작 사건의 턴 번호가 저장된 턴과 다릅니다.")
            end
            return summary(index, event.type, tostring(turnNumber) .. "턴이 시작되었습니다."), nil
        elseif event.type == "player_cards_drawn" then
            local keyError = checkAllowedKeys(payload, { requested = true, drawnCount = true }, payloadPath)
            if keyError then return nil, keyError end
            if not isInteger(payload.requested, 0)
                or not isInteger(payload.drawnCount, 0)
                or payload.drawnCount > payload.requested then
                return nil, makeError("invalid_draw_summary", payloadPath, "턴 시작 드로우 수치가 올바르지 않습니다.")
            end
            return summary(index, event.type, "플레이어가 턴 시작에 카드 " .. tostring(payload.drawnCount)
                .. "장을 뽑았습니다. (요청 " .. tostring(payload.requested) .. "장)"), nil
        elseif event.type == "character_intent" then
            local allowed = { selected = true, actionTag = true }
            local keyError = checkAllowedKeys(payload, allowed, payloadPath)
            if keyError then return nil, keyError end
            if type(payload.selected) ~= "boolean"
                or (payload.selected == false and payload.actionTag ~= nil)
                or (payload.selected == true and payload.actionTag == nil) then
                return nil, makeError("invalid_character_intent", payloadPath, "캐릭터 의도 공개값이 올바르지 않습니다.")
            end
            if payload.selected == false then
                return summary(index, event.type, "상대는 이번 턴에 카드 행동을 준비하지 못했습니다."), nil
            end
            local label, labelError = lookupActionLabel(staticData, payload.actionTag, "character", payloadPath .. ".actionTag")
            if labelError then return nil, labelError end
            return summary(index, event.type, "상대는 " .. label .. " 행동을 준비했습니다."), nil
        elseif event.type == "card_declared" then
            local keyError = checkAllowedKeys(payload, {
                side = true,
                actionTag = true,
                stealthCost = true,
                cardId = true,
                effectChoiceId = true,
            }, payloadPath)
            if keyError then return nil, keyError end
            if not isSide(payload.side) or not isFinite(payload.stealthCost) or payload.stealthCost < 0 then
                return nil, makeError("invalid_card_declaration", payloadPath, "카드 선언 표시값이 올바르지 않습니다.")
            end
            local tagLabel, tagError = lookupActionLabel(staticData, payload.actionTag, payload.side, payloadPath .. ".actionTag")
            if tagError then return nil, tagError end
            if payload.side == "character" then
                if payload.cardId ~= nil or payload.stealthCost ~= 0 then
                    return nil, makeError("character_card_identity_exposed", payloadPath, "캐릭터 일반 카드의 정체를 공개할 수 없습니다.")
                end
                return summary(index, event.type, "상대가 " .. tagLabel .. " 행동을 실행했습니다."), nil
            end
            if payload.cardId == nil then
                return nil, makeError("missing_player_card_identity", payloadPath .. ".cardId", "플레이어 카드 표시명이 필요합니다.")
            end
            local cardName, card, cardError = lookupCardName(staticData, payload.cardId, "player", payloadPath .. ".cardId", false)
            if cardError then return nil, cardError end
            if card.actionTag ~= payload.actionTag then
                return nil, makeError("card_action_mismatch", payloadPath .. ".actionTag", "카드와 공개 행동 태그가 다릅니다.")
            end
            local choiceLabel = nil
            if type(card.effectChoices) == "table" then
                for _, choice in ipairs(card.effectChoices) do
                    if choice.id == payload.effectChoiceId then choiceLabel = choice.label end
                end
                if choiceLabel == nil then
                    return nil, makeError("missing_effect_choice", payloadPath .. ".effectChoiceId", "선택형 카드의 효과 선택값이 올바르지 않습니다.")
                end
            elseif payload.effectChoiceId ~= nil then
                return nil, makeError("unexpected_effect_choice", payloadPath .. ".effectChoiceId", "일반 카드에 효과 선택값이 있습니다.")
            end
            return summary(index, event.type, "플레이어가 ‘" .. cardName .. "’(" .. tagLabel
                .. ")을(를) 사용했습니다."
                .. (choiceLabel and (" 선택 효과: " .. choiceLabel .. ".") or "")
                .. " 은폐 비용 " .. numberText(payload.stealthCost) .. "."), nil
        elseif event.type == "effect_applied" then
            local text, effectError, source = validateEffect(payload, payloadPath, staticData)
            if effectError then return nil, effectError end
            local resourceChange = nil
            local spec = RESOURCE_EFFECTS[payload.op]
            if spec and payload.changed == true and payload.amount > 0 then
                resourceChange = {
                    sequence = index,
                    resource = spec.resource,
                    amount = spec.direction * payload.amount,
                    source = source,
                }
            end
            return summary(index, event.type, text), nil, resourceChange
        elseif event.type == "trigger_suppressed" then
            local keyError = checkAllowedKeys(payload, {
                side = true,
                reasonCode = true,
                identityKnown = true,
                cardId = true,
                slotIndex = true,
            }, payloadPath)
            if keyError then return nil, keyError end
            if not isSide(payload.side)
                or payload.reasonCode ~= "insight"
                or payload.identityKnown ~= true
                or payload.cardId == nil
                or not isInteger(payload.slotIndex, 1)
                or payload.slotIndex > MAX_PLAN_SLOTS then
                return nil, makeError("invalid_trigger_suppression", payloadPath, "공개 억제 사건이 알려진 계획과 일치하지 않습니다.")
            end
            local cardName, _, cardError = lookupCardName(staticData, payload.cardId, payload.side, payloadPath .. ".cardId", true)
            if cardError then return nil, cardError end
            return summary(index, event.type, sideLabel(payload.side) .. "의 " .. tostring(payload.slotIndex)
                .. "번 계획 ‘" .. cardName .. "’ 발동이 간파로 억제되었습니다."), nil
        elseif event.type == "plan_changed" then
            local keyError = checkAllowedKeys(payload, {
                side = true,
                action = true,
                identityKnown = true,
                cardId = true,
                remainingTurns = true,
                slotIndex = true,
            }, payloadPath)
            if keyError then return nil, keyError end
            local validActions = { placed = true, triggered = true, replaced = true, expired = true }
            if not isSide(payload.side)
                or validActions[payload.action] ~= true
                or type(payload.identityKnown) ~= "boolean"
                or not isInteger(payload.slotIndex, 1)
                or payload.slotIndex > MAX_PLAN_SLOTS
                or (payload.remainingTurns ~= nil and not isInteger(payload.remainingTurns, 0))
                or (payload.identityKnown == true) ~= (payload.cardId ~= nil)
                or (payload.side == "player" and payload.identityKnown ~= true)
                or (payload.action == "triggered" and payload.identityKnown ~= true)
                or (payload.side == "character" and payload.action == "placed" and payload.identityKnown ~= false)
                or ((payload.action == "replaced" or payload.action == "expired") and payload.remainingTurns ~= nil) then
                return nil, makeError("invalid_plan_change", payloadPath, "계획 변화 공개값이 올바르지 않습니다.")
            end
            local actionTexts = {
                placed = "배치했습니다.",
                triggered = "발동했습니다.",
                replaced = "교체했습니다.",
                expired = "만료되었습니다.",
            }
            local identityText
            if payload.identityKnown then
                local cardName, _, cardError = lookupCardName(staticData, payload.cardId, payload.side, payloadPath .. ".cardId", true)
                if cardError then return nil, cardError end
                identityText = tostring(payload.slotIndex) .. "번 계획 ‘" .. cardName .. "’을(를) "
            else
                identityText = tostring(payload.slotIndex) .. "번 슬롯의 정체가 드러나지 않은 계획을 "
            end
            local text = sideLabel(payload.side) .. "가 " .. identityText .. actionTexts[payload.action]
            if payload.remainingTurns ~= nil then
                text = text .. " (남은 지속 " .. tostring(payload.remainingTurns) .. "턴)"
            end
            return summary(index, event.type, text), nil
        elseif event.type == "actions_stopped" then
            local keyError = checkAllowedKeys(payload, { side = true, reasonCode = true, count = true }, payloadPath)
            if keyError then return nil, keyError end
            local reason = ACTION_STOP_REASONS[payload.reasonCode]
            if not isSide(payload.side) or reason == nil or not isInteger(payload.count, 1) then
                return nil, makeError("invalid_actions_stopped", payloadPath, "행동 중단 공개값이 올바르지 않습니다.")
            end
            return summary(index, event.type, reason .. " " .. sideLabel(payload.side) .. "의 카드 "
                .. tostring(payload.count) .. "장을 처리하지 않았습니다."), nil
        elseif event.type == "card_removed" then
            local keyError = checkAllowedKeys(payload, { side = true, cardId = true }, payloadPath)
            if keyError then return nil, keyError end
            if not isSide(payload.side) then
                return nil, makeError("invalid_card_removed", payloadPath, "카드 제거 공개값이 올바르지 않습니다.")
            end
            if payload.side == "character" then
                if payload.cardId ~= nil then
                    return nil, makeError("character_card_identity_exposed", payloadPath, "캐릭터 일반 카드의 정체를 공개할 수 없습니다.")
                end
                return summary(index, event.type, "상대가 사용한 카드가 이번 전투에서 제거되었습니다."), nil
            end
            if payload.cardId == nil then
                return nil, makeError("missing_player_card_identity", payloadPath .. ".cardId", "제거된 플레이어 카드의 표시명이 필요합니다.")
            end
            local cardName, _, cardError = lookupCardName(staticData, payload.cardId, "player", payloadPath .. ".cardId", false)
            if cardError then return nil, cardError end
            return summary(index, event.type, "플레이어 카드 ‘" .. cardName .. "’이(가) 이번 전투에서 제거되었습니다."), nil
        elseif event.type == "outcome" then
            local keyError = checkAllowedKeys(payload, {
                status = true,
                reasonCode = true,
                stealth = true,
                resistance = true,
            }, payloadPath)
            if keyError then return nil, keyError end
            if (payload.status ~= "victory" and payload.status ~= "defeat")
                or OUTCOME_REASONS[payload.reasonCode] ~= true
                or (payload.reasonCode == "turn_limit" and payload.status ~= "defeat")
                or not isFinite(payload.stealth)
                or not isFinite(payload.resistance) then
                return nil, makeError("invalid_outcome", payloadPath, "승패 공개값이 올바르지 않습니다.")
            end
            local label = payload.status == "victory" and "승리" or "패배"
            return summary(index, event.type, "전투 " .. label .. "가 확정되었습니다. (은폐 "
                .. numberText(payload.stealth) .. ", 저항 " .. numberText(payload.resistance) .. ")"), nil
        elseif event.type == "mood_evaluated" then
            local keyError = checkAllowedKeys(payload, {
                before = true,
                after = true,
                applied = true,
                forcedCount = true,
                forceCancelled = true,
                resolution = true,
                targetMood = true,
                tiedMoods = true,
                tokensBefore = true,
                tokensAfter = true,
            }, payloadPath)
            if keyError then return nil, keyError end
            local beforeMood, beforeError = lookupMood(staticData, payload.before, payloadPath .. ".before")
            local afterMood, afterError = lookupMood(staticData, payload.after, payloadPath .. ".after")
            if beforeError or afterError then return nil, beforeError or afterError end
            if type(payload.applied) ~= "boolean"
                or not isInteger(payload.forcedCount, 0)
                or type(payload.forceCancelled) ~= "boolean"
                or payload.forceCancelled ~= (payload.forcedCount >= 2)
                or type(payload.tokensBefore) ~= "table"
                or type(payload.tokensAfter) ~= "table" then
                return nil, makeError("invalid_mood_evaluation", payloadPath, "무드 평가 공개값이 올바르지 않습니다.")
            end
            local cancelled = payload.forceCancelled and "강제 변경 효과 " .. payload.forcedCount .. "건은 상쇄되었습니다. " or ""
            if payload.resolution == "forced" then
                if payload.forcedCount ~= 1 or payload.forceCancelled or payload.targetMood ~= payload.after then
                    return nil, makeError("invalid_mood_evaluation", payloadPath, "강제 무드 평가의 필드가 서로 모순됩니다.")
                end
                return summary(index, event.type, "강제 변경 효과로 무드가 "
                    .. beforeMood.label .. "에서 " .. afterMood.label .. "(으)로 결정되었습니다. 토큰은 차감하지 않습니다."), nil
            elseif payload.resolution == "token" then
                local targetMood, targetError = lookupMood(staticData, payload.targetMood, payloadPath .. ".targetMood")
                if targetError then return nil, targetError end
                return summary(index, event.type, cancelled .. targetMood.label
                    .. " 토큰이 단독 최다여서 무드를 " .. afterMood.label .. "(으)로 결정하고 해당 토큰을 0으로 만들었습니다."), nil
            elseif payload.resolution == "tie" then
                if type(payload.tiedMoods) ~= "table" or #payload.tiedMoods < 2 or payload.before ~= payload.after then
                    return nil, makeError("invalid_mood_evaluation", payloadPath, "동률 무드 평가의 필드가 서로 모순됩니다.")
                end
                local labels = {}
                for tieIndex, moodId in ipairs(payload.tiedMoods) do
                    local mood, moodError = lookupMood(staticData, moodId, payloadPath .. ".tiedMoods[" .. tieIndex .. "]")
                    if moodError then return nil, moodError end
                    labels[#labels + 1] = mood.label
                end
                return summary(index, event.type, cancelled .. table.concat(labels, ", ")
                    .. " 토큰이 최다 동률이어서 각각 1개 차감하고 무드를 유지했습니다."), nil
            elseif payload.resolution ~= "none" or payload.before ~= payload.after then
                return nil, makeError("invalid_mood_evaluation", payloadPath, "무드 유지 평가의 필드가 서로 모순됩니다.")
            end
            return summary(index, event.type, cancelled .. "3개 이상인 최다 무드 토큰이 없어 "
                .. beforeMood.label .. " 무드를 유지했습니다."), nil
        elseif event.type == "turn_ended" then
            local keyError = checkAllowedKeys(payload, { turnNumber = true }, payloadPath)
            if keyError then return nil, keyError end
            if not isInteger(payload.turnNumber, 1) or payload.turnNumber ~= turnNumber then
                return nil, makeError("turn_number_mismatch", payloadPath .. ".turnNumber", "종료 사건의 턴 번호가 저장된 턴과 다릅니다.")
            end
            return summary(index, event.type, tostring(turnNumber) .. "턴이 종료되었습니다."), nil
        elseif event.type == "session_ended" then
            local keyError = checkAllowedKeys(payload, { status = true }, payloadPath)
            if keyError then return nil, keyError end
            if payload.status ~= "victory" and payload.status ~= "defeat" then
                return nil, makeError("invalid_session_end", payloadPath .. ".status", "세션 종료 상태가 올바르지 않습니다.")
            end
            local label = payload.status == "victory" and "승리" or "패배"
            return summary(index, event.type, "전투가 " .. label .. "로 종료되었습니다."), nil
        end
        return nil, makeError("unknown_public_event", path .. ".type", "표시 허용 목록에 없는 공개 사건입니다.")
    end

    local function buildPresentation(pendingInput, staticInput)
        if pendingInput == nil then
            return success({ available = false })
        end

        local staticData = normalizeStaticData(staticInput)
        if not hasCompleteStaticData(staticData) then
            return failure({ makeError("invalid_static_data", "$.staticData", "전체 정적 데이터가 필요합니다.") })
        end

        local validation, validationErrors = callModule(
            "stateSchema",
            "validatePendingTurn",
            pendingInput,
            staticData
        )
        if validationErrors then return failure(validationErrors) end
        if validation.referencesValidated ~= true or type(validation.value) ~= "table" then
            return failure({ makeError("pending_not_validated", "$.pendingTurn", "pendingTurn의 전체 참조를 검증하지 못했습니다.") })
        end

        local pending = validation.value
        if type(pending.afterState) ~= "table" or pending.afterState.lastCommittedTurnId ~= pending.turnId then
            return failure({ makeError("pending_not_committed", "$.pendingTurn.afterState", "확정 상태에 반영된 pendingTurn만 표시할 수 있습니다.") })
        end
        local turnNumber = type(pending.beforeState) == "table" and pending.beforeState.turnNumber or nil
        if not isInteger(turnNumber, 1) then
            return failure({ makeError("invalid_turn_number", "$.pendingTurn.beforeState.turnNumber", "표시할 턴 번호가 올바르지 않습니다.") })
        end

        local envelope = type(pending.turnResult) == "table" and pending.turnResult.publicResult or nil
        local envelopeError = checkAllowedKeys(envelope, { schemaVersion = true, events = true }, "$.pendingTurn.turnResult.publicResult")
        if envelopeError then return failure({ envelopeError }) end
        if envelope.schemaVersion ~= SCHEMA_VERSION then
            return failure({ makeError("unsupported_public_schema", "$.pendingTurn.turnResult.publicResult.schemaVersion", "지원하지 않는 공개 사건 스키마입니다.") })
        end
        local eventCount = getArrayLength(envelope.events)
        if eventCount == nil then
            return failure({ makeError("invalid_public_events", "$.pendingTurn.turnResult.publicResult.events", "공개 사건은 1부터 이어지는 배열이어야 합니다.") })
        end

        local summaries = {}
        local resourceChanges = {
            stealth = {},
            resistance = {},
        }
        local counts = {}
        local outcomeStatus = nil
        local sessionStatus = nil
        for index = 1, eventCount do
            local event = envelope.events[index]
            local item, eventError, resourceChange = presentEvent(event, index, turnNumber, staticData)
            if eventError then return failure({ eventError }) end
            summaries[index] = item
            if resourceChange ~= nil then
                local entries = resourceChanges[resourceChange.resource]
                entries[#entries + 1] = resourceChange
            end
            counts[event.type] = (counts[event.type] or 0) + 1
            if event.type == "outcome" then outcomeStatus = event.payload.status end
            if event.type == "session_ended" then sessionStatus = event.payload.status end
        end

        for _, eventType in ipairs({
            "turn_mode",
            "turn_started",
            "player_cards_drawn",
            "character_intent",
            "mood_evaluated",
            "turn_ended",
        }) do
            if counts[eventType] ~= 1 then
                return failure({ makeError("required_public_event_count", "$.pendingTurn.turnResult.publicResult.events", "필수 공개 사건의 개수가 올바르지 않습니다.") })
            end
        end
        for _, eventType in ipairs({ "outcome", "session_ended" }) do
            if (counts[eventType] or 0) > 1 then
                return failure({ makeError("duplicate_terminal_event", "$.pendingTurn.turnResult.publicResult.events", "종료 공개 사건이 중복되었습니다.") })
            end
        end
        if outcomeStatus ~= sessionStatus then
            return failure({ makeError("terminal_event_mismatch", "$.pendingTurn.turnResult.publicResult.events", "승패와 세션 종료 공개가 서로 다릅니다.") })
        end
        local afterStatus = pending.afterState.status
        if afterStatus == "active" then
            if outcomeStatus ~= nil or sessionStatus ~= nil then
                return failure({ makeError("active_turn_has_terminal_event", "$.pendingTurn.turnResult.publicResult.events", "계속 중인 전투 턴에 종료 공개가 있습니다.") })
            end
        elseif afterStatus == "victory" or afterStatus == "defeat" then
            if outcomeStatus ~= afterStatus or sessionStatus ~= afterStatus then
                return failure({ makeError("terminal_state_event_mismatch", "$.pendingTurn.turnResult.publicResult.events", "확정 상태와 승패·세션 종료 공개가 서로 다릅니다.") })
            end
        else
            return failure({ makeError("invalid_after_status", "$.pendingTurn.afterState.status", "확정 상태가 올바르지 않습니다.") })
        end

        return success({
            available = true,
            turnNumber = turnNumber,
            summaries = summaries,
            resourceChanges = resourceChanges,
        })
    end

    local arguments = { ... }
    if action == "build" then
        return buildPresentation(arguments[1], arguments[2])
    end
    return failure({
        makeError("unknown_action", "$.action", "지원하지 않는 턴 표시 작업입니다."),
    })
end)

]],
    [[[
turnPromptFormatter
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(message, publicMarker)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            message = message,
            publicMarker = publicMarker,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isSide(value)
        return value == "player" or value == "character"
    end

    local function isDenseArray(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return false
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return false
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        return count == maximum
    end

    local function checkAllowedKeys(value, allowed, path)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return makeError("invalid_object", path, "프롬프트 사건 값은 일반 객체여야 합니다.")
        end
        for key in pairs(value) do
            if type(key) ~= "string" or allowed[key] ~= true then
                return makeError("unexpected_field", path, "프롬프트 허용 목록 밖의 필드가 있습니다.")
            end
        end
        return nil
    end

    local function nestedFailure(prefix, report)
        local errors = {}
        local nested = type(report) == "table" and report.errors or nil
        if type(nested) == "table" and #nested > 0 then
            for _, item in ipairs(nested) do
                local code = type(item) == "table" and item.code or nil
                local path = type(item) == "table" and item.path or nil
                local suffix = type(path) == "string" and path or "$"
                if suffix:sub(1, 1) == "$" then
                    suffix = suffix:sub(2)
                else
                    suffix = "." .. suffix
                end
                errors[#errors + 1] = makeError(
                    type(code) == "string" and code or "nested_validation_failed",
                    prefix .. suffix,
                    "저장된 턴 자료의 하위 검증에 실패했습니다."
                )
            end
        else
            errors[1] = makeError(
                "nested_validation_failed",
                prefix,
                "저장된 턴 자료의 하위 검증에 실패했습니다."
            )
        end
        return errors
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError("runtime_unavailable", "$.runtime", "스크립트 실행기를 찾을 수 없습니다."),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok or type(report) ~= "table" then
            return nil, {
                makeError("module_call_failed", "$.runtime." .. moduleName, "하위 검증 모듈 호출에 실패했습니다."),
            }
        end
        if report.ok ~= true then
            return nil, nestedFailure("$.runtime." .. moduleName, report)
        end
        return report, nil
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function actionTagMatches(staticData, actionTag, actor)
        local tags = type(staticData.registry) == "table" and staticData.registry.actionTags or nil
        local definition = type(tags) == "table" and tags[actionTag] or nil
        return type(definition) == "table"
            and definition.id == actionTag
            and definition.owner == actor
    end

    local function hasMechanism(card, mechanismId)
        for _, currentId in ipairs(type(card) == "table" and type(card.mechanisms) == "table" and card.mechanisms or {}) do
            if currentId == mechanismId then
                return true
            end
        end
        return false
    end

    local function narrationMatches(staticData, payload, narrationKey, planRequired)
        for _, card in pairs(type(staticData.cards) == "table" and staticData.cards or {}) do
            local isPlan = hasMechanism(card, "plan")
            if type(card) == "table"
                and card.owner == payload.actor
                and (planRequired == true) == isPlan
                and (payload.actionTag == nil or card.actionTag == payload.actionTag) then
                local entry = type(card.narration) == "table" and card.narration[narrationKey] or nil
                if type(entry) == "table"
                    and entry.actorAction == payload.actorAction
                    and (payload.actor ~= "character" or entry.actorThought == payload.actorThought)
                    and (payload.actor == "character" or payload.actorThought == nil) then
                    return true
                end
            end
        end
        return false
    end

    local function knownPlanWithoutNarration(staticData, actor, narrationKey)
        for _, card in pairs(type(staticData.cards) == "table" and staticData.cards or {}) do
            if type(card) == "table" and card.owner == actor and hasMechanism(card, "plan") then
                local entry = type(card.narration) == "table" and card.narration[narrationKey] or nil
                if entry == nil then
                    return true
                end
            end
        end
        return false
    end

    local function validateEffect(payload, path, staticData)
        if type(payload) ~= "table" or getmetatable(payload) ~= nil then
            return nil, makeError("invalid_effect", path, "LLM 효과 사건이 일반 객체가 아닙니다.")
        end
        local op = payload.op
        local allowed
        if op == "pay_stealth_cost"
            or op == "damage_resistance"
            or op == "recover_resistance"
            or op == "lose_stealth"
            or op == "recover_stealth" then
            allowed = { op = true, target = true, changed = true, amount = true, before = true, after = true }
        elseif op == "draw_cards" then
            allowed = { op = true, target = true, changed = true, requested = true, drawnCount = true }
        elseif op == "skip_actions" then
            allowed = { op = true, target = true, changed = true, scope = true, before = true, after = true }
        elseif op == "add_mood_token" or op == "remove_mood_token" then
            allowed = { op = true, target = true, changed = true, mood = true, amount = true, before = true, after = true }
        elseif op == "force_mood" then
            allowed = { op = true, target = true, changed = true, mood = true, before = true, after = true }
        else
            return nil, makeError("unsupported_effect_op", path .. ".op", "지원하지 않는 LLM 효과 작업입니다.")
        end

        local keyError = checkAllowedKeys(payload, allowed, path)
        if keyError then
            return nil, keyError
        end
        if not isSide(payload.target) or type(payload.changed) ~= "boolean" then
            return nil, makeError("invalid_effect", path, "효과 대상 또는 changed가 올바르지 않습니다.")
        end
        if payload.changed ~= true then
            return nil, makeError("non_narrative_effect", path, "LLM 사건에는 실제 효과가 있는 작업만 들어갈 수 있습니다.")
        end

        local safe = {
            op = op,
            target = payload.target,
            changed = payload.changed,
        }
        if op == "pay_stealth_cost"
            or op == "damage_resistance"
            or op == "recover_resistance"
            or op == "lose_stealth"
            or op == "recover_stealth" then
            local targets = {
                pay_stealth_cost = "player",
                damage_resistance = "character",
                recover_resistance = "character",
                lose_stealth = "player",
                recover_stealth = "player",
            }
            if payload.target ~= targets[op]
                or not isFinite(payload.amount)
                or payload.amount < 0
                or not isFinite(payload.before)
                or not isFinite(payload.after) then
                return nil, makeError("invalid_effect", path, "자원 효과 값이 올바르지 않습니다.")
            end
            local direction = (op == "recover_resistance" or op == "recover_stealth") and 1 or -1
            if payload.after ~= payload.before + direction * payload.amount
                or payload.changed ~= (payload.before ~= payload.after) then
                return nil, makeError("effect_result_mismatch", path, "자원 효과 결과가 연산과 다릅니다.")
            end
            safe.amount = payload.amount
            safe.before = payload.before
            safe.after = payload.after
        elseif op == "draw_cards" then
            if not isInteger(payload.requested, 1)
                or not isInteger(payload.drawnCount, 1)
                or payload.drawnCount > payload.requested
                or payload.changed ~= true then
                return nil, makeError("invalid_effect", path, "드로우 효과 값이 올바르지 않습니다.")
            end
            safe.requested = payload.requested
            safe.drawnCount = payload.drawnCount
        elseif op == "skip_actions" then
            if payload.scope ~= "remainingTurn"
                or payload.before ~= false
                or payload.after ~= true
                or payload.changed ~= true then
                return nil, makeError("invalid_effect", path, "행동 생략 효과 값이 올바르지 않습니다.")
            end
            safe.scope = payload.scope
            safe.before = false
            safe.after = true
        elseif op == "add_mood_token" or op == "remove_mood_token" then
            local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
            if payload.target ~= "character"
                or type(moods) ~= "table"
                or type(moods[payload.mood]) ~= "table"
                or not isInteger(payload.amount, 1)
                or not isInteger(payload.before, 0)
                or payload.after ~= (op == "add_mood_token"
                    and payload.before + payload.amount
                    or math.max(0, payload.before - payload.amount)) then
                return nil, makeError("invalid_effect", path, "무드 토큰 효과 값이 올바르지 않습니다.")
            end
            safe.mood = payload.mood
            safe.amount = payload.amount
            safe.before = payload.before
            safe.after = payload.after
        elseif op == "force_mood" then
            local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
            if payload.target ~= "character"
                or type(moods) ~= "table"
                or type(moods[payload.mood]) ~= "table"
                or not isInteger(payload.before, 0)
                or payload.after ~= payload.before + 1 then
                return nil, makeError("invalid_effect", path, "무드 강제 변경 요청 값이 올바르지 않습니다.")
            end
            safe.mood = payload.mood
            safe.before = payload.before
            safe.after = payload.after
        end
        return safe, nil
    end

    local function validateLlmPayload(eventType, payload, path, staticData, pending)
        if eventType == "turn_mode" then
            local keyError = checkAllowedKeys(payload, { mode = true }, path)
            if keyError then return nil, keyError end
            if payload.mode ~= "pass" and payload.mode ~= "chain_pass" and payload.mode ~= "action" then
                return nil, makeError("invalid_turn_mode", path .. ".mode", "턴 mode가 올바르지 않습니다.")
            end
            if type(pending.projectionReceipt) ~= "table" or payload.mode ~= pending.projectionReceipt.mode then
                return nil, makeError("turn_mode_mismatch", path .. ".mode", "LLM 턴 mode가 projection 영수증과 다릅니다.")
            end
            return { mode = payload.mode }, nil
        elseif eventType == "turn_context" then
            local keyError = checkAllowedKeys(payload, { turnNumber = true }, path)
            if keyError then return nil, keyError end
            if not isInteger(payload.turnNumber, 1) or payload.turnNumber ~= pending.beforeState.turnNumber then
                return nil, makeError("turn_context_mismatch", path .. ".turnNumber", "LLM 턴 번호가 권위 상태와 다릅니다.")
            end
            return { turnNumber = payload.turnNumber }, nil
        elseif eventType == "character_intent" then
            local keyError = checkAllowedKeys(payload, { selected = true, actionTag = true }, path)
            if keyError then return nil, keyError end
            if type(payload.selected) ~= "boolean" then
                return nil, makeError("invalid_character_intent", path, "캐릭터 의도 선택 여부가 올바르지 않습니다.")
            end
            local expectedTag = pending.beforeState.characterIntent.publicActionTag
            if payload.selected == true then
                if not actionTagMatches(staticData, payload.actionTag, "character") or payload.actionTag ~= expectedTag then
                    return nil, makeError("character_intent_mismatch", path, "캐릭터 공개 행동 태그가 권위 상태와 다릅니다.")
                end
                return { selected = true, actionTag = payload.actionTag }, nil
            end
            if payload.actionTag ~= nil or expectedTag ~= nil then
                return nil, makeError("character_intent_mismatch", path, "선택하지 않은 캐릭터 의도에 행동 태그가 있습니다.")
            end
            return { selected = false }, nil
        elseif eventType == "effect_applied" then
            return validateEffect(payload, path, staticData)
        elseif eventType == "action" then
            local keyError = checkAllowedKeys(payload, {
                actor = true,
                action = true,
                identityKnown = true,
                actionTag = true,
                actorAction = true,
                actorThought = true,
            }, path)
            if keyError then return nil, keyError end
            if not isSide(payload.actor)
                or payload.action ~= "played"
                or payload.identityKnown ~= true
                or not actionTagMatches(staticData, payload.actionTag, payload.actor)
                or type(payload.actorAction) ~= "string"
                or payload.actorAction == ""
                or (payload.actor == "player" and payload.actorThought ~= nil)
                or (payload.actorThought ~= nil and (type(payload.actorThought) ~= "string" or payload.actorThought == ""))
                or not narrationMatches(staticData, payload, "play", false) then
                return nil, makeError("invalid_action_narration", path, "행동 narration이 검증된 카드 데이터와 다릅니다.")
            end
            local safe = {
                actor = payload.actor,
                action = "played",
                identityKnown = true,
                actionTag = payload.actionTag,
                actorAction = payload.actorAction,
            }
            if payload.actorThought ~= nil then safe.actorThought = payload.actorThought end
            return safe, nil
        elseif eventType == "plan" then
            local keyError = checkAllowedKeys(payload, {
                actor = true,
                action = true,
                identityKnown = true,
                actorAction = true,
                actorThought = true,
            }, path)
            if keyError then return nil, keyError end
            local actionNames = { placed = true, triggered = true, replaced = true, expired = true }
            if not isSide(payload.actor)
                or actionNames[payload.action] ~= true
                or type(payload.identityKnown) ~= "boolean"
                or (payload.actor == "player" and payload.identityKnown ~= true)
                or (payload.actor == "player" and payload.actorThought ~= nil)
                or (payload.actorThought ~= nil and (type(payload.actorThought) ~= "string" or payload.actorThought == "")) then
                return nil, makeError("invalid_plan_event", path, "계획 narration 사건이 올바르지 않습니다.")
            end
            if payload.identityKnown ~= true then
                if payload.actorAction ~= nil or payload.actorThought ~= nil then
                    return nil, makeError("hidden_plan_narration", path, "숨은 계획에 카드별 narration이 있습니다.")
                end
            else
                local narrationKeys = {
                    placed = "planPlaced",
                    triggered = "planTriggered",
                    replaced = "planExpired",
                    expired = "planExpired",
                }
                local key = narrationKeys[payload.action]
                if payload.actorAction ~= nil then
                    if type(payload.actorAction) ~= "string"
                        or payload.actorAction == ""
                        or not narrationMatches(staticData, payload, key, true) then
                        return nil, makeError("invalid_plan_narration", path, "계획 narration이 검증된 카드 데이터와 다릅니다.")
                    end
                elseif (payload.action == "placed" or payload.action == "triggered")
                    or not knownPlanWithoutNarration(staticData, payload.actor, key) then
                    return nil, makeError("missing_plan_narration", path, "알려진 계획 사건에 필요한 narration이 없습니다.")
                end
            end
            local safe = {
                actor = payload.actor,
                action = payload.action,
                identityKnown = payload.identityKnown,
            }
            if payload.actorAction ~= nil then safe.actorAction = payload.actorAction end
            if payload.actorThought ~= nil then safe.actorThought = payload.actorThought end
            return safe, nil
        elseif eventType == "plan_suppressed" then
            local keyError = checkAllowedKeys(payload, { actor = true, reasonCode = true, identityKnown = true }, path)
            if keyError then return nil, keyError end
            if not isSide(payload.actor) or not isAsciiId(payload.reasonCode) or payload.identityKnown ~= true then
                return nil, makeError("invalid_plan_suppression", path, "계획 억제 사건이 올바르지 않습니다.")
            end
            return {
                actor = payload.actor,
                reasonCode = payload.reasonCode,
                identityKnown = true,
            }, nil
        elseif eventType == "actions_stopped" then
            local keyError = checkAllowedKeys(payload, { side = true, reasonCode = true, count = true }, path)
            if keyError then return nil, keyError end
            if not isSide(payload.side) or not isAsciiId(payload.reasonCode) or not isInteger(payload.count, 1) then
                return nil, makeError("invalid_actions_stopped", path, "행동 중단 사건이 올바르지 않습니다.")
            end
            return { side = payload.side, reasonCode = payload.reasonCode, count = payload.count }, nil
        elseif eventType == "outcome" then
            local keyError = checkAllowedKeys(payload, { status = true, reasonCode = true }, path)
            if keyError then return nil, keyError end
            if (payload.status ~= "victory" and payload.status ~= "defeat")
                or not isAsciiId(payload.reasonCode)
                or payload.status ~= pending.afterState.status then
                return nil, makeError("outcome_mismatch", path, "승패 사건이 확정 상태와 다릅니다.")
            end
            return { status = payload.status, reasonCode = payload.reasonCode }, nil
        elseif eventType == "mood_changed" then
            local keyError = checkAllowedKeys(payload, { before = true, after = true, resolution = true }, path)
            if keyError then return nil, keyError end
            local moods = type(staticData.registry) == "table" and staticData.registry.moods or nil
            if type(moods) ~= "table"
                or type(moods[payload.before]) ~= "table"
                or type(moods[payload.after]) ~= "table"
                or (payload.resolution ~= "forced" and payload.resolution ~= "token")
                or payload.before == payload.after then
                return nil, makeError("invalid_mood_change", path, "무드 변화 사건이 올바르지 않습니다.")
            end
            return { before = payload.before, after = payload.after, resolution = payload.resolution }, nil
        elseif eventType == "session_ended" then
            local keyError = checkAllowedKeys(payload, { status = true }, path)
            if keyError then return nil, keyError end
            if (payload.status ~= "victory" and payload.status ~= "defeat")
                or payload.status ~= pending.afterState.status then
                return nil, makeError("session_outcome_mismatch", path, "세션 종료 사건이 확정 상태와 다릅니다.")
            end
            return { status = payload.status }, nil
        end
        return nil, makeError("unknown_llm_event", path, "지원하지 않는 LLM 사건입니다.")
    end

    local function validateLlmEvent(envelope, staticData, pending)
        local envelopeError = checkAllowedKeys(envelope, { schemaVersion = true, events = true }, "$.pendingTurn.turnResult.llmEvent")
        if envelopeError then return nil, { envelopeError } end
        if envelope.schemaVersion ~= SCHEMA_VERSION or not isDenseArray(envelope.events) then
            return nil, {
                makeError("invalid_llm_envelope", "$.pendingTurn.turnResult.llmEvent", "LLM 사건 envelope가 올바르지 않습니다."),
            }
        end

        local sanitized = { schemaVersion = SCHEMA_VERSION, events = {} }
        local seenMode = false
        local seenContext = false
        local seenIntent = false
        local seenOutcome = false
        local seenSessionEnd = false
        for index, event in ipairs(envelope.events) do
            local path = "$.pendingTurn.turnResult.llmEvent.events[" .. index .. "]"
            local eventError = checkAllowedKeys(event, { sequence = true, type = true, payload = true }, path)
            if eventError then return nil, { eventError } end
            if event.sequence ~= index or not isAsciiId(event.type) then
                return nil, { makeError("invalid_llm_event", path, "LLM 사건 sequence 또는 type이 올바르지 않습니다.") }
            end
            if index == 1 and event.type ~= "turn_mode" then
                return nil, { makeError("missing_turn_mode", path, "첫 LLM 사건은 turn_mode여야 합니다.") }
            end
            if index == 2 and event.type ~= "turn_context" then
                return nil, { makeError("missing_turn_context", path, "두 번째 LLM 사건은 turn_context여야 합니다.") }
            end
            if event.type == "turn_mode" then
                if seenMode then return nil, { makeError("duplicate_turn_mode", path, "turn_mode가 중복되었습니다.") } end
                seenMode = true
            elseif event.type == "turn_context" then
                if seenContext then return nil, { makeError("duplicate_turn_context", path, "turn_context가 중복되었습니다.") } end
                seenContext = true
            elseif event.type == "character_intent" then
                if seenIntent then return nil, { makeError("duplicate_character_intent", path, "character_intent가 중복되었습니다.") } end
                seenIntent = true
            elseif event.type == "outcome" then
                if seenOutcome then return nil, { makeError("duplicate_outcome", path, "outcome이 중복되었습니다.") } end
                seenOutcome = true
            elseif event.type == "session_ended" then
                if seenSessionEnd or index ~= #envelope.events then
                    return nil, { makeError("invalid_session_end", path, "session_ended는 한 번만 마지막에 있어야 합니다.") }
                end
                seenSessionEnd = true
            end

            local safePayload, payloadError = validateLlmPayload(
                event.type,
                event.payload,
                path .. ".payload",
                staticData,
                pending
            )
            if payloadError then return nil, { payloadError } end
            sanitized.events[index] = {
                sequence = index,
                type = event.type,
                payload = safePayload,
            }
        end

        if not seenMode or not seenContext or not seenIntent then
            return nil, {
                makeError("missing_required_llm_event", "$.pendingTurn.turnResult.llmEvent.events", "필수 턴 문맥 사건이 없습니다."),
            }
        end
        local ended = pending.afterState.status ~= "active"
        if ended ~= seenOutcome or ended ~= seenSessionEnd then
            return nil, {
                makeError("llm_outcome_mismatch", "$.pendingTurn.turnResult.llmEvent.events", "LLM 종료 사건과 확정 상태가 다릅니다."),
            }
        end
        return sanitized, nil
    end

    local function encodeString(value)
        local parts = { '"' }
        for index = 1, #value do
            local byte = string.byte(value, index)
            if byte == 34 then
                parts[#parts + 1] = '\\"'
            elseif byte == 92 then
                parts[#parts + 1] = "\\\\"
            elseif byte == 8 then
                parts[#parts + 1] = "\\b"
            elseif byte == 12 then
                parts[#parts + 1] = "\\f"
            elseif byte == 10 then
                parts[#parts + 1] = "\\n"
            elseif byte == 13 then
                parts[#parts + 1] = "\\r"
            elseif byte == 9 then
                parts[#parts + 1] = "\\t"
            elseif byte < 32 then
                parts[#parts + 1] = string.format("\\u%04X", byte)
            else
                parts[#parts + 1] = string.char(byte)
            end
        end
        parts[#parts + 1] = '"'
        return table.concat(parts)
    end

    local encodeCanonical
    encodeCanonical = function(value)
        local valueType = type(value)
        if valueType == "string" then return encodeString(value) end
        if valueType == "boolean" then return value and "true" or "false" end
        if valueType == "number" then
            local encoded = string.format("%.17g", value)
            return encoded == "-0" and "0" or encoded
        end
        if valueType ~= "table" then error("unsupported canonical value") end

        local numeric = false
        local strings = false
        local maximum = 0
        local count = 0
        local keys = {}
        for key in pairs(value) do
            if type(key) == "number" then
                numeric = true
                maximum = math.max(maximum, key)
                count = count + 1
            elseif type(key) == "string" then
                strings = true
                keys[#keys + 1] = key
            else
                error("unsupported canonical key")
            end
        end
        if numeric and strings then error("mixed canonical table") end
        local parts = {}
        if numeric then
            if count ~= maximum then error("sparse canonical array") end
            for index = 1, maximum do parts[index] = encodeCanonical(value[index]) end
            return "[" .. table.concat(parts, ",") .. "]"
        end
        table.sort(keys)
        for _, key in ipairs(keys) do
            parts[#parts + 1] = encodeString(key) .. ":" .. encodeCanonical(value[key])
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end

    local function formatPending(pendingTurn, staticInput)
        local staticData = normalizeStaticData(staticInput)
        if type(staticData) ~= "table"
            or type(staticData.registry) ~= "table"
            or type(staticData.cards) ~= "table"
            or type(staticData.traits) ~= "table"
            or type(staticData.environments) ~= "table"
            or type(staticData.characters) ~= "table" then
            return failure({ makeError("invalid_static_data", "$.staticData", "전체 정적 데이터가 필요합니다.") })
        end

        local validation, validationErrors = callModule(
            "stateSchema",
            "validatePendingTurn",
            pendingTurn,
            staticData
        )
        if validationErrors then return failure(validationErrors) end
        if validation.referencesValidated ~= true or type(validation.value) ~= "table" then
            return failure({ makeError("pending_not_validated", "$.pendingTurn", "pendingTurn의 전체 참조를 검증하지 못했습니다.") })
        end

        local pending = validation.value
        local replay, replayErrors = callModule(
            "turnDraft",
            "validateProjectionReceipt",
            pending.beforeState,
            staticData,
            pending.projectionReceipt
        )
        if replayErrors then return failure(replayErrors) end
        if type(replay.projection) ~= "table" or type(replay.receipt) ~= "table" then
            return failure({ makeError("projection_not_replayed", "$.pendingTurn.projectionReceipt", "projection 영수증을 재생하지 못했습니다.") })
        end

        local llmEvent = type(pending.turnResult) == "table" and pending.turnResult.llmEvent or nil
        local sanitized, llmErrors = validateLlmEvent(llmEvent, staticData, pending)
        if llmErrors then return failure(llmErrors) end

        local ok, encoded = pcall(encodeCanonical, sanitized)
        if not ok then
            return failure({ makeError("prompt_encoding_failed", "$.pendingTurn.turnResult.llmEvent", "LLM 사건 직렬화에 실패했습니다.") })
        end

        local instructions = {
            "[전투 사건 전달]",
            "기존 프리셋의 문체, 시점, 인물 표현과 응답 형식을 그대로 유지하십시오.",
            "아래 JSON은 이번 응답에 반영해야 하는, 이미 확정된 시간순 사건입니다.",
            "사건의 순서, 행동 주체, 수치 변화, 무드와 승패를 바꾸거나 다시 판정하지 마십시오.",
            "actorAction은 장면 속 실제 행동으로 자연스럽게 반영하고, actorThought가 있을 때만 캐릭터의 내면에 반영하십시오.",
            "type, action, op, reasonCode 같은 기계 필드명을 독자에게 그대로 나열하지 마십시오.",
            "이 지침은 기존 프리셋을 대체하지 않고 이번 턴의 확정 사실만 추가합니다.",
        }
        if pending.beforeState.turnNumber == 1
            and string.find(pending.beforeState.battleId, "-session-", 1, true) then
            local character = staticData.characters[pending.beforeState.character.characterId]
            instructions[#instructions + 1] = "다음 세션의 첫 장면이므로, 경찰에 연행되던 플레이어가 문밖으로 한 발을 내딛는 순간 시야가 검게 끊기며 의식을 잃고, 다시 정신을 차리자 눈앞에 "
                .. character.name .. "이 보이는 모습으로 시작한 뒤 이번 턴 사건을 이어서 묘사하십시오."
        end
        if pending.afterState.status == "defeat" then
            instructions[#instructions + 1] = "패배 장면의 끝에서 경찰이 다가와 플레이어를 연행하는 모습으로 마무리하십시오."
        end
        instructions[#instructions + 1] = "사건 JSON:"
        instructions[#instructions + 1] = encoded
        local content = table.concat(instructions, "\n")

        return success(
            { role = "system", content = content },
            "[전투 턴 " .. tostring(pending.beforeState.turnNumber)
                .. "] 이번 턴에 실제로 벌어진 일을 하나의 장면으로 이어서 묘사한다."
        )
    end

    local arguments = { ... }
    if action == "formatPending" then
        return formatPending(arguments[1], arguments[2])
    end
    return failure({
        makeError("unknown_action", "$.action", "지원하지 않는 턴 프롬프트 작업입니다."),
    })
end)

]],
    [[[
turnResolver
]]] = [[
(function(triggerId, action, ...)
    local SCHEMA_VERSION = 1

    local function makeError(code, path, message)
        return {
            code = code,
            path = path,
            message = message,
        }
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(resolution)
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            resolution = resolution,
        }
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function isDenseArray(value)
        if type(value) ~= "table" or getmetatable(value) ~= nil then
            return false
        end
        local count = 0
        local maximum = 0
        for key in pairs(value) do
            if not isInteger(key, 1) then
                return false
            end
            count = count + 1
            maximum = math.max(maximum, key)
        end
        return count == maximum
    end

    local function cloneData(value, path, active)
        local valueType = type(value)
        if valueType ~= "table" then
            if valueType == "nil"
                or valueType == "string"
                or valueType == "number"
                or valueType == "boolean" then
                if valueType == "number" and not isFinite(value) then
                    return nil, makeError("non_finite_number", path, "유한하지 않은 숫자는 결과 데이터에 복제할 수 없습니다.")
                end
                return value, nil
            end
            return nil, makeError("unsupported_type", path, "결과 데이터에 복제할 수 없는 자료형입니다: " .. valueType)
        end
        if getmetatable(value) ~= nil then
            return nil, makeError("metatable_not_allowed", path, "메타테이블이 있는 값은 결과 데이터에 복제할 수 없습니다.")
        end
        active = active or {}
        if active[value] then
            return nil, makeError("circular_reference", path, "순환 참조는 결과 데이터에 복제할 수 없습니다.")
        end
        active[value] = true
        local copy = {}
        for key, item in pairs(value) do
            local keyCopy, keyError = cloneData(key, path .. ".<key>", active)
            if keyError then
                active[value] = nil
                return nil, keyError
            end
            local itemCopy, itemError = cloneData(item, path .. "." .. tostring(key), active)
            if itemError then
                active[value] = nil
                return nil, itemError
            end
            copy[keyCopy] = itemCopy
        end
        active[value] = nil
        return copy, nil
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function appendErrors(target, source)
        if type(source) ~= "table" then
            table.insert(target, makeError("invalid_nested_error", "$", "하위 모듈 오류 목록이 올바르지 않습니다."))
            return
        end
        for _, item in ipairs(source) do
            table.insert(target, {
                code = tostring(type(item) == "table" and item.code or "nested_error"),
                path = tostring(type(item) == "table" and item.path or "$"),
                message = tostring(type(item) == "table" and item.message or "하위 모듈 작업이 실패했습니다."),
            })
        end
    end

    local function callModule(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                makeError("runtime_unavailable", "$.runtime." .. moduleName, "스크립트 실행기를 찾을 수 없습니다."),
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                makeError(
                    "module_call_error",
                    "$.runtime." .. moduleName,
                    moduleName .. "." .. moduleAction .. " 실행에 실패했습니다: " .. tostring(report)
                ),
            }
        end
        if type(report) ~= "table" then
            return nil, {
                makeError("invalid_module_result", "$.runtime." .. moduleName, "하위 모듈이 테이블 결과를 반환하지 않았습니다."),
            }
        end
        if report.ok ~= true then
            local errors = {}
            appendErrors(errors, report.errors)
            return nil, errors
        end
        return report, nil
    end

    local function findInstance(state, instanceId)
        for _, instance in ipairs(type(state) == "table" and type(state.cardInstances) == "table" and state.cardInstances or {}) do
            if type(instance) == "table" and instance.instanceId == instanceId then
                return instance
            end
        end
        return nil
    end

    local function countZone(state, owner, zone)
        local count = 0
        for _, instance in ipairs(type(state.cardInstances) == "table" and state.cardInstances or {}) do
            if instance.owner == owner and instance.zone == zone then
                count = count + 1
            end
        end
        return count
    end

    local function hasMechanism(card, mechanismId)
        for _, currentId in ipairs(type(card) == "table" and type(card.mechanisms) == "table" and card.mechanisms or {}) do
            if currentId == mechanismId then
                return true
            end
        end
        return false
    end

    local function validateOptions(options, authorityState)
        local errors = {}
        if type(options) ~= "table" or getmetatable(options) ~= nil then
            return nil, { makeError("invalid_options", "$.options", "턴 해결 옵션은 일반 테이블이어야 합니다.") }
        end
        for key in pairs(options) do
            if key ~= "turnId" then
                table.insert(errors, makeError(
                    "unexpected_option",
                    "$.options." .. tostring(key),
                    "지원하지 않는 턴 해결 옵션입니다."
                ))
            end
        end
        if not isRuntimeId(options.turnId) then
            table.insert(errors, makeError("invalid_turn_id", "$.options.turnId", "turnId가 올바르지 않습니다."))
        elseif type(authorityState) == "table" and authorityState.lastCommittedTurnId == options.turnId then
            table.insert(errors, makeError("turn_already_committed", "$.options.turnId", "이미 확정한 turnId를 다시 해결할 수 없습니다."))
        end
        if #errors > 0 then
            return nil, errors
        end
        return { turnId = options.turnId }, nil
    end

    local function buildHistoryContext(history)
        if type(runScript) ~= "function" then
            error("battleHistory.context runtime is unavailable", 0)
        end
        local ok, report = pcall(runScript, triggerId, "battleHistory", "context", history)
        if not ok or type(report) ~= "table" or report.ok ~= true or type(report.context) ~= "table" then
            error("battleHistory.context failed", 0)
        end
        return report.context
    end

    local function buildContext(state, phase, card, instance, plan, effectChoiceId)
        local context = {
            turn = state.turnNumber,
            phase = phase,
            mood = state.character.mood,
            history = buildHistoryContext(state.history),
            player = {
                stealth = state.player.stealth,
                handCount = countZone(state, "player", "hand"),
            },
            character = {
                resistance = state.character.resistance,
                moodTokens = state.character.moodTokens,
                publicActionTag = state.characterIntent.publicActionTag,
            },
        }
        if card ~= nil and instance ~= nil then
            context.card = {
                id = card.id,
                instanceId = instance.instanceId,
                owner = card.owner,
                actionTag = card.actionTag,
            }
        end
        if plan ~= nil then
            context.plan = {
                cardId = plan.cardId,
                cardInstanceId = plan.cardInstanceId,
                side = plan.side,
                revealed = plan.revealed,
            }
            if plan.remainingTurns ~= nil then
                context.plan.remainingTurns = plan.remainingTurns
            end
            if plan.remainingCharges ~= nil then
                context.plan.remainingCharges = plan.remainingCharges
            end
        end
        if effectChoiceId ~= nil then context.effectChoiceId = effectChoiceId end
        return context
    end

    local function resolveTurn(authorityState, staticData, projection, options)
        local normalizedOptions, optionErrors = validateOptions(options, authorityState)
        if optionErrors then
            return failure(optionErrors)
        end
        staticData = normalizeStaticData(staticData)

        local turnStartReceipt = type(authorityState) == "table" and authorityState.turnStartReceipt or nil
        if turnStartReceipt ~= nil then
            if type(turnStartReceipt) ~= "table" or getmetatable(turnStartReceipt) ~= nil then
                return failure({
                    makeError("invalid_turn_start_receipt", "$.authorityState.turnStartReceipt", "turnStartReceipt가 일반 테이블이 아닙니다."),
                })
            end
            if turnStartReceipt.turnId ~= normalizedOptions.turnId then
                return failure({
                    makeError(
                        "receipt_turn_id_mismatch",
                        "$.authorityState.turnStartReceipt.turnId",
                        "turnStartReceipt turnId가 해결할 turnId와 다릅니다."
                    ),
                })
            end
            if turnStartReceipt.turnNumber ~= authorityState.turnNumber then
                return failure({
                    makeError(
                        "receipt_turn_mismatch",
                        "$.authorityState.turnStartReceipt.turnNumber",
                        "turnStartReceipt 턴 번호가 현재 전투 턴과 다릅니다."
                    ),
                })
            end
        end

        local projectionReport, projectionErrors = callModule(
            "turnDraft",
            "validateProjection",
            authorityState,
            staticData,
            projection
        )
        if projectionErrors then
            return failure(projectionErrors)
        end
        local validatedProjection = projectionReport.projection
        if type(validatedProjection) ~= "table" or type(validatedProjection.workingState) ~= "table" then
            return failure({
                makeError("invalid_projection_result", "$.projection", "검증된 projection에 workingState가 없습니다."),
            })
        end

        local workingState, cloneError = cloneData(validatedProjection.workingState, "$.projection.workingState")
        if cloneError then
            return failure({ cloneError })
        end
        local playerSelection, selectionCloneError = cloneData(
            validatedProjection.selectedCardInstanceIds,
            "$.projection.selectedCardInstanceIds"
        )
        if selectionCloneError then
            return failure({ selectionCloneError })
        end
        local playerChoices, choicesCloneError = cloneData(
            validatedProjection.effectChoiceByInstanceId or {},
            "$.projection.effectChoiceByInstanceId"
        )
        if choicesCloneError then return failure({ choicesCloneError }) end
        local characterSelection, characterCloneError = cloneData(
            workingState.characterIntent.cardInstanceIds,
            "$.projection.workingState.characterIntent.cardInstanceIds"
        )
        if characterCloneError then
            return failure({ characterCloneError })
        end
        if not isDenseArray(playerSelection) or not isDenseArray(characterSelection) then
            return failure({ makeError("invalid_selection", "$.projection", "선택 목록이 연속 배열이 아닙니다.") })
        end

        local turnId = normalizedOptions.turnId
        local resolvedTurnNumber = authorityState.turnNumber
        local events = {}
        if turnStartReceipt ~= nil then
            local receiptEvents, receiptEventsError = cloneData(
                turnStartReceipt.events,
                "$.authorityState.turnStartReceipt.events"
            )
            if receiptEventsError then
                return failure({ receiptEventsError })
            end
            if not isDenseArray(receiptEvents) then
                return failure({
                    makeError(
                        "invalid_turn_start_events",
                        "$.authorityState.turnStartReceipt.events",
                        "turnStartReceipt 사건이 연속 배열이 아닙니다."
                    ),
                })
            end
            events = receiptEvents
        end
        local nextResolutionOrdinal = 1
        local transientSeed = {
            skipRemaining = { player = false, character = false },
            forcedMoodRequests = {},
            halted = false,
        }
        if turnStartReceipt ~= nil then
            local receiptTransient, receiptTransientError = cloneData(
                turnStartReceipt.transient,
                "$.authorityState.turnStartReceipt.transient"
            )
            if receiptTransientError then
                return failure({ receiptTransientError })
            end
            transientSeed.skipRemaining = receiptTransient.skipRemaining
            transientSeed.forcedMoodRequests = receiptTransient.forcedMoodRequests
        end
        local working = {
            state = workingState,
            transient = transientSeed,
        }
        local baseline = turnStartReceipt ~= nil and turnStartReceipt.baseline or nil
        local startValues = {
            stealth = baseline ~= nil and baseline.stealth or authorityState.player.stealth,
            resistance = baseline ~= nil and baseline.resistance or authorityState.character.resistance,
            mood = baseline ~= nil and baseline.mood or authorityState.character.mood,
        }

        local function source(kind, id, side, instanceId)
            local value = { kind = kind, id = id }
            if side ~= nil then
                value.side = side
            end
            if instanceId ~= nil then
                value.instanceId = instanceId
            end
            return value
        end

        local function appendEvent(eventType, phase, eventSource, payload, resolutionId, side, cause)
            local sequence = #events + 1
            local event = {
                eventId = turnId .. "-event-" .. string.format("%03d", sequence),
                sequence = sequence,
                type = eventType,
                phase = phase,
                source = eventSource,
            }
            if payload ~= nil then
                event.payload = payload
            end
            if resolutionId ~= nil then
                event.resolutionId = resolutionId
            end
            if side ~= nil then
                event.side = side
            end
            if cause ~= nil then
                event.cause = cause
            end
            events[sequence] = event
            return event
        end

        local function cardSource(card, instance)
            return source("card", card.id, card.owner, instance.instanceId)
        end

        local function resolutionCause(resolutionId)
            return {
                kind = "card_resolution",
                resolutionId = resolutionId,
            }
        end

        local function applyCommands(commands, eventSource, phase, resolutionId, side, causeKind)
            if #commands == 0 then
                return true, nil
            end
            local report, errors = callModule(
                "effectEngine",
                "applyCommands",
                staticData,
                { state = working.state, transient = working.transient },
                commands
            )
            if errors then
                return false, errors
            end
            working.state = report.state
            working.transient = report.transient
            for _, applied in ipairs(report.applied or {}) do
                local payload, payloadError = cloneData(applied, "$.effect.applied")
                if payloadError then
                    return false, { payloadError }
                end
                appendEvent(
                    "effect_applied",
                    phase,
                    eventSource,
                    payload,
                    resolutionId,
                    side,
                    {
                        kind = causeKind,
                        resolutionId = resolutionId,
                    }
                )
            end
            return true, nil
        end

        local function applyCost(card, instance, finalCost, phase, resolutionId)
            local before = working.state.player.stealth
            local after = before - finalCost
            if not isFinite(after) then
                return false, {
                    makeError("non_finite_result", "$.player.stealth", "은폐 비용 적용 결과가 유한하지 않습니다."),
                }
            end
            working.state.player.stealth = after
            appendEvent(
                "effect_applied",
                phase,
                cardSource(card, instance),
                {
                    op = "pay_stealth_cost",
                    target = "player",
                    amount = finalCost,
                    before = before,
                    after = after,
                    changed = before ~= after,
                },
                resolutionId,
                card.owner,
                resolutionCause(resolutionId)
            )
            return true, nil
        end

        local function applyTriggerPipeline(
            inputEvent,
            phase,
            resolutionId,
            currentCard,
            currentInstance,
            insightSide,
            allowGameplayCommands
        )
            local pipelineOptions = { phase = phase }
            if currentCard ~= nil and currentInstance ~= nil then
                pipelineOptions.currentCard = {
                    id = currentCard.id,
                    instanceId = currentInstance.instanceId,
                    owner = currentCard.owner,
                    actionTag = currentCard.actionTag,
                }
                if inputEvent.effectChoiceId ~= nil then
                    pipelineOptions.currentCard.effectChoiceId = inputEvent.effectChoiceId
                end
            end
            if insightSide ~= nil then
                pipelineOptions.insightSide = insightSide
            end
            if allowGameplayCommands == false then
                pipelineOptions.allowGameplayCommands = false
            end

            local pipelineReport, pipelineErrors = callModule(
                "triggerPipeline",
                "run",
                staticData,
                { state = working.state, transient = working.transient },
                inputEvent,
                pipelineOptions
            )
            if pipelineErrors then
                return false, pipelineErrors
            end
            if type(pipelineReport.state) ~= "table"
                or type(pipelineReport.transient) ~= "table"
                or not isDenseArray(pipelineReport.records) then
                return false, {
                    makeError(
                        "invalid_trigger_pipeline_result",
                        "$.runtime.triggerPipeline",
                        "triggerPipeline.run 결과가 올바르지 않습니다."
                    ),
                }
            end

            working.state = pipelineReport.state
            working.transient = pipelineReport.transient
            for index, record in ipairs(pipelineReport.records) do
                local recordCopy, recordError = cloneData(
                    record,
                    "$.runtime.triggerPipeline.records[" .. index .. "]"
                )
                if recordError then
                    return false, { recordError }
                end
                if type(recordCopy) ~= "table"
                    or type(recordCopy.type) ~= "string"
                    or type(recordCopy.source) ~= "table"
                    or type(recordCopy.source.kind) ~= "string" then
                    return false, {
                        makeError(
                            "invalid_trigger_pipeline_record",
                            "$.runtime.triggerPipeline.records[" .. index .. "]",
                            "triggerPipeline record envelope가 올바르지 않습니다."
                        ),
                    }
                end

                local eventCause
                if recordCopy.type == "effect_applied" then
                    eventCause = { kind = recordCopy.source.kind .. "_trigger" }
                    if resolutionId ~= nil then
                        eventCause.resolutionId = resolutionId
                    end
                elseif resolutionId ~= nil then
                    eventCause = resolutionCause(resolutionId)
                else
                    eventCause = { kind = "turn_event" }
                end
                appendEvent(
                    recordCopy.type,
                    phase,
                    recordCopy.source,
                    recordCopy.payload,
                    resolutionId,
                    recordCopy.side,
                    eventCause
                )
            end
            return true, nil
        end

        local function latchOutcome(reasonCode, phase, resolutionId)
            if working.state.status ~= "active" then
                return working.state.status
            end
            local outcome = nil
            if working.state.character.resistance <= 0 then
                outcome = "victory"
            elseif working.state.player.stealth <= 0 then
                outcome = "defeat"
            end
            if outcome ~= nil then
                working.state.status = outcome
                working.transient.halted = true
                working.transient.haltReason = reasonCode
                appendEvent(
                    "outcome_latched",
                    phase,
                    source("system", "turn_resolver"),
                    {
                        status = outcome,
                        reasonCode = reasonCode,
                        stealth = working.state.player.stealth,
                        resistance = working.state.character.resistance,
                    },
                    resolutionId,
                    nil,
                    resolutionId and resolutionCause(resolutionId) or { kind = "turn_rule" }
                )
            end
            return outcome
        end

        local function restorePlayerCards(startIndex, reasonCode, phase, resolutionId)
            local restored = {}
            for index = startIndex, #playerSelection do
                local instanceId = playerSelection[index]
                local instance = findInstance(working.state, instanceId)
                if instance ~= nil and instance.zone == "used" then
                    local card = staticData.cards[instance.cardId]
                    local zoneReport, zoneErrors = callModule("cardZones", "moveUsedToHand", working.state, instanceId)
                    if zoneErrors then
                        return false, zoneErrors
                    end
                    working.state = zoneReport.state
                    restored[#restored + 1] = instanceId
                    appendEvent(
                        "card_restored",
                        phase,
                        source("card", card.id, "player", instanceId),
                        {
                            instanceId = instanceId,
                            reasonCode = reasonCode,
                            destination = "hand",
                        },
                        resolutionId,
                        "player",
                        resolutionId and resolutionCause(resolutionId) or { kind = "action_sequence" }
                    )
                end
            end
            if #restored > 0 then
                appendEvent(
                    "action_sequence_stopped",
                    phase,
                    source("system", "turn_resolver"),
                    {
                        side = "player",
                        reasonCode = reasonCode,
                        restoredInstanceIds = restored,
                    },
                    resolutionId,
                    "player",
                    resolutionId and resolutionCause(resolutionId) or { kind = "turn_rule" }
                )
            end
            return true, nil
        end

        local function recordSequenceStopped(side, selectedIds, startIndex, reasonCode, phase, resolutionId)
            local unresolved = {}
            for index = startIndex, #selectedIds do
                unresolved[#unresolved + 1] = selectedIds[index]
            end
            if #unresolved == 0 then
                return
            end
            appendEvent(
                "action_sequence_stopped",
                phase,
                source("system", "turn_resolver"),
                {
                    side = side,
                    reasonCode = reasonCode,
                    unresolvedInstanceIds = unresolved,
                },
                resolutionId,
                side,
                resolutionId and resolutionCause(resolutionId) or { kind = "turn_rule" }
            )
        end

        local function finishCardZone(card, instance, phase, resolutionId, effectChoiceId)
            local isPlan = hasMechanism(card, "plan")
            local isRemove = hasMechanism(card, "remove")
            if isPlan and isRemove then
                return false, {
                    makeError(
                        "unsupported_mechanism_combination",
                        "$.staticData.cards." .. card.id .. ".mechanisms",
                        "plan과 remove의 동시 완료 영역은 아직 정의되지 않았습니다."
                    ),
                }
            end
            local placesPlan = isPlan
            if effectChoiceId ~= nil then
                for _, choice in ipairs(type(card.effectChoices) == "table" and card.effectChoices or {}) do
                    if choice.id == effectChoiceId and choice.placesPlan == false then placesPlan = false end
                end
            end
            if placesPlan then
                local planData = type(card.mechanismData) == "table" and card.mechanismData.plan or nil
                if type(planData) ~= "table" then
                    return false, { makeError("missing_plan_definition", "$.staticData.cards." .. card.id, "계획 데이터가 없습니다.") }
                end
                local planSpec = { revealed = false }
                if effectChoiceId ~= nil then planSpec.effectChoiceId = effectChoiceId end
                if planData.durationTurns ~= nil then
                    planSpec.durationTurns = planData.durationTurns
                end
                if planData.durationIncludesPlacementTurn ~= nil then
                    planSpec.durationIncludesPlacementTurn = planData.durationIncludesPlacementTurn
                end
                if planData.charges ~= nil then
                    planSpec.charges = planData.charges
                end
                local beforePlanSlots, slotError = cloneData(
                    working.state[card.owner].planSlots,
                    "$.plan.before"
                )
                if slotError then
                    return false, { slotError }
                end
                local zoneReport, zoneErrors = callModule(
                    "cardZones",
                    "placePlan",
                    working.state,
                    card.owner,
                    instance.instanceId,
                    planSpec
                )
                if zoneErrors then
                    return false, zoneErrors
                end
                working.state = zoneReport.state
                local afterPlanSlots
                afterPlanSlots, slotError = cloneData(
                    working.state[card.owner].planSlots,
                    "$.plan.after"
                )
                if slotError then
                    return false, { slotError }
                end
                appendEvent(
                    "plan_changed",
                    phase,
                    cardSource(card, instance),
                    {
                        action = "placed",
                        instanceId = instance.instanceId,
                        before = beforePlanSlots,
                        after = afterPlanSlots,
                        planSpec = planSpec,
                        movedInstanceIds = zoneReport.movedInstanceIds or {},
                    },
                    resolutionId,
                    card.owner,
                    resolutionCause(resolutionId)
                )
            elseif isRemove then
                local origin = instance.zone
                local zoneReport, zoneErrors = callModule("cardZones", "moveToRemoved", working.state, instance.instanceId)
                if zoneErrors then
                    return false, zoneErrors
                end
                working.state = zoneReport.state
                appendEvent(
                    "card_zone_changed",
                    phase,
                    cardSource(card, instance),
                    {
                        instanceId = instance.instanceId,
                        origin = origin,
                        destination = "removed",
                    },
                    resolutionId,
                    card.owner,
                    resolutionCause(resolutionId)
                )
            end
            return true, nil
        end

        local function resolveCard(instanceId, expectedSide, selectionIndex)
            local phase = expectedSide == "player" and "player_card" or "character_card"
            local instance = findInstance(working.state, instanceId)
            if type(instance) ~= "table" then
                return false, { makeError("instance_not_found", "$.selectedCards", "선택 카드 인스턴스를 찾을 수 없습니다.") }
            end
            if instance.owner ~= expectedSide then
                return false, { makeError("card_owner_mismatch", "$.selectedCards", "선택 카드의 소유자가 해결 진영과 다릅니다.") }
            end
            local card = staticData.cards[instance.cardId]
            if type(card) ~= "table" or card.id ~= instance.cardId then
                return false, { makeError("unknown_card", "$.selectedCards", "정적 카드 정의를 찾을 수 없습니다.") }
            end
            if type(card.base) ~= "table"
                or not isFinite(card.base.stealthCost)
                or not isFinite(card.base.resistanceDamage) then
                return false, { makeError("invalid_card_base", "$.staticData.cards." .. card.id .. ".base", "카드 기본 수치가 올바르지 않습니다.") }
            end
            local effectChoiceId = expectedSide == "player" and playerChoices[instanceId] or nil

            local modifierReport, modifierErrors = callModule(
                "effectEngine",
                "validateModifiers",
                instance.temporaryModifiers or {}
            )
            if modifierErrors then
                return false, modifierErrors
            end
            local modifiers = modifierReport.modifiers
            local rawCost = card.base.stealthCost
            local rawDamage = card.base.resistanceDamage
            local finalCost = math.max(0, rawCost)
            local finalDamage = math.max(0, rawDamage)
            if expectedSide == "character" and rawCost ~= 0 then
                return false, {
                    makeError(
                        "unsupported_character_cost",
                        "$.staticData.cards." .. card.id .. ".base.stealthCost",
                        "캐릭터 카드의 은폐 비용은 v1에서 0이어야 합니다."
                    ),
                }
            end
            if expectedSide == "character" and rawDamage ~= 0 then
                return false, {
                    makeError(
                        "unsupported_character_base_damage",
                        "$.staticData.cards." .. card.id .. ".base.resistanceDamage",
                        "캐릭터 카드의 base.resistanceDamage 의미는 v1에서 0으로 제한합니다."
                    ),
                }
            end

            local context = buildContext(working.state, phase, card, instance, nil, effectChoiceId)
            local canPlayReport, canPlayErrors = callModule(
                "effectEngine",
                "evaluateCanPlay",
                staticData,
                card.id,
                context,
                { modifiers = modifiers }
            )
            if canPlayErrors then
                return false, canPlayErrors
            end
            local playable = canPlayReport.playable == true
            local reasonCode = canPlayReport.reasonCode
            if expectedSide == "player" and type(card.effectChoices) == "table" then
                local choiceReport, choiceErrors = callModule(
                    "effectEngine",
                    "evaluateEffectChoice",
                    staticData,
                    card.id,
                    effectChoiceId,
                    context,
                    { modifiers = modifiers }
                )
                if choiceErrors then return false, choiceErrors end
                if choiceReport.selectable ~= true then
                    playable = false
                    reasonCode = choiceReport.reasonCode or "effect_choice_unavailable"
                end
            elseif effectChoiceId ~= nil then
                return false, { makeError("unexpected_effect_choice", "$.projection.effectChoiceByInstanceId", "효과 선택지가 없는 카드에 선택값이 있습니다.") }
            end
            if expectedSide == "player" and working.state.player.stealth <= finalCost then
                playable = false
                reasonCode = "insufficient_stealth"
            end
            if not playable then
                if expectedSide == "player" then
                    local restored, restoreErrors = restorePlayerCards(
                        selectionIndex,
                        reasonCode or "card_unavailable",
                        phase,
                        nil
                    )
                    if not restored then
                        return false, restoreErrors
                    end
                else
                    return false, {
                        makeError(
                            "character_card_unavailable_policy_pending",
                            "$.selectedCards.character[" .. selectionIndex .. "]",
                            "캐릭터 의도가 해결 중 사용 불가가 되었을 때의 후속 행동 정책은 아직 확정되지 않았습니다."
                        ),
                    }
                end
                return true, { declared = false, stopped = true }
            end

            local resolutionId = turnId .. "-resolution-" .. string.format("%03d", nextResolutionOrdinal)
            nextResolutionOrdinal = nextResolutionOrdinal + 1

            if expectedSide == "player" then
                if instance.zone ~= "used" then
                    return false, { makeError("invalid_source_zone", "$.selectedCards.player", "projection의 플레이어 선택 카드는 used에 있어야 합니다.") }
                end
                local paid, paymentErrors = applyCost(card, instance, finalCost, phase, resolutionId)
                if not paid then
                    return false, paymentErrors
                end
            else
                if instance.zone ~= "hand" then
                    return false, { makeError("invalid_source_zone", "$.selectedCards.character", "캐릭터 의도 카드는 선언 전 hand에 있어야 합니다.") }
                end
                local zoneReport, zoneErrors = callModule("cardZones", "moveHandToUsed", working.state, instance.instanceId)
                if zoneErrors then
                    return false, zoneErrors
                end
                working.state = zoneReport.state
                instance = findInstance(working.state, instanceId)
            end

            appendEvent(
                "card_declared",
                phase,
                cardSource(card, instance),
                {
                    cardId = card.id,
                    instanceId = instance.instanceId,
                    finalStealthCost = finalCost,
                    effectChoiceId = effectChoiceId,
                },
                resolutionId,
                expectedSide,
                resolutionCause(resolutionId)
            )

            local declaredInput = {
                type = "card_declared",
                side = expectedSide,
                cardId = card.id,
                cardInstanceId = instance.instanceId,
                actionTag = card.actionTag,
                resolutionId = resolutionId,
                effectChoiceId = effectChoiceId,
            }
            local preApplied, preApplyErrors = applyTriggerPipeline(
                declaredInput,
                phase,
                resolutionId,
                card,
                instance,
                hasMechanism(card, "insight") and expectedSide or nil
            )
            if not preApplied then
                return false, preApplyErrors
            end

            local baseApplied, baseErrors = applyCommands(
                {
                    {
                        op = "damage_resistance",
                        target = "character",
                        amount = finalDamage,
                        cause = "baseDamage",
                    },
                },
                cardSource(card, instance),
                phase,
                resolutionId,
                expectedSide,
                "card_base"
            )
            if not baseApplied then
                return false, baseErrors
            end

            context = buildContext(working.state, phase, card, instance, nil, effectChoiceId)
            local cardEffect, cardEffectErrors = callModule(
                "effectEngine",
                "evaluateCardResolve",
                staticData,
                card.id,
                context,
                { modifiers = modifiers }
            )
            if cardEffectErrors then
                return false, cardEffectErrors
            end
            local cardCommandsApplied, cardCommandErrors = applyCommands(
                cardEffect.commands,
                cardSource(card, instance),
                phase,
                resolutionId,
                expectedSide,
                "card_effect"
            )
            if not cardCommandsApplied then
                return false, cardCommandErrors
            end

            local currentMood = working.state.character.mood
            context = buildContext(working.state, phase, card, instance, nil, effectChoiceId)
            local moodEffect, moodEffectErrors = callModule(
                "effectEngine",
                "evaluateMoodEffect",
                staticData,
                card.id,
                currentMood,
                context,
                { modifiers = modifiers }
            )
            if moodEffectErrors then
                return false, moodEffectErrors
            end
            local moodCommandsApplied, moodCommandErrors = applyCommands(
                moodEffect.commands,
                cardSource(card, instance),
                phase,
                resolutionId,
                expectedSide,
                "mood_effect"
            )
            if not moodCommandsApplied then
                return false, moodCommandErrors
            end

            appendEvent(
                "card_resolved",
                phase,
                cardSource(card, instance),
                {
                    cardId = card.id,
                    instanceId = instance.instanceId,
                    finalResistanceDamage = finalDamage,
                },
                resolutionId,
                expectedSide,
                resolutionCause(resolutionId)
            )
            local resolvedInput = {
                type = "card_resolved",
                side = expectedSide,
                cardId = card.id,
                cardInstanceId = instance.instanceId,
                actionTag = card.actionTag,
                resolutionId = resolutionId,
                effectChoiceId = effectChoiceId,
            }
            local postApplied, postApplyErrors = applyTriggerPipeline(
                resolvedInput,
                phase,
                resolutionId,
                card,
                instance,
                nil
            )
            if not postApplied then
                return false, postApplyErrors
            end

            local zoneFinished, zoneFinishErrors = finishCardZone(card, instance, phase, resolutionId, effectChoiceId)
            if not zoneFinished then
                return false, zoneFinishErrors
            end
            local outcome = latchOutcome("card_checkpoint", phase, resolutionId)
            return true, {
                declared = true,
                stopped = outcome ~= nil,
                resolutionId = resolutionId,
            }
        end

        for index, instanceId in ipairs(playerSelection) do
            if working.transient.halted or working.transient.skipRemaining.player == true then
                local restored, restoreErrors = restorePlayerCards(
                    index,
                    working.transient.halted and "outcome_latched" or "skip_actions",
                    "player_card",
                    nil
                )
                if not restored then
                    return failure(restoreErrors)
                end
                break
            end
            local resolved, resultOrErrors = resolveCard(instanceId, "player", index)
            if not resolved then
                return failure(resultOrErrors)
            end
            if resultOrErrors.stopped then
                if working.transient.halted and index < #playerSelection then
                    local restored, restoreErrors = restorePlayerCards(index + 1, "outcome_latched", "player_card", resultOrErrors.resolutionId)
                    if not restored then
                        return failure(restoreErrors)
                    end
                end
                break
            end
        end

        if working.transient.halted or working.transient.skipRemaining.character == true then
            recordSequenceStopped(
                "character",
                characterSelection,
                1,
                working.transient.halted and "outcome_latched" or "skip_actions",
                "character_card",
                nil
            )
        else
            for index, instanceId in ipairs(characterSelection) do
                if working.transient.halted or working.transient.skipRemaining.character == true then
                    recordSequenceStopped(
                        "character",
                        characterSelection,
                        index,
                        working.transient.halted and "outcome_latched" or "skip_actions",
                        "character_card",
                        nil
                    )
                    break
                end
                local resolved, resultOrErrors = resolveCard(instanceId, "character", index)
                if not resolved then
                    return failure(resultOrErrors)
                end
                if resultOrErrors.stopped then
                    recordSequenceStopped(
                        "character",
                        characterSelection,
                        index + 1,
                        "outcome_latched",
                        "character_card",
                        resultOrErrors.resolutionId
                    )
                    break
                end
            end
        end

        if working.state.status == "active" and resolvedTurnNumber == working.state.turnLimit then
            working.state.status = "defeat"
            working.transient.halted = true
            working.transient.haltReason = "turn_limit"
            appendEvent(
                "outcome_latched",
                "turn_end",
                source("system", "turn_resolver"),
                {
                    status = "defeat",
                    reasonCode = "turn_limit",
                    stealth = working.state.player.stealth,
                    resistance = working.state.character.resistance,
                },
                nil,
                nil,
                { kind = "turn_rule" }
            )
        elseif working.state.status == "active" then
            local turnEndInput = {
                type = "turn_end",
                turnNumber = resolvedTurnNumber,
            }
            local endApplied, endApplyErrors = applyTriggerPipeline(
                turnEndInput,
                "turn_end",
                nil,
                nil,
                nil,
                nil,
                nil
            )
            if not endApplied then
                return failure(endApplyErrors)
            end
            latchOutcome("turn_end_checkpoint", "turn_end", nil)
        end

        local moodProjection, moodProjectionErrors = callModule("effectEngine", "projectMood", staticData, {
            turnNumber = resolvedTurnNumber,
            mood = working.state.character.mood,
            moodTokens = working.state.character.moodTokens,
            forcedMoodRequests = working.transient.forcedMoodRequests,
        })
        if moodProjectionErrors then return failure(moodProjectionErrors) end
        local projectedMood = moodProjection.resolution
        local moodPayload = projectedMood.payload
        working.state.character.mood = projectedMood.mood
        working.state.character.moodTokens = projectedMood.moodTokens
        appendEvent(
            "mood_evaluated",
            "turn_end",
            source("system", "mood_tokens"),
            moodPayload,
            nil,
            "character",
            { kind = "turn_rule" }
        )

        if working.state.status == "active" and projectedMood.stealthDelta ~= 0 then
            local moodCommand = {
                op = projectedMood.stealthDelta < 0 and "lose_stealth" or "recover_stealth",
                target = "player",
                amount = math.abs(projectedMood.stealthDelta),
                cause = "moodState",
            }
            local moodApplied, moodApplyErrors = applyCommands(
                { moodCommand },
                source("system", "mood_state"),
                "turn_end",
                nil,
                "player",
                "mood_state"
            )
            if not moodApplied then
                return failure(moodApplyErrors)
            end
            latchOutcome("mood_state_checkpoint", "turn_end", nil)
        end

        local endingStealth = working.state.player.stealth
        local endingResistance = working.state.character.resistance
        local resistancePerformance = startValues.resistance - endingResistance
        local stealthSpent = math.max(0, startValues.stealth - endingStealth)

        local function orderedZoneIds(state, owner, zone)
            local entries = {}
            for index, instance in ipairs(state.cardInstances) do
                if instance.owner == owner and instance.zone == zone then
                    entries[#entries + 1] = {
                        instanceId = instance.instanceId,
                        position = instance.position,
                        sourceIndex = index,
                    }
                end
            end
            table.sort(entries, function(left, right)
                if left.position ~= right.position then
                    return left.position < right.position
                end
                if left.instanceId ~= right.instanceId then
                    return left.instanceId < right.instanceId
                end
                return left.sourceIndex < right.sourceIndex
            end)
            local ids = {}
            for index, entry in ipairs(entries) do
                ids[index] = entry.instanceId
            end
            return ids
        end

        local function cleanupSnapshot(state)
            local playerPlans, playerPlanError = cloneData(state.player.planSlots, "$.cleanup.playerPlans")
            if playerPlanError then
                return nil, playerPlanError
            end
            local characterPlans, characterPlanError = cloneData(
                state.character.planSlots,
                "$.cleanup.characterPlans"
            )
            if characterPlanError then
                return nil, characterPlanError
            end
            return {
                turnNumber = state.turnNumber,
                player = {
                    used = orderedZoneIds(state, "player", "used"),
                    hand = orderedZoneIds(state, "player", "hand"),
                    discard = orderedZoneIds(state, "player", "discard"),
                    planSlots = playerPlans,
                },
                character = {
                    used = orderedZoneIds(state, "character", "used"),
                    hand = orderedZoneIds(state, "character", "hand"),
                    discard = orderedZoneIds(state, "character", "discard"),
                    planSlots = characterPlans,
                },
            }, nil
        end

        local cleanupBefore, cleanupSnapshotError = cleanupSnapshot(working.state)
        if cleanupSnapshotError then
            return failure({ cleanupSnapshotError })
        end
        local cleanupReport, cleanupErrors = callModule("cardZones", "endTurnCleanup", working.state)
        if cleanupErrors then
            return failure(cleanupErrors)
        end
        working.state = cleanupReport.state
        if working.state.turnStartReceipt ~= nil then
            return failure({
                makeError(
                    "turn_start_receipt_not_cleared",
                    "$.afterState.turnStartReceipt",
                    "턴 종료 정리 후 turnStartReceipt가 제거되지 않았습니다."
                ),
            })
        end
        local battleEnded = working.state.status ~= "active"
        if not battleEnded then
            working.state.turnNumber = resolvedTurnNumber + 1
        end
        local cleanupAfter
        cleanupAfter, cleanupSnapshotError = cleanupSnapshot(working.state)
        if cleanupSnapshotError then
            return failure({ cleanupSnapshotError })
        end
        appendEvent(
            "turn_cleanup",
            "cleanup",
            source("system", "card_zones"),
            {
                before = cleanupBefore,
                after = cleanupAfter,
                movedInstanceIds = cleanupReport.movedInstanceIds or {},
                resolvedTurnNumber = resolvedTurnNumber,
            },
            nil,
            nil,
            { kind = "turn_rule" }
        )

        if battleEnded then
            local sessionEndInput = {
                type = "session_end",
                status = working.state.status,
                turnNumber = resolvedTurnNumber,
            }
            local sessionApplied, sessionApplyErrors = applyTriggerPipeline(
                sessionEndInput,
                "session_end",
                nil,
                nil,
                nil,
                nil,
                false
            )
            if not sessionApplied then
                return failure(sessionApplyErrors)
            end
            appendEvent(
                "session_end",
                "session_end",
                source("system", "turn_resolver"),
                { status = working.state.status },
                nil,
                nil,
                { kind = "outcome" }
            )
        end
        working.state.lastCommittedTurnId = turnId

        local historyReport, historyErrors = callModule(
            "battleHistory",
            "appendResolvedTurn",
            authorityState,
            working.state,
            {
                turnId = turnId,
                turnNumber = resolvedTurnNumber,
                selectedCards = {
                    player = playerSelection,
                    character = characterSelection,
                },
                events = events,
                start = {
                    stealth = startValues.stealth,
                    resistance = startValues.resistance,
                    mood = startValues.mood,
                },
                finish = {
                    stealth = endingStealth,
                    resistance = endingResistance,
                    mood = working.state.character.mood,
                    status = working.state.status,
                },
                mood = moodPayload,
            },
            staticData
        )
        if historyErrors then
            return failure(historyErrors)
        end
        if type(historyReport.state) ~= "table" then
            return failure({
                makeError("invalid_history_append_result", "$.runtime.battleHistory", "전투 이력 추가 결과에 상태가 없습니다."),
            })
        end
        working.state = historyReport.state

        local stateReport, stateErrors = callModule(
            "stateSchema",
            "validateBattleState",
            working.state,
            staticData
        )
        if stateErrors then
            return failure(stateErrors)
        end
        local conservationReport, conservationErrors = callModule(
            "cardZones",
            "validateConservation",
            authorityState,
            working.state
        )
        if conservationErrors then
            return failure(conservationErrors)
        end

        local sourceAuthority, sourceError = cloneData(validatedProjection.source, "$.projection.source")
        if sourceError then
            return failure({ sourceError })
        end
        local projectedRng, rngCloneError = cloneData(validatedProjection.projectedRng, "$.projection.projectedRng")
        if rngCloneError then
            return failure({ rngCloneError })
        end
        local afterState, afterCloneError = cloneData(stateReport.value or working.state, "$.afterState")
        if afterCloneError then
            return failure({ afterCloneError })
        end

        return success({
            schemaVersion = SCHEMA_VERSION,
            kind = "turnResolution",
            battleId = authorityState.battleId,
            turnId = turnId,
            turnNumber = resolvedTurnNumber,
            source = {
                kind = "turnDraftProjection",
                mode = validatedProjection.mode,
                authority = sourceAuthority,
                projectedRng = projectedRng,
            },
            selectedCards = {
                player = playerSelection,
                character = characterSelection,
            },
            events = events,
            metrics = {
                startingStealth = startValues.stealth,
                endingStealth = endingStealth,
                startingResistance = startValues.resistance,
                endingResistance = endingResistance,
                resistancePerformance = resistancePerformance,
                stealthSpent = stealthSpent,
                moodChanged = moodPayload.applied,
                moodResolution = moodPayload.resolution,
                forcedMoodCount = moodPayload.forcedCount,
            },
            afterState = afterState,
        })
    end

    local arguments = { ... }
    if action == "resolveTurn" then
        return resolveTurn(arguments[1], arguments[2], arguments[3], arguments[4])
    end
    return failure({
        makeError("unknown_action", "$.action", "지원하지 않는 턴 해결 작업입니다: " .. tostring(action)),
    })
end)

]],
    [[[
uiRender
]]] = [[
(function(triggerId, mode, htmlName)
    local UI_VAR = "🔯🔯🔯"
    local POPUP_VAR = "helltrainUiPopupV1"

    if not htmlName or htmlName == "" then
        debug(1, "uiRender error: empty html name.")
        return
    end

    local html = loadLores(triggerId, htmlName .. ".html")

    if not html then
        debug(1, "uiRender error: html not found " .. tostring(htmlName))
        return
    end

    local renderModes = {
        set = function()
            setChatVar(triggerId, UI_VAR, html)
        end,
        append = function()
            -- 기존 버튼 route 이름은 호환용으로 유지한다. popup slot은 한 번에
            -- 하나의 창만 소유하므로 append도 교체로 처리한다.
            setChatVar(triggerId, POPUP_VAR, html)
        end,
        popup = function()
            setChatVar(triggerId, POPUP_VAR, html)
        end
    }

    local render = renderModes[mode]

    if not render then
        debug(1, "uiRender error: unknown mode " .. tostring(mode))
        return
    end

    render()
end)

]],
    [[[
viewBuilder
]]] = [[
(function()
    local PRESENTATION_CACHE_MAX_ENTRIES = 256
    local presentationCache = {}
    local presentationCacheSize = 0
    local presentationClock = 0
    local presentationStats = { hits = 0, misses = 0, evictions = 0 }

    local function resolveRegistry(registry)
        if type(registry) == "table" and type(registry.registry) == "table" then
            return registry.registry
        end
        if type(registry) == "table" and type(registry.data) == "table" then
            return resolveRegistry(registry.data)
        end
        return registry
    end

    local function clonePresentation(value, seen)
        if type(value) ~= "table" then return value end
        seen = seen or {}
        if seen[value] ~= nil then return seen[value] end
        local copy = {}
        seen[value] = copy
        for key, item in pairs(value) do
            copy[clonePresentation(key, seen)] = clonePresentation(item, seen)
        end
        return copy
    end

    local function presentationKey(card, registry)
        local parts = {}
        local function append(value)
            local text = tostring(value or "")
            parts[#parts + 1] = tostring(#text) .. ":" .. text
        end
        append("presentation-v2")
        append("card.id")
        append(type(card) == "table" and card.id)
        append("card.name")
        append(type(card) == "table" and card.name)
        append("card.description")
        append(type(card) == "table" and card.description)
        append("card.actionTag")
        append(type(card) == "table" and card.actionTag)
        local mechanisms = type(card) == "table" and type(card.mechanisms) == "table" and card.mechanisms or {}
        append("card.mechanisms")
        append(#mechanisms)
        for _, value in ipairs(mechanisms) do append(value) end
        local rules = type(card) == "table" and type(card.rules) == "table" and card.rules or {}
        append("card.rules")
        append(#rules)
        for _, value in ipairs(rules) do append(value) end

        registry = resolveRegistry(registry)
        for _, collectionName in ipairs({ "actionTags", "mechanisms" }) do
            append("registry." .. collectionName)
            local collection = type(registry) == "table" and registry[collectionName] or nil
            local keys = {}
            for key in pairs(type(collection) == "table" and collection or {}) do keys[#keys + 1] = key end
            table.sort(keys, function(left, right) return tostring(left) < tostring(right) end)
            append(#keys)
            for _, key in ipairs(keys) do
                local entry = collection[key]
                append(key)
                append(type(entry) == "table" and entry.id)
                append(type(entry) == "table" and entry.label)
                append(type(entry) == "table" and entry.tooltip)
            end
        end
        return table.concat(parts, "|")
    end

    local function evictPresentationIfNeeded()
        if presentationCacheSize < PRESENTATION_CACHE_MAX_ENTRIES then return end
        local oldestKey
        local oldest
        for key, entry in pairs(presentationCache) do
            if oldest == nil or entry.lastUsed < oldest.lastUsed then
                oldestKey, oldest = key, entry
            end
        end
        if oldestKey ~= nil then
            presentationCache[oldestKey] = nil
            presentationCacheSize = presentationCacheSize - 1
            presentationStats.evictions = presentationStats.evictions + 1
        end
    end

    return function(triggerId, action, ...)
    local SCHEMA_VERSION = 1
    local MAX_PLAN_CAPACITY = 16

    local function addError(errors, code, path, message)
        table.insert(errors, {
            code = code,
            path = path,
            message = message,
        })
    end

    local function failure(errors)
        return {
            ok = false,
            schemaVersion = SCHEMA_VERSION,
            errors = errors,
        }
    end

    local function success(key, value)
        local response = {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
        }
        if key then
            response[key] = value
        end
        return response
    end

    local function isFinite(value)
        return type(value) == "number"
            and value == value
            and value ~= math.huge
            and value ~= -math.huge
    end

    local function isInteger(value, minimum)
        return isFinite(value)
            and value % 1 == 0
            and (minimum == nil or value >= minimum)
    end

    local function isPlanCapacity(value)
        return isInteger(value, 1) and value <= MAX_PLAN_CAPACITY
    end

    local function isAsciiId(value)
        return type(value) == "string"
            and string.match(value, "^[a-z][a-z0-9_]*$") ~= nil
    end

    local function isRuntimeId(value)
        return type(value) == "string"
            and string.match(value, "^[A-Za-z0-9][A-Za-z0-9_-]*$") ~= nil
    end

    local function objectPath(path, key)
        if type(key) == "string" and string.match(key, "^[A-Za-z_][A-Za-z0-9_]*$") then
            return path .. "." .. key
        end
        return path .. "[" .. string.format("%q", tostring(key)) .. "]"
    end

    local function inspectTable(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "expected_table", path, "테이블이어야 합니다.")
            return nil
        end

        local numericCount = 0
        local maximum = 0
        local hasNumeric = false
        local hasString = false
        local stringKeys = {}

        for key in pairs(value) do
            if type(key) == "number" then
                hasNumeric = true
                numericCount = numericCount + 1
                if not isInteger(key, 1) then
                    addError(errors, "invalid_array_index", path, "배열 인덱스는 1 이상의 정수여야 합니다.")
                    return nil
                end
                if key > maximum then
                    maximum = key
                end
            elseif type(key) == "string" then
                hasString = true
                table.insert(stringKeys, key)
            else
                addError(errors, "invalid_object_key", path, "객체 키는 문자열이어야 합니다.")
                return nil
            end
        end

        if hasNumeric and hasString then
            addError(errors, "mixed_table", path, "숫자 인덱스와 문자열 키를 함께 사용할 수 없습니다.")
            return nil
        end
        if hasNumeric then
            if numericCount ~= maximum then
                addError(errors, "sparse_array", path, "배열 인덱스는 1부터 빈틈없이 이어져야 합니다.")
                return nil
            end
            return "array", maximum
        end
        if hasString then
            table.sort(stringKeys)
            return "object", stringKeys
        end
        return "array", 0
    end

    local function validateJsonSafe(value, path, errors, active)
        local valueType = type(value)
        if valueType == "string" or valueType == "boolean" then
            return
        end
        if valueType == "number" then
            if not isFinite(value) then
                addError(errors, "non_finite_number", path, "NaN과 무한대는 View에 넣을 수 없습니다.")
            end
            return
        end
        if valueType ~= "table" then
            addError(errors, "unsupported_type", path, "View에 넣을 수 없는 자료형입니다: " .. valueType)
            return
        end
        if getmetatable(value) ~= nil then
            addError(errors, "metatable_not_allowed", path, "View에는 메타테이블을 사용할 수 없습니다.")
            return
        end
        active = active or {}
        if active[value] then
            addError(errors, "circular_reference", path, "순환 참조가 있는 View는 허용하지 않습니다.")
            return
        end
        active[value] = true
        local kind, shape = inspectTable(value, path, errors)
        if kind == "array" then
            for index = 1, shape do
                validateJsonSafe(value[index], path .. "[" .. index .. "]", errors, active)
            end
        elseif kind == "object" then
            for _, key in ipairs(shape) do
                validateJsonSafe(value[key], objectPath(path, key), errors, active)
            end
        end
        active[value] = nil
    end

    local function checkAllowedKeys(value, allowed, path, errors)
        if type(value) ~= "table" then
            return
        end
        for key in pairs(value) do
            if type(key) ~= "string" or not allowed[key] then
                addError(errors, "unknown_field", objectPath(path, key), "battleView에 허용되지 않은 필드입니다.")
            end
        end
    end

    local function getArrayLength(value, path, errors)
        local kind, length = inspectTable(value, path, errors)
        if kind ~= "array" then
            if kind ~= nil then
                addError(errors, "expected_array", path, "연속 배열이어야 합니다.")
            end
            return nil
        end
        return length
    end

    local function normalizeStaticData(staticData)
        if type(staticData) == "table" and type(staticData.data) == "table" then
            return staticData.data
        end
        return staticData
    end

    local function hasMechanism(card, mechanismId)
        if type(card) ~= "table" or type(card.mechanisms) ~= "table" then
            return false
        end
        for _, id in ipairs(card.mechanisms) do
            if id == mechanismId then
                return true
            end
        end
        return false
    end

    local function appendNestedErrors(target, prefix, nested)
        if type(nested) ~= "table" or type(nested.errors) ~= "table" then
            addError(target, "validation_failed", prefix, "하위 검증 결과를 읽을 수 없습니다.")
            return
        end
        for _, item in ipairs(nested.errors) do
            local suffix = tostring(item.path or "$")
            if string.sub(suffix, 1, 1) == "$" then
                suffix = string.sub(suffix, 2)
            end
            addError(
                target,
                tostring(item.code or "validation_failed"),
                prefix .. suffix,
                tostring(item.message or "하위 검증에 실패했습니다.")
            )
        end
    end

    local function lookupTag(registry, tagId, path, errors)
        registry = resolveRegistry(registry)
        local action = type(registry) == "table"
            and type(registry.actionTags) == "table"
            and registry.actionTags[tagId]
            or nil
        local mechanism = type(registry) == "table"
            and type(registry.mechanisms) == "table"
            and registry.mechanisms[tagId]
            or nil

        if action and mechanism then
            addError(errors, "tag_registry_collision", path, "행동 태그와 메커니즘 ID가 충돌합니다: " .. tagId)
            return nil
        end
        local entry = action or mechanism
        if not entry then
            addError(errors, "unknown_tag_token", path, "등록되지 않은 태그입니다: " .. tagId)
            return nil
        end
        if type(entry.label) ~= "string" or entry.label == ""
            or type(entry.tooltip) ~= "string" or entry.tooltip == "" then
            addError(errors, "invalid_tag_metadata", path, "태그 표시명과 툴팁이 필요합니다: " .. tagId)
            return nil
        end

        return {
            kind = "tag",
            id = tagId,
            label = entry.label,
            tagKind = action and "action" or "mechanism",
            tooltip = entry.tooltip,
        }
    end

    local function buildTagGlossary(publicAction, handItems)
        local byId = {}
        local function appendTag(tag)
            if type(tag) ~= "table" or tag.kind ~= "tag" or type(tag.id) ~= "string" then
                return
            end
            byId[tag.id] = {
                kind = "tag",
                id = tag.id,
                label = tag.label,
                tagKind = tag.tagKind,
                tooltip = tag.tooltip,
            }
        end
        local function appendSegments(segments)
            for _, segment in ipairs(type(segments) == "table" and segments or {}) do
                if type(segment) == "table" and segment.kind == "tag" then
                    appendTag(segment)
                end
            end
        end
        local function appendRuleLines(ruleLines)
            for _, ruleLine in ipairs(type(ruleLines) == "table" and ruleLines or {}) do
                appendSegments(type(ruleLine) == "table" and ruleLine.segments or nil)
            end
        end

        if type(publicAction) == "table" and publicAction.status == "tagRevealed" then
            appendTag(publicAction.tag)
        end
        for _, item in ipairs(type(handItems) == "table" and handItems or {}) do
            appendTag(item.actionTag)
            for _, mechanism in ipairs(type(item.mechanisms) == "table" and item.mechanisms or {}) do
                appendTag(mechanism)
            end
            appendSegments(item.descriptionSegments)
            appendRuleLines(item.ruleLines)
        end

        local glossary = {}
        local ids = {}
        for id in pairs(byId) do
            ids[#ids + 1] = id
        end
        table.sort(ids, function(left, right)
            return tostring(left) < tostring(right)
        end)
        for _, id in ipairs(ids) do
            glossary[#glossary + 1] = byId[id]
        end
        return glossary
    end

    local function appendText(segments, value)
        if value == "" then
            return
        end
        local previous = segments[#segments]
        if previous and previous.kind == "text" then
            previous.value = previous.value .. value
        else
            table.insert(segments, {
                kind = "text",
                value = value,
            })
        end
    end

    local function tokenizeTags(source, registry, sourcePath)
        local errors = {}
        sourcePath = sourcePath or "$"
        if type(source) ~= "string" then
            addError(errors, "invalid_text", sourcePath, "태그를 해석할 값이 문자열이 아닙니다.")
            return failure(errors)
        end

        local segments = {}
        local cursor = 1
        while cursor <= #source do
            local tokenStart = string.find(source, "::tag[", cursor, true)
            if not tokenStart then
                appendText(segments, string.sub(source, cursor))
                break
            end

            appendText(segments, string.sub(source, cursor, tokenStart - 1))
            local idStart = tokenStart + #"::tag["
            local tokenCloseStart, tokenCloseEnd = string.find(source, "]::", idStart, true)
            if not tokenCloseStart then
                addError(errors, "malformed_tag_token", sourcePath, "닫히지 않은 태그 토큰이 있습니다.")
                return failure(errors)
            end

            local tagId = string.sub(source, idStart, tokenCloseStart - 1)
            if not isAsciiId(tagId) then
                addError(errors, "malformed_tag_token", sourcePath, "태그 ID는 소문자 ASCII ID여야 합니다: " .. tagId)
                return failure(errors)
            end

            local tag = lookupTag(registry, tagId, sourcePath, errors)
            if not tag then
                return failure(errors)
            end
            table.insert(segments, tag)
            cursor = tokenCloseEnd + 1
        end

        if #source == 0 then
            return success("segments", {})
        end
        return success("segments", segments)
    end

    local function tokenizeForBuild(source, registry, path, errors)
        local tokenized = tokenizeTags(source, registry, "$")
        if not tokenized.ok then
            appendNestedErrors(errors, path, tokenized)
            return {}
        end
        return tokenized.segments
    end

    local function buildRuleLines(rules, registry, path, errors)
        local lines = {}
        if type(rules) ~= "table" then
            addError(errors, "invalid_rules", path, "규칙 목록이 배열이 아닙니다.")
            return lines
        end
        for index, rule in ipairs(rules) do
            table.insert(lines, {
                segments = tokenizeForBuild(rule, registry, path .. "[" .. index .. "]", errors),
            })
        end
        return lines
    end

    local SOURCE_KIND_LABELS = {
        card = "카드",
        plan = "계획",
        trait = "특징",
        perk = "퍽",
        environment = "환경",
    }

    local function collectRelatedTags(explicitTags, descriptionSegments, ruleLines)
        local tags = {}
        local seen = {}
        local function append(tag)
            if type(tag) == "table" and tag.kind == "tag" and not seen[tag.id] then
                seen[tag.id] = true
                tags[#tags + 1] = tag
            end
        end
        for _, tag in ipairs(explicitTags or {}) do append(tag) end
        for _, segment in ipairs(descriptionSegments or {}) do append(segment) end
        for _, line in ipairs(ruleLines or {}) do
            for _, segment in ipairs(line.segments or {}) do append(segment) end
        end
        return tags
    end

    local function buildEffectSourceView(source, registry, path, errors)
        if type(source) ~= "table" then
            addError(errors, "invalid_effect_source", path, "효과 원인 정보가 테이블이 아닙니다.")
            return nil
        end
        local kindLabel = SOURCE_KIND_LABELS[source.kind]
        if kindLabel == nil
            or (source.side ~= nil and source.side ~= "player" and source.side ~= "character")
            or type(source.name) ~= "string" or source.name == ""
            or type(source.description) ~= "string" or source.description == ""
            or type(source.rules) ~= "table"
            or type(source.tags) ~= "table" then
            addError(errors, "invalid_effect_source", path, "효과 원인 표시값이 올바르지 않습니다.")
            return nil
        end

        local explicitTags = {}
        for index, tagId in ipairs(source.tags) do
            local tag = lookupTag(registry, tagId, path .. ".tags[" .. index .. "]", errors)
            if tag then explicitTags[#explicitTags + 1] = tag end
        end
        local descriptionSegments = tokenizeForBuild(
            source.description,
            registry,
            path .. ".description",
            errors
        )
        local ruleLines = buildRuleLines(source.rules, registry, path .. ".rules", errors)
        local relatedTags = collectRelatedTags(explicitTags, descriptionSegments, ruleLines)
        local view = {
            kind = source.kind,
            kindLabel = kindLabel,
            name = source.name,
            descriptionSegments = descriptionSegments,
            ruleLines = ruleLines,
            relatedTags = relatedTags,
            hasRelatedTags = #relatedTags > 0,
        }
        if source.side ~= nil then view.side = source.side end
        return view
    end

    local function signedNumber(value)
        local text = value % 1 == 0 and string.format("%.0f", value) or tostring(value)
        return value > 0 and ("+" .. text) or text
    end

    local function buildBattleLogView(state, staticData, errors)
        if type(state) ~= "table" or state.status == "active" then
            return { available = false, turnCount = 0, entries = {} }
        end
        if type(runScript) ~= "function" then
            addError(errors, "history_view_runtime_unavailable", "$.history", "상세 전투 로그 빌더를 찾을 수 없습니다.")
            return { available = false, turnCount = 0, entries = {} }
        end
        local ok, report = pcall(runScript, triggerId, "battleHistory", "buildPublicView", state.history, staticData)
        if not ok or type(report) ~= "table" then
            addError(errors, "history_view_failed", "$.history", "상세 전투 로그 생성 호출에 실패했습니다.")
            return { available = false, turnCount = 0, entries = {} }
        end
        if report.ok ~= true then
            appendNestedErrors(errors, "$.history", report)
            return { available = false, turnCount = 0, entries = {} }
        end
        if type(report.view) ~= "table" then
            addError(errors, "invalid_history_view", "$.history", "상세 전투 로그 View가 없습니다.")
            return { available = false, turnCount = 0, entries = {} }
        end
        return report.view
    end

    local function buildLastTurnView(lastTurn, registry, errors)
        if type(lastTurn) ~= "table" or lastTurn.available ~= true then
            return { available = false }
        end
        local view = {
            available = true,
            turnNumber = lastTurn.turnNumber,
            summaries = lastTurn.summaries,
            resourceChanges = {
                stealth = {},
                resistance = {},
            },
        }
        for _, resource in ipairs({ "stealth", "resistance" }) do
            local sourceEntries = type(lastTurn.resourceChanges) == "table"
                and lastTurn.resourceChanges[resource]
                or nil
            if type(sourceEntries) ~= "table" then
                addError(errors, "invalid_resource_changes", "$.lastTurn.resourceChanges." .. resource, "자원 변화 목록이 배열이 아닙니다.")
            else
                for index, entry in ipairs(sourceEntries) do
                    local path = "$.lastTurn.resourceChanges." .. resource .. "[" .. index .. "]"
                    local source = type(entry) == "table"
                        and buildEffectSourceView(entry.source, registry, path .. ".source", errors)
                        or nil
                    if type(entry) ~= "table"
                        or not isInteger(entry.sequence, 1)
                        or not isFinite(entry.amount)
                        or entry.amount == 0 then
                        addError(errors, "invalid_resource_change", path, "자원 변화 표시값이 올바르지 않습니다.")
                    elseif source then
                        view.resourceChanges[resource][#view.resourceChanges[resource] + 1] = {
                            sequence = entry.sequence,
                            amount = entry.amount,
                            amountLabel = signedNumber(entry.amount),
                            direction = entry.amount > 0 and "increase" or "decrease",
                            source = source,
                        }
                    end
                end
            end
        end
        return view
    end

    local function buildSafeCardSummaryUncached(card, registry, path, errors)
        if type(card) ~= "table" then
            addError(errors, "missing_card", path, "카드 정의를 찾을 수 없습니다.")
            return nil
        end

        local actionTag = lookupTag(registry, card.actionTag, path .. ".actionTag", errors)
        local mechanisms = {}
        for index, mechanismId in ipairs(card.mechanisms or {}) do
            local tag = lookupTag(registry, mechanismId, path .. ".mechanisms[" .. index .. "]", errors)
            if tag then
                table.insert(mechanisms, tag)
            end
        end

        return {
            cardId = card.id,
            name = card.name,
            descriptionSegments = tokenizeForBuild(card.description, registry, path .. ".description", errors),
            ruleLines = buildRuleLines(card.rules, registry, path .. ".rules", errors),
            actionTag = actionTag or {
                kind = "tag",
                id = "invalid",
                label = "오류",
                tagKind = "action",
                tooltip = "태그 정보를 불러오지 못했습니다.",
            },
            mechanisms = mechanisms,
        }
    end

    local function buildSafeCardSummary(card, registry, path, errors)
        local key = presentationKey(card, registry)
        local cached = presentationCache[key]
        if cached ~= nil then
            presentationClock = presentationClock + 1
            cached.lastUsed = presentationClock
            cached.hits = cached.hits + 1
            presentationStats.hits = presentationStats.hits + 1
            return clonePresentation(cached.value)
        end

        presentationStats.misses = presentationStats.misses + 1
        local beforeErrors = #errors
        local built = buildSafeCardSummaryUncached(card, registry, path, errors)
        if built ~= nil and #errors == beforeErrors then
            evictPresentationIfNeeded()
            presentationClock = presentationClock + 1
            presentationCache[key] = {
                value = clonePresentation(built),
                lastUsed = presentationClock,
                hits = 0,
            }
            presentationCacheSize = presentationCacheSize + 1
        end
        return built
    end

    local function buildPlanView(slot, slotIndex, owner, cards, registry, path, errors)
        local hasDuration = slot.remainingTurns ~= nil
        local hidden = owner == "character" and slot.revealed ~= true
        local view = {
            slotIndex = slotIndex,
            status = hidden and "hidden" or "revealed",
            hasDuration = hasDuration,
        }
        if hasDuration then
            view.remainingTurns = slot.remainingTurns
        end
        if not hidden then
            view.card = buildSafeCardSummary(cards[slot.cardId], registry, path .. ".card", errors)
        end
        return view
    end

    local function buildPlanViews(ownerState, owner, cards, registry, path, errors)
        local capacity = ownerState.planCapacity
        local slots = ownerState.planSlots
        local views = {}
        if not isPlanCapacity(capacity) then
            addError(
                errors,
                "invalid_plan_capacity",
                "$." .. owner .. ".planCapacity",
                "계획 용량은 1 이상 " .. MAX_PLAN_CAPACITY .. " 이하의 정수여야 합니다."
            )
            return views
        end
        for slotIndex = 1, capacity do
            local slot = slots[slotIndex]
            if slot == nil then
                views[slotIndex] = {
                    slotIndex = slotIndex,
                    status = "empty",
                    hasDuration = false,
                }
            else
                views[slotIndex] = buildPlanView(
                    slot,
                    slotIndex,
                    owner,
                    cards,
                    registry,
                    path .. "[" .. slotIndex .. "]",
                    errors
                )
            end
        end
        return views
    end

    local function buildMoodView(state, data, errors)
        local moodId = state.character.mood
        local mood = data.registry.moods[moodId]
        if type(mood) ~= "table" then
            addError(errors, "unknown_mood", "$.character.mood", "무드 표시 정보를 찾을 수 없습니다.")
            mood = { id = moodId, label = moodId, order = 0 }
        end

        local tokens = {}
        local stateTokens = type(state.character.moodTokens) == "table" and state.character.moodTokens or {}
        for registeredMoodId in pairs(data.registry.moods) do
            tokens[registeredMoodId] = stateTokens[registeredMoodId] or 0
        end

        return {
            id = moodId,
            label = mood.label,
            tokenThreshold = 3,
            tokens = tokens,
        }
    end

    local function buildTraitViews(state, data, errors)
        local views = {}
        for _, traitId in ipairs(state.character.traitIds) do
            local trait = data.traits[traitId]
            if type(trait) == "table" and trait.visibility == "public" then
                table.insert(views, {
                    id = trait.id,
                    name = trait.name,
                    description = trait.description,
                    ruleLines = buildRuleLines(trait.rules, data.registry, "$.character.traits." .. traitId .. ".rules", errors),
                })
            end
        end
        return views
    end

    local function countZones(instances)
        local counts = {
            deckCount = 0,
            usedCount = 0,
            discardCount = 0,
            removedCount = 0,
        }
        for _, instance in ipairs(instances) do
            if instance.owner == "player" then
                if instance.zone == "deck" then
                    counts.deckCount = counts.deckCount + 1
                elseif instance.zone == "used" then
                    counts.usedCount = counts.usedCount + 1
                elseif instance.zone == "discard" then
                    counts.discardCount = counts.discardCount + 1
                elseif instance.zone == "removed" then
                    counts.removedCount = counts.removedCount + 1
                end
            end
        end
        return counts
    end

    local function callRuntime(moduleName, moduleAction, ...)
        if type(runScript) ~= "function" then
            return nil, {
                code = "runtime_unavailable",
                path = "$.runtime." .. moduleName,
                message = "스크립트 실행기를 찾을 수 없습니다.",
            }
        end
        local ok, report = pcall(runScript, triggerId, moduleName, moduleAction, ...)
        if not ok then
            return nil, {
                code = "runtime_call_error",
                path = "$.runtime." .. moduleName,
                message = moduleName .. "." .. moduleAction .. " 실행에 실패했습니다: " .. tostring(report),
            }
        end
        if type(report) ~= "table" then
            return nil, {
                code = "invalid_runtime_result",
                path = "$.runtime." .. moduleName,
                message = "하위 모듈 결과가 테이블이 아닙니다.",
            }
        end
        return report, nil
    end

    local function findInstance(instances, instanceId)
        for _, instance in ipairs(type(instances) == "table" and instances or {}) do
            if instance.instanceId == instanceId then
                return instance
            end
        end
        return nil
    end

    local function findSubwayStation(line, stationId)
        for _, routePath in ipairs(type(line) == "table" and line.paths or {}) do
            for _, station in ipairs(routePath.stations or {}) do
                if station.id == stationId then
                    return station
                end
            end
        end
        return nil
    end

    local function buildSubwayView(state, data, errors, completedTurnsOverride)
        local transit = state.transit
        local line = type(transit) == "table"
            and type(data.subwayLines) == "table"
            and data.subwayLines[transit.lineId]
            or nil
        if type(line) ~= "table" then
            addError(errors, "missing_subway_line", "$.transit.lineId", "전투 지하철 노선 표시 정보를 찾을 수 없습니다.")
            return nil
        end

        local completedTurns = completedTurnsOverride
        if completedTurns == nil then
            completedTurns = state.status == "active"
                and state.turnNumber - 1
                or state.turnNumber
        end
        if completedTurns < 0 then completedTurns = 0 end
        if completedTurns > state.turnLimit then completedTurns = state.turnLimit end
        local currentIndex = completedTurns + 1
        local stations = {}
        for index, stationId in ipairs(transit.stationIds) do
            local station = findSubwayStation(line, stationId)
            if type(station) ~= "table" then
                addError(errors, "missing_subway_station", "$.transit.stationIds[" .. index .. "]", "전투 이동 역 표시 정보를 찾을 수 없습니다.")
            else
                local status = index < currentIndex and "passed"
                    or (index == currentIndex and "current" or "upcoming")
                stations[index] = {
                    index = index,
                    id = station.id,
                    code = station.code,
                    name = station.name,
                    status = status,
                    isStart = index == 1,
                    isDestination = index == #transit.stationIds,
                }
            end
        end
        if #stations ~= #transit.stationIds then
            return nil
        end

        return {
            lineId = line.id,
            lineName = line.name,
            lineCode = line.code,
            lineColor = line.color,
            operatorName = line.operatorName,
            startStation = stations[1],
            currentStation = stations[currentIndex],
            destinationStation = stations[#stations],
            stations = stations,
        }
    end

    local CARD_REASON_MESSAGES = {
        insufficient_stealth = "은폐가 부족합니다",
        no_available_effect_choice = "선택 가능한 효과가 없습니다",
    }

    local CARD_DISPLAY_FIELD_NAMES = {
        "className",
        "orderLabel",
        "showDetail",
        "showPreviewFlag",
        "showChoicePopover",
        "choicePopoverId",
        "actionKind",
        "actionCommand",
        "actionTarget",
        "actionAriaLabel",
        "actionAriaPressed",
        "actionAriaExpanded",
        "actionDisabled",
        "helpPrimary",
        "helpMessages",
    }

    local EFFECT_CHOICE_DISPLAY_FIELD_NAMES = {
        "command",
        "disabled",
        "showUnavailableText",
    }

    local function makeChoicePopoverId(battleId, turnId, instanceId)
        return table.concat({ "htp", tostring(battleId or ""), tostring(turnId or ""), "choice", tostring(instanceId or "") }, "-")
    end

    local function makeCardInteractionCommand(instanceId, interactionToken)
        if type(interactionToken) ~= "string" or interactionToken == "" then
            return ""
        end
        return table.concat({
            "battleController",
            "clickCard",
            tostring(instanceId or ""),
            interactionToken,
        }, "|")
    end

    local function makeEffectChoiceCommand(instanceId, choiceId, interactionToken)
        if type(interactionToken) ~= "string" or interactionToken == "" then
            return ""
        end
        return table.concat({
            "battleController",
            "selectCardEffect",
            tostring(instanceId or ""),
            tostring(choiceId or ""),
            interactionToken,
        }, "|")
    end

    local function buildEffectChoiceDisplay(instanceId, choice, interactionToken)
        return {
            command = makeEffectChoiceCommand(instanceId, choice.id, interactionToken),
            disabled = choice.selectable ~= true,
            showUnavailableText = choice.selectable ~= true,
        }
    end

    local function buildCardDisplay(card, context)
        local focused = context.phase == "selecting"
            and context.focusedInstanceId == card.instanceId
        local classNames = { "ht-card" }
        if focused then classNames[#classNames + 1] = "is-focused" end
        if card.selected == true then classNames[#classNames + 1] = "is-selected" end
        if card.origin == "preview" then classNames[#classNames + 1] = "is-preview" end
        if card.playable == false then classNames[#classNames + 1] = "is-unplayable" end

        local choicePopoverId = makeChoicePopoverId(
            context.battleId,
            context.turnId,
            card.instanceId
        )
        local actionKind = card.selected ~= true and card.hasEffectChoices == true
            and "choose"
            or "toggle"
        local helpPrimary
        if card.selected == true then
            helpPrimary = "다시 누르면 선택 취소"
        elseif card.hasEffectChoices == true then
            helpPrimary = "누르면 사용할 효과 선택"
        else
            helpPrimary = "누르면 상세 표시 및 사용 등록"
        end

        local helpMessages = {}
        if card.selected == true
            and card.hasEffectChoices == true
            and type(card.selectedEffectChoice) == "table" then
            helpMessages[#helpMessages + 1] = "선택 효과 · " .. tostring(card.selectedEffectChoice.label or "")
        end
        local reasonMessage = CARD_REASON_MESSAGES[card.reasonCode]
        if reasonMessage ~= nil then
            helpMessages[#helpMessages + 1] = reasonMessage
        end

        return {
            className = table.concat(classNames, " "),
            orderLabel = card.selected == true and tostring(card.selectionOrder) or "＋",
            showDetail = focused,
            showPreviewFlag = card.origin == "preview",
            showChoicePopover = card.hasEffectChoices == true,
            choicePopoverId = choicePopoverId,
            actionKind = actionKind,
            actionCommand = actionKind == "toggle"
                and makeCardInteractionCommand(card.instanceId, context.interactionToken)
                or "",
            actionTarget = actionKind == "choose" and choicePopoverId or "",
            actionAriaLabel = actionKind == "choose"
                and (tostring(card.name or "") .. " 효과 선택")
                or (tostring(card.name or "") .. " 카드 상세 보기 및 선택"),
            actionAriaPressed = card.selected == true and "true" or "false",
            actionAriaExpanded = focused and "true" or "false",
            actionDisabled = context.locked == true,
            helpPrimary = helpPrimary,
            helpMessages = helpMessages,
        }
    end

    local function appendFields(target, fields)
        for key, value in pairs(fields) do
            target[key] = value
        end
        return target
    end

    local function displayValuesEqual(left, right, active)
        if type(left) ~= type(right) then return false end
        if type(left) ~= "table" then return left == right end
        active = active or {}
        active[left] = active[left] or {}
        if active[left][right] then return true end
        active[left][right] = true
        for key, value in pairs(left) do
            if not displayValuesEqual(value, right[key], active) then return false end
        end
        for key in pairs(right) do
            if left[key] == nil then return false end
        end
        return true
    end

    local function buildBattleView(state, staticData, context)
        local errors = {}
        local data = normalizeStaticData(staticData)
        if type(data) ~= "table"
            or type(data.registry) ~= "table"
            or type(data.cards) ~= "table"
            or type(data.traits) ~= "table"
            or type(data.environments) ~= "table"
            or type(data.subwayLines) ~= "table"
            or type(data.characters) ~= "table" then
            addError(errors, "missing_static_data", "$", "battleView 생성에는 검증된 전체 정적 데이터가 필요합니다.")
            return failure(errors)
        end

        local stateValidation, stateCallError = callRuntime("stateSchema", "validateBattleState", state, data)
        if stateCallError then
            table.insert(errors, stateCallError)
            return failure(errors)
        end
        if stateValidation.ok ~= true then
            appendNestedErrors(errors, "$.state", stateValidation)
            return failure(errors)
        end

        if context ~= nil and (type(context) ~= "table" or getmetatable(context) ~= nil) then
            addError(errors, "invalid_view_context", "$.context", "battleView context는 메타테이블 없는 객체여야 합니다.")
            return failure(errors)
        end
        context = context or {}
        checkAllowedKeys(context, {
            draft = true,
            pendingTurn = true,
            lastCommittedPending = true,
            generationLocked = true,
            aftermath = true,
        }, "$.context", errors)
        local draftInput = rawget(context, "draft")
        local pendingInput = rawget(context, "pendingTurn")
        local lastCommittedInput = rawget(context, "lastCommittedPending")
        local generationLocked = rawget(context, "generationLocked")
        local aftermathInput = rawget(context, "aftermath")
        if generationLocked ~= nil and generationLocked ~= true then
            addError(
                errors,
                "invalid_generation_lock",
                "$.context.generationLocked",
                "generationLocked는 생성을 기다리는 동안에만 true로 지정할 수 있습니다."
            )
            return failure(errors)
        end
        if draftInput ~= nil and pendingInput ~= nil then
            addError(errors, "ambiguous_view_context", "$.context", "draft와 pendingTurn을 동시에 표시할 수 없습니다.")
            return failure(errors)
        end
        if generationLocked and pendingInput ~= nil then
            addError(
                errors,
                "ambiguous_generation_lock",
                "$.context",
                "pendingTurn 자체가 이미 출력 대기 잠금을 나타내므로 generationLocked를 함께 사용할 수 없습니다."
            )
            return failure(errors)
        end
        if aftermathInput ~= nil then
            if type(aftermathInput) ~= "table" or getmetatable(aftermathInput) ~= nil then
                addError(errors, "invalid_aftermath_context", "$.context.aftermath", "승리 후 자유행동 View context가 일반 객체가 아닙니다.")
                return failure(errors)
            end
            checkAllowedKeys(aftermathInput, {
                completedTurnNumber = true,
                phase = true,
            }, "$.context.aftermath", errors)
            if state.status ~= "victory"
                or not isInteger(aftermathInput.completedTurnNumber, state.turnNumber)
                or aftermathInput.completedTurnNumber >= state.turnLimit then
                addError(errors, "invalid_aftermath_context", "$.context.aftermath", "자유행동 진행이 조기 승리 전투 범위와 다릅니다.")
            end
            if aftermathInput.phase ~= "ready"
                and aftermathInput.phase ~= "inFlight"
                and aftermathInput.phase ~= "requestInjected" then
                addError(errors, "invalid_aftermath_phase", "$.context.aftermath.phase", "자유행동 View phase가 올바르지 않습니다.")
            end
            if draftInput ~= nil or pendingInput ~= nil or generationLocked then
                addError(errors, "ambiguous_aftermath_context", "$.context", "자유행동과 전투 선택 또는 생성 잠금을 함께 표시할 수 없습니다.")
            end
            if #errors > 0 then return failure(errors) end
        end

        local displayState = state
        local phase
        local locked
        local turnId
        local selectedIds = {}
        local selectedChoices = {}
        local previewIds = {}
        local focusedInstanceId = nil
        local interactionToken = nil
        if state.status == "active" and pendingInput ~= nil then
            local pendingValidation, pendingCallError = callRuntime(
                "stateSchema",
                "validatePendingTurn",
                pendingInput,
                data
            )
            if pendingCallError then
                table.insert(errors, pendingCallError)
                return failure(errors)
            end
            if pendingValidation.ok ~= true then
                appendNestedErrors(errors, "$.context.pendingTurn", pendingValidation)
                return failure(errors)
            end
            local receiptValidation, receiptCallError = callRuntime(
                "turnDraft",
                "validateProjectionReceipt",
                state,
                data,
                pendingInput.projectionReceipt
            )
            if receiptCallError then
                table.insert(errors, receiptCallError)
                return failure(errors)
            end
            if receiptValidation.ok ~= true then
                appendNestedErrors(errors, "$.context.pendingTurn.projectionReceipt", receiptValidation)
                return failure(errors)
            end
            phase = "awaitingOutput"
            locked = true
            turnId = pendingInput.turnId
            selectedIds = receiptValidation.receipt.selectedCardInstanceIds
            selectedChoices = receiptValidation.receipt.effectChoiceByInstanceId or {}
            previewIds = receiptValidation.projection.preview.availableDrawnInstanceIds
        elseif state.status == "active" then
            if draftInput == nil then
                addError(errors, "missing_turn_draft", "$.context.draft", "선택 중 battleView에는 검증할 turnDraft가 필요합니다.")
                return failure(errors)
            end
            -- turnDraft inspect는 외부 draft를 한 번만 재생 검증하면서
            -- 정규 draft와 interaction token을 함께 반환한다.
            local draftInspection, draftCallError = callRuntime(
                "turnDraft",
                "inspect",
                state,
                data,
                draftInput
            )
            if draftCallError then
                table.insert(errors, draftCallError)
                return failure(errors)
            end
            if draftInspection.ok ~= true then
                appendNestedErrors(errors, "$.context.draft", draftInspection)
                return failure(errors)
            end
            if type(draftInspection.interactionToken) ~= "string"
                or string.match(draftInspection.interactionToken, "^draftv1_%d+_%d+_%d+$") == nil then
                addError(
                    errors,
                    "invalid_interaction_token",
                    "$.context.draft",
                    "turnDraft가 유효한 UI 상호작용 토큰을 반환하지 않았습니다."
                )
                return failure(errors)
            end
            interactionToken = draftInspection.interactionToken
            phase = generationLocked and "awaitingOutput" or "selecting"
            locked = generationLocked == true
            local startReceipt = type(state.turnStartReceipt) == "table" and state.turnStartReceipt or nil
            turnId = startReceipt and startReceipt.turnId
                or string.format("%s-turn-%03d", state.battleId, state.turnNumber)
            selectedIds = draftInspection.draft.registeredCardInstanceIds
            selectedChoices = draftInspection.draft.effectChoiceByInstanceId or {}
            previewIds = draftInspection.draft.preview.availableDrawnInstanceIds
            if not generationLocked then
                focusedInstanceId = draftInspection.draft.focusedInstanceId
            end
        else
            if draftInput ~= nil or pendingInput ~= nil or generationLocked then
                addError(errors, "ended_view_context", "$.context", "종료된 battleView에는 draft, 현재 pendingTurn, 생성 잠금을 사용할 수 없습니다.")
                return failure(errors)
            end
            phase = "ended"
            locked = true
            turnId = aftermathInput ~= nil
                and string.format("%s-aftermath-%03d", state.battleId, aftermathInput.completedTurnNumber)
                or state.lastCommittedTurnId
                or string.format("%s-turn-%03d", state.battleId, state.turnNumber)
        end

        local lastTurn = { available = false }
        if lastCommittedInput ~= nil then
            if state.lastCommittedTurnId == nil then
                addError(
                    errors,
                    "unexpected_last_committed_pending",
                    "$.context.lastCommittedPending",
                    "확정 턴이 없는 상태에는 직전 pendingTurn을 표시할 수 없습니다."
                )
                return failure(errors)
            end
            if type(lastCommittedInput) ~= "table"
                or lastCommittedInput.battleId ~= state.battleId
                or lastCommittedInput.turnId ~= state.lastCommittedTurnId then
                addError(
                    errors,
                    "last_committed_pending_mismatch",
                    "$.context.lastCommittedPending",
                    "직전 pendingTurn이 현재 전투의 마지막 확정 턴과 일치하지 않습니다."
                )
                return failure(errors)
            end
            local presented, presentationCallError = callRuntime(
                "turnPresentation",
                "build",
                lastCommittedInput,
                data
            )
            if presentationCallError then
                table.insert(errors, presentationCallError)
                return failure(errors)
            end
            if presented.ok ~= true then
                appendNestedErrors(errors, "$.context.lastCommittedPending", presented)
                return failure(errors)
            end
            if type(presented.lastTurn) ~= "table" or presented.lastTurn.available ~= true then
                addError(
                    errors,
                    "missing_last_turn_presentation",
                    "$.context.lastCommittedPending",
                    "직전 확정 턴에서 공개 표시 자료를 만들지 못했습니다."
                )
                return failure(errors)
            end
            lastTurn = buildLastTurnView(presented.lastTurn, data.registry, errors)
        end

        local characterDefinition = data.characters[displayState.character.characterId]
        local environment = data.environments[displayState.environmentId]
        if type(characterDefinition) ~= "table" or type(environment) ~= "table" then
            addError(errors, "missing_static_reference", "$", "캐릭터 또는 환경 정의를 찾을 수 없습니다.")
            return failure(errors)
        end

        local selectedOrder = {}
        for index, instanceId in ipairs(selectedIds) do
            selectedOrder[instanceId] = index
        end

        local displayEntries = {}
        local visibleSet = {}
        local handInstances = {}
        for _, instance in ipairs(displayState.cardInstances) do
            if instance.owner == "player" and instance.zone == "hand" then
                table.insert(handInstances, instance)
            end
        end
        table.sort(handInstances, function(left, right)
            return left.position < right.position
        end)
        for _, instance in ipairs(handInstances) do
            visibleSet[instance.instanceId] = true
            table.insert(displayEntries, { instance = instance, origin = "hand" })
        end
        for index, instanceId in ipairs(previewIds) do
            if visibleSet[instanceId] then
                addError(errors, "duplicate_preview_card", "$.preview[" .. index .. "]", "프리뷰 카드가 권위 손패와 중복되었습니다.")
            else
                local instance = findInstance(displayState.cardInstances, instanceId)
                if type(instance) ~= "table" or instance.owner ~= "player" then
                    addError(errors, "invalid_preview_card", "$.preview[" .. index .. "]", "프리뷰 카드 인스턴스를 권위 상태에서 찾을 수 없습니다.")
                else
                    visibleSet[instanceId] = true
                    table.insert(displayEntries, { instance = instance, origin = "preview" })
                end
            end
        end

        local handItems = {}
        local playableById = {}
        local cardDisplayContext = {
            battleId = displayState.battleId,
            turnId = turnId,
            phase = phase,
            locked = locked,
            interactionToken = interactionToken,
            focusedInstanceId = focusedInstanceId,
        }
        for slot, entry in ipairs(displayEntries) do
            local instance = entry.instance
            local card = data.cards[instance.cardId]
            local summary = buildSafeCardSummary(card, data.registry, "$.hand.items[" .. slot .. "]", errors)
            if summary then
                local baseStealthCost = card.base.stealthCost
                local baseResistanceDamage = card.base.resistanceDamage
                local playable = true
                local reasonCode = "none"
                if locked then
                    playable = false
                    reasonCode = phase == "awaitingOutput" and "awaiting_output" or "battle_ended"
                elseif displayState.player.stealth <= baseStealthCost then
                    playable = false
                    reasonCode = "insufficient_stealth"
                end
                local effectChoices = {}
                local selectableChoiceCount = 0
                for choiceIndex, choice in ipairs(type(card.effectChoices) == "table" and card.effectChoices or {}) do
                    local choicePath = "$.hand.items[" .. slot .. "].effectChoices[" .. choiceIndex .. "]"
                    local choiceContext = {
                        turn = displayState.turnNumber,
                        phase = "player_selection",
                        mood = displayState.character.mood,
                        player = { stealth = displayState.player.stealth },
                        character = {
                            resistance = displayState.character.resistance,
                            moodTokens = displayState.character.moodTokens,
                            publicActionTag = displayState.characterIntent.publicActionTag,
                        },
                        card = {
                            id = card.id,
                            instanceId = instance.instanceId,
                            owner = card.owner,
                            actionTag = card.actionTag,
                        },
                    }
                    local choiceReport, choiceCallError = callRuntime(
                        "effectEngine",
                        "evaluateEffectChoice",
                        data,
                        card.id,
                        choice.id,
                        choiceContext
                    )
                    local selectable = not locked
                        and choiceCallError == nil
                        and type(choiceReport) == "table"
                        and choiceReport.ok == true
                        and choiceReport.selectable == true
                    if choiceCallError ~= nil then
                        table.insert(errors, choiceCallError)
                    elseif type(choiceReport) ~= "table" or choiceReport.ok ~= true then
                        appendNestedErrors(errors, choicePath, choiceReport)
                    end
                    if selectable then selectableChoiceCount = selectableChoiceCount + 1 end
                    local effectChoiceView = {
                        id = choice.id,
                        label = choice.label,
                        descriptionSegments = tokenizeForBuild(choice.description, data.registry, choicePath .. ".description", errors),
                        selectable = selectable,
                        reasonCode = selectable and "none" or (choiceReport and choiceReport.reasonCode or (locked and "locked" or "unavailable")),
                        unavailableText = choice.unavailableText or "현재 상태에서는 이 효과를 선택할 수 없습니다.",
                    }
                    appendFields(
                        effectChoiceView,
                        buildEffectChoiceDisplay(
                            instance.instanceId,
                            effectChoiceView,
                            interactionToken
                        )
                    )
                    effectChoices[#effectChoices + 1] = effectChoiceView
                end
                if not locked and #effectChoices > 0 and selectableChoiceCount == 0 then
                    playable = false
                    reasonCode = "no_available_effect_choice"
                end
                playableById[instance.instanceId] = playable

                local selectedChoice = nil
                local selectedChoiceId = selectedChoices[instance.instanceId]
                if selectedChoiceId ~= nil then
                    for _, choice in ipairs(effectChoices) do
                        if choice.id == selectedChoiceId then
                            selectedChoice = { id = choice.id, label = choice.label }
                            break
                        end
                    end
                end

                local cardView = {
                    slot = slot,
                    origin = entry.origin,
                    instanceId = instance.instanceId,
                    cardId = summary.cardId,
                    name = summary.name,
                    descriptionSegments = summary.descriptionSegments,
                    ruleLines = summary.ruleLines,
                    actionTag = summary.actionTag,
                    mechanisms = summary.mechanisms,
                    effectChoices = effectChoices,
                    hasEffectChoices = #effectChoices > 0,
                    selectedEffectChoice = selectedChoice,
                    baseStealthCost = baseStealthCost,
                    finalStealthCost = baseStealthCost,
                    baseResistanceDamage = baseResistanceDamage,
                    finalResistanceDamage = baseResistanceDamage,
                    playable = playable,
                    reasonCode = reasonCode,
                    selected = selectedOrder[instance.instanceId] ~= nil,
                    selectionOrder = selectedOrder[instance.instanceId] or 0,
                }
                appendFields(cardView, buildCardDisplay(cardView, cardDisplayContext))
                table.insert(handItems, cardView)
            end
        end

        local mainActionCount = 0
        local mainActionIndex = nil
        local selectedPlayable = true
        for index, instanceId in ipairs(selectedIds) do
            local instance = findInstance(displayState.cardInstances, instanceId)
            local card = instance and data.cards[instance.cardId] or nil
            if card and not hasMechanism(card, "chain") then
                mainActionCount = mainActionCount + 1
                mainActionIndex = index
            end
            if visibleSet[instanceId] ~= true or playableById[instanceId] ~= true then
                selectedPlayable = false
            end
        end

        local selectedCount = #selectedIds
        local hasMainAction = mainActionCount == 1
        local mainActionLast = mainActionCount == 0 or mainActionIndex == selectedCount
        local mode = selectedCount == 0 and "pass"
            or (hasMainAction and "action" or "chain_pass")
        local canSubmit = not locked
            and mainActionCount <= 1
            and mainActionLast
            and selectedPlayable
        local selectionReason = "none"
        if locked then
            selectionReason = phase == "awaitingOutput" and "awaiting_output" or "battle_ended"
        elseif mainActionCount > 1 then
            selectionReason = "multiple_main_actions"
        elseif not mainActionLast then
            selectionReason = "main_action_not_last"
        elseif not selectedPlayable then
            selectionReason = "unplayable_selection"
        end

        local publicAction = { status = "none" }
        if displayState.characterIntent.publicActionTag ~= nil then
            local tag = lookupTag(data.registry, displayState.characterIntent.publicActionTag, "$.character.publicAction.tag", errors)
            if tag then
                publicAction = {
                    status = "tagRevealed",
                    tag = tag,
                }
            end
        end

        local outcomeLabels = {
            active = "진행 중",
            victory = "승리",
            defeat = "패배",
        }
        local subwayView = buildSubwayView(
            displayState,
            data,
            errors,
            aftermathInput and aftermathInput.completedTurnNumber or nil
        )
        if subwayView == nil then
            return failure(errors)
        end

        local selectionView = {
            count = selectedCount,
            mode = mode,
            hasMainAction = hasMainAction,
            canSubmit = canSubmit,
            reasonCode = selectionReason,
        }
        if phase == "selecting" and focusedInstanceId ~= nil then
            selectionView.focusedInstanceId = focusedInstanceId
        end

        local view = {
            schemaVersion = SCHEMA_VERSION,
            kind = "battleView",
            battleId = displayState.battleId,
            turnId = turnId,
            phase = phase,
            locked = locked,
            tagGlossary = buildTagGlossary(publicAction, handItems),
            subway = subwayView,
            environment = {
                id = environment.id,
                name = environment.name,
                description = environment.description,
                ruleLines = buildRuleLines(environment.rules, data.registry, "$.environment.rules", errors),
            },
            player = {
                stealth = displayState.player.stealth,
                planCapacity = displayState.player.planCapacity,
                plans = buildPlanViews(
                    displayState.player,
                    "player",
                    data.cards,
                    data.registry,
                    "$.player.plans",
                    errors
                ),
            },
            character = {
                id = characterDefinition.id,
                name = characterDefinition.name,
                resistance = displayState.character.resistance,
                startingResistance = characterDefinition.battle.startingResistance,
                mood = buildMoodView(displayState, data, errors),
                publicAction = publicAction,
                traits = buildTraitViews(displayState, data, errors),
                planCapacity = displayState.character.planCapacity,
                plans = buildPlanViews(
                    displayState.character,
                    "character",
                    data.cards,
                    data.registry,
                    "$.character.plans",
                    errors
                ),
            },
            hand = {
                count = #handItems,
                items = handItems,
            },
            selection = selectionView,
            zones = countZones(displayState.cardInstances),
            lastTurn = lastTurn,
            battleLog = buildBattleLogView(displayState, data, errors),
            outcome = {
                status = displayState.status,
                label = outcomeLabels[displayState.status],
            },
            aftermath = aftermathInput == nil and { active = false } or {
                active = true,
                awaitingOutput = aftermathInput.phase ~= "ready",
                finalTurn = aftermathInput.completedTurnNumber + 1 == state.turnLimit,
            },
        }
        if interactionToken ~= nil then
            view.interactionToken = interactionToken
        end

        if #errors > 0 then
            return failure(errors)
        end

        return success("view", view)
    end

    local function validateTagView(value, path, errors, expectedTagKind)
        if type(value) ~= "table" then
            addError(errors, "invalid_tag_view", path, "태그 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            kind = true,
            id = true,
            label = true,
            tagKind = true,
            tooltip = true,
        }, path, errors)
        if value.kind ~= "tag" then
            addError(errors, "invalid_tag_kind", path .. ".kind", "태그 조각의 kind는 tag여야 합니다.")
        end
        if not isAsciiId(value.id) then
            addError(errors, "invalid_tag_id", path .. ".id", "태그 ID가 올바르지 않습니다.")
        end
        if type(value.label) ~= "string" or value.label == "" then
            addError(errors, "invalid_tag_label", path .. ".label", "태그 표시명이 필요합니다.")
        end
        if value.tagKind ~= "action" and value.tagKind ~= "mechanism" then
            addError(errors, "invalid_tag_type", path .. ".tagKind", "tagKind가 올바르지 않습니다.")
        elseif expectedTagKind and value.tagKind ~= expectedTagKind then
            addError(errors, "tag_role_mismatch", path .. ".tagKind", "이 위치의 태그 종류는 " .. expectedTagKind .. "이어야 합니다.")
        end
        if type(value.tooltip) ~= "string" or value.tooltip == "" then
            addError(errors, "invalid_tag_tooltip", path .. ".tooltip", "태그 툴팁이 필요합니다.")
        end
    end

    local function validateSegments(value, path, errors)
        local length = getArrayLength(value, path, errors)
        if length == nil then
            return
        end
        for index = 1, length do
            local segment = value[index]
            local segmentPath = path .. "[" .. index .. "]"
            if type(segment) ~= "table" then
                addError(errors, "invalid_segment", segmentPath, "문장 조각이 테이블이 아닙니다.")
            elseif segment.kind == "text" then
                checkAllowedKeys(segment, { kind = true, value = true }, segmentPath, errors)
                if type(segment.value) ~= "string" or segment.value == "" then
                    addError(errors, "invalid_text_segment", segmentPath .. ".value", "빈 텍스트 조각은 허용하지 않습니다.")
                end
            elseif segment.kind == "tag" then
                validateTagView(segment, segmentPath, errors)
            else
                addError(errors, "invalid_segment_kind", segmentPath .. ".kind", "알 수 없는 문장 조각입니다.")
            end
        end
    end

    local function validateRuleLines(value, path, errors)
        local length = getArrayLength(value, path, errors)
        if length == nil then
            return
        end
        for index = 1, length do
            local line = value[index]
            local linePath = path .. "[" .. index .. "]"
            if type(line) ~= "table" then
                addError(errors, "invalid_rule_line", linePath, "규칙 줄이 테이블이 아닙니다.")
            else
                checkAllowedKeys(line, { segments = true }, linePath, errors)
                validateSegments(line.segments, linePath .. ".segments", errors)
            end
        end
    end

    local function validateTagArray(value, path, errors, expectedTagKind)
        local length = getArrayLength(value, path, errors)
        if length == nil then
            return
        end
        for index = 1, length do
            validateTagView(value[index], path .. "[" .. index .. "]", errors, expectedTagKind)
        end
    end

    local function validateSafeCardSummary(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_card_summary", path, "카드 요약이 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            cardId = true,
            name = true,
            descriptionSegments = true,
            ruleLines = true,
            actionTag = true,
            mechanisms = true,
        }, path, errors)
        if not isAsciiId(value.cardId) then
            addError(errors, "invalid_card_id", path .. ".cardId", "카드 ID가 올바르지 않습니다.")
        end
        if type(value.name) ~= "string" or value.name == "" then
            addError(errors, "invalid_card_name", path .. ".name", "카드 이름이 필요합니다.")
        end
        validateSegments(value.descriptionSegments, path .. ".descriptionSegments", errors)
        validateRuleLines(value.ruleLines, path .. ".ruleLines", errors)
        validateTagView(value.actionTag, path .. ".actionTag", errors, "action")
        validateTagArray(value.mechanisms, path .. ".mechanisms", errors, "mechanism")
    end

    local function validateEffectSourceView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_effect_source", path, "효과 원인 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            kind = true,
            kindLabel = true,
            side = true,
            name = true,
            descriptionSegments = true,
            ruleLines = true,
            relatedTags = true,
            hasRelatedTags = true,
        }, path, errors)
        if SOURCE_KIND_LABELS[value.kind] ~= value.kindLabel then
            addError(errors, "invalid_effect_source_kind", path .. ".kind", "효과 원인 종류와 표시명이 일치하지 않습니다.")
        end
        if value.side ~= nil and value.side ~= "player" and value.side ~= "character" then
            addError(errors, "invalid_effect_source_side", path .. ".side", "효과 원인 진영이 올바르지 않습니다.")
        end
        if type(value.name) ~= "string" or value.name == "" then
            addError(errors, "invalid_effect_source_name", path .. ".name", "효과 원인 이름이 필요합니다.")
        end
        validateSegments(value.descriptionSegments, path .. ".descriptionSegments", errors)
        validateRuleLines(value.ruleLines, path .. ".ruleLines", errors)
        local tagCount = getArrayLength(value.relatedTags, path .. ".relatedTags", errors)
        if tagCount then
            validateTagArray(value.relatedTags, path .. ".relatedTags", errors)
            if value.hasRelatedTags ~= (tagCount > 0) then
                addError(errors, "effect_source_tag_flag_mismatch", path .. ".hasRelatedTags", "관련 태그 표시 여부가 태그 목록과 다릅니다.")
            end
        end
        if value.hasRelatedTags ~= true and value.hasRelatedTags ~= false then
            addError(errors, "invalid_effect_source_tag_flag", path .. ".hasRelatedTags", "관련 태그 표시 여부는 불리언이어야 합니다.")
        end
    end

    local function validateResourceChanges(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_resource_changes", path, "자원 변화 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, { stealth = true, resistance = true }, path, errors)
        local seenSequences = {}
        for _, resource in ipairs({ "stealth", "resistance" }) do
            local entries = value[resource]
            local length = getArrayLength(entries, path .. "." .. resource, errors)
            if length then
                for index = 1, length do
                    local entry = entries[index]
                    local entryPath = path .. "." .. resource .. "[" .. index .. "]"
                    if type(entry) ~= "table" then
                        addError(errors, "invalid_resource_change", entryPath, "자원 변화 항목이 테이블이 아닙니다.")
                    else
                        checkAllowedKeys(entry, {
                            sequence = true,
                            amount = true,
                            amountLabel = true,
                            direction = true,
                            source = true,
                        }, entryPath, errors)
                        if not isInteger(entry.sequence, 1) or seenSequences[entry.sequence] then
                            addError(errors, "invalid_resource_change_sequence", entryPath .. ".sequence", "자원 변화 사건 순번이 올바르지 않습니다.")
                        else
                            seenSequences[entry.sequence] = true
                        end
                        if not isFinite(entry.amount)
                            or entry.amount == 0
                            or entry.amountLabel ~= signedNumber(entry.amount)
                            or entry.direction ~= (entry.amount > 0 and "increase" or "decrease") then
                            addError(errors, "invalid_resource_change_amount", entryPath, "자원 변화량 표시가 올바르지 않습니다.")
                        end
                        validateEffectSourceView(entry.source, entryPath .. ".source", errors)
                    end
                end
            end
        end
    end

    local function validatePlanView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_plan_view", path, "계획 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            slotIndex = true,
            status = true,
            hasDuration = true,
            remainingTurns = true,
            card = true,
        }, path, errors)
        if not isInteger(value.slotIndex, 1) then
            addError(errors, "invalid_plan_slot_index", path .. ".slotIndex", "계획 슬롯 번호가 올바르지 않습니다.")
        end
        if value.status ~= "empty" and value.status ~= "hidden" and value.status ~= "revealed" then
            addError(errors, "invalid_plan_status", path .. ".status", "계획 공개 상태가 올바르지 않습니다.")
        end
        if value.hasDuration ~= true and value.hasDuration ~= false then
            addError(errors, "invalid_plan_duration_flag", path .. ".hasDuration", "hasDuration은 불리언이어야 합니다.")
        elseif value.hasDuration then
            if not isInteger(value.remainingTurns, 1) then
                addError(errors, "invalid_remaining_turns", path .. ".remainingTurns", "남은 지속 턴이 올바르지 않습니다.")
            end
        elseif value.remainingTurns ~= nil then
            addError(errors, "unexpected_remaining_turns", path .. ".remainingTurns", "지속시간이 없는 계획에 남은 턴을 표시할 수 없습니다.")
        end

        if value.status == "revealed" then
            validateSafeCardSummary(value.card, path .. ".card", errors)
        elseif value.card ~= nil then
            addError(errors, "hidden_plan_leak", path .. ".card", "미공개 또는 빈 계획에 카드 정보를 넣을 수 없습니다.")
        end
        if value.status == "empty" and value.hasDuration ~= false then
            addError(errors, "empty_plan_duration", path .. ".hasDuration", "빈 계획에는 지속시간이 없습니다.")
        end
    end

    local function validatePlanViews(value, capacity, path, errors, allowHidden)
        local length = getArrayLength(value, path, errors)
        if length == nil then
            return
        end
        if isPlanCapacity(capacity) and length ~= capacity then
            addError(errors, "plan_capacity_mismatch", path, "계획 View 배열 길이가 계획 용량과 다릅니다.")
        end

        local emptyStarted = false
        for index = 1, length do
            local plan = value[index]
            local planPath = path .. "[" .. index .. "]"
            validatePlanView(plan, planPath, errors)
            if type(plan) == "table" then
                if plan.slotIndex ~= index then
                    addError(errors, "plan_slot_index_mismatch", planPath .. ".slotIndex", "계획 배열 순서와 슬롯 번호가 다릅니다.")
                end
                if plan.status == "empty" then
                    emptyStarted = true
                elseif emptyStarted then
                    addError(errors, "plan_slot_order_mismatch", planPath .. ".status", "활성 계획은 빈 계획 슬롯보다 앞에 있어야 합니다.")
                end
                if plan.status == "hidden" and not allowHidden then
                    addError(errors, "hidden_player_plan", planPath .. ".status", "플레이어 자신의 계획은 숨김 상태로 표시할 수 없습니다.")
                end
            end
        end
    end

    local function validateCardView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_card_view", path, "손패 카드 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            slot = true,
            origin = true,
            instanceId = true,
            cardId = true,
            name = true,
            descriptionSegments = true,
            ruleLines = true,
            actionTag = true,
            mechanisms = true,
            effectChoices = true,
            hasEffectChoices = true,
            selectedEffectChoice = true,
            baseStealthCost = true,
            finalStealthCost = true,
            baseResistanceDamage = true,
            finalResistanceDamage = true,
            playable = true,
            reasonCode = true,
            selected = true,
            selectionOrder = true,
            className = true,
            orderLabel = true,
            showDetail = true,
            showPreviewFlag = true,
            showChoicePopover = true,
            choicePopoverId = true,
            actionKind = true,
            actionCommand = true,
            actionTarget = true,
            actionAriaLabel = true,
            actionAriaPressed = true,
            actionAriaExpanded = true,
            actionDisabled = true,
            helpPrimary = true,
            helpMessages = true,
        }, path, errors)
        if not isInteger(value.slot, 1) then
            addError(errors, "invalid_card_slot", path .. ".slot", "손패 슬롯이 올바르지 않습니다.")
        end
        if value.origin ~= "hand" and value.origin ~= "preview" then
            addError(errors, "invalid_card_origin", path .. ".origin", "카드 표시 origin은 hand 또는 preview여야 합니다.")
        end
        if not isRuntimeId(value.instanceId) then
            addError(errors, "invalid_instance_id", path .. ".instanceId", "카드 인스턴스 ID가 올바르지 않습니다.")
        end
        if not isAsciiId(value.cardId) then
            addError(errors, "invalid_card_id", path .. ".cardId", "카드 ID가 올바르지 않습니다.")
        end
        if type(value.name) ~= "string" or value.name == "" then
            addError(errors, "invalid_card_name", path .. ".name", "카드 이름이 필요합니다.")
        end
        validateSegments(value.descriptionSegments, path .. ".descriptionSegments", errors)
        validateRuleLines(value.ruleLines, path .. ".ruleLines", errors)
        validateTagView(value.actionTag, path .. ".actionTag", errors, "action")
        validateTagArray(value.mechanisms, path .. ".mechanisms", errors, "mechanism")
        local choiceCount = getArrayLength(value.effectChoices, path .. ".effectChoices", errors)
        local choiceIds = {}
        if choiceCount then
            for index = 1, choiceCount do
                local choice = value.effectChoices[index]
                local choicePath = path .. ".effectChoices[" .. index .. "]"
                if type(choice) ~= "table" then
                    addError(errors, "invalid_effect_choice_view", choicePath, "효과 선택지 View가 테이블이 아닙니다.")
                else
                    checkAllowedKeys(choice, {
                        id = true,
                        label = true,
                        descriptionSegments = true,
                        selectable = true,
                        reasonCode = true,
                        unavailableText = true,
                        command = true,
                        disabled = true,
                        showUnavailableText = true,
                    }, choicePath, errors)
                    if not isAsciiId(choice.id) or choiceIds[choice.id] then
                        addError(errors, "invalid_effect_choice_id", choicePath .. ".id", "효과 선택지 ID가 올바르지 않거나 중복되었습니다.")
                    else
                        choiceIds[choice.id] = true
                    end
                    if type(choice.label) ~= "string" or choice.label == "" then
                        addError(errors, "invalid_effect_choice_label", choicePath .. ".label", "효과 선택지 표시명이 필요합니다.")
                    end
                    validateSegments(choice.descriptionSegments, choicePath .. ".descriptionSegments", errors)
                    if type(choice.selectable) ~= "boolean" or type(choice.reasonCode) ~= "string"
                        or (choice.selectable and choice.reasonCode ~= "none")
                        or (not choice.selectable and choice.reasonCode == "none") then
                        addError(errors, "invalid_effect_choice_availability", choicePath, "효과 선택 가능 상태가 올바르지 않습니다.")
                    end
                    if type(choice.unavailableText) ~= "string" or choice.unavailableText == "" then
                        addError(errors, "invalid_effect_choice_unavailable_text", choicePath .. ".unavailableText", "효과 선택 불가 안내가 필요합니다.")
                    end
                    if type(choice.command) ~= "string"
                        or type(choice.disabled) ~= "boolean"
                        or type(choice.showUnavailableText) ~= "boolean" then
                        addError(errors, "invalid_effect_choice_display", choicePath, "효과 선택지 표시 결정이 올바르지 않습니다.")
                    elseif choice.disabled ~= (choice.selectable ~= true)
                        or choice.showUnavailableText ~= choice.disabled then
                        addError(errors, "effect_choice_display_mismatch", choicePath, "효과 선택지 표시 결정이 선택 가능 상태와 다릅니다.")
                    end
                end
            end
        end
        if value.hasEffectChoices ~= (choiceCount ~= nil and choiceCount > 0) then
            addError(errors, "effect_choice_flag_mismatch", path .. ".hasEffectChoices", "효과 선택지 표시 여부가 목록과 다릅니다.")
        end
        if value.selectedEffectChoice ~= nil then
            if type(value.selectedEffectChoice) ~= "table"
                or not isAsciiId(value.selectedEffectChoice.id)
                or type(value.selectedEffectChoice.label) ~= "string"
                or value.selectedEffectChoice.label == ""
                or not choiceIds[value.selectedEffectChoice.id] then
                addError(errors, "invalid_selected_effect_choice", path .. ".selectedEffectChoice", "선택된 효과 표시값이 올바르지 않습니다.")
            elseif value.selected ~= true then
                addError(errors, "orphan_selected_effect_choice", path .. ".selectedEffectChoice", "등록되지 않은 카드에 선택 효과가 있습니다.")
            end
        elseif value.hasEffectChoices and value.selected == true then
            addError(errors, "missing_selected_effect_choice", path .. ".selectedEffectChoice", "등록된 선택형 카드에 선택 효과 표시가 없습니다.")
        end
        for _, field in ipairs({
            "baseStealthCost",
            "finalStealthCost",
            "baseResistanceDamage",
            "finalResistanceDamage",
        }) do
            if not isFinite(value[field]) or value[field] < 0 then
                addError(errors, "invalid_card_number", path .. "." .. field, "카드 수치는 0 이상의 유한한 숫자여야 합니다.")
            end
        end
        if value.playable ~= true and value.playable ~= false then
            addError(errors, "invalid_playable", path .. ".playable", "playable은 불리언이어야 합니다.")
        end
        if type(value.reasonCode) ~= "string" then
            addError(errors, "invalid_reason_code", path .. ".reasonCode", "사유 코드는 문자열이어야 합니다.")
        elseif value.playable == true and value.reasonCode ~= "none" then
            addError(errors, "playable_reason_mismatch", path .. ".reasonCode", "사용 가능한 카드는 사유 코드가 none이어야 합니다.")
        elseif value.playable == false and value.reasonCode == "none" then
            addError(errors, "disabled_reason_missing", path .. ".reasonCode", "사용할 수 없는 카드에는 사유 코드가 필요합니다.")
        end
        if value.selected ~= true and value.selected ~= false then
            addError(errors, "invalid_selected", path .. ".selected", "selected는 불리언이어야 합니다.")
        end
        if not isInteger(value.selectionOrder, 0) then
            addError(errors, "invalid_selection_order", path .. ".selectionOrder", "선택 순서가 올바르지 않습니다.")
        elseif value.selected and value.selectionOrder == 0 then
            addError(errors, "selected_order_missing", path .. ".selectionOrder", "선택 카드에는 1 이상의 선택 순서가 필요합니다.")
        elseif not value.selected and value.selectionOrder ~= 0 then
            addError(errors, "unselected_order_present", path .. ".selectionOrder", "미선택 카드의 선택 순서는 0이어야 합니다.")
        end
        for _, field in ipairs({
            "className", "orderLabel", "choicePopoverId", "actionKind",
            "actionCommand", "actionTarget", "actionAriaLabel",
            "actionAriaPressed", "actionAriaExpanded", "helpPrimary",
        }) do
            if type(value[field]) ~= "string" then
                addError(errors, "invalid_card_display_string", path .. "." .. field, "카드 표시 결정 문자열이 필요합니다.")
            end
        end
        for _, field in ipairs({
            "showDetail", "showPreviewFlag", "showChoicePopover", "actionDisabled",
        }) do
            if type(value[field]) ~= "boolean" then
                addError(errors, "invalid_card_display_flag", path .. "." .. field, "카드 표시 결정 플래그는 불리언이어야 합니다.")
            end
        end
        if value.actionKind ~= "toggle" and value.actionKind ~= "choose" then
            addError(errors, "invalid_card_action_kind", path .. ".actionKind", "카드 동작 종류가 올바르지 않습니다.")
        end
        local helpCount = getArrayLength(value.helpMessages, path .. ".helpMessages", errors)
        if helpCount then
            for index = 1, helpCount do
                if type(value.helpMessages[index]) ~= "string" or value.helpMessages[index] == "" then
                    addError(errors, "invalid_card_help_message", path .. ".helpMessages[" .. index .. "]", "카드 도움말은 비어 있지 않은 문자열이어야 합니다.")
                end
            end
        end
    end

    local function validateSubwayStationView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_subway_station_view", path, "역 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            index = true,
            id = true,
            code = true,
            name = true,
            status = true,
            isStart = true,
            isDestination = true,
        }, path, errors)
        if not isInteger(value.index, 1) then
            addError(errors, "invalid_subway_station_index", path .. ".index", "역 순번이 올바르지 않습니다.")
        end
        if not isAsciiId(value.id) then
            addError(errors, "invalid_subway_station_id", path .. ".id", "역 ID가 올바르지 않습니다.")
        end
        if type(value.code) ~= "string"
            or string.match(value.code, "^[A-Za-z]+%d%d$") == nil then
            addError(errors, "invalid_subway_station_code", path .. ".code", "역 번호가 올바르지 않습니다.")
        end
        if type(value.name) ~= "string" or value.name == "" then
            addError(errors, "invalid_subway_station_name", path .. ".name", "역 이름이 필요합니다.")
        end
        if value.status ~= "passed" and value.status ~= "current" and value.status ~= "upcoming" then
            addError(errors, "invalid_subway_station_status", path .. ".status", "역 진행 상태가 올바르지 않습니다.")
        end
        if value.isStart ~= true and value.isStart ~= false then
            addError(errors, "invalid_subway_start_flag", path .. ".isStart", "isStart는 불리언이어야 합니다.")
        end
        if value.isDestination ~= true and value.isDestination ~= false then
            addError(errors, "invalid_subway_destination_flag", path .. ".isDestination", "isDestination은 불리언이어야 합니다.")
        end
    end

    local function sameSubwayStation(left, right)
        return type(left) == "table"
            and type(right) == "table"
            and left.index == right.index
            and left.id == right.id
            and left.code == right.code
            and left.name == right.name
            and left.status == right.status
            and left.isStart == right.isStart
            and left.isDestination == right.isDestination
    end

    local function validateSubwayView(value, path, errors)
        if type(value) ~= "table" then
            addError(errors, "invalid_subway_view", path, "지하철 노선 View가 테이블이 아닙니다.")
            return
        end
        checkAllowedKeys(value, {
            lineId = true,
            lineName = true,
            lineCode = true,
            lineColor = true,
            operatorName = true,
            startStation = true,
            currentStation = true,
            destinationStation = true,
            stations = true,
        }, path, errors)
        if not isAsciiId(value.lineId) then
            addError(errors, "invalid_subway_line_id", path .. ".lineId", "노선 ID가 올바르지 않습니다.")
        end
        for _, field in ipairs({ "lineName", "lineCode", "operatorName" }) do
            if type(value[field]) ~= "string" or value[field] == "" then
                addError(errors, "invalid_subway_line_label", path .. "." .. field, "노선 표시 문자열이 필요합니다.")
            end
        end
        if type(value.lineColor) ~= "string"
            or string.match(value.lineColor, "^#%x%x%x%x%x%x$") == nil then
            addError(errors, "invalid_subway_line_color", path .. ".lineColor", "노선 색상은 #RRGGBB 형식이어야 합니다.")
        end

        validateSubwayStationView(value.startStation, path .. ".startStation", errors)
        validateSubwayStationView(value.currentStation, path .. ".currentStation", errors)
        validateSubwayStationView(value.destinationStation, path .. ".destinationStation", errors)

        local length = getArrayLength(value.stations, path .. ".stations", errors)
        if length == nil then
            return
        end
        if length < 8 or length > 13 then
            addError(errors, "invalid_subway_route_length", path .. ".stations", "전투 노선은 8~13개 역이어야 합니다.")
        end

        local currentCount = 0
        local currentStation = nil
        local reachedCurrent = false
        for index = 1, length do
            local station = value.stations[index]
            local stationPath = path .. ".stations[" .. index .. "]"
            validateSubwayStationView(station, stationPath, errors)
            if type(station) == "table" then
                if station.index ~= index then
                    addError(errors, "subway_station_index_mismatch", stationPath .. ".index", "역 순번과 배열 위치가 다릅니다.")
                end
                if station.isStart ~= (index == 1) then
                    addError(errors, "subway_start_mismatch", stationPath .. ".isStart", "출발역 표시는 첫 역에만 있어야 합니다.")
                end
                if station.isDestination ~= (index == length) then
                    addError(errors, "subway_destination_mismatch", stationPath .. ".isDestination", "도착역 표시는 마지막 역에만 있어야 합니다.")
                end
                if station.status == "current" then
                    currentCount = currentCount + 1
                    currentStation = station
                    reachedCurrent = true
                elseif station.status == "passed" and reachedCurrent then
                    addError(errors, "invalid_subway_status_order", stationPath .. ".status", "통과한 역은 현재역보다 앞에 있어야 합니다.")
                elseif station.status == "upcoming" and not reachedCurrent then
                    addError(errors, "invalid_subway_status_order", stationPath .. ".status", "예정 역은 현재역보다 뒤에 있어야 합니다.")
                end
            end
        end
        if currentCount ~= 1 then
            addError(errors, "invalid_subway_current_count", path .. ".stations", "현재역은 정확히 하나여야 합니다.")
        end
        if length > 0 then
            if not sameSubwayStation(value.startStation, value.stations[1]) then
                addError(errors, "subway_start_reference_mismatch", path .. ".startStation", "출발역 요약과 노선의 첫 역이 다릅니다.")
            end
            if not sameSubwayStation(value.destinationStation, value.stations[length]) then
                addError(errors, "subway_destination_reference_mismatch", path .. ".destinationStation", "도착역 요약과 노선의 마지막 역이 다릅니다.")
            end
            if not sameSubwayStation(value.currentStation, currentStation) then
                addError(errors, "subway_current_reference_mismatch", path .. ".currentStation", "현재역 요약과 노선의 현재역이 다릅니다.")
            end
        end
    end

    local function validateAftermathView(value, path, errors)
        if value == nil then return end
        if type(value) ~= "table" then
            addError(errors, "invalid_aftermath_view", path, "승리 후 자유행동 View가 테이블이 아닙니다.")
            return
        end
        if value.active == false then
            checkAllowedKeys(value, { active = true }, path, errors)
            return
        end
        checkAllowedKeys(value, {
            active = true,
            awaitingOutput = true,
            finalTurn = true,
        }, path, errors)
        if value.active ~= true then
            addError(errors, "invalid_aftermath_active", path .. ".active", "자유행동 active는 불리언이어야 합니다.")
        end
        for _, field in ipairs({ "awaitingOutput", "finalTurn" }) do
            if value[field] ~= true and value[field] ~= false then
                addError(errors, "invalid_aftermath_flag", path .. "." .. field, "자유행동 표시 플래그는 불리언이어야 합니다.")
            end
        end
    end

    local function validateBattleView(view)
        local errors = {}
        if type(view) ~= "table" then
            addError(errors, "invalid_view", "$", "battleView가 테이블이 아닙니다.")
            return failure(errors)
        end
        validateJsonSafe(view, "$", errors)
        if #errors > 0 then
            return failure(errors)
        end
        checkAllowedKeys(view, {
            schemaVersion = true,
            kind = true,
            battleId = true,
            turnId = true,
            phase = true,
            locked = true,
            interactionToken = true,
            tagGlossary = true,
            subway = true,
            environment = true,
            player = true,
            character = true,
            hand = true,
            selection = true,
            zones = true,
            lastTurn = true,
            battleLog = true,
            outcome = true,
            aftermath = true,
        }, "$", errors)
        if view.schemaVersion ~= SCHEMA_VERSION then
            addError(errors, "unsupported_schema", "$.schemaVersion", "지원하지 않는 battleView 스키마입니다.")
        end
        if view.kind ~= "battleView" then
            addError(errors, "invalid_kind", "$.kind", "kind는 battleView여야 합니다.")
        end
        if not isRuntimeId(view.battleId) or not isRuntimeId(view.turnId) then
            addError(errors, "invalid_runtime_id", "$", "battleId와 turnId가 올바르지 않습니다.")
        end
        if view.phase ~= "selecting" and view.phase ~= "awaitingOutput" and view.phase ~= "ended" then
            addError(errors, "invalid_phase", "$.phase", "알 수 없는 battleView phase입니다.")
        end
        if view.locked ~= true and view.locked ~= false then
            addError(errors, "invalid_locked", "$.locked", "locked는 불리언이어야 합니다.")
        elseif (view.phase == "selecting" and view.locked) or (view.phase ~= "selecting" and not view.locked) then
            addError(errors, "phase_lock_mismatch", "$.locked", "phase와 locked 값이 일치하지 않습니다.")
        end
        if view.interactionToken ~= nil
            and (type(view.interactionToken) ~= "string"
                or string.match(view.interactionToken, "^draftv1_%d+_%d+_%d+$") == nil) then
            addError(errors, "invalid_interaction_token", "$.interactionToken", "UI 상호작용 토큰이 올바르지 않습니다.")
        elseif view.phase == "selecting" and view.interactionToken == nil then
            addError(errors, "missing_interaction_token", "$.interactionToken", "선택 가능한 View에는 상호작용 토큰이 필요합니다.")
        elseif view.phase == "ended" and view.interactionToken ~= nil then
            addError(errors, "ended_interaction_token", "$.interactionToken", "종료 View에는 상호작용 토큰을 넣을 수 없습니다.")
        end
        validateAftermathView(view.aftermath, "$.aftermath", errors)

        local glossaryLength = getArrayLength(view.tagGlossary, "$.tagGlossary", errors)
        if glossaryLength then
            local seenTagIds = {}
            for index = 1, glossaryLength do
                local tag = view.tagGlossary[index]
                local path = "$.tagGlossary[" .. index .. "]"
                validateTagView(tag, path, errors)
                if type(tag) == "table" and type(tag.id) == "string" then
                    if seenTagIds[tag.id] then
                        addError(errors, "duplicate_glossary_tag", path .. ".id", "태그 설명 ID가 중복되었습니다.")
                    end
                    seenTagIds[tag.id] = true
                end
            end
        end

        validateSubwayView(view.subway, "$.subway", errors)

        if type(view.environment) ~= "table" then
            addError(errors, "invalid_environment", "$.environment", "environment가 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.environment, { id = true, name = true, description = true, ruleLines = true }, "$.environment", errors)
            if not isAsciiId(view.environment.id) or type(view.environment.name) ~= "string" or type(view.environment.description) ~= "string" then
                addError(errors, "invalid_environment_value", "$.environment", "환경 표시 값이 올바르지 않습니다.")
            end
            validateRuleLines(view.environment.ruleLines, "$.environment.ruleLines", errors)
        end

        if type(view.player) ~= "table" then
            addError(errors, "invalid_player", "$.player", "player가 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.player, {
                stealth = true,
                planCapacity = true,
                plans = true,
            }, "$.player", errors)
            if not isFinite(view.player.stealth) then
                addError(errors, "invalid_stealth", "$.player.stealth", "은폐 표시값이 올바르지 않습니다.")
            end
            if not isPlanCapacity(view.player.planCapacity) then
                addError(
                    errors,
                    "invalid_plan_capacity",
                    "$.player.planCapacity",
                    "플레이어 계획 용량은 1 이상 " .. MAX_PLAN_CAPACITY .. " 이하의 정수여야 합니다."
                )
            end
            validatePlanViews(view.player.plans, view.player.planCapacity, "$.player.plans", errors, false)
        end

        if type(view.character) ~= "table" then
            addError(errors, "invalid_character", "$.character", "character가 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.character, {
                id = true,
                name = true,
                resistance = true,
                startingResistance = true,
                mood = true,
                publicAction = true,
                traits = true,
                planCapacity = true,
                plans = true,
            }, "$.character", errors)
            if not isAsciiId(view.character.id) or type(view.character.name) ~= "string" then
                addError(errors, "invalid_character_value", "$.character", "캐릭터 표시 값이 올바르지 않습니다.")
            end
            if not isFinite(view.character.resistance) or not isFinite(view.character.startingResistance) then
                addError(errors, "invalid_resistance", "$.character", "저항 표시값이 올바르지 않습니다.")
            end

            local mood = view.character.mood
            if type(mood) ~= "table" then
                addError(errors, "invalid_mood", "$.character.mood", "무드 View가 테이블이 아닙니다.")
            else
                checkAllowedKeys(mood, {
                    id = true,
                    label = true,
                    tokenThreshold = true,
                    tokens = true,
                }, "$.character.mood", errors)
                if not isAsciiId(mood.id) or type(mood.label) ~= "string" then
                    addError(errors, "invalid_mood_value", "$.character.mood", "무드 표시 값이 올바르지 않습니다.")
                end
                if mood.tokenThreshold ~= 3 or type(mood.tokens) ~= "table" then
                    addError(errors, "invalid_mood_tokens", "$.character.mood", "무드 토큰 표시값이 올바르지 않습니다.")
                else
                    for _, moodId in ipairs({ "rejection", "suspicion", "ignore", "confusion", "compliance" }) do
                        if not isInteger(mood.tokens[moodId], 0) then
                            addError(errors, "invalid_mood_token_count", "$.character.mood.tokens." .. moodId, "무드 토큰 표시값은 0 이상의 정수여야 합니다.")
                        end
                    end
                end
            end

            local publicAction = view.character.publicAction
            if type(publicAction) ~= "table" then
                addError(errors, "invalid_public_action", "$.character.publicAction", "공개 행동 View가 테이블이 아닙니다.")
            elseif publicAction.status == "none" then
                checkAllowedKeys(publicAction, { status = true }, "$.character.publicAction", errors)
            elseif publicAction.status == "tagRevealed" then
                checkAllowedKeys(publicAction, { status = true, tag = true }, "$.character.publicAction", errors)
                validateTagView(publicAction.tag, "$.character.publicAction.tag", errors, "action")
            else
                addError(errors, "invalid_public_action_status", "$.character.publicAction.status", "공개 행동 상태가 올바르지 않습니다.")
            end

            local traitCount = getArrayLength(view.character.traits, "$.character.traits", errors)
            if traitCount then
                for index = 1, traitCount do
                    local trait = view.character.traits[index]
                    local path = "$.character.traits[" .. index .. "]"
                    if type(trait) ~= "table" then
                        addError(errors, "invalid_trait_view", path, "특징 View가 테이블이 아닙니다.")
                    else
                        checkAllowedKeys(trait, { id = true, name = true, description = true, ruleLines = true }, path, errors)
                        if not isAsciiId(trait.id) or type(trait.name) ~= "string" or type(trait.description) ~= "string" then
                            addError(errors, "invalid_trait_value", path, "특징 표시 값이 올바르지 않습니다.")
                        end
                        validateRuleLines(trait.ruleLines, path .. ".ruleLines", errors)
                    end
                end
            end
            if not isPlanCapacity(view.character.planCapacity) then
                addError(
                    errors,
                    "invalid_plan_capacity",
                    "$.character.planCapacity",
                    "캐릭터 계획 용량은 1 이상 " .. MAX_PLAN_CAPACITY .. " 이하의 정수여야 합니다."
                )
            end
            validatePlanViews(view.character.plans, view.character.planCapacity, "$.character.plans", errors, true)
        end

        if type(view.hand) ~= "table" then
            addError(errors, "invalid_hand", "$.hand", "hand가 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.hand, { count = true, items = true }, "$.hand", errors)
            local handCount = getArrayLength(view.hand.items, "$.hand.items", errors)
            if handCount and view.hand.count ~= handCount then
                addError(errors, "hand_count_mismatch", "$.hand.count", "손패 개수와 항목 수가 다릅니다.")
            end
            if handCount then
                local instanceSeen = {}
                local previewStarted = false
                for index = 1, handCount do
                    local item = view.hand.items[index]
                    local itemPath = "$.hand.items[" .. index .. "]"
                    validateCardView(item, itemPath, errors)
                    if type(item) == "table" then
                        local expectedDisplay = buildCardDisplay(item, {
                            battleId = view.battleId,
                            turnId = view.turnId,
                            phase = view.phase,
                            locked = view.locked,
                            interactionToken = view.interactionToken,
                            focusedInstanceId = type(view.selection) == "table"
                                and view.selection.focusedInstanceId
                                or nil,
                        })
                        for _, field in ipairs(CARD_DISPLAY_FIELD_NAMES) do
                            if not displayValuesEqual(item[field], expectedDisplay[field]) then
                                addError(errors, "card_display_mismatch", itemPath .. "." .. field, "카드 표시 결정이 정규 View 계산과 다릅니다.")
                            end
                        end
                        for choiceIndex, choice in ipairs(type(item.effectChoices) == "table" and item.effectChoices or {}) do
                            local expectedChoiceDisplay = buildEffectChoiceDisplay(
                                item.instanceId,
                                choice,
                                view.interactionToken
                            )
                            for _, field in ipairs(EFFECT_CHOICE_DISPLAY_FIELD_NAMES) do
                                if not displayValuesEqual(choice[field], expectedChoiceDisplay[field]) then
                                    addError(errors, "effect_choice_display_mismatch", itemPath .. ".effectChoices[" .. choiceIndex .. "]." .. field, "효과 선택 표시 결정이 정규 View 계산과 다릅니다.")
                                end
                            end
                        end
                    end
                    if type(item) == "table" and item.slot ~= index then
                        addError(errors, "hand_slot_mismatch", itemPath .. ".slot", "손패 배열 순서와 슬롯이 다릅니다.")
                    end
                    if type(item) == "table" and isRuntimeId(item.instanceId) then
                        if instanceSeen[item.instanceId] then
                            addError(errors, "duplicate_view_card", itemPath .. ".instanceId", "같은 카드 인스턴스를 View에 중복 표시할 수 없습니다.")
                        end
                        instanceSeen[item.instanceId] = true
                    end
                    if type(item) == "table" then
                        if item.origin == "preview" then
                            previewStarted = true
                        elseif item.origin == "hand" and previewStarted then
                            addError(errors, "view_origin_order", itemPath .. ".origin", "권위 손패 카드는 프리뷰 카드보다 앞에 표시해야 합니다.")
                        end
                        if view.phase == "awaitingOutput"
                            and (item.playable ~= false or item.reasonCode ~= "awaiting_output") then
                            addError(errors, "awaiting_card_not_locked", itemPath, "출력 대기 중인 카드는 awaiting_output으로 잠겨야 합니다.")
                        elseif view.phase == "ended"
                            and (item.playable ~= false or item.reasonCode ~= "battle_ended") then
                            addError(errors, "ended_card_not_locked", itemPath, "종료된 전투의 카드는 battle_ended로 잠겨야 합니다.")
                        end
                    end
                end
            end
        end

        if type(view.selection) ~= "table" then
            addError(errors, "invalid_selection", "$.selection", "selection이 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.selection, {
                count = true,
                mode = true,
                hasMainAction = true,
                canSubmit = true,
                reasonCode = true,
                focusedInstanceId = true,
            }, "$.selection", errors)
            if not isInteger(view.selection.count, 0)
                or (view.selection.mode ~= "pass"
                    and view.selection.mode ~= "chain_pass"
                    and view.selection.mode ~= "action")
                or (view.selection.hasMainAction ~= true and view.selection.hasMainAction ~= false)
                or (view.selection.canSubmit ~= true and view.selection.canSubmit ~= false)
                or type(view.selection.reasonCode) ~= "string" then
                addError(errors, "invalid_selection_value", "$.selection", "선택 표시 값이 올바르지 않습니다.")
            end
            if view.selection.focusedInstanceId ~= nil and not isRuntimeId(view.selection.focusedInstanceId) then
                addError(errors, "invalid_focus", "$.selection.focusedInstanceId", "상세 표시 카드 인스턴스 ID가 올바르지 않습니다.")
            elseif view.phase ~= "selecting" and view.selection.focusedInstanceId ~= nil then
                addError(errors, "locked_view_focus", "$.selection.focusedInstanceId", "출력 대기 또는 종료 View에는 focus를 보존하지 않습니다.")
            end
            if type(view.hand) == "table" and type(view.hand.items) == "table" then
                local selectedCount = 0
                local orders = {}
                local mainActionCount = 0
                local mainActionOrder = nil
                local selectedPlayable = true
                local focusedVisible = view.selection.focusedInstanceId == nil
                for _, item in ipairs(view.hand.items) do
                    if type(item) == "table" and item.instanceId == view.selection.focusedInstanceId then
                        focusedVisible = true
                    end
                    if type(item) == "table" and item.selected == true then
                        selectedCount = selectedCount + 1
                        if isInteger(item.selectionOrder, 1) then
                            orders[item.selectionOrder] = (orders[item.selectionOrder] or 0) + 1
                        end
                        if item.playable ~= true then
                            selectedPlayable = false
                        end

                        local hasChain = false
                        if type(item.mechanisms) == "table" then
                            for _, mechanism in ipairs(item.mechanisms) do
                                if type(mechanism) == "table" and mechanism.id == "chain" then
                                    hasChain = true
                                    break
                                end
                            end
                        end
                        if not hasChain then
                            mainActionCount = mainActionCount + 1
                            mainActionOrder = item.selectionOrder
                        end
                    end
                end
                if view.selection.count ~= selectedCount then
                    addError(errors, "selection_count_mismatch", "$.selection.count", "선택 개수와 손패의 선택 표시가 다릅니다.")
                end
                if not focusedVisible then
                    addError(errors, "focused_card_not_visible", "$.selection.focusedInstanceId", "focus 카드는 현재 표시 카드에 있어야 합니다.")
                end
                for order = 1, selectedCount do
                    if orders[order] ~= 1 then
                        addError(errors, "selection_order_gap", "$.hand.items", "선택 순서는 1부터 중복 없이 이어져야 합니다.")
                        break
                    end
                end

                local expectedHasMainAction = mainActionCount == 1
                local mainActionLast = mainActionCount == 0 or mainActionOrder == selectedCount
                local expectedMode = selectedCount == 0 and "pass"
                    or (expectedHasMainAction and "action" or "chain_pass")
                local expectedCanSubmit = view.locked == false
                    and mainActionCount <= 1
                    and mainActionLast
                    and selectedPlayable
                local expectedReason = "none"
                if view.locked == true then
                    expectedReason = view.phase == "awaitingOutput" and "awaiting_output" or "battle_ended"
                elseif mainActionCount > 1 then
                    expectedReason = "multiple_main_actions"
                elseif not mainActionLast then
                    expectedReason = "main_action_not_last"
                elseif not selectedPlayable then
                    expectedReason = "unplayable_selection"
                end

                if view.selection.hasMainAction ~= expectedHasMainAction then
                    addError(errors, "main_action_summary_mismatch", "$.selection.hasMainAction", "손패 선택에서 계산한 주 행동 여부와 다릅니다.")
                end
                if view.selection.mode ~= expectedMode then
                    addError(errors, "selection_mode_mismatch", "$.selection.mode", "손패 선택에서 계산한 projection mode와 다릅니다.")
                end
                if view.selection.canSubmit ~= expectedCanSubmit then
                    addError(errors, "submit_summary_mismatch", "$.selection.canSubmit", "손패 선택에서 계산한 전송 가능 여부와 다릅니다.")
                end
                if view.selection.reasonCode ~= expectedReason then
                    addError(errors, "selection_reason_mismatch", "$.selection.reasonCode", "손패 선택에서 계산한 사유 코드와 다릅니다.")
                end
            end
        end

        if type(view.zones) ~= "table" then
            addError(errors, "invalid_zones", "$.zones", "zones가 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.zones, {
                deckCount = true,
                usedCount = true,
                discardCount = true,
                removedCount = true,
            }, "$.zones", errors)
            for _, field in ipairs({ "deckCount", "usedCount", "discardCount", "removedCount" }) do
                if not isInteger(view.zones[field], 0) then
                    addError(errors, "invalid_zone_count", "$.zones." .. field, "카드 영역 개수가 올바르지 않습니다.")
                end
            end
        end

        if type(view.lastTurn) ~= "table" then
            addError(errors, "invalid_last_turn", "$.lastTurn", "lastTurn이 테이블이 아닙니다.")
        else
            if view.lastTurn.available == false then
                checkAllowedKeys(view.lastTurn, { available = true }, "$.lastTurn", errors)
            elseif view.lastTurn.available == true then
                checkAllowedKeys(view.lastTurn, {
                    available = true,
                    turnNumber = true,
                    summaries = true,
                    resourceChanges = true,
                }, "$.lastTurn", errors)
                if not isInteger(view.lastTurn.turnNumber, 1) then
                    addError(errors, "invalid_last_turn_number", "$.lastTurn.turnNumber", "직전 공개 턴 번호가 올바르지 않습니다.")
                end
                local summaryCount = getArrayLength(view.lastTurn.summaries, "$.lastTurn.summaries", errors)
                if summaryCount then
                    for index = 1, summaryCount do
                        local item = view.lastTurn.summaries[index]
                        local itemPath = "$.lastTurn.summaries[" .. index .. "]"
                        if type(item) ~= "table" then
                            addError(errors, "invalid_turn_summary", itemPath, "턴 공개 요약이 테이블이 아닙니다.")
                        else
                            checkAllowedKeys(item, {
                                sequence = true,
                                type = true,
                                text = true,
                            }, itemPath, errors)
                            if item.sequence ~= index
                                or not isAsciiId(item.type)
                                or type(item.text) ~= "string"
                                or item.text == "" then
                                addError(errors, "invalid_turn_summary", itemPath, "턴 공개 요약 값이 올바르지 않습니다.")
                            end
                        end
                    end
                end
                validateResourceChanges(view.lastTurn.resourceChanges, "$.lastTurn.resourceChanges", errors)
            else
                addError(errors, "invalid_last_turn_availability", "$.lastTurn.available", "lastTurn.available은 불리언이어야 합니다.")
            end
        end

        if type(view.outcome) ~= "table" then
            addError(errors, "invalid_outcome", "$.outcome", "outcome이 테이블이 아닙니다.")
        else
            checkAllowedKeys(view.outcome, { status = true, label = true }, "$.outcome", errors)
            if view.outcome.status ~= "active" and view.outcome.status ~= "victory" and view.outcome.status ~= "defeat" then
                addError(errors, "invalid_outcome_status", "$.outcome.status", "결과 상태가 올바르지 않습니다.")
            end
            if type(view.outcome.label) ~= "string" or view.outcome.label == "" then
                addError(errors, "invalid_outcome_label", "$.outcome.label", "결과 표시명이 필요합니다.")
            end
            if view.phase == "ended" and view.outcome.status == "active" then
                addError(errors, "ended_outcome_mismatch", "$.outcome.status", "종료 View의 결과는 active일 수 없습니다.")
            elseif view.phase ~= "ended" and view.outcome.status ~= "active" then
                addError(errors, "active_phase_outcome_mismatch", "$.outcome.status", "선택 또는 출력 대기 View의 결과는 active여야 합니다.")
            end
        end
        if type(view.aftermath) == "table" and view.aftermath.active == true then
            if view.phase ~= "ended"
                or type(view.outcome) ~= "table"
                or view.outcome.status ~= "victory" then
                addError(errors, "aftermath_view_mismatch", "$.aftermath", "자유행동 View는 확정된 승리 화면에서만 표시할 수 있습니다.")
            end
        end

        if #errors > 0 then
            return failure(errors)
        end
        return success(nil, nil)
    end

    local arguments = { ... }
    if action == "tokenizeTags" then
        return tokenizeTags(arguments[1], arguments[2], arguments[3])
    elseif action == "buildCardPresentation" then
        local errors = {}
        local card = buildSafeCardSummary(arguments[1], arguments[2], arguments[3] or "$.card", errors)
        if #errors > 0 or card == nil then
            return failure(errors)
        end
        return success("card", card)
    elseif action == "presentationCacheStats" then
        return {
            ok = true,
            schemaVersion = SCHEMA_VERSION,
            errors = {},
            cache = {
                entries = presentationCacheSize,
                maxEntries = PRESENTATION_CACHE_MAX_ENTRIES,
                hits = presentationStats.hits,
                misses = presentationStats.misses,
                evictions = presentationStats.evictions,
            },
        }
    elseif action == "clearPresentationCache" then
        local removed = presentationCacheSize
        presentationCache = {}
        presentationCacheSize = 0
        return success("removed", removed)
    elseif action == "validateBattleView" then
        return validateBattleView(arguments[1])
    elseif action == "buildBattleView" then
        local built = buildBattleView(arguments[1], arguments[2], arguments[3])
        if type(built) ~= "table" or built.ok ~= true then
            return built
        end
        local validation = validateBattleView(built.view)
        if not validation.ok then
            return validation
        end
        return built
    end

    local errors = {}
    addError(errors, "unknown_action", "$", "지원하지 않는 View 작업입니다: " .. tostring(action))
    return failure(errors)
    end
end)()

]],
    [[[
캐릭터 프로필
]]] = [[
(function (triggerId, characterName)
    local uiAppend = loadLores(triggerId, "캐릭터 프로필.html")
    if type(uiAppend) ~= "string" or uiAppend == "" then
        debug(1, "캐릭터 프로필 UI를 불러오지 못했습니다: " .. tostring(characterName))
        return
    end
    setChatVar(triggerId, "helltrainUiPopupV1", uiAppend)
end)

]],
}

--기본 변수
DEBUG = 2 --디버그 메시지 depth. 숫자가 클수록 덜 중요하고 디테일 한 메시지.

--전역 상수
DEFAULT_LORE_OPTION = { alwaysActive = false, insertOrder = 100, key = "", secondKey = "", regex = false }


--디버깅
function debug(depth, ...)
    if depth <= DEBUG then
        print(...)
    end
end

--tonumber를 콤마제거후 숫자로 인식하도록 오버라이딩
old_tonumber = tonumber
tonumber = function(str, base)
    if type(str) == "string" then
        local cleaned_str = string.gsub(str, ",", "")
        return old_tonumber(cleaned_str, base)
    else
        return old_tonumber(str, base)
    end
end

--json을 chatVar 형식으로 저장
function toChatVar(triggerId, name, data)
    if data == nil then
        data = getState(triggerId, name)
    end

    if type(data) ~= "table" then
        setChatVar(triggerId, name, tostring(data))
        return tostring(data)
    end

    local function encodeString(value)
        return json.encode(tostring(value))
    end

    local function encodeForChatVar(value)
        local parts = {}

        for k, v in pairs(value) do
            local encodedValue

            if type(v) == "table" then
                encodedValue = encodeString(encodeForChatVar(v))
            else
                encodedValue = encodeString(v)
            end

            table.insert(parts, encodeString(k) .. ":" .. encodedValue)
        end

        return "{" .. table.concat(parts, ",") .. "}"
    end

    local encoded = encodeForChatVar(data)
    setChatVar(triggerId, name, encoded)
    return encoded
end

--chatVar를 state 형식으로 저장
function toState(triggerId, name)
    local source = getChatVar(triggerId, name)

    if not source or source == "" then
        debug(1, "toState error: chat var " .. tostring(name) .. " is empty.")
        setState(triggerId, name, {})
        return getState(triggerId, name)
    end

    local function tryDecode(value)
        if type(value) ~= "string" then
            return nil
        end

        local trimmed = value:match("^%s*(.-)%s*$")
        local first = trimmed:sub(1, 1)
        if first ~= "{" and first ~= "[" then
            return nil
        end

        local ok, decoded = pcall(json.decode, trimmed)
        if ok and type(decoded) == "table" then
            return decoded
        end
        return nil
    end

    local function decodeFromChatVar(value)
        if type(value) == "table" then
            local decoded = {}
            for k, v in pairs(value) do
                decoded[k] = decodeFromChatVar(v)
            end
            return decoded
        end

        local decoded = tryDecode(value)
        if decoded then
            return decodeFromChatVar(decoded)
        end

        return value
    end

    local root = tryDecode(source)
    if not root then
        setState(triggerId, name, source)
        return source
    end

    local decoded = decodeFromChatVar(root)
    setState(triggerId, name, decoded)
    return decoded
end

local function stripHtmlLineIndent(source)
    source = source:gsub("^[ \t]+", "")
    source = source:gsub("\r\n[ \t]+", "\r\n")
    source = source:gsub("\n[ \t]+", "\n")
    source = source:gsub("\r[ \t]+", "\r")
    return source
end

--로어북에서 내용을 불러와 return
function loadLores(triggerId, lore)
    local targetLores = getLoreBooks(triggerId, lore)
    if type(targetLores) ~= "table" then
        return nil
    end

    local contents = {}
    for _, loreEntry in ipairs(targetLores) do
        table.insert(contents, loreEntry.content)
    end
    local returnContents = table.concat(contents)

    --주석 제거
    returnContents = returnContents
        :gsub("%-%-%-[^\r\n]*", "")

    if type(lore) == "string" and string.match(lore, "%.html$") then
        returnContents = stripHtmlLineIndent(returnContents)
    end

    if returnContents == "" then
        return nil
    else
        return returnContents
    end
end

-- Executable lore entries are complete modules, not mergeable fragments. RisuAI
-- returns matches in local -> global -> module order. This game's authoritative
-- runtime bundle is the module entry, so the last non-empty match must replace
-- stale character/global copies. Concatenating duplicate modules can turn two
-- adjacent anonymous functions into an accidental function call.
local function loadScriptLore(_triggerId, script)
    return __HELLTRAIN_BUNDLED_SCRIPT_SOURCES[script]
end

-- 배포 시 executable Lua lore 또는 static DB가 바뀌면 이 revision도 반드시 올린다. production
-- warm path는 이 명시적 계약 덕분에 이벤트 사이에서 getLoreBooks/CBS bridge를
-- 생략한다. 개발 중에는 setRunScriptCacheDevelopmentMode(true)를 사용하면 매
-- 이벤트의 첫 모듈 호출에서 source를 다시 확인한다.
RUNTIME_BUNDLE_REVISION = RUNTIME_BUNDLE_REVISION
    or "runtime-bundle-standalone-6e758b0633742883"
RUNTIME_CACHE_DEVELOPMENT_BYPASS = RUNTIME_CACHE_DEVELOPMENT_BYPASS == true

local RUN_SCRIPT_SOURCE_CACHE_MAX_ENTRIES = 64
local RUN_SCRIPT_WARM_CACHE_MAX_ENTRIES = 128
local RUN_SCRIPT_TRANSACTION_MAX_ENTRIES = 64
local RUN_SCRIPT_NAMESPACE_VAR = "runtimeModuleCacheV1.namespace"

local runScriptSourceBuckets = {}
local runScriptSourceCacheSize = 0
local runScriptWarmCache = {}
local runScriptWarmCacheSize = 0
local runScriptCacheClock = 0
local runScriptCacheEpoch = 0
local currentRuntimeMode = "unscoped"
local activeRuntimeEvent = nil
local runScriptCacheStats = {
    events = 0,
    requests = 0,
    transactionHits = 0,
    transactionCapacitySkips = 0,
    warmHits = 0,
    warmMisses = 0,
    sourceFetches = 0,
    sourceHits = 0,
    sourceMisses = 0,
    compiles = 0,
    sourceEvictions = 0,
    warmEvictions = 0,
    clears = 0,
    developmentModeChanges = 0,
    namespaceReads = 0,
    namespaceWrites = 0,
    namespaceWriteFailures = 0,
    volatileNamespaces = 0,
    missingSources = 0,
    compileFailures = 0,
    loadFailures = 0,
    invalidHandlers = 0,
    executionFailures = 0,
}

local function fingerprintRunScriptIdentity(source)
    local first = 0
    local second = 0
    for index = 1, #source do
        local byte = string.byte(source, index)
        first = (first * 131 + byte) % 2147483647
        second = (second * 137 + byte + index) % 2147483629
    end
    return tostring(#source) .. ":" .. tostring(first) .. ":" .. tostring(second)
end

local function runtimeCacheKeyPart(value)
    local text = tostring(value or "")
    return tostring(#text) .. ":" .. text
end

local function makeRunScriptWarmKey(event, script)
    return table.concat({
        runtimeCacheKeyPart(event.bundleRevision),
        runtimeCacheKeyPart(event.mode),
        runtimeCacheKeyPart(event.namespace),
        runtimeCacheKeyPart(event.characterIdentity),
        runtimeCacheKeyPart(script),
    }, "|")
end

local function touchRunScriptCacheEntry(entry)
    runScriptCacheClock = runScriptCacheClock + 1
    entry.lastUsed = runScriptCacheClock
end

local function currentRunScriptBundleRevision()
    local revision = tostring(RUNTIME_BUNDLE_REVISION or "")
    if revision == "" then
        return "invalid-empty-revision"
    end
    return revision
end

local function resolveRunScriptNamespace(triggerId)
    runScriptCacheStats.namespaceReads = runScriptCacheStats.namespaceReads + 1
    if type(getChatVar) == "function" then
        local readOk, existing = pcall(getChatVar, triggerId, RUN_SCRIPT_NAMESPACE_VAR)
        if readOk
            and type(existing) == "string"
            and string.match(existing, "^runtime%-ns%-v1:%d+:%d+:%d+$") then
            return existing
        end
    end

    local generated = "runtime-ns-v1:" .. fingerprintRunScriptIdentity(tostring(triggerId or ""))
    if type(setChatVar) == "function" then
        local writeOk = pcall(setChatVar, triggerId, RUN_SCRIPT_NAMESPACE_VAR, generated)
        if writeOk then
            runScriptCacheStats.namespaceWrites = runScriptCacheStats.namespaceWrites + 1
            local readOk, stored = pcall(getChatVar, triggerId, RUN_SCRIPT_NAMESPACE_VAR)
            if readOk and stored == generated then
                return generated
            end
        end
        runScriptCacheStats.namespaceWriteFailures = runScriptCacheStats.namespaceWriteFailures + 1
    end

    -- 권한이 없는 mode에서는 event access key fingerprint를 사용한다. access key는
    -- top-level 호출마다 달라 warm hit는 포기하지만 다른 채팅과 섞이지 않는다.
    runScriptCacheStats.volatileNamespaces = runScriptCacheStats.volatileNamespaces + 1
    return "volatile:" .. generated
end

local function resolveRunScriptCharacterIdentity(triggerId)
    local name = ""
    local firstMessage = ""
    if type(getName) == "function" then
        local ok, value = pcall(getName, triggerId)
        if ok and type(value) == "string" then
            name = value
        end
    end
    if type(getCharacterFirstMessage) == "function" then
        local ok, value = pcall(getCharacterFirstMessage, triggerId)
        if ok and type(value) == "string" then
            firstMessage = value
        end
    end
    return fingerprintRunScriptIdentity(name .. "\0" .. firstMessage)
end

-- 모든 host hook의 시작에서 호출한다. namespace/character host read는 실제로
-- runScript가 호출될 때까지 지연하므로 editInput 같은 가벼운 hook에는 비용이 없다.
function beginRunScriptEvent(triggerId, mode)
    currentRuntimeMode = type(mode) == "string" and mode ~= "" and mode or "unscoped"
    activeRuntimeEvent = {
        triggerId = triggerId,
        mode = currentRuntimeMode,
        bundleRevision = currentRunScriptBundleRevision(),
        cacheEpoch = runScriptCacheEpoch,
        handlers = {},
        handlerCount = 0,
    }
    runScriptCacheStats.events = runScriptCacheStats.events + 1
    return currentRuntimeMode
end

local function ensureRunScriptEvent(triggerId)
    local revision = currentRunScriptBundleRevision()
    if activeRuntimeEvent == nil
        or activeRuntimeEvent.triggerId ~= triggerId
        or activeRuntimeEvent.bundleRevision ~= revision
        or activeRuntimeEvent.cacheEpoch ~= runScriptCacheEpoch then
        beginRunScriptEvent(triggerId, currentRuntimeMode)
    end
    if activeRuntimeEvent.namespace == nil then
        activeRuntimeEvent.namespace = resolveRunScriptNamespace(triggerId)
        activeRuntimeEvent.characterIdentity = resolveRunScriptCharacterIdentity(triggerId)
    end
    return activeRuntimeEvent
end

local function evictOldestRunScriptSourceEntry()
    if runScriptSourceCacheSize < RUN_SCRIPT_SOURCE_CACHE_MAX_ENTRIES then
        return
    end
    local oldestScript = nil
    local oldestSource = nil
    local oldestEntry = nil
    for scriptName, bucket in pairs(runScriptSourceBuckets) do
        for source, entry in pairs(bucket) do
            if oldestEntry == nil or entry.lastUsed < oldestEntry.lastUsed then
                oldestScript = scriptName
                oldestSource = source
                oldestEntry = entry
            end
        end
    end
    if oldestEntry ~= nil then
        local bucket = runScriptSourceBuckets[oldestScript]
        bucket[oldestSource] = nil
        if next(bucket) == nil then
            runScriptSourceBuckets[oldestScript] = nil
        end
        runScriptSourceCacheSize = runScriptSourceCacheSize - 1
        runScriptCacheStats.sourceEvictions = runScriptCacheStats.sourceEvictions + 1
    end
end

local function instantiateRunScriptHandler(script, source)
    local bucket = runScriptSourceBuckets[script]
    local entry = bucket and bucket[source] or nil
    local chunk = nil
    if entry ~= nil then
        runScriptCacheStats.sourceHits = runScriptCacheStats.sourceHits + 1
        entry.hits = entry.hits + 1
        touchRunScriptCacheEntry(entry)
        chunk = entry.chunk
    else
        runScriptCacheStats.sourceMisses = runScriptCacheStats.sourceMisses + 1
        local functionString = "return" .. source
        debug(3, functionString)
        local err = nil
        chunk, err = load(functionString, "lore_function:" .. tostring(script), "t", _G)
        if not chunk then
            runScriptCacheStats.compileFailures = runScriptCacheStats.compileFailures + 1
            debug(1, "컴파일 오류: " .. (err or "알 수 없음"))
            return nil
        end
        runScriptCacheStats.compiles = runScriptCacheStats.compiles + 1
    end

    -- compiled chunk는 context 사이에 공유해도 handler closure는 namespace마다 새로
    -- 만든다. 모듈이 outer local cache를 가져도 다른 채팅과 mutable state가 섞이지 않는다.
    local ok, handler = pcall(chunk)
    if not ok then
        runScriptCacheStats.loadFailures = runScriptCacheStats.loadFailures + 1
        debug(1, "스크립트 로드 오류: " .. tostring(handler))
        if entry ~= nil then
            bucket[source] = nil
            runScriptSourceCacheSize = runScriptSourceCacheSize - 1
        end
        return nil
    end
    if type(handler) ~= "function" then
        runScriptCacheStats.invalidHandlers = runScriptCacheStats.invalidHandlers + 1
        debug(1, "runScript error: lorebook '" .. script .. "' did not return a function.")
        if entry ~= nil then
            bucket[source] = nil
            runScriptSourceCacheSize = runScriptSourceCacheSize - 1
        end
        return nil
    end

    if entry == nil then
        evictOldestRunScriptSourceEntry()
        bucket = runScriptSourceBuckets[script]
        if bucket == nil then
            bucket = {}
            runScriptSourceBuckets[script] = bucket
        end
        entry = {
            chunk = chunk,
            sourceLength = #source,
            sourceFingerprint = fingerprintRunScriptIdentity(source),
            hits = 0,
        }
        touchRunScriptCacheEntry(entry)
        bucket[source] = entry
        runScriptSourceCacheSize = runScriptSourceCacheSize + 1
    end
    return handler, entry.sourceFingerprint
end

local function evictOldestRunScriptWarmEntry()
    if runScriptWarmCacheSize < RUN_SCRIPT_WARM_CACHE_MAX_ENTRIES then
        return
    end
    local oldestKey = nil
    local oldestEntry = nil
    for key, entry in pairs(runScriptWarmCache) do
        if oldestEntry == nil or entry.lastUsed < oldestEntry.lastUsed then
            oldestKey = key
            oldestEntry = entry
        end
    end
    if oldestEntry ~= nil then
        runScriptWarmCache[oldestKey] = nil
        runScriptWarmCacheSize = runScriptWarmCacheSize - 1
        runScriptCacheStats.warmEvictions = runScriptCacheStats.warmEvictions + 1
    end
end

local function storeRunScriptWarmHandler(key, event, script, handler, sourceFingerprint)
    evictOldestRunScriptWarmEntry()
    local entry = {
        handler = handler,
        script = script,
        bundleRevision = event.bundleRevision,
        mode = event.mode,
        namespaceFingerprint = fingerprintRunScriptIdentity(event.namespace),
        characterIdentity = event.characterIdentity,
        sourceFingerprint = sourceFingerprint,
        hits = 0,
    }
    touchRunScriptCacheEntry(entry)
    runScriptWarmCache[key] = entry
    runScriptWarmCacheSize = runScriptWarmCacheSize + 1
    return handler
end

function setRunScriptCacheDevelopmentMode(enabled)
    local nextValue = enabled == true
    if RUNTIME_CACHE_DEVELOPMENT_BYPASS ~= nextValue then
        RUNTIME_CACHE_DEVELOPMENT_BYPASS = nextValue
        -- dev에서 관측한 source와 기존 production warm handler가 엇갈리지 않도록
        -- 모드 전환 시 warm layer만 폐기한다. compiled source cache는 안전하게 재사용한다.
        runScriptWarmCache = {}
        runScriptWarmCacheSize = 0
        runScriptCacheEpoch = runScriptCacheEpoch + 1
        activeRuntimeEvent = nil
        runScriptCacheStats.developmentModeChanges = runScriptCacheStats.developmentModeChanges + 1
    end
    return RUNTIME_CACHE_DEVELOPMENT_BYPASS
end

-- 개발 중 로어 교체나 진단 도구에서 명시적으로 캐시를 비울 수 있다.
-- script를 생략하면 전체를, 전달하면 해당 모듈의 compiled/warm entry를 제거한다.
function clearRunScriptCache(script)
    if script ~= nil and type(script) ~= "string" then
        return 0
    end

    local removedSources = 0
    if script == nil then
        removedSources = runScriptSourceCacheSize
        runScriptSourceBuckets = {}
        runScriptSourceCacheSize = 0
        runScriptWarmCache = {}
        runScriptWarmCacheSize = 0
    else
        local bucket = runScriptSourceBuckets[script]
        if bucket ~= nil then
            for _ in pairs(bucket) do
                removedSources = removedSources + 1
            end
            runScriptSourceBuckets[script] = nil
            runScriptSourceCacheSize = runScriptSourceCacheSize - removedSources
        end
        for key, entry in pairs(runScriptWarmCache) do
            if entry.script == script then
                runScriptWarmCache[key] = nil
                runScriptWarmCacheSize = runScriptWarmCacheSize - 1
            end
        end
    end

    runScriptCacheEpoch = runScriptCacheEpoch + 1
    activeRuntimeEvent = nil
    runScriptCacheStats.clears = runScriptCacheStats.clears + 1
    return removedSources
end

function getRunScriptCacheDiagnostics()
    local diagnostics = {
        bundleRevision = currentRunScriptBundleRevision(),
        developmentBypass = RUNTIME_CACHE_DEVELOPMENT_BYPASS,
        cacheEpoch = runScriptCacheEpoch,
        currentMode = currentRuntimeMode,
        maxSourceEntries = RUN_SCRIPT_SOURCE_CACHE_MAX_ENTRIES,
        maxWarmEntries = RUN_SCRIPT_WARM_CACHE_MAX_ENTRIES,
        maxTransactionEntries = RUN_SCRIPT_TRANSACTION_MAX_ENTRIES,
        sourceEntries = runScriptSourceCacheSize,
        warmEntries = runScriptWarmCacheSize,
        events = runScriptCacheStats.events,
        requests = runScriptCacheStats.requests,
        transactionHits = runScriptCacheStats.transactionHits,
        transactionCapacitySkips = runScriptCacheStats.transactionCapacitySkips,
        warmHits = runScriptCacheStats.warmHits,
        warmMisses = runScriptCacheStats.warmMisses,
        sourceFetches = runScriptCacheStats.sourceFetches,
        sourceHits = runScriptCacheStats.sourceHits,
        sourceMisses = runScriptCacheStats.sourceMisses,
        compiles = runScriptCacheStats.compiles,
        sourceEvictions = runScriptCacheStats.sourceEvictions,
        warmEvictions = runScriptCacheStats.warmEvictions,
        clears = runScriptCacheStats.clears,
        developmentModeChanges = runScriptCacheStats.developmentModeChanges,
        namespaceReads = runScriptCacheStats.namespaceReads,
        namespaceWrites = runScriptCacheStats.namespaceWrites,
        namespaceWriteFailures = runScriptCacheStats.namespaceWriteFailures,
        volatileNamespaces = runScriptCacheStats.volatileNamespaces,
        missingSources = runScriptCacheStats.missingSources,
        compileFailures = runScriptCacheStats.compileFailures,
        loadFailures = runScriptCacheStats.loadFailures,
        invalidHandlers = runScriptCacheStats.invalidHandlers,
        executionFailures = runScriptCacheStats.executionFailures,
        sources = {},
        warm = {},
    }
    -- 이전 진단 소비자와 호환되는 alias. 새 코드는 명시적인 source* 필드를 쓴다.
    diagnostics.entries = diagnostics.sourceEntries
    diagnostics.hits = diagnostics.sourceHits
    diagnostics.misses = diagnostics.sourceMisses
    diagnostics.evictions = diagnostics.sourceEvictions

    for scriptName, bucket in pairs(runScriptSourceBuckets) do
        for _, entry in pairs(bucket) do
            table.insert(diagnostics.sources, {
                script = scriptName,
                sourceLength = entry.sourceLength,
                sourceFingerprint = entry.sourceFingerprint,
                hits = entry.hits,
                lastUsed = entry.lastUsed,
            })
        end
    end
    for _, entry in pairs(runScriptWarmCache) do
        table.insert(diagnostics.warm, {
            script = entry.script,
            bundleRevision = entry.bundleRevision,
            mode = entry.mode,
            namespaceFingerprint = entry.namespaceFingerprint,
            characterIdentity = entry.characterIdentity,
            sourceFingerprint = entry.sourceFingerprint,
            hits = entry.hits,
            lastUsed = entry.lastUsed,
        })
    end
    local function sortDiagnostics(left, right)
        if left.script == right.script then
            return (left.sourceFingerprint or "") < (right.sourceFingerprint or "")
        end
        return left.script < right.script
    end
    table.sort(diagnostics.sources, sortDiagnostics)
    table.sort(diagnostics.warm, sortDiagnostics)
    return diagnostics
end

--로어북에서 스크립트를 호출해 실행
local function invokeRunScriptHandler(handler, triggerId, ...)
    local packed = table.pack(pcall(handler, triggerId, ...))
    if not packed[1] then
        runScriptCacheStats.executionFailures = runScriptCacheStats.executionFailures + 1
        debug(1, "스크립트 실행 오류: " .. tostring(packed[2]))
        return nil
    end
    return table.unpack(packed, 2, packed.n)
end

function runScript(triggerId, script, ...)
    runScriptCacheStats.requests = runScriptCacheStats.requests + 1
    local event = ensureRunScriptEvent(triggerId)
    local transactionHandler = event.handlers[script]
    if transactionHandler ~= nil then
        runScriptCacheStats.transactionHits = runScriptCacheStats.transactionHits + 1
        return invokeRunScriptHandler(transactionHandler, triggerId, ...)
    end

    local handler = nil
    local sourceFingerprint = nil
    local warmKey = makeRunScriptWarmKey(event, script)
    if not RUNTIME_CACHE_DEVELOPMENT_BYPASS then
        local warmEntry = runScriptWarmCache[warmKey]
        if warmEntry ~= nil then
            runScriptCacheStats.warmHits = runScriptCacheStats.warmHits + 1
            warmEntry.hits = warmEntry.hits + 1
            touchRunScriptCacheEntry(warmEntry)
            handler = warmEntry.handler
        else
            runScriptCacheStats.warmMisses = runScriptCacheStats.warmMisses + 1
        end
    end

    if handler == nil then
        runScriptCacheStats.sourceFetches = runScriptCacheStats.sourceFetches + 1
        local source = loadScriptLore(triggerId, script)
        if not source then
            runScriptCacheStats.missingSources = runScriptCacheStats.missingSources + 1
            debug(1, "runScript error: lorebook '" .. script .. "' not found.")
            return nil
        end
        handler, sourceFingerprint = instantiateRunScriptHandler(script, source)
        if handler == nil then
            return nil
        end
        if not RUNTIME_CACHE_DEVELOPMENT_BYPASS then
            storeRunScriptWarmHandler(warmKey, event, script, handler, sourceFingerprint)
        end
    end

    if event.handlerCount < RUN_SCRIPT_TRANSACTION_MAX_ENTRIES then
        event.handlers[script] = handler
        event.handlerCount = event.handlerCount + 1
    else
        runScriptCacheStats.transactionCapacitySkips = runScriptCacheStats.transactionCapacitySkips + 1
    end

    return invokeRunScriptHandler(handler, triggerId, ...)
end

--로어북에서 db를 호출해 return
function loadDB(triggerId, db)
    local lores = getLoreBooks(triggerId, db)

    if #lores == 0 then
        debug(1, "loadDB error: lorebook '" .. db .. "' not found.")
        return nil
    end

    local merged = {}
    local loadedCount = 0

    for _, lore in ipairs(lores) do
        local ok, decoded = pcall(json.decode, lore.content)

        if not ok or decoded == nil then
            debug(1, "loadDB error: invalid json in lorebook '" .. db .. "'.")
            return nil
        end

        if type(decoded) ~= "table" then
            return decoded
        end

        loadedCount = loadedCount + 1
        for k, v in pairs(decoded) do
            if type(k) == "number" then
                table.insert(merged, v)
            else
                merged[k] = v
            end
        end
    end

    if loadedCount == 0 then
        return nil
    end

    return merged
end

--변수를 로어북으로 저장
function saveDB(triggerId, name, data, ...)
    if data == nil then
        debug(1, "saveDB error: data is nil.")
        return
    end
    upsertLocalLoreBook(triggerId, name, json.encode(data), ...)
    debug(2, "saveDB: "..name.." saved successfully.")
    debug(3, name, json.encode(data))
end

--구분자로 문자열을 나누어 return
function splitByDelimiter(text, delimiter)
    local result = {}
    local source = tostring(text or "")
    local startIndex = 1

    while true do
        local foundStart, foundEnd = string.find(source, delimiter, startIndex, true)

        if not foundStart then
            table.insert(result, string.sub(source, startIndex))
            break
        end

        table.insert(result, string.sub(source, startIndex, foundStart - 1))
        startIndex = foundEnd + 1
    end

    return result
end

local function controllerSucceeded(label, report)
    if type(report) ~= "table" then
        debug(1, label .. ": battleController가 결과를 반환하지 않았습니다.")
        return false
    end
    if report.ok == true then
        return true
    end

    local errors = type(report.errors) == "table" and report.errors or {}
    if #errors == 0 then
        debug(1, label .. ": battleController가 상세 오류 없이 실패했습니다.")
        return false
    end
    for _, item in ipairs(errors) do
        if type(item) == "table" then
            debug(
                1,
                label
                    .. ": " .. tostring(item.code)
                    .. " at " .. tostring(item.path)
                    .. ": " .. tostring(item.message)
            )
        else
            debug(1, label .. ": " .. tostring(item))
        end
    end
    return false
end

